begin;
    with j as (select * from jsonb_to_recordset($law7v026$[{"code_id":"NK_RF_2","article_number":"259.1","version_date":"2000-07-31","article_text":"1. При установлении налогоплательщиком в учетной политике для целей налогообложения линейного метода начисления амортизации, а также при применении линейного метода начисления амортизации в отношении объектов амортизируемого имущества в соответствии с пунктом 3 статьи 259 настоящего Кодекса применяется порядок начисления амортизации, установленный настоящей статьей.\n\n2. Сумма начисленной за один месяц амортизации в отношении объекта амортизируемого имущества определяется как произведение его первоначальной (восстановительной) стоимости и нормы амортизации, определенной для данного объекта.\n\nНорма амортизации по каждому объекту амортизируемого имущества определяется по формуле:\n\nгде K - норма амортизации в процентах к первоначальной (восстановительной) стоимости объекта амортизируемого имущества;\n\nn - срок полезного использования данного объекта амортизируемого имущества, выраженный в месяцах (без учета сокращения (увеличения) срока в соответствии с абзацем вторым пункта 13 статьи 258 настоящего Кодекса).\n\n3. Начисление амортизации по амортизируемому имуществу в виде капитальных вложений в объекты основных средств, которые в соответствии с настоящей главой подлежат амортизации и амортизация по которым начисляется линейным методом, начинается у арендодателя с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию, у арендатора - с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию.\n\n4. Начисление амортизации по амортизируемому имуществу в виде капитальных вложений в объекты полученных по договору безвозмездного пользования основных средств, которые в соответствии с настоящей главой подлежат амортизации и амортизация по которым начисляется линейным методом, начинается у организации-ссудодателя с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию капитальных вложений, у организации-ссудополучателя - с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию.\n\n(Дополнение статьей - Федеральный закон от 22.07.2008 № 158-ФЗ)","article_title":"Статья 259.1. Порядок расчета сумм амортизации при применении линейного метода начисления амортизации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39dff44b1af288eb74ab6803e23caa808d976b428e3c06e4f8aa39bc8e01b572"},{"code_id":"NK_RF_2","article_number":"259.2","version_date":"2000-07-31","article_text":"1. При установлении налогоплательщиком в учетной политике для целей налогообложения нелинейного метода начисления амортизации используется порядок начисления амортизации, установленный настоящей статьей.\n\n2. На 1-е число налогового периода, с начала которого учетной политикой для целей налогообложения установлено применение нелинейного метода начисления амортизации, для каждой амортизационной группы (подгруппы) определяется суммарный баланс, который рассчитывается как суммарная стоимость всех объектов амортизируемого имущества, отнесенных к данной амортизационной группе (подгруппе), в порядке, установленном статьей 322 настоящего Кодекса с учетом положений настоящей статьи.\n\nВ дальнейшем суммарный баланс каждой амортизационной группы (подгруппы) определяется на 1-е число месяца, для которого определяется сумма начисленной амортизации, в порядке, установленном настоящей статьей.\n\nДля амортизационных групп и входящих в их состав подгрупп суммарный баланс определяется без учета объектов амортизируемого имущества, амортизация по которым начисляется линейным методом в соответствии с пунктом 3 статьи 259 настоящего Кодекса.\n\n3. По мере ввода в эксплуатацию объектов амортизируемого имущества первоначальная стоимость таких объектов увеличивает суммарный баланс соответствующей амортизационной группы (подгруппы). При этом первоначальная стоимость таких объектов включается в суммарный баланс соответствующей амортизационной группы (подгруппы) с 1-го числа месяца, следующего за месяцем, когда они были введены в эксплуатацию.\n\nПри изменении первоначальной стоимости основных средств в соответствии с пунктом 2 статьи 257 настоящего Кодекса в случаях достройки, дооборудования, реконструкции, модернизации, технического перевооружения, частичной ликвидации объектов суммы, на которые изменяется первоначальная стоимость указанных объектов, учитываются в суммарном балансе соответствующей амортизационной группы (подгруппы).\n\n4. Суммарный баланс каждой амортизационной группы (подгруппы) ежемесячно уменьшается на суммы начисленной по этой группе (подгруппе) амортизации.\n\nСумма начисленной за один месяц амортизации для каждой амортизационной группы (подгруппы) определяется исходя из произведения суммарного баланса соответствующей амортизационной группы (подгруппы) на начало месяца и норм амортизации, установленных настоящей статьей, по следующей формуле:\n\nгде A - сумма начисленной за один месяц амортизации для соответствующей амортизационной группы (подгруппы);\n\nB - суммарный баланс соответствующей амортизационной группы (подгруппы);\n\nk - норма амортизации для соответствующей амортизационной группы (подгруппы).\n\n5. В целях применения нелинейного метода начисления амортизации применяются следующие нормы амортизации:\n\nАмортизационная группа\n\n6. Начисление амортизации по амортизируемому имуществу в виде капитальных вложений в объекты арендованных основных средств, которое в соответствии с настоящей главой подлежит амортизации и амортизация по которому начисляется нелинейным методом в соответствии со статьей 259 настоящего Кодекса, начинается у арендодателя с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию, у арендатора - с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию.\n\n7. Начисление амортизации по амортизируемому имуществу в виде капитальных вложений в объекты полученных по договору безвозмездного пользования основных средств, которое в соответствии с настоящей главой подлежит амортизации и амортизация по которому начисляется нелинейным методом в соответствии со статьей 259 настоящего Кодекса, начинается у организации-ссудодателя с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию, у организации-ссудополучателя - с 1-го числа месяца, следующего за месяцем, в котором это имущество было введено в эксплуатацию.\n\n8. Начисление амортизации по объектам, амортизация по которым начисляется нелинейным методом, исключенным из состава амортизируемого имущества в соответствии с пунктом 3 статьи 256 настоящего Кодекса, прекращается с 1-го числа месяца, следующего за месяцем исключения данного объекта из состава амортизируемого имущества. При этом суммарный баланс соответствующей амортизационной группы (подгруппы) уменьшается на остаточную стоимость указанных объектов.\n\n9. При прекращении договора безвозмездного пользования и возврате объектов амортизируемого имущества налогоплательщику, а также при расконсервации, завершении реконструкции (модернизации) объекта основных средств, амортизация по которому начисляется нелинейным методом, амортизация по нему начисляется с 1-го числа месяца, следующего за месяцем, в котором произошли возврат объектов налогоплательщику, завершение реконструкции (модернизации) или расконсервация объекта основного средства, а суммарный баланс соответствующей амортизационной группы (подгруппы) увеличивается на остаточную стоимость указанных объектов с учетом положений пункта 9 статьи 258 настоящего Кодекса.\n\n10. При выбытии объектов амортизируемого имущества суммарный баланс соответствующей амортизационной группы (подгруппы) уменьшается на остаточную стоимость таких объектов.\n\n11. В случае, если в результате выбытия амортизируемого имущества суммарный баланс соответствующей амортизационной группы (подгруппы) был уменьшен до достижения суммарным балансом нуля, такая амортизационная группа (подгруппа) ликвидируется.\n\n12. В случае, если суммарный баланс амортизационной группы (подгруппы) становится менее 20 000 рублей, в месяце, следующем за месяцем, когда указанное значение было достигнуто, если за это время суммарный баланс соответствующей амортизационной группы (подгруппы) не увеличился в результате ввода в эксплуатацию объектов амортизируемого имущества, налогоплательщик вправе ликвидировать указанную группу (подгруппу), при этом значение суммарного баланса относится на внереализационные расходы текущего периода.\n\n13. По истечении срока полезного использования объекта амортизируемого имущества, определенного в соответствии со статьей 258 настоящего Кодекса, налогоплательщик может исключить данный объект из состава амортизационной группы (подгруппы) без изменения суммарного баланса этой амортизационной группы (подгруппы) на дату вывода этого объекта амортизируемого имущества из ее состава. При этом начисление амортизации исходя из суммарного баланса этой амортизационной группы (подгруппы) продолжается в порядке, установленном настоящей статьей.\n\nДля целей настоящего пункта срок полезного использования объектов амортизируемого имущества, введенных в эксплуатацию до 1-го числа налогового периода, с начала которого учетной политикой для целей налогообложения установлено применение нелинейного метода начисления амортизации, принимается с учетом срока эксплуатации соответствующих объектов до указанной даты.\n\n(Дополнение статьей - Федеральный закон от 22.07.2008 № 158-ФЗ)","article_title":"Статья 259.2. Порядок расчета сумм амортизации при применении нелинейного метода начисления амортизации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a44014560e540ae8e9a300e38527b4833391c389555c2cb541c91ceb5de77ea2"},{"code_id":"NK_RF_2","article_number":"259.3","version_date":"2000-07-31","article_text":"1. Налогоплательщики вправе применять к основной норме амортизации специальный коэффициент, но не выше 2:\n\n1) в отношении амортизируемых основных средств, используемых для работы в условиях агрессивной среды и (или) повышенной сменности.\n\nНалогоплательщики, использующие амортизируемые основные средства для работы в условиях агрессивной среды и (или) повышенной сменности, вправе использовать специальный коэффициент, указанный в настоящем пункте, только при начислении амортизации в отношении указанных основных средств.\n\nВ целях настоящей главы под агрессивной средой понимается совокупность природных и (или) искусственных факторов, влияние которых вызывает повышенный износ (старение) основных средств в процессе их эксплуатации. К работе в агрессивной среде приравнивается также нахождение основных средств в контакте с взрыво-, пожароопасной, токсичной или иной агрессивной технологической средой, которая может послужить причиной (источником) инициирования аварийной ситуации.\n\nПри применении нелинейного метода начисления амортизации указанный специальный коэффициент не применяется к основным средствам, относящимся к первой - третьей амортизационным группам.\n\nПоложения настоящего подпункта применяются в отношении амортизируемых основных средств, которые были приняты на учет до 1 января 2014 года; (Дополнение абзацем - Федеральный закон от 29.11.2012 № 206-ФЗ)\n\n2) в отношении собственных амортизируемых основных средств налогоплательщиков - сельскохозяйственных организаций промышленного типа (птицефабрики, животноводческие комплексы, зверосовхозы, тепличные комбинаты);\n\n3) в отношении собственных амортизируемых основных средств налогоплательщиков - организаций, имеющих статус резидента промышленно-производственной или туристско-рекреационной особой экономической зоны либо участника свободной экономической зоны; (В редакции Федерального закона от 29.11.2014 № 379-ФЗ)\n\n4) в отношении амортизируемых основных средств, относящихся к объектам (за исключением зданий), имеющим высокую энергетическую эффективность, в соответствии с перечнем таких объектов, установленным Правительством Российской Федерации, или к объектам (за исключением зданий), имеющим высокий класс энергетической эффективности, если в отношении таких объектов в соответствии с законодательством Российской Федерации предусмотрено определение классов их энергетической эффективности; (Дополнение подпунктом - Федеральный закон от 23.11.2009 № 261-ФЗ) (В редакции Федерального закона от 30.09.2017 № 286-ФЗ)\n\n5) в отношении амортизируемых основных средств, относящихся к основному технологическому оборудованию, эксплуатируемому в случае применения наилучших доступных технологий, согласно утвержденному Правительством Российской Федерации перечню основного технологического оборудования; (Дополнение подпунктом - Федеральный закон от 21.07.2014 № 219-ФЗ)\n\n6) в отношении амортизируемых основных средств, включенных в первую - седьмую амортизационные группы и произведенных в соответствии с условиями специального инвестиционного контракта.\n\nПорядок отнесения амортизируемых основных средств к произведенным в соответствии с условиями специального инвестиционного контракта определяется Правительством Российской Федерации.\n\n(Дополнение подпунктом - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n2. Налогоплательщики вправе применять к основной норме амортизации специальный коэффициент, но не выше 3:\n\n1) в отношении амортизируемых основных средств, являющихся предметом договора финансовой аренды (договора лизинга). (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nУказанный специальный коэффициент не применяется к основным средствам, относящимся к первой - третьей амортизационным группам;\n\n2) в отношении амортизируемых основных средств, используемых только для осуществления научно-технической деятельности;\n\n3) в отношении амортизируемых основных средств, используемых налогоплательщиками, указанными в пункте 1 статьи 2752 настоящего Кодекса, исключительно при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья.\n\nВ случае, если амортизируемое основное средство, в отношении которого в соответствии с настоящим подпунктом к основной норме амортизации был применен специальный коэффициент, начинает использоваться при осуществлении деятельности, не связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, ранее 1-го числа месяца, следующего за месяцем, в котором отношение остаточной стоимости такого объекта основных средств к его первоначальной стоимости оказалось ниже 0,2, сумма амортизации, начисленной с применением специального коэффициента, подлежит перерасчету без применения указанного коэффициента. Разница между пересчитанной таким способом амортизацией и фактически начисленной амортизацией за каждый налоговый (отчетный) период подлежит восстановлению и включению в состав внереализационных доходов начиная с налогового периода, в котором впервые был применен указанный коэффициент;\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n4) (Дополнение подпунктом - Федеральный закон от 30.09.2017 № 286-ФЗ) (Утратил силу  - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n5) в отношении амортизируемых основных средств, включенных на дату их ввода в эксплуатацию в единый реестр российской радиоэлектронной продукции.\n\nПереходные ключи между кодами Общероссийского классификатора продукции по видам экономической деятельности, содержащимися в едином реестре российской радиоэлектронной продукции, и кодами Общероссийского классификатора основных фондов утверждаются федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере инвестиционной деятельности;\n\n(Дополнение подпунктом - Федеральный закон от 14.07.2022 № 321-ФЗ)\n\n6) в отношении нематериальных активов в виде исключительных прав на программы для электронных вычислительных машин и базы данных, включенные в единый реестр российских программ для электронных вычислительных машин и баз данных. Положение настоящего подпункта не распространяется на нематериальные активы, срок полезного использования которых определен налогоплательщиком в порядке, установленном абзацем вторым пункта 2 статьи 258 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 321-ФЗ)\n\n3. Налогоплательщики, применяющие нелинейны\n\nй метод начисления амортизации и передавшие (получившие) основные средства, которые являются предметом лизинга, в соответствии с договорами, заключенными участниками лизинговой сделки до введения в действие настоящей главы, выделяют такое имущество в отдельную подгруппу в составе соответствующих амортизационных групп. Амортизация этого имущества начисляется по объектам амортизируемого имущества в соответствии с методом и нормами, которые существовали на момент передачи (получения) имущества, а также с применением специального коэффициента не выше 3.\n\n4. Допускается начисление амортизации по нормам амортизации ниже установленных настоящей главой по решению руководителя организации-налогоплательщика, закрепленному в учетной политике для целей налогообложения в порядке, установленном для выбора применяемого метода начисления амортизации.\n\nПри реализации амортизируемого имущества налогоплательщиками, использующими пониженные нормы амортизации, остаточная стоимость реализуемых объектов амортизируемого имущества определяется исходя из фактически применяемой нормы амортизации.\n\n(Дополнение статьей - Федеральный закон от 22.07.2008 № 158-ФЗ)","article_title":"Статья 259.3. Применение повышающих (понижающих) коэффициентов к норме амортизации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d66114ff7237be33deb979f7d9ae9509ae5226e43358c9ce2313af089b118a7f"},{"code_id":"NK_RF_2","article_number":"260","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 260. Расходы на ремонт основных средств и иного имущества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"14dd40b2fe01e745bc15707592007179ef348e0027234782f116c62a6be55c16"},{"code_id":"NK_RF_2","article_number":"261","version_date":"2000-07-31","article_text":"К расходам на освоение природных ресурсов, в частности, относятся:\n\nрасходы на поиски и оценку месторождений полезных ископаемых (включая аудит запасов), в том числе расходы, связанные со строительством (бурением) и (или) ликвидацией (консервацией) скважин (за исключением признаваемых амортизируемым имуществом), разведку полезных ископаемых и (или) гидрогеологические изыскания, осуществляемые на участке недр в соответствии с полученными в установленном порядке лицензиями или иными разрешениями уполномоченных органов, а также расходы на приобретение необходимой геологической и иной информации у третьих лиц, в том числе в государственных органах; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nрасходы на подготовку территории к ведению горных, строительных и других работ в соответствии с установленными требованиями к безопасности, охране земель, недр и других природных ресурсов и окружающей среды, в том числе на устройство временных подъездных путей и дорог для вывоза добываемых горных пород, полезных ископаемых и отходов, подготовку площадок для строительства соответствующих сооружений, хранения плодородного слоя почвы, предназначенного для последующей рекультивации земель, хранения добываемых горных пород, полезных ископаемых и отходов;\n\nрасходы на возмещение комплексного ущерба, наносимого природным ресурсам налогоплательщиками в процессе строительства и эксплуатации объектов, на переселение и выплату компенсаций за снос жилья в процессе разработки месторождений. К этим расходам также относятся расходы, предусмотренные договорами (соглашениями) с органами государственной власти субъектов Российской Федерации, с органами местного самоуправления и (или) родовыми, семейными общинами коренных малочисленных народов, заключенными такими налогоплательщиками. (В редакции федеральных законов от 06.06.2005 № 58-ФЗ; от 18.12.2006 № 232-ФЗ; от 26.11.2008 № 224-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nРасходы на освоение природных ресурсов, указанные в пункте 1 настоящей статьи, учитываются в порядке, предусмотренном статьей 325 настоящего Кодекса. При осуществлении расходов на освоение природных ресурсов, относящихся к нескольким участкам недр, указанные расходы учитываются отдельно по каждому участку недр в доле, определяемой налогоплательщиком в соответствии с принятой им учетной политикой для целей налогообложения. Указанные расходы признаются для целей налогообложения с 1-го числа месяца, следующего за месяцем, в котором завершены данные работы (этапы работ), и включаются в состав прочих расходов, если иное не установлено пунктом 7 настоящей статьи, в следующем порядке: (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 30.09.2013 № 268-ФЗ)\n\nрасходы, предусмотренные абзацем третьим пункта 1 настоящей статьи, а также расходы на проведение работ по зарезке боковых стволов эксплуатационных скважин включаются в состав расходов равномерно в течение 12 месяцев; (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 23.07.2013 № 213-ФЗ)\n\nрасходы, предусмотренные в абзацах четвертом и пятом пункта 1 настоящей статьи, включаются в состав расходов равномерно в течение двух лет, но не более срока эксплуатации. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nРешение о признании соответствующей скважины непродуктивной принимается налогоплательщиком один раз и в дальнейшем изменению не подлежит. При этом налогоплательщик уведомляет налоговый орган по месту своего учета о решении, принятом в отношении каждой скважины, не позднее установленного настоящей главой предельного срока представления налоговой декларации за отчетный (налоговый) период, в котором он фактически включил расходы (часть таких расходов) по скважине в состав прочих расходов.\n\nАбзац. (Утратил силу - Федеральный закон от 28.12.2016 № 463-ФЗ)\n\nЕсли на участке недр выделено более одного нового морского месторождения углеводородного сырья, налогоплательщик вправе по своему выбору отнести указанные расходы либо любую их часть к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, осуществляемой на любом новом морском месторождении углеводородного сырья, выделенном на этом участке недр.\n\nВ целях настоящего Кодекса новое морское месторождение углеводородного сырья признается выделенным на участке недр с даты первого согласования в установленном порядке технологической схемы разработки соответствующего месторождения. (Дополнение абзацем - Федеральный закон от 28.12.2016 № 463-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 28.12.2016 № 463-ФЗ)\n\nНалогоплательщики, указанные в подпункте 1 пункта 1 статьи 2752 настоящего Кодекса, ежегодно не позднее установленного настоящей главой предельного срока для представления налоговой декларации за налоговый период информируют налоговый орган по месту нахождения (по месту учета в качестве крупнейших налогоплательщиков) по форме, утверждаемой федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов:\n\nо сумме понесенных в истекшем налоговом периоде расходов на освоение природных ресурсов по каждому участку недр, на котором осуществляется (осуществлялась в истекшем налоговом периоде) деятельность, связанная с добычей углеводородного сырья на новом морском месторождении углеводородного сырья;\n\nо новых морских месторождениях углеводородного сырья, выделенных в истекшем налоговом периоде на участках недр, на которых осуществляется (осуществлялась в истекшем налоговом периоде) деятельность, связанная с добычей углеводородного сырья на новом морском месторождении углеводородного сырья;\n\nо каждом принятом в истекшем налоговом периоде решении об отнесении расходов на освоение природных ресурсов к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, по каждому новому месторождению углеводородного сырья (с указанием сумм таких расходов);\n\nо принятых в истекшем налоговом периоде решениях о прекращении работ на указанном участке недр в связи с экономической нецелесообразностью, геологической бесперспективностью или по иным причинам.\n\n(Дополнение пунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n10. К расходам на выполнение работ по освоению природных ресурсов также относятся расходы налогоплательщика, предоставившего заем на финансирование зарубежного геолого-разведочного проекта по договору займа, удовлетворяющему условиям, установленным пунктом 11 настоящей статьи, в размере такого займа (без учета начисленных процентов) в случае прекращения обязательств по этому договору займа в полном объеме без удовлетворения имущественных требований налогоплательщика в связи с окончанием работ на указанном зарубежном геолого-разведочном проекте и признанием такого проекта экономически нецелесообразным и (или) геологически бесперспективным. Указанные расходы учитываются в порядке, установленном пунктом 12 настоящей статьи.\n\nПризнание зарубежного геолого-разведочного проекта успешным или экономически нецелесообразным и (или) геологически бесперспективным осуществляется налогоплательщиком самостоятельно в соответствии с порядком (в том числе предусматривающим критерии успешности, экономической нецелесообразности и (или) геологической бесперспективности), установленным в учетной политике налогоплательщика для целей налогообложения. Указанный порядок разрабатывается налогоплательщиком самостоятельно и подлежит утверждению до даты выдачи им первого займа на финансирование зарубежного геолого-разведочного проекта. Указанный порядок не подлежит изменению в течение десяти последовательных налоговых периодов, считая с налогового периода его утверждения.\n\nДля целей настоящего Кодекса зарубежным геолого-разведочным проектом признается деятельность иностранной организации за пределами территории Российской Федерации и границ континентального шельфа Российской Федерации в границах пространственного объекта с определенными географическими координатами, связанная с геологическим изучением недр, поиском и оценкой месторождений полезных ископаемых, разведкой полезных ископаемых, при одновременном выполнении следующих условий:\n\nтакая иностранная организация в качестве основного вида деятельности участвует в проектах по добыче полезных ископаемых, осуществляемых в соответствии с соглашениями о разделе продукции, концессионными соглашениями, лицензионными договорами либо иными аналогичными договорами на условиях риска;\n\nтакая иностранная организация является стороной одного или нескольких указанных в абзаце четвертом настоящего пункта договоров либо создание такой иностранной организации предусмотрено одним или несколькими указанными договорами, и она осуществляет деятельность по добыче полезных ископаемых на основании и в соответствии с условиями одного или нескольких указанных договоров;\n\nуказанные в абзаце четвертом настоящего пункта договоры однозначно устанавливают географические координаты пространственных объектов, в границах которых осуществляется деятельность, связанная с геологическим изучением недр, поиском и оценкой месторождений полезных ископаемых, разведкой полезных ископаемых.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\n11. Для целей настоящего Кодекса займом на финансирование зарубежного геолого-разведочного проекта признается предоставление имущества по договору займа, одновременно удовлетворяющему следующим условиям:\n\nдоговор займа заключен между российской организацией как заимодавцем и иностранной организацией, непосредственно осуществляющей деятельность по реализации зарубежного геолого-разведочного проекта, как заемщиком, при этом являющейся взаимозависимым лицом указанной российской организации в соответствии с пунктом 2 статьи 1051 настоящего Кодекса на протяжении всего срока действия такого договора займа;\n\nдоговор займа впервые заключен после 1 января 2018 года;\n\nдоговор займа предусматривает условие использования заемщиком полученного по договору займа имущества исключительно на осуществление деятельности по реализации зарубежного геолого-разведочного проекта;\n\nроссийская организация - налогоплательщик приняла решение о признании суммы займа, предоставленного по соответствующему договору займа, в качестве займа на финансирование зарубежного геолого-разведочного проекта для целей налогообложения.\n\nРешение, указанное в абзаце пятом настоящего пункта, российской организацией - налогоплательщиком принимается один раз и не подлежит изменению в дальнейшем. При этом такой налогоплательщик уведомляет налоговый орган по месту своего учета об указанном решении не позднее 1-го числа квартала, следующего за кварталом, в котором заключен соответствующий договор займа. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nДля целей настоящей главы датой выдачи займа на финансирование зарубежного геолого-разведочного проекта признается дата первого перечисления средств заимодавцем заемщику по соответствующему договору займа.\n\nВ случае заключения нового договора займа на финансирование зарубежного геолого-разведочного проекта взамен ранее заключенного (изменения условий ранее заключенного договора займа) датой выдачи займа на финансирование зарубежного геолого-разведочного проекта признается дата возникновения первоначального обязательства, существовавшего между сторонами.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)","article_title":"Статья 261. Расходы на освоение природных ресурсов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86b5fce31fe425ed0e514ec3989a08ed5570db7b6f03811d493f89867e524adf"},{"code_id":"NK_RF_2","article_number":"262","version_date":"2000-07-31","article_text":"1. В целях настоящей главы расходами на научные исследования и (или) опытно-конструкторские разработки признаются расходы, относящиеся к созданию новой или усовершенствованию производимой продукции (товаров, работ, услуг), к созданию новых или усовершенствованию применяемых технологий, методов организации производства и управления.\n\n2. К расходам на научные исследования и (или) опытно-конструкторские разработки относятся:\n\n1) суммы амортизации по основным средствам и нематериальным активам (за исключением зданий и сооружений), используемым для выполнения научных исследований и (или) опытно-конструкторских разработок, начисленные в соответствии с настоящей главой за период, определяемый как количество полных календарных месяцев, в течение которых\n\nуказанные основные средства и нематериальные активы использовались исключительно для выполнения научных исследований и (или) опытно-конструкторских разработок;\n\n2) расходы на оплату труда работников, участвующих в выполнении научных исследований и (или) опытно-конструкторских разработок, предусмотренные пунктами 1 - 3 и 21 части второй статьи 255 настоящего Кодекса, за период выполнения этими работниками научных исследований и (или) опытно-конструкторских разработок, а также суммы страховых взносов, начисленные в установленном настоящим Кодексом порядке на указанные расходы на оплату труда; (В редакции Федерального закона от 18.07.2017 № 166-ФЗ)\n\n3) материальные расходы, предусмотренные подпунктами 1 - 3 и 5 пункта 1 статьи 254 настоящего Кодекса, непосредственно связанные с выполнением научных исследований и (или) опытно-конструкторских разработок;\n\n31) расходы на приобретение исключительных прав на изобретения, полезные модели или промышленные образцы по договору об отчуждении либо прав использования указанных результатов интеллектуальной деятельности по лицензионному договору в случае использования указанных прав исключительно в научных исследованиях и (или) опытно-конструкторских разработках; (Дополнение подпунктом - Федеральный закон от 18.07.2017 № 166-ФЗ)\n\n32) расходы на приобретение исключительных прав на изобретения, полезные модели, промышленные образцы, селекционные достижения, программы для ЭВМ и базы данных, топологии интегральных микросхем по договору об отчуждении исключительных прав, прав использования указанных результатов интеллектуальной деятельности по лицензионному договору в случае использования приобретенных прав исключительно в научных исследованиях и (или) опытно-конструкторских разработках; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n4) другие расходы, непосредственно связанные с выполнением научных исследований и (или) опытно-конструкторских разработок, в сумме не более 75 процентов суммы расходов, указанных в подпункте 2 настоящего пункта; (В редакции Федерального закона от 18.07.2017 № 166-ФЗ)\n\n5) стоимость работ по договорам на выполнение научно-исследовательских работ, договорам на выполнение опытно-конструкторских и технологических работ - для налогоплательщика, выступающего в качестве заказчика научных исследований и (или) опытно-конструкторских разработок;\n\n6) отчисления на формирование фондов поддержки научной, научно-технической и инновационной деятельности, созданных в соответствии с Федеральным законом \"О науке и государственной научно-технической политике\", в сумме не более 1,5 процента доходов от реализации, определяемых в соответствии со статьей 249 настоящего Кодекса.\n\n3. Если работники, указанные в подпункте 2 пункта 2 настоящей статьи, в период выполнения научных исследований и (или) опытно-конструкторских разработок привлекались для осуществления иной деятельности налогоплательщика, не связанной с выполнением научных исследований и (или) опытно-конструкторских разработок, расходами на научные исследования и (или) опытно-конструкторские разработки признаются соответствующие суммы расходов на оплату труда указанных работников пропорционально времени, в течение которого эти работники привлекались для выполнения научных исследований и (или) опытно-конструкторских разработок.\n\n4. Расходы налогоплательщика на научные исследования и (или) опытно-конструкторские разработки, предусмотренные подпунктами 1 - 5 пункта 2 настоящей статьи, признаются для целей налогообложения независимо от результата соответствующих научных исследований и (или) опытно-конструкторских разработок в порядке, предусмотренном настоящей статьей, после завершения этих исследований или разработок (отдельных этапов работ) и (или) подписания сторонами акта сдачи-приемки.\n\nНалогоплательщик вправе включать расходы на научные исследования и (или) опытно-конструкторские разработки в состав прочих расходов в том отчетном (налоговом) периоде, в котором завершены такие исследования или разработки (отдельные этапы работ), если иное не предусмотрено настоящей статьей.\n\nДля целей настоящего пункта к фактическим затратам налогоплательщика на научные исследования и (или) опытно-конструкторские разработки относятся затраты, предусмотренные подпунктами 1 - 5 пункта 2 настоящей статьи.\n\nОтчет представляется в налоговый орган одновременно с налоговой декларацией по итогам налогового периода, в котором завершены научные исследования и (или) опытно-конструкторские разработки (отдельные этапы работ).\n\nОтчет представляется налогоплательщиком в отношении каждого научного исследования и опытно-конструкторской разработки (отдельного этапа работы) и должен соответствовать установленным национальным стандартом общим требованиям к структуре и правилам оформления научных и технических отчетов.\n\nНалогоплательщик в соответствии со статьей 83 настоящего Кодекса, отнесенный к категории крупнейших, представляет отчет в налоговый орган по месту учета в качестве крупнейшего налогоплательщика.\n\nНалоговый орган вправе назначить экспертизу отчета в целях проверки соответствия выполненных научных исследований и (или) опытно-конструкторских разработок перечню научных исследований и (или) опытно-конструкторских разработок, утвержденному Правительством Российской Федерации, в порядке, установленном статьей 95 настоящего Кодекса, если иное не установлено настоящим пунктом. Указанная экспертиза может быть проведена государственными академиями наук, федеральными и национальными исследовательскими университетами, государственными научными центрами, национальными исследовательскими центрами. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалогоплательщик вправе не представлять в налоговый орган отчет в случае, если он размещен в определенной Правительством Российской Федерации государственной информационной системе. При этом при представлении налоговой декларации налогоплательщик обязан представить в налоговый орган сведения, подтверждающие размещение отчета и идентифицирующие отчет в соответствующей государственной информационной системе в формате и по форме, которые утверждены федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если отчет, размещенный в указанной государственной информационной системе, содержит информацию о соответствии выполненных научных исследований и (или) опытно-конструкторских разработок перечню научных исследований и (или) опытно-конструкторских разработок, утвержденному Правительством Российской Федерации, экспертиза такого отчета, предусмотренная абзацем пятым настоящего пункта, не назначается. Порядок подтверждения соответствия выполненных научных исследований и (или) опытно-конструкторских разработок перечню научных исследований и (или) опытно-конструкторских разработок, указанному в настоящем абзаце, и размещения такой информации в указанной государственной информационной системе устанавливается Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае непредставления отчета о выполненных научных исследованиях и (или) опытно-конструкторских разработках (отдельных этапах работ), либо его отсутствия в определенной Правительством Российской Федерации государственной информационной системе, либо отсутствия сведений, подтверждающих размещение отчета и идентифицирующих отчет в соответствующей государственной информационной системе, суммы расходов на выполнение данных исследований и (или) разработок (отдельных этапов работ) учитываются в составе прочих расходов в размере фактических затрат.\n\n(Пункт в редакции Федерального закона от 18.07.2017 № 166-ФЗ)\n\nЕсли указанными результатами интеллектуальной деятельности являются исключительные права на изобретение, полезную модель или промышленный образец, внесенные в соответствующий государственный реестр Российской Федерации при получении патента, то налогоплательщик, являющийся организацией, включенной в реестр малых технологических компаний в соответствии с Федеральным законом от 4 августа 2023 года № 478-ФЗ \"О развитии технологических компаний в Российской Федерации\", при формировании первоначальной стоимости нематериальных активов может воспользоваться правом, предусмотренным пунктом 7 настоящей статьи, вне зависимости от отнесения соответствующих научных исследований и (или) опытно-конструкторских разработок к перечню научных исследований и (или) опытно-конструкторских разработок, утвержденному Правительством Российской Федерации, и от выполнения условий, предусмотренных пунктом 8 настоящей статьи.\n\nИзбранный налогоплательщиком порядок учета указанных расходов отражается в учетной политике для целей налогообложения. При этом суммы расходов на научные исследования и (или) опытно-конструкторские разработки, ранее включенные в состав прочих расходов в соответствии с настоящей главой, восстановлению и включению в первоначальную стоимость нематериального актива не подлежат.\n\nВ случае реализации налогоплательщиком нематериального актива, полученного в результате осуществления расходов на научные исследования и (или) опытно-конструкторские разработки, первоначальная стоимость которых сформирована с применением повышающего коэффициента, с убытком данный убыток не учитывается для целей налогообложения.\n\n(Пункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n(Статья в редакции Федерального закона от 07.06.2011 № 132-ФЗ)","article_title":"Статья 262. Расходы на научные исследования и (или) опытно-конструкторские разработки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa4ec025cea60a62eea4bb880166b262565f189981939027c99bb3a499d10379"},{"code_id":"NK_RF_2","article_number":"263","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\n1) добровольное страхование средств транспорта (водного, воздушного, наземного, трубопроводного), в том числе арендованного, расходы на содержание которого включаются в расходы, связанные с производством и реализацией;\n\n2) добровольное страхование грузов;\n\n3) добровольное страхование основных средств производственного назначения (в том числе арендованных), нематериальных активов, объектов незавершенного капитального строительства (в том числе арендованных);\n\n4) добровольное страхование рисков, связанных с выполнением строительно-монтажных работ;\n\n5) добровольное страхование товарно-материальных запасов;\n\n6) добровольное страхование урожая сельскохозяйственных культур и животных;\n\n7) добровольное страхование иного имущества, используемого налогоплательщиком при осуществлении деятельности, направленной на получение дохода;\n\n8) добровольное страхование ответственности за причинение вреда или ответственности по договору, если такое страхование является условием осуществления налогоплательщиком деятельности в соответствии с международными обязательствами Российской Федерации или общепринятыми международными требованиями; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 26.11.2008 № 224-ФЗ)\n\n9) добровольное страхование риска ответственности за неисполнение либо ненадлежащее исполнение обязательств, связанных с финансированием строительства и (или) со строительством олимпийских объектов, осуществляемое в соответствии со статьей 14 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n91) добровольное страхование имущественных интересов, связанных с обращением банковских карт, выпущенных (эмитированных) налогоплательщиком, в случаях возникновения убытков страхователя в результате проведения третьими лицами операций с использованием поддельных, утерянных или украденных у держателей банковских карт, списания денежных средств на основании подделанных слипов или квитанций электронного терминала, подтверждающих проведение операций держателем банковской карты, проведения иных незаконных операций с банковскими картами; (Дополнение подпунктом - Федеральный закон от 19.07.2009 № 202-ФЗ)\n\n92) добровольное страхование экспортных кредитов и инвестиций от предпринимательских и (или) политических рисков; (Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n93) добровольное страхование, осуществляемое в соответствии с законодательством Российской Федерации, в целях обеспечения финансирования мероприятий, предусмотренных планом предупреждения и ликвидации разливов нефти и нефтепродуктов; (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n10) другие виды добровольного имущественного страхования, если в соответствии с законодательством Российской Федерации такое страхование является условием осуществления налогоплательщиком своей деятельности и (или) если такое страхование направлено на компенсацию расходов (убытков, недополученных доходов), учитываемых для целей налогообложения, которые могут возникнуть в результате страхового случая. (Дополнение подпунктом - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)","article_title":"Статья 263. Расходы на обязательное и добровольное имущественное страхование","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1df3c22af92847cd135d54b92a03b50b85f679226c97cd02a1eeae424331d9e"},{"code_id":"NK_RF_2","article_number":"264","version_date":"2000-07-31","article_text":"1. К прочим расходам, связанным с производством и реализацией, относятся следующие расходы налогоплательщика:\n\n1) суммы налогов и сборов, таможенных пошлин и сборов, страховых взносов на обязательное пенсионное страхование, обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, начисленные в установленном настоящим Кодексом порядке, за исключением перечисленных в статье 270 настоящего Кодекса; (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 03.07.2016 № 243-ФЗ; от 27.11.2017 № 335-ФЗ)\n\n2) расходы на сертификацию продукции и услуг, а также на декларирование соответствия с участием третьей стороны; (В редакции Федерального закона от 30.12.2008 № 313-ФЗ)\n\n21) расходы по стандартизации с учетом положений пунктов 5 и 6 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 21.11.2011 № 330-ФЗ) (В редакции  Федерального закона от 06.03.2022 № 37-ФЗ)\n\n3) суммы комиссионных сборов и иных подобных расходов за выполненные сторонними организациями работы (предоставленные услуги);\n\n4) суммы портовых и аэродромных сборов, расходы на услуги лоцмана и иные аналогичные расходы; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) суммы выплаченных подъемных в пределах норм, установленных в соответствии с законодательством Российской Федерации;\n\n6) расходы на обеспечение пожарной безопасности налогоплательщика в соответствии с законодательством Российской Федерации, расходы на содержание службы газоспасателей, расходы на услуги по охране имущества, обслуживанию охранно-пожарной сигнализации, расходы на приобретение услуг пожарной охраны и иных услуг охранной деятельности, в том числе услуг, оказываемых вневедомственной охраной в соответствии с законодательством Российской Федерации, а также расходы на содержание собственной службы безопасности по выполнению функций экономической защиты банковских и хозяйственных операций и сохранности материальных ценностей (за исключением расходов на экипировку, приобретение оружия и иных специальных средств защиты); (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 06.06.2005 № 58-ФЗ, от 29.05.2019 № 108-ФЗ)\n\n7) расходы на обеспечение нормальных условий труда и мер по технике безопасн\n\nости, предусмотренных законодательством Российской Федерации, расходы на гражданскую оборону в соответствии с законодательством Российской Федерации, а также расходы на лечение профессиональных заболеваний работников, занятых на работах с вредными или тяжелыми условиями труда, расходы, связанные с содержанием помещений и инвентаря здравпунктов, находящихся непосредственно на территории организации. К таким расходам относятся также расходы на дезинфекцию помещений и приобретение приборов, лабораторного оборудования, спецодежды и других средств индивидуальной и коллективной защиты, не указанных в подпункте 3 пункта 1 статьи 254 настоящего Кодекса, для выполнения санитарно-эпидемиологических и гигиенических требований органов государственной власти и органов местного самоуправления, их должностных лиц в связи с распространением новой коронавирусной инфекции; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 22.04.2020 № 121-ФЗ)\n\n8) расходы по набору работников, включая расходы на услуги специализированных организаций по подбору персонала; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n9) расходы на оказание услуг по гарантийному ремонту и обслуживанию, включая отчисления в резерв на предстоящие расходы на гарантийный ремонт и гарантийное обслуживание (с учетом положений статьи 267 настоящего Кодекса);\n\n10) арендные (лизинговые) платежи за арендуемое (принятое в лизинг) имущество (в том числе земельные участки). В случае, если в состав лизинговых платежей включена выкупная стоимость предмета лизинга, подлежащего по окончании срока действия договора лизинга передаче лизингополучателю в собственность на основании договора купли-продажи, лизинговые платежи учитываются в составе расходов за минусом этой выкупной стоимости; (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n101) плата, вносимая концессионером концеденту в период использования (эксплуатации) объекта концессионного соглашения (концессионная плата); (Дополнение подпунктом - Федеральный закон от 30.06.2008 № 108-ФЗ)\n\n11) расходы на содержание служебного транспорта (автомобильного, железнодорожного, воздушного и иных видов транспорта). Расходы на компенсацию за использование для служебных поездок личных легковых автомобилей и мотоциклов в пределах норм, установленных Правительством Российской Федерации; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n111) расходы, связанные с возмещением расходов дистанционного работника, связанных с использованием им для выполнения трудовой функции принадлежащих ему или арендованных им оборудования, программно-технических средств, средств защиты информации и иных средств, в сумме, определяемой коллективным договором, локальным нормативным актом, трудовым договором, дополнительным соглашением к трудовому договору, но не более 35 рублей за каждый день выполнения трудовой функции дистанционно, либо в сумме документально подтвержденных расходов дистанционного работника.\n\nСпособ возмещения расходов каждому дистанционному работнику по локальным нормативным актам либо по документально подтвержденным фактическим расходам закрепляется в локальных нормативных актах или трудовом договоре (дополнительном соглашении). При отсутствии указанных положений в локальных нормативных актах или трудовом договоре (дополнительном соглашении) возмещение расходов осуществляется только по документально подтвержденным фактическим расходам;\n\n(Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n12) расходы на командировки, в частности на:\n\nпроезд работника к месту командировки и обратно к месту постоянной работы;\n\nнаем жилого помещения. По этой статье расходов подлежат возмещению также расходы работника на оплату дополнительных услуг, оказываемых в гостиницах (за исключением расходов на обслуживание в барах и ресторанах, расходов на обслуживание в номере, расходов за пользование рекреационно-оздоровительными объектами);\n\nсуточные или полевое довольствие; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 22.07.2008 № 158-ФЗ)\n\nоформление и выдачу виз, паспортов, ваучеров, приглашений и иных аналогичных документов;\n\nконсульские, аэродромные сборы, сборы за право въезда, прохода, транзита автомобильного и иного транспорта, за пользование морскими каналами, другими подобными сооружениями и иные аналогичные платежи и сборы;\n\nвыплаты работнику в виде безотчетных сумм, право на выплаты которых установлено актом Президента Российской Федерации и (или) актом Правительства Российской Федерации, в целях возмещения его дополнительных расходов, связанных с командированием на территории, нуждающиеся в обеспечении жизнедеятельности населения и восстановлении объектов инфраструктуры, в размерах, определенных локальными нормативными актами работодателя, но не более 700 рублей за каждый день нахождения в такой командировке; (Дополнение абзацем - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n121) расходы на доставку от места жительства (сбора) до места работы и обратно работников, занятых в организациях, которые осуществляют свою деятельность вахтовым способом или в полевых (экспедиционных) условиях. Указанные расходы должны быть предусмотрены коллективными договорами; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n13) расходы на рацион питания экипажей морских, речных и воздушных судов; (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\n14) расходы на юридические и информационные услуги; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n15) расходы на консультационные и иные аналогичные услуги; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n16) плата государственному и (или) частному нотариусу за нотариальное оформление. При этом такие расходы принимаются в пределах тарифов, утвержденных в установленном порядке;\n\n17) расходы на аудиторские услуги; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n18) расходы на управление организацией или отдельными ее подразделениями, а также расходы на приобретение услуг по управлению организацией или ее отдельными подразделениями; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n19) расходы на услуги по предоставлению труда работников (персонала) сторонними организациями для участия в производственной деятельности, в том числе в управлении производством, выполнении иных функций, связанных с производством и (или) реализацией продукции (работ, услуг); (В редакции Федерального закона от 05.05.2014 № 116-ФЗ)\n\n20) расходы на публикацию бухгалтерской (финансовой) отчетности, а также публикацию и иное раскрытие другой информации, если законодательством Российской Федерации на налогоплательщика возложена обязанность осуществлять их публикацию (раскрытие); (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n21) расходы, связанные с представлением форм и сведений государственного статистического наблюдения, если законодательством Российской Федерации на налогоплательщика возложена обязанность представлять эту информацию;\n\n22) представительские расходы, связанные с официальным приемом и обслуживанием представителей других организаций, участвующих в переговорах в целях установления и поддержания сотрудничества, в порядке, предусмотренном пунктом 2 настоящей статьи;\n\n23) расходы на обучение и прохождение независимой оценки квалификации на соответствие требованиям к квалификации работников налогоплательщика в порядке, предусмотренном пунктом 3 настоящей статьи; (В редакции Федерального закона от 18.07.2017 № 169-ФЗ)\n\n24) расходы на канцелярские товары;\n\n25) расходы на почтовые, телефонные, телеграфные и другие подобные услуги, расходы на оплату услуг связи, вычислительных центров и банков, включая расходы на услуги факсимильной и спутниковой связи, электронной почты, а также информационных систем (СВИФТ, информационно-телекоммуникационная сеть \"Интернет\" и иные аналогичные системы); (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\n\n26) расходы, связанные с приобретением права на использование программ для ЭВМ и баз данных, программно-аппаратных комплексов по договорам с правообладателем (по лицензионным и сублицензионным соглашениям), а также расходы на адаптацию и модификацию этих программ для ЭВМ, баз данных. К указанным расходам также относятся расходы на приобретение исключительных прав на программы для ЭВМ стоимостью менее суммы стоимости амортизируемого имущества, определенной пунктом 1 статьи 256 настоящего Кодекса. Указанные расходы, связанные с приобретением права на использование по договорам с правообладателем (по лицензионным и сублицензионным соглашениям) программ для ЭВМ и баз данных, программно-аппаратных комплексов, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных, могут учитываться в размере фактических затрат с применением коэффициента 2; (В редакции  федеральных законов от 07.06.2011 № 132-ФЗ, от 14.07.2022 № 323-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n27) расходы на текущее изучение (исследование) конъюнктуры рынка, сбор информации, непосредственно связанной с производством и реализацией товаров (работ, услуг); (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n28) расходы на рекламу производимых (приобретенных) и (или) реализуемых товаров (работ, услуг), деятельности налогоплательщика, товарного знака и знака обслуживания, включая участие в выставках и ярмарках, с учетом положений пункта 4 настоящей статьи, за исключением расходов, перечисленных в статье 270 настоящего Кодекса; (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 29.11.2024 № 416-ФЗ)\n\n29) взносы, вклады и иные обязательные платежи, уплачиваемые некоммерческим организациям, если уплата таких взносов, вкладов и иных обязательных платежей является условием для осуществления деятельности налогоплательщиками - плательщиками таких взносов, вкладов или иных обязательных платежей;\n\n30) взносы, уплачиваемые международным организациям и организациям, предоставляющим платежные системы и электронные системы передачи информации, если уплата таких взносов является обязательным условием для осуществления деятельности налогоплательщиками - плательщиками таких взносов или является условием предоставления международной организацией услуг, необходимых для ведения налогоплательщиком - плательщиком таких взносов указанной деятельности; (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\n31) расходы, связанные с оплатой услуг сторонним организациям по содержанию и реализации в установленном законодательством Российской Федерации порядке предметов залога и заклада за время нахождения указанных предметов у залогодержателя после передачи залогодателем;\n\n32) расходы на содержание вахтовых и временных поселков, включая все объекты жилищно-коммунального и социально-бытового назначения, подсобных хозяйств и иных аналогичных служб, в организациях, осуществляющих свою деятельность вахтовым способом или работающих в полевых (экспедиционных) условиях. Указанные расходы для целей налогообложения признаются в пределах нормативов на содержание аналогичных объектов и служб, утвержденных органами местного самоуправления по месту деятельности налогоплательщика. Если такие нормативы органами местного самоуправления не утверждены, налогоплательщик вправе применять порядок определения расходов на содержание этих объектов, действующий для аналогичных объектов, находящихся на данной территории и подведомственных указанным органам; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n33) отчисления предприятий и организаций, эксплуатирующих особо радиационно опасные и ядерно опасные производства и объекты, для формирования резервов, предназначенных для обеспечения безопасности указанных производств и объектов на всех стадиях их жизненного цикла и развития в соответствии с законодательством Российской Федерации об использовании атомной энергии и в порядке, установленном Правительством Российской Федерации; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n34) расходы на подготовку и освоение новых производств, цехов и агрегатов;\n\n35) расходы, связанные с внедрением технологий производства, а также методов организации производства и управления; (В редакции Федерального закона от 07.06.2011 № 132-ФЗ)\n\n36) расходы на услуги по ведению бухгалтерского учета, оказываемые сторонними организациями или индивидуальными предпринимателями; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n37) периодические (текущие) платежи за пользование правами на результаты интеллектуальной деятельности и правами на средства индивидуализации (в частности, правами, возникающими из патентов на изобретения, полезные модели, промышленные образцы); (В редакции Федерального закона от 23.11.2015 № 322-ФЗ)\n\n38) расходы, осуществленные налогоплательщиком-организацией, использующей труд инвалидов, в виде средств, направленных на цели, обеспечивающие социальную защиту инвалидов, если от общего числа работников такого налогоплательщика инвалиды составляют не менее 50 процентов и доля расходов на оплату труда инвалидов в расходах на оплату труда составляет не менее 25 процентов. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nЦелями социальной защиты инвалидов в соответствии с законодательством Российской Федерации о социальной защите инвалидов признаются: (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nулучшение условий и охраны труда инвалидов; (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nсоздание и сохранение рабочих мест для инвалидов (закупка и монтаж оборудования, в том числе организация труда рабочих-надомников); (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nобучение (в том числе новым профессиям и приемам труда) и трудоустройство инвалидов; (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nизготовление и ремонт протезных изделий; (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nприобретение и обслуживание технических средств реабилитации (включая приобретение собак-проводников); (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nсанаторно-курортное обслуживание инвалидов, а также лиц, сопровождающих инвалидов I группы и детей-инвалидов; (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nзащита прав и законных интересов инвалидов; (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nмероприятия по интеграции инвалидов в общество (включая культурные, спортивные и иные подобные мероприятия); (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nобеспечение инвалидам равных с другими гражданами возможностей (включая транспортное обслуживание лиц, сопровождающих инвалидов I группы и детей-инвалидов); (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nприобретение и распространение среди инвалидов печатных изданий общественных организаций инвалидов; (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nприобретение и распространение среди инвалидов видеоматериалов с субтитрами или сурдопереводом; (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nвзносы, направленные указанными организациями общественным организациям инвалидов на их содержание. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nПри определении общего числа инвалидов в среднесписочную численность работников не включаются инвалиды, работающие по совместительству, договорам подряда и другим договорам гражданско-правового характера;\n\n39) расходы налогоплательщиков - общественных организаций инвалидов, а также налогоплательщиков-учреждений, единственными собственниками имущества которых являются общественные организации инвалидов, в виде средств, направленных на осуществление деятельности указанных общественных организаций инвалидов и на цели, указанные в подпункте 38 настоящего пункта.\n\nПолучатели средств, предназначенных на осуществление деятельности общественной организации инвалидов и на цели социальной защиты инвалидов, по окончании налогового периода представляют в соответствующие налоговые органы по месту своего учета отчет о целевом использовании полученных средств. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПри нецелевом использовании таких средств с момента, когда их получатель фактически использовал такие средства не по целевому назначению (нарушил условия предоставления этих средств), такие средства признаются доходом у налогоплательщика, получившего эти средства.\n\nРасходы, указанные в подпункте 38 настоящего пункта и настоящем подпункте, не могут быть включены в расходы, связанные с производством и (или) реализацией подакцизных товаров, минерального сырья, других полезных ископаемых и иных товаров по перечню, определяемому Правительством Российской Федерации по согласованию с общероссийскими организациями инвалидов, а также с оказанием посреднических услуг, связанных с реализацией таких товаров, минерального сырья и полезных ископаемых; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n391) расходы налогоплательщиков-организаций, уставный (складочный) капитал которых состоит полностью из вклада религиозных организаций, в виде сумм прибыли, полученной от реализации религиозной литературы и предметов религиозного назначения, при условии перечисления этих сумм на осуществление уставной деятельности указанных религиозных организаций; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n392) расходы на формирование в порядке, установленном статьей 2671 настоящего Кодекса, резервов предстоящих расходов в целях социальной защиты инвалидов, предусмотренных подпунктом 38 настоящего пункта, которые осуществлены налогоплательщиком - общественной организацией инвалидов, а также налогоплательщиком - организацией, использующей труд инвалидов, если от общего числа работников такого налогоплательщика инвалиды составляют не менее 50 процентов и доля расходов на оплату труда инвалидов в расходах на оплату труда составляет не менее 25 процентов; (Дополнение подпунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\n393) расходы на формирование в порядке, установленном статьей 2672 настоящего Кодекса, резервов предстоящих расходов на научные исследования и (или) опытно-конструкторские разработки; (Дополнение подпунктом - Федеральный закон от 07.06.2011 № 132-ФЗ)\n\n40) платежи за регистрацию прав на недвижимое имущество и землю, сделок с указанными объектами, платежи за предоставление информации о зарегистрированных правах, оплата услуг уполномоченных органов и специализированных организаций по оценке имущества, изготовлению документов кадастрового и технического учета (инвентаризации) объектов недвижимости;\n\n41) расходы по договорам гражданско-правового характера (включая договоры подряда), заключенным с индивидуальными предпринимателями, не состоящими в штате организации;\n\n42) расходы налогоплательщиков - сельскохозяйственных организаций на питание работников, занятых на сельскохозяйственных работах;\n\n43) расходы на замену бракованных, утративших товарный вид в процессе перевозки и (или) реализации и недостающих экземпляров периодических печатных изданий в упаковках, но не более 7 процентов стоимости тиража соответствующего номера периодического печатного издания;\n\n44) потери в виде стоимости бракованной, утратившей товарный вид, а также нереализованной в пределах сроков, указанных в настоящем подпункте, (морально устаревшей) продукции средств массовой информации и книжной продукции, списываемой налогоплательщиками, осуществляющими производство и выпуск продукции средств массовой информации и книжной продукции, в пределах не более 30 процентов стоимости тиража соответствующего номера периодического печатного издания или соответствующего тиража книжной продукции, а также расходы на списание и утилизацию бракованной, утратившей товарный вид и нереализованной продукции средств\n\nмассовой информации и книжной продукции. (В редакции Федерального закона от 15.10.2020 № 323-ФЗ)\n\nРасходом признается стоимость продукции средств массовой информации и книжной продукции, не реализованной в течение следующих сроков:\n\nдля периодических печатных изданий - в пределах срока до выхода следующего номера соответствующего периодического печатного издания;\n\nдля книг и иных непериодических печатных изданий - в пределах 24 месяцев после выхода их в свет;\n\nдля календарей (независимо от их вида) - до 1 апреля года, к которому они относятся;\n\n45) взносы по обязательному социальному страхованию от несчастных случаев на производстве и профессиональных заболеваний, производимые в соответствии с законодательством Российской Федерации;\n\n46) отчисления налогоплательщиков, осуществляемые на обеспечение предусмотренной законодательством Российской Федерации надзорной деятельности специализированных учреждений в целях осуществления контроля за соблюдением такими налогоплательщиками соответствующих требований и условий, а также отчисления налогоплательщиков в резервы, создаваемые в соответствии с законодательством Российской Федерации, регулирующим деятельность в области связи;\n\n47) потери от брака; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n48) расходы, связанные с содержанием помещений объектов общественного питания, обслуживающих трудовые коллективы (включая суммы начисленной амортизации, расходы на проведение ремонта помещений, расходы на освещение, отопление, водоснабжение, электроснабжение, а также на топливо для приготовления пищи), если подобные расходы не учитываются в соответствии со статьей 2751 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\n481) расходы работодателя по выплате в соответствии с законодательством Российской Федерации пособия по временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности работника, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\", в части, не покрытой страховыми выплатами, произведенными работникам страховыми организациями, имеющими лицензии, выданные в соответствии с законодательством Российской Федерации на осуществление соответствующего вида деятельности, по договорам с работодателями в пользу работников на случай их временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\"; (Дополнение подпунктом - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции Федерального закона от 28.12.2010 № 395-ФЗ)\n\n482) платежи (взносы) работодателей по договорам добровольного личного страхования, заключенным со страховыми организациями, имеющими лицензии, выданные в соответствии с законодательством Российской Федерации на осуществление соответствующего вида деятельности, в пользу работников на случай их временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\". Указанные платежи (взносы) включаются в состав расходов, если сумма страховой выплаты по таким договорам не превышает определяемого в соответствии с законодательством Российской Федерации размера пособия по временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности работника, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\". При этом совокупная сумма этих платежей (взносов) работодателей и взносов, указанных в абзаце десятом пункта 16 части второй статьи 255 настоящего Кодекса, включается в состав расходов в размере, не превышающем 3 процентов суммы расходов на оплату труда; (Дополнение подпунктом - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции Федерального закона от 28.12.2010 № 395-ФЗ)\n\n483) расходы налогоплательщиков, связанные с безвозмездным предоставлением эфирного времени и (или) печатной площади в соответствии с законодательством Российской Федерации о выборах и референдумах; (Дополнение подпунктом - Федеральный закон от 17.07.2009 № 161-ФЗ)\n\n484) расходы налогоплательщиков, связанные с безвозмездным оказанием услуг по изготовлению и (или) распространению социальной рекламы в соответствии с законодательством Российской Федерации о рекламе. Указанные в настоящем подпункте расходы признаются для целей налогообложения при условии соблюдения требований к социальной рекламе, установленных подпунктом 32 пункта 3 статьи 149 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 18.07.2011 № 235-ФЗ)\n\n485) расходы налогоплательщика, в пользу которого в установленном законодательством Российской Федерации порядке переходит право пользования участком недр, в виде компенсации расходов на освоение природных ресурсов, ранее осуществленных прежним владельцем лицензии на пользование этим участком недр в целях ее приобретения, в сумме фактических затрат налогоплательщика, а также расходы оператора по соглашению о сервисных рисках, предусмотренные соглашением о сервисных рисках, в виде суммы денежных средств, перечисленных пользователю недр, равной размеру понесенных пользователем недр до заключения соглашения о сервисных рисках расходов (их части), связанных с осуществлением пользователем недр деятельности по разработке; (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ) (В редакции  Федерального закона от 17.02.2023 № 22-ФЗ)\n\n486) суммы вступительных и гарантийных взносов негосударственных пенсионных фондов, гарантийных взносов Фонда пенсионного и социального страхования Российской Федерации, уплаченных в фонд гарантирования пенсионных накоплений в соответствии с Федеральным законом от 28 декабря 2013 года № 422-ФЗ \"О гарантировании прав застрахованных лиц в системе обязательного пенсионного страхования Российской Федерации при формировании и инвестировании средств пенсионных накоплений, установлении и осуществлении выплат за счет средств пенсионных накоплений\" либо в фонд гарантирования пенсионных резервов в соответствии со статьей 20 Федерального закона от 28 декабря 2022 года № 555-ФЗ \"О гарантировании прав участников негосударственных пенсионных фондов в рамках деятельности по негосударственному пенсионному обеспечению и формированию долгосрочных сбережений\"; (Дополнение подпунктом - Федеральный закон от 23.06.2014 № 167-ФЗ) (В редакции  федеральных законов от 14.07.2022 № 239-ФЗ, от 23.03.2024 № 58-ФЗ)\n\n487) расходы, связанные с предоставлением (передачей) имущества, имущественных прав (работ, услуг) безвозмездно в случаях, если эта обязанность налогоплательщика установлена законодательством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 382-ФЗ) (В редакции  федеральных законов от 14.07.2022 № 323-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n488) расходы на оплату услуг клиринговых организаций, связанных с выдачей, обслуживанием обращения и погашением клиринговых сертификатов участия; (Дополнение подпунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n489) средства, перечисленные в бюджет субъекта Российской Федерации на основании соглашений (договоров) о безвозмездных целевых взносах, заключенных в соответствии с законодательством Российской Федерации об электроэнергетике; (Дополнение подпунктом - Федеральный закон от 30.09.2017 № 286-ФЗ)\n\n4810) расходы унитарной некоммерческой организации, созданной в целях реализации программы реновации жилищного фонда в городе Москве в соответствии со статьей 77 Закона Российской Федерации от 15 апреля 1993 года № 4802-I \"О статусе столицы Российской Федерации\", на приобретение (создание) объектов недвижимого имущества в рамках реализации программы реновации жилищного фонда в городе Москве, за исключением расходов, произведенных в рамках целевого финансирования и целевых поступлений в соответствии с подпунктом 14 пункта 1 и пунктом 2 статьи 251 настоящего Кодекса. Указанные расходы признаются для целей налогообложения на дату передачи принадлежащих указанной организации на праве собственности объектов недвижимого имущества городу Москве в связи с реализацией программы реновации жилищного фонда в городе Москве; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 352-ФЗ)\n\n4811) расходы налогоплательщиков, связанные с безвозмездным предоставлением эфирного времени и (или) печатной площади в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 14 марта 2020 года № 1-ФКЗ \"О совершенствовании регулирования отдельных вопросов организации и функционирования публичной власти\"; (Дополнение подпунктом - Федеральный закон от 26.03.2020 № 68-ФЗ)\n\n4812) расходы на приобретение медицинских изделий для диагностики (лечения) новой коронавирусной инфекции по перечню, утверждаемому Правительством Российской Федерации, а также на сооружение, изготовление, доставку и доведение указанных медицинских изделий до состояния, в котором они пригодны для использования; (Дополнение подпунктом - Федеральный закон от 22.04.2020 № 121-ФЗ)\n\n4813) расходы, связанные с приобретением газа, поставляемого потребителям, использующим газ для обеспечения постоянного горения Вечного огня и периодического горения Огня памяти на воинских захоронениях и мемориальных сооружениях, находящихся вне воинских захоронений, в соответствии с Законом Российской Федерации от 14 января 1993 года № 4292-I \"Об увековечении памяти погибших при защите Отечества\", и (или) оказанием услуг по его транспортировке по газораспределительным сетям до указанных потребителей при условии, что на основании актов Правительства Российской Федерации передача газа и оказание услуг по его транспортировке выполняются без взимания платы с потребителей; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n4814) расходы эксплуатирующей организации атомных станций Российской Федерации в виде безвозмездно перечисленных денежных средств энергосбытовой организации, уполномоченной Правительством Российской Федерации на осуществление купли-продажи электрической энергии (мощности) для целей поставки электрической энергии (мощности) на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области (далее в целях настоящей главы - единый закупщик), на возмещение недополученных доходов и (или) финансового обеспечения (возмещения) затрат единого закупщика, в размере, определенном на основании актов Правительства Российской Федерации либо федерального органа исполнительной власти, осуществляющего функции по принятию нормативных правовых актов и контролю за соблюдением антимонопольного законодательства, законодательства в сфере государственного регулирования цен (тарифов) на товары (услуги); (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ) (В редакции  Федерального закона от 23.07.2025 № 229-ФЗ)\n\n49) другие расходы, связанные с производством и (или) реализацией. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nК представительским расходам не относятся расходы на организацию развлечений, отдыха, профилактики или лечения заболеваний.\n\nПредставительские расходы в течение отчетного (налогового) периода включаются в состав прочих расходов в размере, не превышающем 4 процента от расходов налогоплательщика на оплату труда за этот отчетный (налоговый) период.\n\n1) обучение по основным профессиональным образовательным программам, основным программам профессионального обучения и дополнительным профессиональным программам осуществляется на основании договора с российской образовательной организацией, научной организацией либо иностранной образовательной организацией, имеющими право на ведение образовательной деятельности, прохождение независимой оценки квалификации на соответствие требованиям к квалификации работника налогоплательщика осуществляется на основании договора оказания услуг по проведению независимой оценки квалификации на соответствие требованиям к квалификации в соответствии с законодательством Российской Федерации;\n\n2) обучение по основным профессиональным образовательным программам, основным программам профессионального обучения и дополнительным профессиональным программам проходят работники налогоплательщика, заключившие с налогоплательщиком трудовые договоры, либо физические лица, заключившие с налогоплательщиком договоры, предусматривающие обязанность физического лица не позднее трех месяцев после окончания указанного обучения, оплаченного налогоплательщиком, заключить с ним трудовой договор и отработать у налогоплательщика не менее одного года, независимую оценку квалификации на соответствие требованиям к квалификации в соответствии с законодательством Российской Федерации проходят работники налогоплательщика, заключившие с ним трудовой договор.\n\nВ случае, если трудовой договор между указанным физическим лицом и налогоплательщиком был прекращен до истечения одного года с даты начала его действия, за исключением случаев прекращения трудового договора по обстоятельствам, не зависящим от воли сторон (статья 83 Трудового кодекса Российской Федерации), налогоплательщик обязан включить во внереализационные доходы отчетного (налогового) периода, в котором прекратил действие данный трудовой договор, сумму платы за указанное обучение соответствующего физического лица, учтенную ранее при исчислении налоговой базы. В случае, если трудовой договор физического лица с налогоплательщиком не был заключен по истечении трех месяцев после окончания обучения, оплаченного налогоплательщиком, указанные расходы также включаются во внереализационные доходы отчетного (налогового) периода, в котором истек данный срок заключения трудового договора.\n\nНалогоплательщик обязан хранить документы, подтверждающие расходы на обучение, в течение всего срока действия соответствующего договора обучения и одного года работы физического лица, обучение которого было оплачено налогоплательщиком в соответствии с заключенным с налогоплательщиком трудовым договором, но не менее четырех лет.\n\nНалогоплательщик обязан хранить документы, подтверждающие расходы на прохождение работником независимой оценки квалификации на соответствие требованиям к квалификации, в течение всего срока действия договора оказания услуг по проведению независимой оценки квалификации на соответствие требованиям к квалификации и одного года работы физического лица, прохождение независимой оценки квалификации на соответствие требованиям к квалификации которого было оплачено налогоплательщиком в соответствии с заключенным с налогоплательщиком трудовым договором, но не менее четырех лет.\n\nК расходам на обучение также относятся расходы налогоплательщика, осуществленные на основании договоров о сетевой форме реализации образовательных программ, заключенных в соответствии с Федеральным законом от 29 декабря 2012 года № 273-ФЗ \"Об образовании в Российской Федерации\" с образовательными организациями, в частности расходы на содержание помещений и оборудования налогоплательщика, используемых для обучения, оплату труда, стоимость имущества, переданного для обеспечения процесса обучения, и иные расходы в рамках указанных договоров. Такие расходы признаются в том налоговом периоде, в котором они были понесены, при условии, что в данном налоговом периоде хотя бы один из обучающихся, окончивших обучение в указанных образовательных организациях, заключил трудовой договор с налогоплательщиком на срок не менее одного года.\n\nНе признаются расходами на обучение работников налогоплательщика либо физических лиц, предусмотренными настоящим пунктом, расходы, связанные с организацией развлечения, отдыха или лечения.\n\n(Пункт в редакции Федерального закона от 18.07.2017 № 169-ФЗ)\n\nрасходы на рекламные мероприятия через средства массовой информации (в том числе объявления в печати, передача по радио и телевидению), информационно-телекоммуникационные сети, при кино- и видеообслуживании; (В редакции Федерального закона от 23.07.2013 № 215-ФЗ)\n\nрасходы на световую и иную наружную рекламу, включая изготовление рекламных стендов и рекламных щитов;\n\nрасходы на участие в выставках, ярмарках, экспозициях, на оформление витрин, выставок-продаж, комнат образцов и демонстрационных залов, изготовление рекламных брошюр и каталогов, содержащих информацию о реализуемых товарах, выполняемых работах, оказываемых услугах, товарных знаках и знаках обслуживания, и (или) о самой организации, на уценку товаров, полностью или частично потерявших свои первоначальные качества при экспонировании. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\nРасходы налогоплательщика на приобретение (изготовление) призов, вручаемых победителям розыгрышей таких призов во время проведения массовых рекламных кампаний, а также расходы на иные виды рекламы, не указанные в абзацах втором - четвертом настоящего пункта, осуществленные им в течение отчетного (налогового) периода, для целей налогообложения признаются в размере, не превышающем 1 процента выручки от реализации, определяемой в соответствии со статьей 249 настоящего Кодекса. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n1) расходы на проведение работ по разработке национальных стандартов, включенных в программу национальной стандартизации, утвержденную федеральным органом исполнительной власти в сфере стандартизации, а также расходы на проведение работ по разработке региональных стандартов при условии утверждения таких стандартов, введения их в действие на территории Российс\n\nкой Федерации в качестве национальных стандартов федеральным органом исполнительной власти в сфере стандартизации и их регистрации в Федеральном информационном фонде стандартов в соответствии с Федеральным законом от 29 июня 2015 года № 162-ФЗ \"О стандартизации в Российской Федерации\";\n\n2) расходы на проведение работ по разработке документов по стандартизации оборонной продукции, включенных в годовой план стандартизации военной продукции, утвержденный федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики, нормативно-правовому регулированию в области обороны, в порядке, установленном законодательством Российской Федерации о стандартизации, при условии утверждения таких документов федеральным органом исполнительной власти в сфере стандартизации;\n\n3) расходы на проведение работ по разработке документов по стандартизации оборонной продукции, включенных в годовой план стандартизации, утвержденный Государственной корпорацией по атомной энергии \"Росатом\" в порядке, установленном нормативными правовыми актами Российской Федерации, при условии утверждения таких документов Государственной корпорацией по атомной энергии \"Росатом\", а также включения сведений о таких документах в сводный перечень документов по стандартизации оборонной продукции в соответствии с указанным порядком;\n\n4) расходы на проведение работ по разработке документов по стандартизации, включенных в программы стандартизации, предусматривающие разработку, пересмотр, изменение документов по стандартизации оборонной продукции в отношении отдельных групп продукции или иных объектов стандартизации на определенный срок (среднесрочный и долгосрочный периоды планирования), утвержденные государственными заказчиками государственного оборонного заказа, при условии утверждения таких документов федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики, нормативно-правовому регулированию в области обороны, федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере стандартизации, федеральным органом исполнительной власти в сфере стандартизации, Государственной корпорацией по атомной энергии \"Росатом\" и Государственной корпорацией по космической деятельности \"Роскосмос\" в пределах полномочий, установленных нормативными правовыми актами Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 21.11.2011 № 330-ФЗ) (В редакции  Федерального закона от 06.03.2022 № 37-ФЗ)","article_title":"Статья 264. Прочие расходы, связанные с производством и (или) реализацией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b36629b4b8b28de457e7462f3389ce6d66b75388681654d9f5581f204ee4c8b8"},{"code_id":"NK_RF_2","article_number":"264.1","version_date":"2000-07-31","article_text":"1. В целях настоящей главы расходами на приобретение права на земельные участки признаются расходы на приобретение земельных участков из земель, находящихся в государственной или муниципальной собственности, на которых находятся здания, строения, сооружения или которые приобретаются для целей капитального строительства объектов основных средств на этих участках.\n\n2. Расходами на приобретение права на земельные участки также признаются расходы на приобретение права на заключение договора аренды земельных участков при условии заключения указанного договора аренды.\n\n3. Расходы на приобретение права на земельные участки, указанные в пункте 1 настоящей статьи, включаются в состав прочих расходов, связанных с производством и (или) реализацией, в следующем порядке:\n\n1) по выбору налогоплательщика сумма расходов на приобретение права на земельные участки признается расходами отчетного (налогового) периода равномерно в течение срока, который определяется налогоплательщиком самостоятельно и не должен быть менее пяти лет, либо признается расходами отчетного (налогового) периода в размере, не превышающем 30 процентов исчисленной в соответствии со статьей 274 настоящего Кодекса налоговой базы предыдущего налогового периода, до полного признания всей суммы указанных расходов, если иное не предусмотрено настоящей статьей.\n\nПорядок признания расходов на приобретение права на земельные участки применяется в соответствии с принятой организацией учетной политикой для целей налогообложения.\n\nДля расчета предельных размеров расходов, исчисляемых в соответствии с настоящей статьей, налоговая база предыдущего налогового периода определяется без учета суммы расходов указанного налогового периода на приобретение права на земельные участки.\n\nЕсли земельные участки приобретаются на условиях рассрочки, срок которой превышает указанный в абзаце первом настоящего подпункта срок, то такие расходы признаются расходами отчетного (налогового) периода равномерно в течение срока, установленного договором;\n\n2) сумма расходов на приобретение права на земельные участки подлежит включению в состав прочих расходов с момента документально подтвержденного факта подачи документов на государственную регистрацию указанного права.\n\nВ целях настоящей статьи под документальным подтверждением факта подачи документов на государственную регистрацию прав понимается расписка в получении органом, осуществляющим государственную регистрацию прав на недвижимое имущество и сделок с ним, документов на государственную регистрацию указанных прав.\n\n4. Правила, установленные пунктом 3 настоящей статьи, применяются также в отношении порядка признания расходов, указанных в пункте 2 настоящей статьи, если иное не предусмотрено настоящим пунктом.\n\nЕсли договор аренды земельного участка в соответствии с законодательством Российской Федерации не подлежит государственной регистрации, то расходы на приобретение права на заключение такого договора аренды признаются расходами равномерно в течение срока действия этого договора аренды.\n\n5. При реализации земельного участка и зданий (строений, сооружений), находящихся на нем, прибыль (убыток) определяется в следующем порядке:\n\n1) прибыль (убыток) от реализации зданий (строений, сооружений) принимается для целей налогообложения в порядке, установленном настоящей главой;\n\n2) прибыль (убыток) от реализации права на земельный участок определяется как разница между ценой реализации и не возмещенными налогоплательщику затратами, связанными с приобретением права на этот участок. Под невозмещенными затратами для целей настоящей статьи понимается разница между затратами налогоплательщика на приобретение права на земельный участок и суммой расходов, учтенных для целей налогообложения до момента реализации указанного права в порядке, установленном настоящей статьей;\n\n3) убыток от реализации права на земельный участок включается в состав прочих расходов налогоплательщика равными долями в течение срока, установленного в соответствии с подпунктом 1 пункта 3 настоящей статьи, и фактического срока владения этим участком.\n\n(Дополнение статьей - Федеральный закон от 30.12.2006 № 268-ФЗ)","article_title":"Статья 264.1. Расходы на приобретение права на земельные участки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2da00b075a69e8b55567e3a4b6250c77e3246a089223816e44efbf9d87a1ff14"},{"code_id":"NK_RF_2","article_number":"265","version_date":"2000-07-31","article_text":"1. В состав внереализационных расходов, не связанных с производством и реализацией, включаются обоснованные затраты на осуществление деятельности, непосредственно не связанной с производством и (или) реализацией. К таким расходам относятся, в частности:\n\n1) расходы на содержание переданного по договору аренды (лизинга) имущества (включая амортизацию по этому имуществу).\n\nДля организаций, предоставляющих на систематической основе за плату во временное пользование и (или) временное владение и пользование свое имущество и (или) исключительные права, возникающие из патентов на изобретения, полезные модели, промышленные образцы, и (или) исключительные права на другие виды интеллектуальной собственности, расходами, связанными с производством и реализацией, считаются расходы, связанные с этой деятельностью; (В редакции Федерального закона от 23.11.2015 № 322-ФЗ)\n\n2) расходы в виде процентов по долговым обязательствам любого вида, в том числе процентов, начисленных по ценным бумагам и иным обязательствам, выпущенным (эмитированным) налогоплательщиком с учетом особенностей, предусмотренных статьей 269 настоящего Кодекса (для банков особенности определения расходов в виде процентов определяются в соответствии со статьями 269 и 291 настоящего Кодекса), а также процентов, уплачиваемых в связи с реструктуризацией задолженности по налогам и сборам в соответствии с порядком, установленным Правительством Российской Федерации. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\nПри этом расходом признаются проценты по долговым обязательствам любого вида вне зависимости от характера предоставленного кредита или займа (текущего и (или) инвестиционного). Расходом признается только сумма процентов, начисленных за фактическое время пользования заемными средствами (фактическое время нахождения указанных ценных бумаг у третьих лиц) и первоначальной доходности, установленной эмитентом (заимодавцем) в условиях эмиссии (выпуска, договора), но не выше фактической; (В редакции федеральных законов от 06.06.2005 № 58-ФЗ; от 24.07.2007 № 216-ФЗ)\n\n3) расходы на организацию выпуска собственных ценных бумаг, в частности на подготовку проспекта эмиссии ценных бумаг, изготовление или приобретение бланков, регистрацию ценных бумаг, расходы, связанные с обслуживанием собственных ценных бумаг, в том числе расходы на услуги реестродержателя, депозитария, платежного агента по процентным (дивидендным) платежам, расходы, связанные с ведением реестра, предоставлением информации акционерам в соответствии с законодательством Российской Федерации, и другие аналогичные расходы; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n31) расходы по погашению эмитентом собственных эмиссионных долговых ценных бумаг, обращающихся на организованном рынке ценных бумаг, в сумме разницы между стоимостью их погашения и их номинальной стоимостью; (Дополнение подпунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n4) расходы, связанные с обслуживанием приобретенных налогоплательщиком ценных бумаг, в том числе оплата услуг реестродержателя, депозитария, расходы, связанные с получением информации в соответствии с законодательством Российской Федерации, и другие аналогичные расходы; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) расходы в виде отрицательной курсовой разницы, за исключением отрицательной курсовой разницы, возникающей от переоценки выданных (полученных) авансов.\n\nОтрицательной курсовой разницей в целях настоящей главы признается курсовая разница, возникающая при уценке имущества в виде валютных ценностей (за исключением ценных бумаг, номинированных в иностранной валюте) и требований, стоимость которых выражена в иностранной валюте, или при дооценке обязательств, стоимость которых выражена в иностранной валюте.\n\nПоложения настоящего подпункта применяются в случае, если указанная уценка или дооценка производится в связи с изменением официального курса иностранной валюты к рублю Российской Федерации, установленного Центральным банком Российской Федерации, либо с изменением курса иностранной валюты (условных денежных единиц) к рублю Российской Федерации, установленного законом или соглашением сторон, если выраженная в этой иностранной валюте (условных денежных единицах) стоимость требований (обязательств), подлежащих оплате в рублях, определяется по курсу, установленному законом или соглашением сторон соответственно;\n\n(Подпункт в редакции Федерального закона от 20.04.2014 № 81-ФЗ)\n\n51) (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (Утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\n6) расходы в виде отрицательной (положительной) разницы, образующейся вследствие отклонения курса продажи (покупки) иностранной валюты от официального курса Центрального банка Российской Федерации, установленного на дату перехода права собственности на иностранную валюту (особенности определения расходов банков от этих операций устанавливаются статьей 291 настоящего Кодекса); (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n7) расходы налогоплательщика, применяющего метод начисления, на формирование резервов по сомнительным долгам (в порядке, установленном статьей 266 настоящего Кодекса); (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n71) расходы организации - владельца лицензии на пользование участком недр, в границах которого расположено новое морское месторождение углеводородного сырья, на формирование резервов предстоящих расходов, связанных с завершением деятельности по добыче углеводородного сырья на таком новом морском месторождении углеводородного сырья (в порядке, установленном статьей 2674 настоящего Кодекса); (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n8) расходы на ликвидацию выводимых из эксплуатации основных средств, на списание нематериальных активов, включая суммы недоначисленной в соответствии с установленным сроком полезного использования амортизации, а также расходы на ликвидацию объектов незавершенного строительства и иного имущества, монтаж которого не завершен (расходы на демонтаж, разборку, вывоз разобранного имущества), охрану недр и другие аналогичные работы, если иное не установлено статьей 2674 настоящего Кодекса; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 26.11.2008 № 224-ФЗ; от 30.09.2013 № 268-ФЗ)\n\nРасходы в виде сумм недоначисленной в соответствии с установленным сроком полезного использования амортизации включаются в состав внереализационных расходов, не связанных с производством и реализацией, только по объектам амортизируемого имущества, по которым амортизация начисляется линейным методом. Объекты амортизируемого имущества, по которым амортизация начисляется нелинейным методом, выводятся из эксплуатации в порядке, установленном пунктом 13 статьи 2592 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n9) расходы, связанные с консервацией и расконсервацией производственных мощностей и объектов, в том числе затраты на содержание законсервированных производственных мощностей и объектов; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n10) судебные расходы и арбитражные сборы; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n11) затраты на аннулированные производственные заказы, а также затраты на производство, не давшее продукции. Признание расходов по аннулированным заказам, а также затрат на производство, не давшее продукции, осуществляется на основании актов налогоплательщика, утвержденных руководителем или уполномоченным им лицом, в размере прямых затрат, определяемых в соответствии со статьями 318 и 319 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n12) расходы по операциям с тарой, если иное не предусмотрено положениями пункта 3 статьи 254 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n13) расходы в виде признанных должником или подлежащих уплате должником на основании решения суда, вступившего в законную силу, штрафов, пеней и (или) иных санкций за нарушение договорных или долговых обязательств, а также расходы на возмещение причиненного ущерба; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n14) расходы в виде сумм налогов, относящихся к поставленным материально-производственным запасам, работам, услугам, если кредиторская задолженность (обязательства перед кредиторами) по такой поставке списана в отчетном периоде в соответствии с пунктом 18 статьи 250 настоящего Кодекса; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\n15) расходы на услуги банков, включая услуги, связанные с продажей иностранной валюты при взыскании налога, сбора, пеней и штрафа в порядке, предусмотренном статьей 46 настоящего Кодекса, с установкой и эксплуатацией электронных систем документооборота между банком и клиентами, в том числе систем \"клиент-банк\"; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n16) расходы на проведение собраний акционеров (участников, пайщиков), в частности расходы, связанные с арендой помещений, подготовкой и рассылкой необходимой для проведения собраний информации, и иные расходы, непосредственно связанные с проведением собрания; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\n17) расходы на проведение работ по мобилизационной подготовке, включая затраты на содержание мощностей и объектов, необходимых для выполнения мобилизационного плана, за исключением расходов на приобретение, создание, реконструкцию, модернизацию, техническое перевооружение амортизируемого имущества, относящегося к мобилизационным мощностям; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 29.11.2012 № 206-ФЗ)\n\n18) расходы по операциям с производными финансовыми инструментами с учетом положений статей 301 - 305 настоящего Кодекса; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 03.07.2016 № 242-ФЗ)\n\n19) расходы в виде отчислений организаций, входящих в структуру ДОСААФ России, для аккумулирования и перераспределения средств организациям, входящим в структуру ДОСААФ России, в целях обеспечения подготовки в соответствии с законодательством Российской Федерации граждан по военно-учетным специальностям, военно-патриотического воспитания молодежи, развития авиационных, технических и военно-прикладных видов спорта; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ; от 28.12.2010 № 397-ФЗ)\n\n191) расходы в виде премии (скидки), выплаченной (предоставленной) продавцом покупателю вследствие выполнения определенных условий договора, в частности объема покупок; (Дополнение подпунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\n192) расходы в виде целевых отчислений от лотерей, осуществляемые в размере и порядке, которые предусмотрены законодательством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\n193) расходы на формирование резервов предстоящих расходов налогоплательщиком - некоммерческой организацией, зарегистрированной в соответствии с Федеральным законом \"О некоммерческих организациях\", определенные в размере и порядке, которые установлены статьей 2673 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 18.07.2011 № 235-ФЗ)\n\n194) расходы на создание объектов социальной, инженерной, коммунальной и транспортной инфраструктур, безвозмездно передаваемых в государственную или муниципальную собственность, за исключением расходов международных холдинговых компаний на создание объектов, переданных в соответствии с требованиями пункта 4 статьи 28410 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 210-ФЗ) (В редакции  федеральных законов от 14.07.2022 № 323-ФЗ, от 19.12.2023 № 595-ФЗ)\n\n195) расходы в виде стоимости имущества (включая денежные средства), предназначенного для использования в целях предупреждения и предотвращения распространения, а также диагностики и лечения новой коронавирусной инфекции, безвозмездно переданного медицинским организациям, являющимся некоммерческими организациями, органам государственной власти и управления и (или) органам местного самоуправления, государственным и муниципальным учреждениям, государственным и муниципальным унитарным предприятиям; (Дополнение подпунктом - Федеральный закон от 08.06.2020 № 172-ФЗ)\n\n196) расходы в виде стоимости имущества (включая денежные средства), безвозмездно переданного следующим некоммерческим организациям:\n\nнекоммерческим организациям, включенным в реестр социально ориентированных некоммерческих организаций. Порядок ведения реестра социально ориенти\n\nрованных некоммерческих организаций, федеральный орган исполнительной власти, уполномоченный на ведение указанного реестра, критерии включения некоммерческих организаций в указанный реестр устанавливаются Правительством Российской Федерации; (В редакции Федерального закона от 30.04.2021 № 104-ФЗ)\n\nцентрализованным религиозным организациям, религиозным организациям, входящим в структуру централизованных религиозных организаций, социально ориентированным некоммерческим организациям, учредителями которых являются централизованные религиозные организации или религиозные организации, входящие в структуру централизованных религиозных организаций;\n\nабзац. (Утратил силу - Федеральный закон от 30.04.2021 № 104-ФЗ)\n\nРасходы, предусмотренные настоящим подпунктом, для целей налогообложения признаются в размере, не превышающем 1 процента выручки от реализации, определяемой в соответствии со статьей 249 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 08.06.2020 № 172-ФЗ)\n\n197) расходы в виде стоимости безвозмездно переданного в государственную и (или) муниципальную собственность (возвращенного в рамках концессионного соглашения) имущества (имущественных прав), финансирование которых осуществлено за счет средств субсидий, указанных в абзаце третьем пункта 41 статьи 271 настоящего Кодекса, в размере, не превышающем величину доходов, признаваемых в порядке, установленном абзацем третьим пункта 41 статьи 271 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 335-ФЗ) (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n198) перечисленные бюджетными учреждениями в федеральный бюджет денежные средства, полученные от предоставления права использования исключительных прав на изобретения и (или) секреты производства (ноу-хау) в отношении вакцины для профилактики новой коронавирусной инфекции; (Дополнение подпунктом - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n199) денежные средства, причитающиеся к выплате налогоплательщиком, являющимся лицом, выпустившим цифровые финансовые активы и (или) цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права (за исключением выплат, связанных с их выкупом), в соответствии с обязательствами, предусмотренными решением о выпуске этих цифровых финансовых активов и (или) цифровых прав, если иное не предусмотрено статьей 270 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n1910) расходы в виде суммы, равной значению НВЭТАН, рассчитанному в соответствующем месяце в порядке, определенном пунктом 37 статьи 3432 настоящего Кодекса.\n\nПри этом налогоплательщик обязан вести учет общей суммы расходов, учтенных на основании данного подпункта, определяемой нарастающим итогом;\n\n(Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n1910-1) расходы в виде суммы, равной значению показателя НВТИ, рассчитанному в соответствующем месяце в порядке, определенном пунктом 39 статьи 3432 настоящего Кодекса.\n\nПри этом налогоплательщик обязан вести учет общей суммы расходов, учтенных на основании данного подпункта, определяемой нарастающим итогом;\n\n(Дополнение подпунктом - Федеральный закон от 23.02.2023 № 36-ФЗ)\n\n1911) расходы в виде сумм, признанных внереализационными доходами в соответствии с пунктом 29 части второй статьи 250 настоящего Кодекса, - в случае утраты организацией статуса налогоплательщика - участника соглашения о защите и поощрении капиталовложений по основанию, предусмотренному подпунктом 2 пункта 3 статьи 2517 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\n1912) расходы в виде безвозмездно переданных денежных средств и (или) иного имущества, указанных в пункте 93 статьи 217 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n1912-1) расходы в виде стоимости имущества (за исключением денежных средств), работ, услуг, безвозмездно переданных являющимся казенными учреждениями воинским частям и организациям Вооруженных Сил Российской Федерации, войск национальной гвардии Российской Федерации, органов федеральной службы безопасности, при условии, что данные имущество, работы, услуги переданы в целях их использования указанными воинскими частями и организациями в ходе специальной военной операции. Факт получения указанными воинской частью или организацией данного имущества (результатов выполненных работ, оказанных услуг) и цели его (их) использования подтверждаются документом, подписанным командиром (руководителем) указанных воинской части или организации либо уполномоченным им лицом; (Дополнение подпунктом - Федеральный закон от 23.07.2025 № 227-ФЗ)\n\n1913) расходы в виде стоимости доходной части добытых полезных ископаемых либо в виде денежных средств или иного имущества, полученных от реализации добытых полезных ископаемых и относящихся к их доходной части, подлежащих передаче при их распределении по соглашению о сервисных рисках либо по соглашению об управлении финансированием; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n1914) расходы, осуществленные при заключении соглашения о сервисных рисках либо соглашения об управлении финансированием, если они являются условием заключения указанных соглашений; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n20) другие обоснованные расходы. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n2. В целях настоящей главы к внереализационным расходам приравниваются убытки, полученные налогоплательщиком в отчетном (налоговом) периоде, в частности:\n\n1) в виде убытков прошлых налоговых периодов, выявленных в текущем отчетном (налоговом) периоде;\n\n2) суммы безнадежных долгов, а в случае, если налогоплательщик принял решение о создании резерва по сомнительным долгам, суммы безнадежных долгов, не покрытые за счет средств резерва; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n3) потери от простоев по внутрипроизводственным причинам; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n4) не компенсируемые виновниками потери от простоев по внешним причинам; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) расходы в виде недостачи материальных ценностей в производстве и на складах, на предприятиях торговли в случае отсутствия виновных лиц, а также убытки от хищений, виновники которых не установлены. В данных случаях факт отсутствия виновных лиц должен быть документально подтвержден уполномоченным органом государственной власти; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n6) потери от стихийных бедствий, пожаров, аварий и других чрезвычайных ситуаций, включая затраты, связанные с предотвращением или ликвидацией последствий стихийных бедствий или чрезвычайных ситуаций; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n7) убытки по сделке уступки права требования в порядке, установленном статьей 279 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n8) убыток, возникающий у налогоплательщика - участника (пайщика) организации при ее ликвидации (в том числе в результате применения процедуры банкротства), выходе (выбытии) из организации и определяемый на дату ликвидации организации, выхода (выбытия) из организации как отрицательная разница между доходами в виде рыночной цены получаемого указанным участником (пайщиком) имущества (имущественных прав) и фактически оплаченной (вне зависимости от формы оплаты) налогоплательщиком - участником (пайщиком) этой организации стоимости доли (пая). (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)","article_title":"Статья 265. Внереализационные расходы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f50951f735562e1ed13380981017aa2bacc398b9a4d34b4620f4d29766757df"},{"code_id":"NK_RF_2","article_number":"266","version_date":"2000-07-31","article_text":"Для налогоплательщиков-банков сомнительным долгом также признается задолженность по уплате процентов, образовавшаяся после 1 января 2015 года, по долговым обязательствам любого вида (за исключением задолженности, образовавшейся по долговым ценным бумагам, указанным в подпункте 146 пункта 4 статьи 271 настоящего Кодекса) в случае, если эта задолженность не погашена в сроки, установленные договором, вне зависимости от наличия залога, поручительства, банковской гарантии. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nДля налогоплательщиков - страховых организаций, определяющих доходы и расходы по методу начисления по договорам страхования, сострахования, перестрахования, по которым сформированы страховые резервы, резерв сомнительных долгов по дебиторской задолженности, связанной с уплатой страховых премий (взносов), не формируется. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nДля налогоплательщиков - кредитных потребительских кооперативов и микрофинансовых организаций не признается сомнительной задолженность, по которой в соответствии со статьей 2973 настоящего Кодекса предусмотрено создание резервов на возможные потери по займам. (Дополнение абзацем - Федеральный закон от 02.11.2013 № 301-ФЗ)\n\nНе признается сомнительным долгом задолженность, возникшая по операциям, по которым датой признания дохода в соответствии с положениями статьи 271 настоящего Кодекса является дата поступления денежных средств или погашения задолженности иным способом. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nБезнадежными долгами (долгами, нереальными ко взысканию) также признаются долги, невозможность взыскания которых подтверждена постановлением судебного пристава-исполнителя об окончании исполнительного производства, вынесенным в порядке, установленном Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", в случае возврата взыскателю исполнительного документа по следующим основаниям: (Дополнение абзацем - Федеральный закон от 29.11.2012 № 206-ФЗ)\n\nневозможно установить место нахождения должника, его имущества либо получить сведения о наличии принадлежащих ему денежных средств и иных ценностей, находящихся на счетах, во вкладах или на хранении в банках или иных кредитных организациях; (Дополнение абзацем - Федеральный закон от 29.11.2012 № 206-ФЗ)\n\nу должника отсутствует имущество, на которое может быть обращено взыскание, и все принятые судебным приставом-исполнителем допустимые законом меры по отысканию его имущества оказались безрезультатными. (Дополнение абзацем - Федеральный закон от 29.11.2012 № 206-ФЗ)\n\nБезнадежными долгами (долгами, нереальными ко взысканию) также признаются долги гражданина, признанного банкротом, по которым он освобождается от дальнейшего исполнения требований кредиторов (считаются погашенными) в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\". (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nБезнадежными долгами (долгами, нереальными ко взысканию) также признаются суммы прекращенных перед налогоплательщиком - уполномоченным банком денежных обязательств, перечень которых определен актом Правительства Российской Федерации, принятым на основании части 3 статьи 5 Федерального закона от 29 июля 2018 года № 263-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации\". (Дополнение абзацем - Федеральный закон от 06.06.2019 № 125-ФЗ)\n\nБезнадежными долгами (долгами, нереальными ко взысканию) также признаются суммы прекращенных перед налогоплательщиком - кредитной организацией денежных обязательств по уплате задолженности по кредитному договору при выполнении следующих условий: (Дополнение абзацем - Федеральный закон от 13.07.2020 № 204-ФЗ)\n\nкредит предоставлен юридическим лицам или индивидуальным предпринимателям в период с 1 января по 31 декабря 2020 года на возобновление деятельности или на неотложные нужды для поддержки и сохранения занятости; (Дополнение абзацем - Федеральный закон от 13.07.2020 № 204-ФЗ)\n\nв отношении кредитного договора кредитной организации в 2020 и (или) в 2021 году предоставляется (предоставлялась) субсидия по процентной ставке в порядке, установленном Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 13.07.2020 № 204-ФЗ)\n\nБезнадежными долгами (долгами, нереальными ко взысканию) также признаются суммы прекращенных перед налогоплательщиком - кредитной организацией денежных обязательств по уплате задолженности по кредитному договору при выполнении следующих условий: (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nкредит предоставлен юридическим лицам или индивидуальным предпринимателям в период с 1 января по 31 декабря 2021 года на восстановление предпринимательской деятельности; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nв отношении кредитного договора кредитной организации в 2021 и (или) в 2022 году предоставляется (предоставлялась) субсидия по процентной ставке в порядке, установленном Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nБезнадежным долгом (долгом, нереальным ко взысканию) также признается величина, равная 30 процентам от суммы обязательств перед налогоплательщиком - кредитной организацией, которые считаются исполненными в соответствии с частью 14 статьи 71 Федерального закона от 3 апреля 2020 года № 106-ФЗ \"О внесении изменений в Федеральный закон \"О Центральном банке Российской Федерации (Банке России)\" и отдельные законодательные акты Российской Федерации в части особенностей изменения условий кредитного договора, договора займа\". (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nБезнадежными долгами (долгами, нереальными ко взысканию) также признаются суммы денежных обязательств, возникших из соглашения о финансировании участия в кредите (займе) перед налогоплательщиком - внешним участником, которые прекращены по основаниям, указанным в части 2 статьи 101 Федерального закона от 31 декабря 2017 года № 486-ФЗ \"О синдицированном кредите (займе) и внесении изменений в отдельные законодательные акты Российской Федерации\", либо по аналогичным основаниям, предусмотренным законодательством иностранного государства. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nДля целей настоящего Кодекса под соглашением о финансировании участия в кредите (займе) признается соглашение, заключаемое в соответствии с Федеральным законом от 31 декабря 2017 года № 486-ФЗ \"О синдицированном кредите (займе) и внесении изменений в отдельные законодательные акты Российской Федерации\" или применимым законодательством иностранных государств. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nБезнадежными долгами (долгами, нереальными ко взысканию) также признаются суммы денежных обязательств, которые прекращены по основаниям, указанным в статье 2 Федерального закона от 7 октября 2022 года № 377-ФЗ \"Об особенностях исполнения обязательств по кредитным договорам (договорам займа) лицами, призванными на военную службу по мобилизации в Вооруженные Силы Российской Федерации, лицами, принимающими участие в специальной военной операции, а также членами их семей и о внесении изменений в отдельные законодательные акты Российской Федерации\". (Дополнение абзацем - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\nБезнадежным долгом (долгом, нереальным к взысканию) также признается дебиторская задолженность, которая возникла в рамках соглашения о сервисных рисках либо соглашения об управлении финансированием и обязательства по которой прекращены в случае досрочного расторжения таких соглашений (в том числе в связи с прекращением деятельности по разработке участка недр, в отношении которого заключены такие соглашения, в порядке, установленном законодательством, и (или) в соответствии с условиями соответствующего соглашения) по обстоятельствам, за которые не отвечает ни одна из сторон соответствующего соглашения, и при этом отсутствуют добытые полезные ископаемые либо количества добытых полезных ископаемых недостаточно для покрытия расходов сторон соответствующего соглашения. (Дополнение абзацем - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\nБезнадежным долгом (долгом, нереальным к взысканию) также признается задолженность по процентам по долговым обязательствам иностранной организации, которые признаны в составе доходов в соответствии с положениями подпункта 144 пункта 4 статьи 271 настоящего Кодекса, при выполнении условий, указанных в подпункте 12 пункта 2 статьи 310 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 23.07.2025 № 227-ФЗ)\n\nПоложения настоящего пункта распространяются также на приобретенные банками права требования по кредитам, если обязательства по этим правам признаны безнадежными по основаниям, установленным настоящей статьей. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n1) по сомнительной задолженности со сроком возникновения свыше 90 календарных дней - в сумму создаваемого резерва включается полная сумма выявленной на основании инвентаризации задолженности; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n2) по сомните\n\nльной задолженности со сроком возникновения от 45 до 90 календарных дней (включительно) - в сумму резерва включается 50 процентов от суммы выявленной на основании инвентаризации задолженности; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n3) по сомнительной задолженности со сроком возникновения до 45 дней - не увеличивает сумму создаваемого резерва.\n\nПри этом сумма создаваемого резерва по сомнительным долгам, исчисленного по итогам налогового периода, не может превышать 10 процентов от выручки за указанный налоговый период, определяемой в соответствии со статьей 249 настоящего Кодекса (для банков, кредитных потребительских кооперативов и микрофинансовых организаций - от суммы доходов, определяемых в соответствии с настоящей главой, за исключением доходов в виде восстановленных резервов). При исчислении резерва по сомнительным долгам в течение налогового периода по итогам отчетных периодов его сумма не может превышать большую из величин - 10 процентов от выручки за предыдущий налоговый период или 10 процентов от выручки за текущий отчетный период. (В редакции Федерального закона от 30.11.2016 № 405-ФЗ)\n\nРезерв по сомнительным долгам используется организацией лишь на покрытие убытков от безнадежных долгов, признанных таковыми в порядке, установленном настоящей статьей. (В редакции Федерального закона от 30.11.2016 № 405-ФЗ)\n\nВ случае, если налогоплательщик принял решение о создании резерва по сомнительным долгам, списание долгов, признаваемых безнадежными в соответствии с настоящей статьей, осуществляется за счет суммы созданного резерва. В случае, если сумма созданного резерва меньше суммы безнадежных долгов, подлежащих списанию, разница (убыток) подлежит включению в состав внереализационных расходов. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 266. Расходы на формирование резервов по сомнительным долгам","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44be1b41af0bce1a6a87a964327d0fd6aa412aa7a4f43745ad794a6b44e54948"},{"code_id":"NK_RF_2","article_number":"267","version_date":"2000-07-31","article_text":"1. Налогоплательщики, осуществляющие реализацию товаров (работ), вправе создавать резервы на предстоящие расходы по гарантийному ремонту и гарантийному обслуживанию, и отчисления на формирование таких резервов принимаются для целей налогообложения в порядке, предусмотренном настоящей статьей.\n\n2. Налогоплательщик самостоятельно принимает решение о создании такого резерва и в учетной политике для целей налогообложения определяет предельный размер отчислений в этот резерв. При этом резерв создается в отношении тех товаров (работ), по которым в соответствии с условиями заключенного договора с покупателем предусмотрены обслуживание и ремонт в течение гарантийного срока.\n\nПо истечении налогового периода налогоплательщик должен скорректировать размер созданного резерва, исходя из доли фактически осуществленных расходов по гарантийному ремонту и обслуживанию в объеме выручки от реализации указанных товаров (работ) за истекший период.\n\nВ случае, если налогоплательщик принял решение о создании резерва по гарантийному ремонту и обслуживанию товаров (работ), списание расходов на гарантийный ремонт осуществляется за счет суммы созданного резерва. В случае, если сумма созданного резерва меньше суммы расходов на ремонт, произведенных налогоплательщиком, разница между ними подлежит включению в состав прочих расходов.\n\n(Пункт в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 267. Расходы на формирование резерва по гарантийному ремонту и гарантийному обслуживанию","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"986acf14cb2749fc61e41dba7c2740c595bcdf1ff25483dd1b70b3c38e8090f4"},{"code_id":"NK_RF_2","article_number":"267.1","version_date":"2000-07-31","article_text":"1. Налогоплательщики - общественные организации инвалидов и организации, указанные в абзаце первом подпункта 38 пункта 1 статьи 264 настоящего Кодекса, могут создавать резерв предстоящих расходов, направляемых на цели, обеспечивающие социальную защиту инвалидов. Указанные резервы могут создаваться на срок не более пяти лет.\n\n2. Налогоплательщик на основании программ, разработанных и им утвержденных, самостоятельно принимает решение о создании резерва, указанного в пункте 1 настоящей статьи, что отражается в учетной политике для целей налогообложения. При этом расходы налогоплательщика, осуществляемые им при реализации указанных программ, производятся за счет резерва, указанного в пункте 1 настоящей статьи.\n\nСумма резерва, не полностью использованная налогоплательщиком в течение запланированного периода, подлежит включению в состав внереализационных доходов налогоплательщика текущего отчетного (налогового) периода.\n\nПри нецелевом использовании указанных в абзаце первом настоящего пункта средств они подлежат включению в налоговую базу того налогового периода, в котором было произведено их нецелевое использование.\n\n(Дополнение статьей - Федеральный закон от 06.06.2005 № 58-ФЗ)","article_title":"Статья 267.1. Расходы на формирование резервов предстоящих расходов, направляемых на цели, обеспечивающие социальную защиту инвалидов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"adafa4ec9a6e9d0120b6be629f649dc43a574a93f0480a7c644f58060bd1b37c"},{"code_id":"NK_RF_2","article_number":"267.2","version_date":"2000-07-31","article_text":"1. Налогоплательщик вправе создавать резервы предстоящих расходов на научные исследования и (или) опытно-конструкторские разработки (далее в настоящей статье - резервы) в порядке, предусмотренном настоящей статьей.\n\n2. Налогоплательщик на основании разработанных и утвержденных им программ проведения научных исследований и (или) опытно-конструкторских разработок самостоятельно принимает решение о создании каждого резерва и отражает это решение в учетной политике для целей налогообложения. Резерв для реализации каждой утвержденной программы, указанной в настоящем пункте, может создаваться на срок, на который запланировано проведение соответствующих научных исследований и (или) опытно-конструкторских разработок, но не более двух лет. Избранный налогоплательщиком срок создания резерва отражается в учетной политике для целей налогообложения.\n\n3. Размер создаваемого резерва не может превышать планируемые расходы (смету) на реализацию утвержденной налогоплательщиком программы проведения научных исследований и (или) опытно-конструкторских разработок.\n\nСмета на реализацию утвержденной налогоплательщиком программы проведения научных исследований и (или) опытно-конструкторских разработок может включать только затраты, признаваемые расходами на научные исследования и (или) опытно-конструкторские разработки в соответствии с подпунктами 1 - 5 пункта 2 статьи 262 настоящего Кодекса.\n\nПри этом предельный размер отчислений в резервы не может превышать сумму, определяемую по формуле:\n\nN = I x 0,03 - S,\n\nгде N - предельный размер отчислений в резервы;\n\nI - доходы от реализации отчетного (налогового) периода, определяемые в соответствии со статьей 249 настоящего Кодекса;\n\nS - расходы налогоплательщика, указанные в подпункте 6 пункта 2 статьи 262 настоящего Кодекса.\n\n4. Сумма отчислений в резерв включается в состав прочих расходов по состоянию на последнее число отчетного (налогового) периода.\n\n5. Налогоплательщик, формирующий резерв предстоящих расходов на научные исследования и (или) опытно-конструкторские разработки, производит расходы, осуществляемые при реализации программ проведения научных исследований и (или) опытно-конструкторских разработок, за счет указанного резерва.\n\nЕсли сумма созданного резерва, указанного в пункте 1 настоящей статьи, оказалась меньше суммы фактических расходов на проведение указанных в пункте 2 настоящей статьи программ, разница между указанными суммами учитывается как расходы налогоплательщика на научные исследования и (или) опытно-конструкторские разработки в соответствии со статьями 262 и 3321 настоящего Кодекса.\n\nСумма резерва, не полностью использованная налогоплательщиком в течение срока создания резерва, подлежит восстановлению в составе внереализационных доходов отчетного (налогового) периода, в котором были произведены соответствующие отчисления в резерв.\n\n(Дополнение статьей - Федеральный закон от 07.06.2011 № 132-ФЗ)","article_title":"Статья 267.2. Расходы на формирование резервов предстоящих расходов на научные исследования и (или) опытно-конструкторские разработки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4184aa0a4a4afa7e7e697d9632d97372abb03fe66f466ee3e8fb83ed694c33fb"},{"code_id":"NK_RF_2","article_number":"267.3","version_date":"2000-07-31","article_text":"1. Налогоплательщики - некоммерческие организации (далее в настоящей статье - налогоплательщик), кроме созданных в форме государственной корпорации, государственной компании, объединения юридических лиц, вправе создавать резерв предстоящих расходов, связанных с ведением предпринимательской деятельности и учитываемых при определении налоговой базы.\n\n2. Налогоплательщик самостоятельно принимает решение о создании резерва предстоящих расходов и определяет в учетной политике для целей налогообложения виды расходов, в отношении которых создается указанный резерв.\n\nВ случае, если налогоплательщик принял решение о создании резерва предстоящих расходов, списание расходов, в отношении которых сформирован указанный резерв, осуществляется за счет суммы созданного резерва.\n\n3. Размер создаваемого резерва предстоящих расходов определяется на основании разработанных и утвержденных налогоплательщиком смет расходов на срок, не превышающий три календарных года.\n\nСумма отчислений в резерв включается в состав внереализационных расходов на последнее число отчетного (налогового) периода. Предельный размер отчислений в резерв предстоящих расходов не может превышать 20 процентов от суммы доходов отчетного (налогового) периода, учитываемых при определении налоговой базы. При этом, если налогоплательщиком сформирован резерв предстоящих расходов на осуществление расходов, предусмотренных несколькими сметами расходов, налогоплательщик самостоятельно в налоговом учете распределяет сумму отчислений в резерв между сметами расходов.\n\n4. Сумма резерва, не полностью использованная налогоплательщиком для осуществления расходов, предусмотренных сметой расходов, подлежит включению в состав внереализационных доходов налогоплательщика на последнее число налогового (отчетного) периода, на который приходится дата окончания сметы расходов.\n\nВ случае, если сумма созданного резерва оказалась меньше фактических расходов, в отношении которых сформирован резерв, разница между указанными суммами включается в состав расходов, учитываемых при определении налоговой базы.\n\n(Дополнение статьей - Федеральный закон от 18.07.2011 № 235-ФЗ)","article_title":"Статья 267.3. Расходы на формирование резервов предстоящих расходов некоммерческих организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05c085a9dee3bd63452024b4eae2cddbe536edc9b617729890d3f625cc976e18"},{"code_id":"NK_RF_2","article_number":"267.4","version_date":"2000-07-31","article_text":"1. Организация - владелец лицензии на пользование участком недр, в границах которого расположено новое морское месторождение углеводородного сырья, вправе создавать резерв предстоящих расходов, связанных с завершением деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья, начиная с налогового периода, по состоянию на 1 января которого, по данным государственного баланса запасов полезных ископаемых, степень выработанности запасов на соответствующем новом морском месторождении углеводородного сырья достигла уровня 70 процентов, в порядке, предусмотренном настоящей статьей.\n\nРезерв предстоящих расходов, связанных с завершением деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья, создается налогоплательщиком только при условии отражения в согласованной в установленном порядке проектной документации на разработку соответствующего месторождения перечня мероприятий и видов работ, которые предполагается осуществить при ликвидации выводимых из эксплуатации объектов.\n\n2. Организация - владелец лицензии на пользование участком недр, в границах которого расположено новое морское месторождение углеводородного сырья, самостоятельно принимает решение о создании резерва предстоящих расходов, связанных с завершением деятельности по добыче углеводородного сырья на каждом новом морском месторождении углеводородного сырья, и отражает порядок создания и использования указанного резерва в учетной политике для целей налогообложения.\n\n3. Расходами, связанными с завершением деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья, признаются расходы на ликвидацию выводимых из эксплуатации основных средств, а также расходы на ликвидацию объектов незавершенного строительства и иного имущества, монтаж которого не завершен (расходы на демонтаж, разборку, вывоз разобранного имущества), охрану недр, окружающей среды и иные аналогичные мероприятия, предусмотренные законодательством о недропользовании.\n\nПри этом суммы недоначисленной амортизации по выводимым из эксплуатации объектам основных средств и стоимость ликвидируемых объектов незавершенного строительства не признаются расходами, связанными с завершением деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья.\n\n4. Суммы отчислений в резерв включаются в состав расходов, учитываемых при определении налоговой базы в соответствии со статьей 2752 настоящего Кодекса, на последнее число отчетного (налогового) периода.\n\n5. Сумма отчислений в резерв в каждом отчетном (налоговом) периоде не может превышать 1 процент от доходов, определяемых в соответствии со статьей 2993 настоящего Кодекса и полученных в соответствующем отчетном (налоговом) периоде.\n\n6. Списание осуществленных расходов, связанных с завершением деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья, в отношении которого сформирован резерв, осуществляется за счет суммы созданного резерва.\n\n7. Общая сумма отчислений в резерв за все отчетные (налоговые) периоды не может превышать общую сумму затрат на ликвидацию скважин и объектов промыслового обустройства и рекультивацию земель, определенную в согласованной в установленном порядке проектной документации на разработку соответствующего нового морского месторождения углеводородного сырья.\n\n8. В случае, если остаточная сумма резерва на начало отчетного (налогового) периода оказалась меньше суммы фактически понесенных в отчетном (налоговом) периоде расходов, указанных в настоящей статье, соответствующая сумма превышения учитывается в этом отчетном (налоговом) периоде в составе расходов в порядке, предусмотренном настоящей главой для соответствующих видов расходов.\n\n9. Сумма резерва, не полностью использованная налогоплательщиком в отчетном (налоговом) периоде, может быть перенесена им на следующий отчетный (налоговый) период.\n\nСумма резерва, не полностью использованная налогоплательщиком на момент принятия им решения о завершении деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья, подлежит включению в состав внереализационных доходов налогоплательщика на последнее число отчетного (налогового) периода, в котором были фактически завершены мероприятия, предусмотренные планом ликвидации скважин и объектов промыслового обустройства и рекультивации земель, но не позднее даты окончания действия лицензии на право пользования участком недр, в границах которого расположено это новое морское месторождение углеводородного сырья.\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 268-ФЗ)","article_title":"Статья 267.4. Расходы на формирование резерва предстоящих расходов, связанных с завершением деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0e5b268dc1d695382b5046d24f3d7b62a52fe2c9c81d1de608c29b5195c5a416"},{"code_id":"NK_RF_2","article_number":"268","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\n1) при реализации амортизируемого имущества (\n\nза исключением объектов, в отношении которых налогоплательщик использовал право на применение инвестиционного налогового вычета в соответствии со статьей 2861 настоящего Кодекса и налогового вычета в соответствии со статьей 3436 настоящего Кодекса) - на остаточную стоимость амортизируемого имущества, определяемую в соответствии с пунктами 1 и 3 статьи 257 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ случае, если налогоплательщик реализовал основное средство ранее чем по истечении пяти лет с момента введения его в эксплуатацию лицу, являющемуся взаимозависимым с налогоплательщиком, и в отношении такого основного средства были применены положения абзаца второго пункта 9 статьи 258 настоящего Кодекса, остаточная стоимость при реализации указанного амортизируемого имущества увеличивается на сумму расходов, включенных в состав внереализационных доходов в соответствии с абзацем четвертым пункта 9 статьи 258 настоящего Кодекса. А в случае, если в отношении указанного амортизируемого имущества были применены положения пункта 11 статьи 2862 настоящего Кодекса, остаточная стоимость при реализации указанного амортизируемого имущества увеличивается на сумму налога, восстановленного в соответствии с абзацем первым пункта 11 статьи 2862 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.11.2012 № 206-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n2) при реализации прочего имущества (за исключением ценных бумаг, продукции собственного производства, покупных товаров) - на цену приобретения (создания) этого имущества, если иное не предусмотрено пунктом 22 статьи 277 настоящего Кодекса, а также на сумму расходов, указанных в абзаце втором пункта 2 статьи 254 настоящего Кодекса; (В редакции федеральных законов от 06.06.2005 № 58-ФЗ; от 25.11.2009 № 281-ФЗ; от 15.02.2016 № 32-ФЗ)\n\n21) при реализации имущественных прав (долей, паев), если иное не предусмотрено настоящим подпунктом, - на цену приобретения данных имущественных прав (долей, паев) и на сумму расходов, связанных с их приобретением и реализацией, а также на величину вклада в виде денежных средств, уменьшенных на сумму денежных средств, указанных в подпункте 111 пункта 1 статьи 251 настоящего Кодекса, в имущество организаций, доли (паи) которых были приобретены, если иное не предусмотрено пунктом 10 статьи 3091 или пунктом 22 статьи 277 настоящего Кодекса. Величина вклада в виде денежных средств в имущество организации, уменьшающая доходы от реализации долей (паев), рассчитывается пропорционально реализуемым долям (паям) в общей величине долей (паев), принадлежащих налогоплательщику. (В редакции  федеральных законов от 15.02.2016 № 32-ФЗ, от 09.11.2020 № 368-ФЗ, от 14.07.2022 № 324-ФЗ)\n\nПри реализации имущественных прав (в том числе цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права), цена приобретения которых частично уже учтена на дату реализации этих имущественных прав в составе расходов в соответствии с нормами настоящей главы (в частности, в соответствии с абзацами третьим и четвертым пункта 53 статьи 272 настоящего Кодекса), цена приобретения этих имущественных прав уменьшается на сумму указанных расходов. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nПри реализации акций, долей в случае, если ранее такой реализации осуществлялось уменьшение уставного капитала хозяйственного общества (товарищества) путем уменьшения номинальной стоимости акций, долей в пределах первоначального вклада (взноса) в уставный капитал хозяйственного общества (товарищества), цена приобретения данных акций, долей уменьшается на стоимость имущества (имущественных прав), ранее полученного участником хозяйственного общества (товарищества) при уменьшении уставного капитала этого хозяйственного общества (товарищества) в соответствии с законодательством Российской Федерации в пределах первоначального вклада (взноса). Настоящее положение не распространяется на случаи, когда хозяйственное общество (товарищество) обязано уменьшить свой уставный капитал в соответствии с требованиями законодательства Российской Федерации. (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nПри реализации долей, паев, полученных участниками, пайщиками при реорганизации организаций, ценой приобретения таких долей, паев признается их стоимость, определяемая в соответствии с пунктами 4 - 6 статьи 277 настоящего Кодекса.\n\nПри реализации имущественного права, которое представляет собой право требования долга, налоговая база определяется с учетом положений, установленных статьей 279 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nПри реализации акций (долей участия), прощенные обязательства по оплате которых учитываются для целей налогообложения в соответствии с подпунктами 215 и 217 пункта 1 статьи 251 настоящего Кодекса, их стоимость признается равной нулю; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\n3) при реализации покупных товаров - на стоимость приобретения данных товаров, определяемую в соответствии с принятой организацией учетной политикой для целей налогообложения одним из следующих методов оценки покупных товаров:\n\nпо стоимости первых по времени приобретения (ФИФО); (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\nпо средней стоимости; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nпо стоимости единицы товара. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nПри реализации имущества и (или) имущественных прав, указанных в настоящей статье, налогоплательщик также вправе уменьшить доходы от таких операций на сумму расходов, непосредственно связанных с такой реализацией, в частности на расходы по оценке, хранению, обслуживанию и транспортировке реализуемого имущества. При этом при реализации покупных товаров расходы, связанные с их покупкой и реализацией, формируются с учетом положений статьи 320 настоящего Кодекса; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\n4) при реализации объекта основных средств (нематериального актива), в отношении которого налогоплательщик использовал право на применение инвестиционного налогового вычета, до истечения срока его полезного использования - на первоначальную стоимость такого объекта основных средств (нематериального актива) при условии восстановления в соответствии с пунктом 12 статьи 2861 настоящего Кодекса суммы налога, не уплаченной в связи с применением такого вычета; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n5) при реализации объекта основных средств, в отношении которого налогоплательщик использовал право на применение инвестиционного налогового вычета в части стоимости основного средства, - на остаточную стоимость амортизируемого имущества, определяемую в соответствии с пунктом 1 статьи 257 настоящего Кодекса, соответствующую части первоначальной стоимости такого объекта основных средств, сформированной за счет расходов, в части которых налогоплательщик не использовал право на применение инвестиционного налогового вычета. (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nПри реализации амортизируемого имущества, при формировании первоначальной стоимости которого применялись положения абзаца третьего пункта 1 и абзаца тринадцатого пункта 3 статьи 257 настоящего Кодекса, убыток от реализации такого амортизируемого имущества признается равным нулю. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 268. Особенности определения расходов при реализации товаров и (или) имущественных прав","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61d56427533e86c3cb2cc2c3a96d60a07eb5c978750e789fb6a9e8c44abaf968"},{"code_id":"NK_RF_2","article_number":"268.1","version_date":"2000-07-31","article_text":"1. В целях настоящей главы разница между ценой приобретения предприятия как имущественного комплекса и стоимостью чистых активов предприятия как имущественного комплекса (активы за вычетом обязательств) признается расходом (доходом) налогоплательщика в порядке, установленном настоящей статьей.\n\nВеличину превышения цены покупки предприятия как имущественного комплекса над стоимостью его чистых активов следует рассматривать как надбавку к цене, уплачиваемую покупателем в ожидании будущих экономических выгод.\n\nВеличину превышения стоимости чистых активов предприятия как имущественного комплекса над ценой его покупки следует рассматривать как скидку с цены, предоставляемую покупателю в связи с отсутствием факторов наличия стабильных покупателей, репутации качества, навыков маркетинга и сбыта, деловых связей, опыта управления, уровня квалификации персонала и с учетом других факторов.\n\n2. Сумма уплачиваемой надбавки (получаемой скидки) при приобретении предприятия как имущественного комплекса определяется как разница между ценой покупки и стоимостью чистых активов предприятия как имущественного комплекса, определяемой по передаточному акту.\n\nПри приобретении предприятия как имущественного комплекса в порядке приватизации на аукционе или по конкурсу величина уплачиваемой покупателем надбавки (получаемой скидки) определяется как разница между ценой покупки и оценочной (начальной) стоимостью предприятия как имущественного комплекса.\n\n3. Сумма уплачиваемой покупателем надбавки (получаемой скидки) учитывается в целях налогообложения в следующем порядке:\n\n1) надбавка, уплачиваемая покупателем предприятия как имущественного комплекса, признается расходом равномерно в течение пяти лет начиная с месяца, следующего за месяцем государственной регистрации права собственности покупателя на предприятие как имущественный комплекс;\n\n2) скидка, получаемая покупателем предприятия как имущественного комплекса, признается доходом в том месяце, в котором осуществлена государственная регистрация перехода права собственности на предприятие как имущественный комплекс.\n\n4. Убыток, полученный продавцом от реализации предприятия как имущественного комплекса, признается расходом, учитываемым в целях налогообложения в порядке, установленном статьей 283 настоящего Кодекса.\n\n5. В целях настоящей главы расходами покупателя на приобретение в составе предприятия как имущественного комплекса активов и имущественных прав признается их стоимость, определяемая по передаточному акту.\n\n(Дополнение статьей - Федеральный закон от 24.07.2007 № 216-ФЗ)","article_title":"Статья 268.1. Особенности признания доходов и расходов при приобретении предприятия как имущественного комплекса","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe7c30cb9d996d31df8301788c07d76437494cfcbbe16455ed28564a91cb4bb4"},{"code_id":"NK_RF_2","article_number":"269","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nПо долговым обязательствам любого вида доходом (расходом) признаются проценты, исчисленные исходя из фактической ставки, если иное не установлено настоящей статьей.\n\nПо долговым обязательствам любого вида, возникшим в результате сделок, признаваемых в соответствии с настоящим Кодексом контролируемыми сделками, доходом (расходом) признается процент, исчисленный исходя из фактической ставки с учетом положений раздела V1 настоящего Кодекса, если иное не установлено настоящей статьей.\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nпризнать доходом процент, исчисленный исходя из фактической ставки по таким долговым обязательствам, если эта ставка превышает минимальное значение интервала предельных значений, установленного пунктом 12 настоящей статьи;\n\nпризнать расходом процент, исчисленный исходя из фактической ставки по таким долговым обязательствам, если эта ставка менее максимального значения интервала предельных значений, установленного пунктом 12 настоящей статьи.\n\nПри несоблюдении условий, установленных абзацами первым - третьим настоящего пункта, по долговым обязательствам, возникшим в результате сделок, признаваемых в соответствии с настоящим Кодексом контролируемыми сделками, доходом (расходом) признается процент, исчисленный исходя из фактической ставки с учетом положений раздела V1 настоящего Кодекса. (В редакции Федерального закона от 08.03.2015 № 32-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\n12. В целях пункта 11 настоящей статьи устанавливаются следующие интервалы предельных значений процентных ставок по долговым обязательствам:\n\n1) по долговому обязательству, оформленному в рублях, - от 10 до 150 процентов ключевой ставки Центрального банка Российской Федерации. При этом минимальное значение интервала предельных значений процентных ставок, определенного в соответствии с настоящим подпунктом, не может быть менее 2 процентов;\n\n2) по долговому обязательству, оформленному в евро, - от 1 процента до ставки &euro;STR в евро, увеличенной на 7 процентных пунктов;\n\n3) по долговому обязательству, оформленному в китайских юанях, - от 1 процента до ставки SHIBOR в китайских юанях, увеличенной на 7 процентных пунктов;\n\n4) по долговому обязательству, оформленному в фунтах стерлингов, - от 1 процента до ставки SONIA в фунтах стерлингов, увеличенной на 7 процентных пунктов;\n\n5) по долговому обязательству, оформленному в швейцарских франках или японских иенах, - от 1 процента до ставки SARON в швейцарских франках или TONAR в японских иенах, увеличенной на 5 процентных пунктов;\n\n6) по долговому обязательству, оформленному в иных валютах, не указанных в подпунктах 1 - 5 настоящего пункта, - от 1 процента до ставки SOFR в долларах США, увеличенной на 7 процентных пунктов.\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ) (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n13. В целях применения пункта 12 настоящей статьи:\n\n1) в отношении долговых обязательств, по которым ставка является фиксированной и не изменяется в течение всего срока действия долгового обязательства, под ключевой ставкой Центрального банка Российской Федерации (ставкой &euro;STR, ставкой SHIBOR, ставкой SONIA, ставкой SARON, ставкой TONAR, ставкой SOFR) понимается соответствующая ставка, действовавшая на дату привлечения денежных средств или иного имущества в виде долгового обязательства; (В редакции федеральных законов от 08.03.2015 № 32-ФЗ, от 02.07.2021 № 305-ФЗ)\n\n2) в отношении долговых обязательств, не указанных в подпункте 1 настоящего пункта, под ключевой ставкой Центрального банка Российской Федерации (ставкой &euro;STR, ставкой SHIBOR, ставкой SONIA, ставкой SARON, ставкой TONAR, ставкой SOFR) понимается соответствующая ставка, действующая на дату признания доходов (расходов) в виде процентов в соответствии с настоящей главой; (В редакции федеральных законов от 08.03.2015 № 32-ФЗ, от 02.07.2021 № 305-ФЗ)\n\n3) в отношении интервалов предельных значений процентных ставок по долговым обязательствам, установленным подпунктом 3 пункта 12 настоящей статьи, принимается ставка SHIBOR на срок, в наибольшей степени соответствующий сроку долгового обязательства, указанного в пункте 11 настоящей статьи; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n4) в отношении интервалов предельных значений процентных ставок по долговым обязательствам, установленным подпунктами 2, 4 - 6 пункта 12 настоящей статьи, принимается ставка &euro;STR (ставка SONIA, ставка SARON, ставка TONAR, ставка SOFR), опубликованная на начало рабочего дня. (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n1) по долговому обязательству перед иностранным лицом, являющимся взаимозависимым лицом налогоплательщика - российской организации в соответствии с подпунктом 1, 2 или 9 пункта 2 статьи 1051 настоящего Кодекса, если такое иностранное лицо прямо или косвенно участвует в налогоплательщике - российской организации, указанной в абзаце первом настоящего пункта;\n\n2) по долговому обязательству перед лицом, признаваемым в соответствии с подпунктом 1, 2, 3 или 9 пункта 2 статьи 1051 настоящего Кодекса взаимозависимым лицом иностранного лица, указанного в подпункте 1 настоящего пункта, если иное не предусмотрено пунктом 8 настоящей статьи;\n\n3) по долговому обязательству, по которому иностранное лицо, указанное в подпункте 1 настоящего пункта, и (или) его взаимозависимое лицо, указанное в подпункте 2 настоящего пункта, выступают поручителем, гарантом или иным образом обязуются обеспечить исполнение этого долгового обязательства налогоплательщика - российской организации, если иное не предусмотрено пунктом 9 настоящей статьи.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 25-ФЗ)\n\nее чем в 12,5 раза) превышает разницу между суммой активов и величиной обязательств этого налогоплательщика (далее в настоящей статье - собственный капитал) на последнее число отчетного (налогового) периода, при определении предельного размера процентов, подлежащих включению в состав расходов этого налогоплательщика, применяются правила, установленные пунктами 4 - 6 настоящей статьи. При определении размера контролируемой задолженности налогоплательщика в целях настоящей статьи учитываются суммы контролируемой задолженности, возникшей по всем обязательствам этого налогоплательщика, указанным в пункте 2 настоящей статьи, в совокупности.\n\nВ целях настоящей статьи организацией, занимающейся лизинговой деятельностью, признается организация, у которой в отчетном (налоговом) периоде, на последнее число которого определяется предельный размер процентов, подлежащих включению в состав расходов, доходы от осуществления лизинговой деятельности, учитываемые при определении налоговой базы в соответствии с настоящей главой, составляют не менее 90 процентов всех доходов, учитываемых при определении налоговой базы в соответствии с настоящей главой за указанный отчетный (налоговый) период.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 25-ФЗ)\n\nКоэффициент капитализации в целях настоящей статьи определяется путем деления величины соответствующей непогашенной контролируемой задолженности на величину собственного капитала, соответствующего доле участия взаимозависимого иностранного лица, указанного в подпункте 1 пункта 2 настоящей статьи, в российской организации, и деления полученного результата на 3 (для банков и организаций, занимающихся лизинговой деятельностью, - на 12,5).\n\nПри определении величины собственного капитала не учитываются суммы долговых обязательств в виде задолженности по налогам и сборам, включая текущую задолженность по уплате налогов и сборов, суммы отсрочек, рассрочек и инвестиционного налогового кредита.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 25-ФЗ)\n\nПри этом правила, установленные пунктом 4 настоящей статьи, не применяются в отношении процентов по заемным средствам, если непогашенная задолженность по соответствующему долговому обязательству не является контролируемой.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 25-ФЗ)\n\nденежные средства, составляющие указанную непогашенную задолженность, направлены исключительно на финансирование инвестиционного проекта, реализуемого налогоплательщиком на территории Российской Федерации;\n\nусловия договора, в соответствии с которым возникло указанное в настоящем пункте долговое обязательство, предусматривают начало погашения суммы непогашенной задолженности по такому долговому обязательству не ранее чем через пять лет после его возникновения;\n\nсовокупная доля прямого и косвенного участия взаимозависимого иностранного лица, указанного в подпункте 1 пункта 2 настоящей статьи, в российской организации не превышает 35 процентов;\n\nместом регистрации (местом налогового резидентства) лица, перед которым возникло долговое обязательство, является иностранное государство, с которым заключен договор (соглашение, конвенция) об избежании двойного налогообложения.\n\nДля целей настоящего пункта инвестиционным проектом признается создание на территории Российской Федерации нового производственного комплекса для производства товаров и (или) оказания услуг. Производственный комплекс признается новым, если он введен в эксплуатацию после 1 января 2019 года и ранее в эксплуатации не был.\n\nВ случае невыполнения одного из условий, установленных настоящим пунктом, к непогашенной задолженности по указанному в настоящем пункте долговому обязательству применяются положения настоящей статьи без учета положений настоящего пункта с даты возникновения соответствующего долгового обязательства.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\n1) долговое обязательство возникло перед российской организацией или физическом лицом, являющимися в соответствии с настоящим Кодексом налоговыми резидентами Российской Федерации в течение всего отчетного (налогового) периода и признаваемыми взаимозависимыми лицами иностранного лица, указанного в подпункте 1 пункта 2 настоящей статьи, на основании подпункта 1, 2, 3 или 9 пункта 2 статьи 1051 настоящего Кодекса;\n\n2) российская организация или физическое лицо, перед которыми возникло долговое обязательство, в течение отчетного (налогового) периода не имеет непогашенной задолженности по сопоставимым долговым обязательствам перед иностранным лицом, указанным в подпунктах 1 и (или) 2 пункта 2 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 25-ФЗ)\n\n1) долговое обязательство возникло перед организацией, являющейся банком (включая организации, признаваемые банками в соответствии с законодательством иностранных государств), международной финансовой организацией, созданной в соответствии с международным договором Российской Федерации, или банком развития - государственной корпорацией, не признаваемыми взаимозависимыми лицами как с налогоплательщиком - российской организацией, так и с лицами, выступающими поручителем, гарантом или иным образом обязующимися исполнить долговое обязательство налогоплательщика; (В редакции федеральных законов от 29.12.2017 № 466-ФЗ, от 29.09.2019 № 325-ФЗ)\n\n2) с момента возникновения долгового обязательства налогоплательщика не происходило прекращения (исполнения) указанного долгового обязательства как в части суммы основного долга, так и в части уплаты процентов иностранным лицом, указанным в подпункте 1 пункта 2 настоящей статьи, и (или) его взаимозависимым лицом, указанным в подпункте 2 пункта 2 настоящей статьи, выступающими поручителем, гарантом или иным образом обязующимися обеспечить исполнение указанного долгового обязательства.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 25-ФЗ)\n\n11. Определение сопоставимости долговых обязательств в целях подпункта 2 пункта 8 настоящей статьи производится с учетом следующих особенностей:\n\n1) для определения сопоставимости долговых обязательств учитываются общая сумма этих обязательств и срок, на который они предоставлены;\n\n2) при наличии нескольких долговых обязательств по сделкам, заключенным с иностранным лицом, указанным в подпунктах 1 и (или) 2 пункта 2 настоящей статьи, для определения общей суммы долговых обязательств в целях подпункта 1 настоящего пункта суммы таких обязательств суммируются;\n\n3) если валюта долгового обязательства перед иностранным лицом, указанным в подпунктах 1 и (или) 2 пункта 2 настоящей статьи, отличается от валюты долгового обязательства, с которым производится сопоставление, долговые обязательства приводятся к единой валюте по курсу, установленному Центральным банком Российской Федерации на дату возникновения долгового обязательства перед кредитором;\n\n4) в случае, если срок, на который предоставлено долговое обязательство налогоплательщику - российской организации, не превышает срок, на который возникла непогашенная задолженность по долговому обязательству перед иностранным лицом, указанным в подпунктах 1 и (или) 2 пункта 2 настоящей статьи, такие сроки считаются сопоставимыми.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 25-ФЗ)","article_title":"Статья 269. Особенности учета процентов по долговым обязательствам в целях налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c6506f64cb41ad6ad376ed088531990502ba7769d39b19692c09de148b60eab3"},{"code_id":"NK_RF_2","article_number":"270","version_date":"2000-07-31","article_text":"При определении налоговой базы не учитываются следующие расходы:\n\n1) в виде сумм начисленных налогоплательщиком дивидендов и других сумм прибыли после налогообложения; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\n2) в виде платежей в целях возмещения ущерба, пеней, штрафов, санкций, перечисляемых в бюджет (в государственные внебюджетные фонды), процентов, подлежащих уплате в бюджет в соответствии со статьей 1761 настоящего Кодекса, а также штрафов и других санкций, взимаемых государственными организациями, которым законодательством Российской Федерации предоставлено право наложения указанных санкций; (В редакции федеральных законов от 17.12.2009 № 318-ФЗ, от 02.07.2021 № 305-ФЗ)\n\n3) в виде взноса в уставный (складочный) капитал, вклада в простое товарищество, в инвестиционное товарищество; (В редакции Федерального закона от 28.11.2011 № 336-ФЗ)\n\n4) в виде суммы налога, суммы налога на сверхприбыль (обеспечительного платежа), суммы туристического налога, а также суммы платежей за выбросы загрязняющих веществ в атмосферный воздух, сбросы загрязняющих веществ в составе сточных вод в водные объекты, осуществляемые с превышением нормативов допустимых сбросов, за размещение отходов производства и потребления с превышением установленных лимитов на их размещение; (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 21.07.2014 № 219-ФЗ, от 04.08.2023 № 415-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n5) в виде расходов по приобретению и (или) созданию амортизируемого имущества, а также расходов, осуществленных в случаях достройки, дооборудования, реконструкции, модернизации, технического перевооружения объектов основных средств, за исключением расходов, указанных в пункте 9 статьи 258 и подпункте 4812 пункта 1 статьи 264 настоящего Кодекса; (В редакции федеральных законов от 06.06.2005 № 58-ФЗ, от 22.07.2008 № 158-ФЗ, от 22.04.2020 № 121-ФЗ)\n\n51) в виде расходов на приобретение, создание, достройку, дооборудование, реконструкцию, модернизацию, техническое перевооружение объектов основных средств и нематериальных активов, в отношении которых налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в соответствии со статьей 2861 настоящего Кодекса, если иное не предусмотрено настоящим Кодексом, либо воспользовался или воспользуется правом на применение налогового вычета для СЗПК, указанного в статье 2518 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции  Федерального закона от 28.06.2022 № 225-ФЗ)\n\n52) в виде расходов на приобретение, сооружение, изготовление, доставку объектов основных средств и доведение таких объектов до состояния, пригодного для использования, учитываемых при определении налоговых вычетов, установленных статьями 3436, 3437 и 3439 настоящего Кодекса, и в виде расходов по договорам технологического присоединения, договорам инвестирования и иным аналогичным договорам, в отношении которых налогоплательщик воспользовался правом на применение налогового вычета в соответствии со статьей 3436 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 13.07.2020 № 195-ФЗ) (В редакции  Федерального закона от 28.12.2022 № 566-ФЗ)\n\n53) в виде процентов по кредитам, учитываемых при применении налогового вычета в соответствии со статьей 3437 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n6) в виде взносов на добровольное страхование, кроме взносов, указанных в статьях 255, 263 и 291 настоящего Кодекса; (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\n7) в виде взносов на негосударственное пенсионное обеспечение, кроме взносов, указанных в статье 255 настоящего Кодекса;\n\n8) в виде процентов, начисленных налогоплательщиком-заемщиком кредитору сверх сумм, признаваемых расходами в целях налогообложения в соответствии со статьей 269 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n9) в виде имущества (включая денежные средства), переданного комиссионером, агентом и (или) иным поверенным в связи с исполнением обязательств по договору комиссии, агентскому договору или иному аналогичному договору, а также в счет оплаты затрат, произведенной комиссионером, агентом и (или) иным поверенным за комитента, принципала и (или) иного доверителя, если такие затраты не подлежат включению в состав расходов комиссионера, агента и (или) иного поверенного в соответствии с условиями заключенных договоров; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n10) в виде сумм отчислений в резерв под обесценение вложений в ценные бумаги, создаваемые организациями в соответствии с законодательством Российской Федерации, за исключением сумм отчислений в резервы под обесценение ценных бумаг, производимых профессиональными участниками рынка ценных бумаг в соответствии со статьей 300 настоящего Кодекса;\n\n11) в виде гарантийных взносов, перечисляемых в специальные фонды, создаваемые в соответствии с требованиями законодательства Российской Федерации, предназначенные для снижения рисков неисполнения обязательств по сделкам при осуществлении клиринговой деятельности или деятельности по организации торговли на рынке ценных бумаг;\n\n111) в виде расходов, понесенных за счет средств компенсационных фондов, создаваемых в соответствии с требованиями законодательства Российской Федерации и предназначенных для возмещения убытков, причиненных в результате несостоятельности (банкротства) форекс-дилеров; (Дополнение пунктом - Федеральный закон от 29.12.2014 № 460-ФЗ)\n\n112) в виде имущества, внесенного в имущественный пул клиринговой организации, а также в виде клиринговых сертификатов участия, предъявленных к погашению клиринговой организации, выдавшей такие сертификаты, в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\"; (Дополнение пунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n12) в виде средств или иного имущества, которые переданы по долговым обязательствам, в том числе по договорам кредита, займа, соглашениям о финансировании участия в кредите (займе) (иных аналогичных средств или иного имущества независимо от формы оформления заимствований, включая долговые ценные бумаги), а также в виде средств или иного имущества, которые направлены в счет погашения таких долговых обязательств; (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n121) в виде сумм денежных средств, причитающихся к выплате налогоплательщиком, являющимся лицом, выпустившим цифровые финансовые активы, решением о выпуске которых предусмотрено обязательство по выплате дохода в сумме, равной сумме дивидендов, полученных налогоплательщиком, во исполнение такого обязательства; (Дополнение пунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n122) в виде сумм денежных средств, переданных управляющему товарищу по соглашению об управлении финансированием в целях осуществления им деятельности в качестве оператора по соглашению о сервисных рисках, а также сумм денежных средств, переданных управляющим товарищем участнику соглашения об управлении финансированием в размере стоимости компенсационной части добытых полезных ископаемых, причитающейся такому участнику в рамках этого соглашения; (Дополнение пунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n13) в виде сумм убытков по объектам обслуживающих производств и хозяйств, включая объекты жилищно-коммунальной и социально-культурной сферы в части, превышающей предельный размер, определяемый в соответствии со статьей 2751 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n14) в виде имущества, работ, услуг, имущественных прав, переданных в порядке предварительной оплаты налогоплательщиками, определяющими доходы и расходы по методу начисления;\n\n15) в виде сумм добровольных членских взносов (включая вступительные взносы) в общественные организации, сумм добровольных взносов участников союзов, ассоциаций, организаций (объединений) на содержание указанных союзов, ассоциаций, организаций (объединений);\n\n16) в виде стоимости безвозмездно переданного имущества (работ, услуг, имущественных прав) и расходов, связанных с такой передачей, если иное не предусмотрено настоящей главой; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 17.07.2009 № 161-ФЗ)\n\n161) в виде сумм начисленной амортизации по основным средствам, передаваемым налогоплательщиком в безвозмездное пользование, за исключением передаваемых (предоставляемых) в безвозмездное пол\n\nьзование в случаях, если такая обязанность налогоплательщика установлена законодательством Российской Федерации; (Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n17) в виде стоимости имущества, переданного в рамках целевого финансирования в соответствии с подпунктом 14 пункта 1 статьи 251 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n18) в виде отрицательной разницы, образовавшейся в результате переоценки драгоценных камней при изменении в установленном порядке прейскурантов цен;\n\n19) в виде сумм налогов, предъявленных в соответствии с настоящим Кодексом налогоплательщиком покупателю (приобретателю) товаров (работ, услуг, имущественных прав), если иное не предусмотрено настоящим Кодексом, а также сумм торгового сбора; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 29.11.2014 № 382-ФЗ)\n\n20) в виде средств, перечисляемых профсоюзным организациям;\n\n21) в виде расходов на любые виды вознаграждений, предоставляемых руководству или работникам помимо вознаграждений, выплачиваемых на основании трудовых договоров (контрактов);\n\n22) в виде премий, выплачиваемых работникам за счет средств специального назначения или целевых поступлений;\n\n23) в виде сумм материальной помощи работникам, если иное не предусмотрено настоящей главой; (В редакции  федеральных законов от 22.07.2008 № 158-ФЗ, от 21.11.2022 № 443-ФЗ)\n\n24) на оплату дополнительно предоставляемых по коллективному договору (сверх предусмотренных действующим законодательством) отпусков работникам, в том числе женщинам, воспитывающим детей;\n\n25) в виде надбавок к пенсиям, единовременных пособий уходящим на пенсию ветеранам труда, доходов (дивидендов, процентов) по акциям или вкладам трудового коллектива организации, компенсационных начислений в связи с повышением цен, производимых сверх размеров индексации доходов по решениям Правительства Российской Федерации, компенсаций удорожания стоимости питания в столовых, буфетах или профилакториях либо предоставления его по льготным ценам или бесплатно (за исключением специального питания для отдельных категорий работников в случаях, предусмотренных действующим законодательством, и за исключением случаев, когда бесплатное или льготное питание предусмотрено трудовыми договорами (контрактами) и (или) коллективными договорами; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n26) на оплату проезда к месту работы и обратно транспортом общего пользования, специальными маршрутами, ведомственным транспортом, за исключением сумм, подлежащих включению в состав расходов на производство и реализацию товаров (работ, услуг) в силу технологических особенностей производства, и за исключением случаев, когда расходы на оплату проезда к месту работы и обратно предусмотрены трудовыми договорами (контрактами) и (или) коллективными договорами; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n27) на оплату ценовых разниц при реализации по льготным ценам (тарифам) (ниже рыночных цен) товаров (работ, услуг) работникам;\n\n28) на оплату ценовых разниц при реализации по льготным ценам продукции подсобных хозяйств для организации общественного питания;\n\n29) на оплату путевок на лечение или отдых, экскурсий или путешествий, если иное не предусмотрено пунктом 242 части второй статьи 255 настоящего Кодекса, занятий в спортивных секциях, кружках или клубах, посещений культурно-зрелищных или физкультурных (спортивных) мероприятий, подписки, не относящейся к подписке на нормативно-техническую и иную используемую в производственных целях литературу, и на оплату товаров для личного потребления работников, а также другие аналогичные расходы, произведенные в пользу работников; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 23.04.2018 № 113-ФЗ)\n\n(Пункт 30 исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n30) в виде расходов налогоплательщиков-организаций государственного запаса специального (радиоактивного) сырья и делящихся материалов Российской Федерации по операциям с материальными ценностями государственного запаса специального (радиоактивного) сырья и делящихся материалов, связанные с восстановлением и содержанием указанного запаса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n31) в виде стоимости переданных налогоплательщиком - эмитентом акций, распределяемых между акционерами по решению общего собрания акционеров пропорционально количеству принадлежащих им акций, либо разница между номинальной стоимостью новых акций, переданных взамен первоначальных, и номинальной стоимостью первоначальных акций акционера при распределении между акционерами акций при увеличении уставного капитала эмитента; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n311) в виде разницы, образовавшейся в результате превышения цены приобретения акций иностранной организации по данным налогового учета налогоплательщика над стоимостью полученных при погашении (частичном погашении) номинальной стоимости этих акций в связи с уменьшением уставного капитала иностранной организации имущества (включая денежные средства) и (или) имущественных прав, определенной по официальному курсу Центрального банка Российской Федерации, действовавшему на дату такого погашения, при условии, что налогоплательщик в течение не менее 365 календарных дней непрерывно владеет на праве собственности не менее чем 50-процентным вкладом (долей) в уставном (складочном) капитале (фонде) указанной иностранной организации.\n\nДанное положение применяется к доходам, полученным в 2024 и 2025 годах налогоплательщиком, в отношении которого на дату соответствующего погашения номинальной стоимости акций действуют запретительные, ограничительные и (или) аналогичные меры, заключающиеся в установлении запретов и (или) ограничений на проведение расчетов и (или) осуществление финансовых операций, запретов и (или) ограничений на проведение операций, связанных с заемным финансированием и (или) приобретением либо отчуждением ценных бумаг (долей участия в уставном капитале), введенные начиная с 2022 года иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями;\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n32) в виде имущества или имущественных прав, переданных в качестве задатка, залога, обеспечительного платежа; (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 16.04.2022 № 96-ФЗ)\n\n33) в виде сумм налогов, начисленных в бюджеты различных уровней в случае, если такие налоги ранее были включены налогоплательщиком в состав расходов, при списании кредиторской задолженности налогоплательщика по этим налогам в соответствии с подпунктом 21 пункта 1 статьи 251 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n34) в виде сумм целевых отчислений, произведенных налогоплательщиком на цели, указанные в пункте 2 статьи 251 настоящего Кодекса, за исключением целевых отчислений, произведенных в соответствии с подпунктами 195 и 196 пункта 1 статьи 265 настоящего Кодекса; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 08.06.2020 № 172-ФЗ)\n\n(Пункт 36 исключен - Федерального закона от 29.05.2002 № 57-ФЗ)\n\n35) (Пункт утратил силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n36) (Пункт утратил силу - Федеральный закон от 24.07.2007 № 216-ФЗ)\n\n37) в виде сумм выплаченных подъемных сверх норм, установленных законодательством Российской Федерации; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n38) на компенсацию за использование для служебных поездок личных легковых автомобилей и мотоциклов сверх норм таких расходов, установленных Правительством Российской Федерации; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 22.07.2008 № 158-ФЗ; от 23.07.2013 № 248-ФЗ)\n\n39) в виде платы государственному и (или) частному нотариусу за нотариальное оформление сверх тарифов, утвержденных в установленном порядке; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n40) в виде взносов, вкладов и иных обязательных платежей, уплачиваемых некоммерческим организациям и международным организациям, кроме указанных в подпунктах 29 и 30 пункта 1 статьи 264 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n41) на замену бракованных, утративших товарный вид и недостающих экземпляров периодических печатных изданий, а также потери в виде стоимости утратившей товарный вид, бракованной и нереализованной продукции средств массовой информации и книжной продукции, помимо расходов и потерь, указанных в подпунктах 43 и 44 пункта 1 статьи 264 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n42) в виде представительских расходов в части, превышающей их размеры, предусмотренные пунктом 2 статьи 264 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n43) в виде расходов, предусмотренных абзацем пятым пункта 3 статьи 264 настоящего Кодекса; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 29.11.2012 № 206-ФЗ)\n\n44) на приобретение (изготовление) призов, вручаемых победителям розыгрышей таких призов во время проведения массовых рекламных кампаний, на иные виды рекламы, не предусмотренные абзацами вторым - четвертым пункта 4 статьи 264 настоящего Кодекса, сверх установленных абзацем пятым пункта 4 статьи 264 настоящего Кодекса предельных норм, а также расходы рекламодателей на распространение рекламы в информационно-телекоммуникационной сети \"Интернет\", если информация о такой рекламе не была представлена в федеральный орган исполнительной власти, осуществляющий функции по контролю и надзору в сфере средств массовой информации, массовых коммуникаций, информационных технологий и связи, в порядке, установленном статьей 181 Федерального закона от 13 марта 2006 года № 38-ФЗ \"О рекламе\", либо если такая реклама была распространена на информационном ресурсе в информационно-телекоммуникационной сети \"Интернет\", доступ к которому ограничен в соответствии с законодательством Российской Федерации, или на информационном ресурсе иностранного лица, осуществляющего деятельность в информационно-телекоммуникационной сети \"Интернет\" на территории Российской Федерации, не исполнившего требования, запреты и ограничения, предусмотренные Федеральным законом от 1 июля 2021 года № 236-ФЗ \"О деятельности иностранных лиц в информационно-телекоммуникационной сети \"Интернет\" на территории Российской Федерации\" и иным законодательством Российской Федерации; (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 29.11.2024 № 416-ФЗ)\n\n45) в виде сумм отчислений на формирование фондов поддержки научной, научно-технической и инновационной деятельности, созданных в соответствии с Федеральным законом \"О науке и государственной научно-технической политике\", сверх сумм отчислений, предусмотренных подпунктом 6 пункта 2 статьи 262 настоящего Кодекса; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 07.06.2011 № 132-ФЗ)\n\n46) отрицательная разница, полученная от переоценки ценных бумаг по рыночной стоимости; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n47) в виде расходов учредителя доверительного управления, связанных с исполнением договора доверительного управления, если договором доверительного управления предусмотрено, что выгодоприобретателем не является учредитель; (Дополнение пунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n48) в виде расходов, осуществляемых религиозными организациями в связи с совершением религиозных обрядов и церемоний, а также в связи с реализацией религиозной литературы и предметов религиозного назначения; (Дополнение пунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n481) в виде средств, переданных медицинским организациям для оплаты медицинской помощи застрахованным лицам в соответствии с договором на оказание и оплату медицинской помощи по обязательному медицинскому страхованию, заключенным в соответствии с законодательством Российской Федерации об обязательном медицинском страховании; (Дополнение пунктом - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)\n\n482) в виде необходимых расходов управляющей компании, осуществляющей доверительное управление средствами пенсионных накоплений, непосредственно связанных с инвестированием средств пенсионных накоплений, осуществляемых за счет средств пенсионных накоплений и установленных договором доверительного управления средствами пенсионных накоплений; (Дополнение пунктом - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции Федерального закона от 03.07.2019 № 162-ФЗ)\n\n483) в виде сумм, которые направлены организациями, выступающими в качестве страховщиков по обязательному пенсионному страхованию, на пополнение средств пенсионных накоплений, формируемых в соответствии с законодательством Российской Федерации, и которые отражены на пенсионных счетах накопительной пенсии; (Дополнение пунктом - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции федеральных законов от 30.11.2011 № 359-ФЗ; от 29.06.2015 № 177-ФЗ)\n\n484) в виде средств пенсионных накоплений, формируемых в соответствии с законодательством Российской Федерации, передаваемых в соответствии с законодательством Российской Федерации негосударственными пенсионными фондами в Фонд пенсионного и социального страхования Российской Федерации и (или) другой негосударственный пенсионный фонд, которые выступают в качестве страховщика по обязательному пенсионному страхованию; (Дополнение пунктом - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции  федеральных законов от 30.11.2011 № 359-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n485) расходы судовладельцев, связанные с получением доходов, указанных в подпунктах 33 и (или) 332 пункта 1 статьи 251 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 20.12.2005 № 168-ФЗ) (В редакции Федерального закона от 04.06.2018 № 137-ФЗ)\n\n486) расходы банка развития - государственной корпорации; (Дополнение пунктом - Федеральный закон от 17.05.2007 № 83-ФЗ)\n\n487) понесенные налогоплательщиками, являющимися российскими организаторами Олимпийских игр и Паралимпийских игр в соответствии со статьей 3 Федерального закона \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", включая расходы, связанные с инженерными изысканиями при строительстве, архитектурно-строительным проектированием, со строительством, с реконструкцией и организацией эксплуатации олимпийских объектов; (Дополнение пунктом - Федеральный закон от 01.12.2007 № 310-ФЗ)\n\n488) в виде сумм вознаграждений и иных выплат, осуществляемых членам совета директоров; (Дополнение пунктом - Федеральный закон от 22.07.2008 № 158-ФЗ)\n\n489) расходы осуществляющей функции по предоставлению финансовой поддержки на проведение капитального ремонта многоквартирных домов, переселение граждан из аварийного жилищного фонда и модернизацию систем коммунальной инфраструктуры в соответствии с Федеральным законом \"О Фонде содействия реформированию жилищно-коммунального хозяйства\" некоммерческой организации, понесенные в связи с размещением (инвестированием) временно свободных денежных средств; (Дополнение пунктом - Федеральный закон от 01.12.2008 № 225-ФЗ) (В редакции Федерального закона от 29.12.2015 № 398-ФЗ)\n\n4810) в виде выплат потерпевшему, осуществленных в порядке прямого возмещения убытков в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств страховщиком, который застраховал гражданскую ответственность потерпевшего; (Дополнение пунктом - Федеральный закон от 25.12.2008 № 282-ФЗ)\n\n4811) расходы казенных учреждений в связи с исполнением государственных (муниципальных) функций, в том числе с оказанием государственных (муниципальных) услуг (выполнением работ); (Дополнение пунктом - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\n4812) понесенные налогоплательщиками, являющимися российскими маркетинговыми партнерами Международного олимпийского комитета в соответствии со статьей 31 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", в связи с участием в организации и проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в период организации XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, установленный частью 1 статьи 2 указанного Федерального закона; (Дополнение пунктом - Федеральный закон от 30.07.2010 № 242-ФЗ)\n\n4813) расходы, связанные с обеспечением безопасных условий и охраны труда при добыче угля, осуществленные (понесенные) налогоплательщиком и принятые им к вычету в соответствии со статьей 3431 настоящего Кодекса, за исключением расходов, предусмотренных пунктом 5 статьи 3251 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 28.12.2010 № 425-ФЗ)\n\n4814) в виде денежных средств, переданных участником консолидированной группы налогоплательщиков ответственному участнику этой группы для уплаты налога (авансовых платежей, пеней, штрафов) в порядке, установленном настоящим Кодексом для консолидированной группы налогоплательщиков, а также денежных средств, переданных ответственным участником консолидированной группы налогоплательщиков участнику этой группы в связи с уточнением сумм налога (авансовых платежей, пеней, штрафов), подлежащих уплате по этой консолидированной группе налогоплательщиков; (Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n4815) понесенные объединением туроператоров в сфере выездного туризма за счет средств резервного фонда объединения туроператоров в сфере выездного туризма и фондов персональной ответственности туроператоров в сфере выездного туризма, созданных в соответствии с Федеральным законом от 24 ноября 1996 года № 132-ФЗ \"Об основах туристской деятельности в Российской Федерации\"; (Дополнение пунктом - Федеральный закон от 03.05.2012 № 47-ФЗ) (В редакции Федерального закона от 01.05.2016 № 128-ФЗ)\n\n4816) понесенные Организационным комитетом \"Россия-2018\", дочерними организациями Организационного комитета \"Россия-2018\", Российским футбольным союзом, локальной организационной структурой, производителями медиаинформации FIFA, поставщиками товаров (работ, услуг) FIFA, коммерческими партнерами UEFA, поставщиками товаров (работ, услуг) UEFA и вещателями UEFA, определенными Федеральным законом \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года и внесении изменений в отдельные законодательные акты Российской Федерации\" и являющимися российскими организациями, в связи с осуществлением мероприятий, предусмотренных указанным Федеральным законом; (Дополнение пунктом - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции Федерального закона от 01.05.2019 № 101-ФЗ)\n\n4817) понесенные за счет средств сборов за аэронавигационное обслуживание полетов воздушных судов в воздушном пространстве Российской Федерации и (или) за счет средств, полученных из федерального бюджета в качестве компенсации расходов за аэронавигационное обслуживание полетов воздушных судов государственной авиации, освобожденных в соответствии с законодательством Российской Федерации от платы за аэронавигационное обслуживание; (Дополнение пунктом - Федеральный закон от 21.02.2014 № 17-ФЗ)\n\n4818) понесенные автономной некоммерческой организацией, созданной в соответствии с Федеральным законом \"О защите интересов физических лиц, имеющих вклады в б\n\nанках и обособленных структурных подразделениях банков, зарегистрированных и (или) действующих на территории Республики Крым и на территории города федерального значения Севастополя\"; (Дополнение пунктом - Федеральный закон от 20.04.2014 № 78-ФЗ)\n\n4819) в виде стоимости исключительных прав на изобретения, полезные модели, промышленные образцы, программы для электронных вычислительных машин, базы данных, топологии интегральных микросхем, секреты производства (ноу-хау), если эти права ранее получены налогоплательщиком, являвшимся исполнителем государственного контракта, в ходе реализации которого созданы соответствующие результаты интеллектуальной деятельности, от государственного заказчика по договору о безвозмездном отчуждении; (Дополнение пунктом - Федеральный закон от 29.12.2014 № 463-ФЗ)\n\n4820) в виде сумм перечисляемых в федеральный бюджет доходов, указанных в подпункте 52 пункта 1 статьи 251 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 08.03.2015 № 32-ФЗ)\n\n4821) в виде суммы платы в счет возмещения вреда, причиняемого автомобильным дорогам общего пользования федерального значения транспортными средствами, имеющими разрешенную максимальную массу свыше 12 тонн, зарегистрированными в реестре транспортных средств системы взимания платы, в размере, на который в соответствии с пунктом 2 статьи 362 настоящего Кодекса была уменьшена сумма транспортного налога, исчисленного за налоговый (отчетный) период в отношении указанных транспортных средств. Определение суммы указанной платы, не учитываемой при определении налоговой базы по итогам отчетных периодов, производится исходя из суммы авансовых платежей по транспортному налогу, исчисленной налогоплательщиком в соответствии с главой 28 настоящего Кодекса в отношении транспортных средств, имеющих разрешенную максимальную массу свыше 12 тонн, зарегистрированных в реестре транспортных средств системы взимания платы; (Дополнение пунктом - Федеральный закон от 03.07.2016 № 249-ФЗ)\n\n4822) в виде стоимости акций (долей), доходы от реализации которых не учитываются при определении налоговой базы в соответствии с подпунктом 54 пункта 1 статьи 251 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 30.11.2016 № 401-ФЗ) (В редакции  федеральных законов от 27.11.2017 № 335-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n4823) в виде расходов, осуществленных за счет средств, указанных в подпункте 56 пункта 1 статьи 251 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 27.11.2017 № 344-ФЗ)\n\n4824) направленные на восполнение объема средств пенсионных резервов или средств пенсионных накоплений на величину уменьшения средств или величину недополученного дохода негосударственного пенсионного фонда за счет собственных средств согласно пункту 15 статьи 25 Федерального закона от 7 мая 1998 года № 75-ФЗ \"О негосударственных пенсионных фондах\"; (Дополнение пунктом - Федеральный закон от 03.07.2019 № 162-ФЗ)\n\n4825) в виде расходов, связанных с выполнением функций агента Российской Федерации в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\" и подлежащих компенсации за счет доходов, указанных в подпункте 59 пункта 1 статьи 251 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n4826) (Дополнение пунктом - Федеральный закон от 22.04.2020 № 121-ФЗ) (Утратил силу  - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n4827) в виде расходов на научные исследования и (или) опытно-конструкторские разработки, в отношении которых налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в соответствии со статьей 2861 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n4828) расходы, произведенные налогоплательщиком, имеющим статус международной холдинговой компании, в связи с получением доходов от участия в реализации проектов по геологическому изучению, разведке, добыче полезных ископаемых и иных работ, предусмотренных указанными проектами, при условии, что такие проекты осуществляются в соответствии с соглашениями о разделе продукции, концессионными соглашениями, лицензионными соглашениями или иными соглашениями (контрактами) на условиях риска, которые не учитываются при определении налоговой базы в соответствии с пунктом 4 статьи 251 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n4829) расходы международной холдинговой компании в виде отрицательной курсовой разницы, возникающей при уценке имущества в виде валютных ценностей (за исключением ценных бумаг, номинированных в иностранной валюте) и требований, стоимость которых выражена в иностранной валюте, или при дооценке обязательств, стоимость которых выражена в иностранной валюте; (Дополнение пунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n4830) в виде расходов на оплату работ (услуг) по установке, тестированию, адаптации, модификации программ для ЭВМ, баз данных и (или) объектов основных средств, а также расходов на обучение работников, обслуживающих указанные программы, базы данных и (или) объекты основных средств, в отношении которых налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в соответствии со статьей 2861 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n4831) в виде расходов, указанных в подпункте 8 пункта 2 статьи 2861 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n4832) в виде расходов организаций, доля участия в которых указанной в подпункте 22 пункта 2 статьи 251 настоящего Кодекса некоммерческой организации составляет не менее 50 процентов, понесенных за счет имущества (в том числе денежных средств), полученного от указанной некоммерческой организации на осуществление мероприятий, предусмотренных программой развития генетических технологий и (или) соглашением о развитии генетических технологий; (Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n4833) расходы, связанные с получением и реализацией имущества, доходы от реализации которого указаны в подпункте 65 пункта 1 статьи 251 настоящего Кодекса, а также расходы, осуществленные за счет указанных доходов; (Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n4834) расходы в виде стоимости облигаций иностранных организаций (еврооблигаций) и государственных ценных бумаг Российской Федерации, номинальная стоимость которых указана в иностранной валюте (еврооблигаций Российской Федерации), при их обмене (замещении) соответственно на замещающие облигации или замещающие еврооблигации Российской Федерации.\n\nДанное положение применяется держателями еврооблигаций или еврооблигаций Российской Федерации, если такие ценные бумаги принадлежали им на праве собственности или ином вещном праве на 1 марта 2022 года;\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n4835) в виде стоимости имущества, переданного в рамках операций, предусмотренных подпунктом 161 пункта 1 статьи 164 настоящего Кодекса, за исключением такого имущества, приобретенного по договору купли-продажи, порядок признания расходов по которому предусмотрен подпунктом 19 пункта 7 статьи 272 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 14.11.2023 № 538-ФЗ)\n\n49) иные расходы, не соответствующие критериям, указанным в пункте 1 статьи 252 настоящего Кодекса.","article_title":"Статья 270. Расходы, не учитываемые в целях налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c47efa73796940fd48901224eb72fe515423022722ff243bdd23f46167788d61"},{"code_id":"NK_RF_2","article_number":"271","version_date":"2000-07-31","article_text":"Если на участке недр выделено более одного нового морского месторождения углеводородного сырья, сумма доходов до даты выделения на участке недр новых морских месторождений углеводородного сырья, относящихся к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, осуществляемой на каждом новом месторождении на этом участке недр, определяется с учетом положений пункта 3 статьи 2993 настоящего Кодекса.\n\nУказанные в настоящем пункте доходы, выраженные в иностранной валюте, для целей налогообложения пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на даты, соответствующие датам признания аналогичных видов доходов в соответствии с пунктами 3 - 6 настоящей статьи, без учета положений абзаца первого настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nПо производствам с длительным (более одного налогового периода) технологическим циклом в случае, если условиями заключенных договоров не предусмотрена поэтапная сдача работ (услуг), доход от реализации указанных работ (услуг) распределяется налогоплательщиком самостоятельно в соответствии с принципом формирования расходов по указанным работам (услугам). (Дополнение абзацем - Федеральный закон от 31.12.2002 № 191-ФЗ)\n\nДатой реализации недвижимого имущества признается дата передачи недвижимого имущества приобретателю этого имущества по передаточному акту или иному документу о передаче недвижимого имущества. (Дополнение абзацем - Федеральный закон от 29.11.2012 № 206-ФЗ)\n\nДатой реализации принадлежащих налогоплательщику ценных бумаг также признается: (Дополнение абзацем - Федеральный закон от 25.11.2009 № 281-ФЗ) (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nдата прекращения обязательств по передаче ценных бумаг зачетом встречных однородных требований; (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nдата, определяемая в соответствии с пунктом 2 статьи 273 настоящего Кодекса, - для дохода от погашения долговых ценных бумаг, выпущенных в соответствии с законодательством иностранного государства, права на которые учитываются в реестре владельцев ценных бумаг, ведение которого осуществляют иностранные организации в соответствии с законодательством иностранного государства; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nдата фактического получения налогоплательщиком сумм частичного погашения номинальной стоимости ценной бумаги в период ее обращения, предусмотренного условиями выпуска. (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nВ целях настоящей главы однородными признаются требования по передаче имеющих одинаковый объем прав ценных бумаг одного эмитента, одного вида, одной категории (типа) или одного паевого инвестиционного фонда (для инвестиционных паев паевых инвестиционных фондов). (Дополнение абзацем - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\nПри этом зачет встречных однородных требований должен подтверждаться документами в соответствии с законодательством Российской Федерации о прекращении обязательств по передаче (принятию) ценных бумаг, в том числе отчетами клиринговой организации, лиц, осуществляющих брокерскую деятельность, или управляющих, которые в соответствии с законодательством Российской Федерации оказывают налогоплательщику клиринговые, брокерские услуги или осуществляют доверительное управление в интересах налогоплательщика. (Дополнение абзацем - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\nДенежные средства, полученные налогоплательщиком - обладателем цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, в результате выкупа цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, признаются в составе доходов на дату выкупа этих цифровых финансовых активов и (или) цифровых прав.\n\nДоходы в виде денежных средств, полученных налогоплательщиком, являющимся лицом, выпустившим цифровые финансовые активы и (или) цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права, в оплату этих цифровых финансовых активов и (или) цифровых прав, решением о выпуске которых срок выкупа не определен или составляет более 10 лет, признаются на дату истечения десятилетнего срока с даты выпуска этих цифровых финансовых активов и (или) цифровых прав.\n\nДоходы в виде денежных средств, полученных налогоплательщиком, являющимся лицом, выпустившим цифровые финансовые активы и (или) цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права, в оплату этих цифровых финансовых активов или цифровых прав, по которым не предполагается выкуп, признаются на дату получения денежных средств.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n1) дата подписания сторонами акта приема-передачи имущества (приемки-сдачи работ, услуг) - для доходов: (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nабзац; (Исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nв виде безвозмездно полученного имущества (работ, услуг);\n\nпо иным аналогичным доходам;\n\n2) дата поступления денежных средств на расчетный счет (на счет цифрового рубля, в кассу) налогоплательщика - для доходов: (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nв виде дивидендов от долевого участия в деятельности других организаций;\n\nв виде безвозмездно полученных денежных средств;\n\nв виде сумм возврата ранее уплаченных некоммерческим организациям взносов, которые были включены в состав расходов;\n\nв виде процентов, начисляемых на сумму требований конкурсного кредитора в соответствии с законодательством о несостоятельности (банкротстве); (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nв виде иных аналогичных доходов;\n\n(Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n21) дата получения недвижимого имущества по передаточному акту или иному документу о передаче (подтверждающему передачу) недвижимого имущества, дата перехода права собственности на иное имущество (в том числе ценные бумаги) - для доходов в виде дивидендов, полученных в неденежной форме; (Дополнение подпунктом - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\n3) дата осуществления расчетов в соответствии с условиями заключенных договоров или предъявления налогоплательщику документов, служащих основанием для произведения расчетов, либо последний день отчетного (налогового) периода - для доходов:\n\nот сдачи имущества в аренду;\n\nв виде лицензионных платежей (включая роялти) за пользование объектами интеллектуальной собственности;\n\nв виде иных аналогичных доходов;\n\n(Подпункт в редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n4) дата признания должником либо дата вступления в законную силу решения суда - по доходам в виде штрафов, пеней и (или) иных санкций за нарушение договорных или долговых обязательств, а также в виде сумм возмещения убытков (ущерба), если иное не предусмотрено подпунктами 145 и 15 настоящего пункта; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 23.11.2020 № 374-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n5) последний день отчетного (налогового) периода - по доходам:\n\nв виде сумм восстановленных резервов и иным аналогичным доходам;\n\nв виде распределенного в пользу налогоплательщика при его участии в простом товариществе дохода;\n\nпо доходам от доверительного управления имуществом;\n\nпо иным аналогичным доходам;\n\n6) дата выявления дохода (получения и (или) обнаружения документов, подтверждающих наличие дохода) - по доходам прошлых лет;\n\n7) дата перехода права собственности на иностранную валюту и драгоценные металлы при совершении операций с иностранной валютой и драгоценными металлами (в том числе по обезличенным металлическим счетам), а также последнее число текущего месяца - по доходам в виде положительной курсовой разницы по имуществу и требованиям (обязательствам), стоимость которых выражена в иностранной валюте (за исключением авансов), и положительной переоценки стоимости драгоценных металлов и требований (обязательств), выраженных в драгоценных металлах, осуществляемой в порядке, установленном нормативными актами Центрального банка Российской Федерации, если иное не предусмотрено подпунктом 71 настоящего пункта; (В редакции федеральных законов от 28.11.2015 № 328-ФЗ, от 26.03.2022 № 67-ФЗ)\n\n71) дата прекращения (исполнения) требований (обязательств), выраженных в иностранной валюте, при дооценке (уценке) которых возникает положительная курсовая разница, - по доходам в виде положительной курсовой разницы, возникшей в налоговых (отчетных) периодах 2022 - 2027 годов по требованиям (обязательствам), в том числе по требованиям по договору банковского вклада (депозита), стоимость которых выражена в иностранной валюте (за исключением авансов); (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 67-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n8) дата составления акта ликвидации амортизируемого имущества, оформленного в соответствии с требованиями к бухгалтерскому учету, - по доходам в виде полученных материалов или иного имущества при ликвидации выводимого из эксплуатации амортизируемого имущества; (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\n9) дата, когда получатель имуще\n\nства (в том числе денежных средств) фактически использовал указанное имущество (в том числе денежные средства) не по целевому назначению либо нарушил условия, на которых они предоставлялись, - для доходов в виде имущества (в том числе денежных средств), указанных в пунктах 14, 15 статьи 250 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n10) дата перехода права собственности на иностранную валюту для доходов от продажи (покупки) иностранной валюты; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n11) датой получения дохода в виде денежного эквивалента имущества, переданного на пополнение целевого капитала некоммерческой организации в установленном Федеральным законом от 30 декабря 2006 года № 275-ФЗ \"О порядке формирования и использования целевого капитала некоммерческих организаций\" порядке и возвращенного жертвователю или его правопреемникам, признается дата зачисления денежных средств на расчетный счет, счет цифрового рубля налогоплательщика; (Дополнение подпунктом - Федеральный закон от 21.11.2011 № 328-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n12) датой получения дохода в виде прибыли контролируемой иностранной компании признается 31 декабря календарного года, следующего за налоговым периодом, на который приходится дата окончания периода, за который в соответствии с личным законом такой компании составляется финансовая отчетность за финансовый год, а в случае отсутствия в соответствии с личным законом такой компании обязанности по составлению и представлению финансовой отчетности - 31 декабря календарного года, следующего за налоговым периодом, на который приходится дата окончания календарного года, за который определяется ее прибыль; (Дополнение подпунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n13) дата представления в налоговый орган налоговой декларации по акцизам в части операций, указанных в пункте 24 части второй статьи 250 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n14) дата уплаты процентов для доходов в виде процентов по кредитному договору:\n\nпредусмотренная кредитным договором, заключенным специализированным застройщиком с уполномоченным банком, на предоставление целевого кредита в соответствии с Федеральным законом от 30 декабря 2004 года № 214-ФЗ \"Об участии в долевом строительстве многоквартирных домов и иных объектов недвижимости и о внесении изменений в некоторые законодательные акты Российской Федерации\";\n\nустановленная при изменении условий кредитного договора в соответствии с Федеральным законом от 3 апреля 2020 года № 106-ФЗ \"О внесении изменений в Федеральный закон \"О Центральном банке Российской Федерации (Банке России)\" и отдельные законодательные акты Российской Федерации в части особенностей изменения условий кредитного договора, договора займа\";\n\nпредусмотренная кредитным договором, указанным в пункте 622 статьи 217 или подпункте 214 пункта 1 статьи 251 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 13.07.2020 № 204-ФЗ)\n\n141) дата поступления денежных средств, но не позднее 31 марта 2024 года - для доходов в виде процентов, начисленных в 2022 и 2023 годах, по долговым ценным бумагам, выпущенным в соответствии с законодательством иностранного государства, права на которые учитываются в реестре владельцев ценных бумаг, ведение которого осуществляют иностранные организации в соответствии с законодательством иностранного государства; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n142) дата, на которую в соответствии с соглашением о сервисных рисках либо соглашением об управлении финансированием распределяются добытые полезные ископаемые либо денежные средства или иное имущество, полученные от реализации добытых полезных ископаемых, - для доходов, указанных в пункте 30 части второй статьи 250 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n143) последняя дата отчетного (налогового) периода, в котором заключено соглашение о сервисных рисках либо соглашение об управлении финансированием, - для доходов, указанных в пункте 31 части второй статьи 250 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n144) дата, определяемая в соответствии с пунктом 2 статьи 273 настоящего Кодекса, но не позднее 31 декабря 2029 года - для доходов в виде процентов, начисленных в 2023 - 2029 годах, по долговым обязательствам иностранной организации перед налогоплательщиком, доля прямого участия которого в этой иностранной организации составляет более 50 процентов, если в отношении этой иностранной организации в соответствии с законодательством и (или) решениями судов иностранного государства после 5 марта 2022 года были установлены ограничительные меры, в результате которых прекращается начисление процентов по обязательствам этой иностранной организации перед налогоплательщиком. В целях настоящего подпункта для доходов в виде процентов, причисленных к основной сумме долга, датой получения дохода считается дата погашения основной суммы долга; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ) (В редакции  Федерального закона от 23.07.2025 № 227-ФЗ)\n\n145) дата поступления денежных средств (имущества, имущественных прав), но не позднее 31 декабря 2026 года - по доходам в виде штрафов, пеней и (или) иных санкций за нарушение договорных или долговых обязательств, а также в виде сумм возмещения убытков (ущерба), подлежащих уплате на основании решения суда, вступившего в законную силу, но не ранее 5 марта 2022 года, иностранной организацией, местом регистрации которой является государство, совершающее в отношении Российской Федерации, российских юридических и физических лиц недружественные действия, и (или) российской организацией, являющейся солидарным ответчиком этой иностранной организации; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n146) дата поступления денежных средств - для доходов в виде процентов, начисленных по долговым ценным бумагам, выпущенным в соответствии с законодательством иностранного государства, права на которые учитываются в реестре владельцев ценных бумаг, ведение которого осуществляют иностранные организации в соответствии с законодательством иностранного государства; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n15) дата поступления денежных средств (имущества, имущественных прав) для доходов в виде сумм возмещения убытков или ущерба, признанных должником или подлежащих уплате должником в пользу кредитной организации на основании решения суда, вступившего в законную силу, причиненных действиями (бездействием) лиц, контролирующих кредитную организацию, в отношении которой осуществлены (осуществляются) меры по предупреждению банкротства с участием Центрального банка Российской Федерации или государственной корпорации \"Агентство по страхованию вкладов\", предусмотренные Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\"; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n16) дата, на которую у лица, выпустившего цифровые финансовые активы и (или) цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права, возникают обязательства, предусмотренные решением о выпуске этих цифровых финансовых активов и (или) цифровых прав, - для доходов в виде денежных средств, причитающихся к получению налогоплательщиком - обладателем этих цифровых финансовых активов и (или) цифровых прав в связи с исполнением лицом, выпустившим эти цифровые финансовые активы и (или) цифровые права, обязательств, не связанных с выкупом этих цифровых финансовых активов и (или) цифровых прав; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n17) дата, установленная для представления в налоговый орган налоговой декларации по налогу на добавленную стоимость, в которой налогоплательщиком заявлены к вычету суммы налога на добавленную стоимость, предъявленные ему лицом, выпустившим цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права, - для доходов, указанных в пункте 27 части второй статьи 250 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n18) последняя дата каждого месяца пятилетнего периода начиная с 1 января 2025 года - для доходов, указанных в пункте 28 статьи 250 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n181) последняя дата каждого месяца, приходящегося на период начиная с 1 апреля 2029 года по 31 марта 2035 года включительно, - для доходов, указанных в пункте 281 части второй статьи 250 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 23.02.2023 № 36-ФЗ)\n\n19) 1 января года, следующего за годом, в котором в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, было представлено уведомление, указанное в статье 2518 настоящего Кодекса, - для доходов, указанных в пункте 29 части второй статьи 250 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\n20) дата, на которую у лица, осуществляющего майнинг цифровой валюты, возникает право распоряжаться такой цифровой валютой. (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\nсубсидии, полученные на финансирование расходов, не связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, учитываются по мере признания расходов, фактически осуществленных за счет этих средств; (В редакции Федерального закона от 15.04.2019 № 63-ФЗ)\n\nсубсидии, полученные на финансирование расходов, связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, учитываются по мере признания расходов, фактически осуществленных за счет этих средств. При реализации, ликвидации или ином выбытии указанного имущества, имущественных прав полученные субсидии, не учтенные в составе доходов, признаются внереализационными доходами на последнюю дату отчетного (налогового) периода, в котором произошли реализация, ликвидация или иное выбытие указанного имущества, имущественных прав;\n\nсубсидии, полученные на компенсацию ранее произведенных расходов, не связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, или недополученных доходов, учитываются единовременно на дату их зачисления;\n\nсубсидии, полученные на компенсацию ранее произведенных расходов, связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, учитываются единовременно на дату их зачисления в сумме, соответствующей сумме начисленной амортизации по ранее произведенным расходам, связанным с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав. Разница между суммой полученных субсидий и суммой, учтенной в составе доходов на дату их зачисления, отражается в составе доходов в порядке, аналогичном порядку, предусмотренному абзацем третьим настоящего пункта.\n\nВ случае нарушения условий получения субсидий, предусмотренных настоящим пунктом, суммы полученных субсидий в полном объеме отражаются в составе доходов налогового периода, в котором допущено нарушение.\n\nДенежные средства, полученные от концедента по концессионному соглашению, а также денежные средства, полученные от публичного партнера по соглашению о государственно-частном партнерстве, соглашению о муниципально-частном партнерстве, признаются в порядке, предусмотренном настоящим пунктом для учета субсидий. (Дополнение абзацем - Федеральный закон от 30.09.2017 № 286-ФЗ) (В редакции Федерального закона от 25.12.2018 № 493-ФЗ)\n\nДенежные средства, полученные налогоплательщиком из бюджетов бюджетной системы Российской Федерации, в том числе через третьих лиц, в целях финансирования выполняемых работ по переносу, переустройству объектов основных средств, принадлежащих налогоплательщику на праве собственности, хозяйственного ведения или оперативного управления, в связи с созданием или реконструкцией иного объекта (объектов) капитального строительства либо линейных объектов государственной или муниципальной собственности, финансируемых полностью или частично за счет средств бюджетов бюджетной системы Российской Федерации, признаются в порядке, предусмотренном настоящим пунктом для учета субсидий. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 05.04.2010 № 41-ФЗ) (В редакции Федерального закона от 29.12.2014 № 465-ФЗ)\n\nВ случае, если договором займа или иным аналогичным договором (включая долговые обязательства, оформленные ценными бумагами) предусмотрено, что исполнение обязательства по такому договору зависит от стоимости (или иного значения) базового актива с начислением в период действия договора фиксированной процентной ставки, доходы, начисленные исходя из этой фиксированной ставки, признаются на последнее число каждого месяца соответствующего отчетного (налогового) периода, а доходы, фактически полученные исходя из сложившейся стоимости (или иного значения) базового актива, признаются на дату исполнения обязательства по этому договору.\n\nВ случае прекращения действия договора (погашения долгового обязательства) в течение календарного месяца доход признается полученным и включается в состав соответствующих доходов на дату прекращения действия договора (погашения долгового обязательства).\n\nПоложения настоящего пункта не применяются к доходам в виде процентов, начисляемых на сумму требований конкурсного кредитора в соответствии с законодательством о несостоятельности (банкротстве).\n\nНезависимо от положений абзацев первого - третьего настоящего пункта доходы в виде процентов, начисленных по договору займа на финансирование зарубежного геолого-разведочного проекта и не признанных для целей налогообложения за период с даты выдачи такого займа по последнее число месяца, на который приходится дата принятия решения по такому зарубежному геолого-разведочному проекту, учитываются для целей налогообложения одним из следующих способов: (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв случае прекращения обязательств по договору займа на финансирование зарубежного геолого-разведочного проекта в полном объеме без удовлетворения имущественных требований налогоплательщика в связи с окончанием работ на указанном зарубежном геолого-разведочном проекте и признанием такого проекта экономически нецелесообразным и (или) геологически бесперспективным не учитываются для целей налогообложения; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв случае несоответствия договора займа на финансирование зарубежного геолого-разведочного проекта одному из условий, указанных в пункте 11 статьи 261 настоящего Кодекса, учитываются в полном объеме на 1-е число месяца, следующего за месяцем, в котором такое условие было нарушено; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв иных случаях учитываются равномерно в течение двух лет начиная с месяца, следующего за месяцем, на который приходится дата принятия решения по зарубежному геолого-разведочному проекту. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nДатой принятия решения по зарубежному геолого-разведочному проекту признается наиболее ранняя из следующих дат: (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nдата принятия налогоплательщиком решения об успешности зарубежного геолого-разведочного проекта; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nдата прекращения обязательств по договору займа на финансирование зарубежного геолого-разведочного проекта в полном объеме без удовлетворения имущественных требований налогоплательщика в связи с окончанием работ на указанном зарубежном геолого-разведочном проекте и признанием такого проекта экономически нецелесообразным и (или) геологически бесперспективным; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nдата прекращения (частичного прекращения) обязательств по договору займа на финансирование зарубежного геолого-разведочного проекта; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nдата, на которую в отношении договора займа на финансирование зарубежного геолого-разведочного проекта было нарушено одно из условий, указанных в пункте 11 статьи 261 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nпоследнее число месяца, в котором истекают семь последовательных календарных лет с даты выдачи займа на финансирование зарубежного геолого-разведочного проекта. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nПризнание зарубежного геолого-разведочного проекта успешным или экономически нецелесообразным и (или) геологически бесперспективным осуществляется налогоплательщиком самостоятельно в порядке, аналогичном порядку, установленному пунктом 10 статьи 261 настоящего Кодекса в отношении решения, указанного в абзаце пятом пункта 11 статьи 261 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nДоходы в виде процентов, фактически полученные (как в денежной, так и в натуральной форме, в том числе путем зачета встречных требований и обязательств) налогоплательщиком по договору займа на финансирование зарубежного геолого-разведочного проекта в период с даты выдачи такого займа по последнее число месяца, на который приходится дата принятия решения по такому зарубежному геолого-разведочному проекту, признаются на дату и\n\nх получения, определяемую в порядке, установленном пунктом 2 статьи 273 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nТребования (обязательства), стоимость которых выражена в иностранной валюте, имущество в виде валютных ценностей пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату перехода права собственности на указанное имущество, прекращения (исполнения) требований (обязательств) и (или) на последнее число текущего месяца в зависимости от того, что произошло раньше.\n\nЕсли при пересчете выраженной в иностранной валюте (условных денежных единицах) стоимости требований (обязательств), подлежащих оплате в рублях, применяется иной курс иностранной валюты, установленный законом или соглашением сторон, пересчет доходов, требований (обязательств) в соответствии с настоящим пунктом производится по такому курсу.\n\nВ случае получения аванса, задатка доходы, выраженные в иностранной валюте, пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату получения аванса, задатка (в части, приходящейся на аванс, задаток).\n\nТребования, стоимость которых выражена в иностранной валюте, по договору займа на финансирование зарубежного геолого-разведочного проекта (включая задолженность по начисленным процентам) пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату принятия решения по зарубежному геолого-разведочному проекту, определяемую в порядке, установленном пунктом 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nДоходы в виде положительной курсовой разницы, возникающей в результате пересчета требований по договору займа на финансирование зарубежного геолого-разведочного проекта на дату принятия решения по зарубежному геолого-разведочному проекту, признаются в составе внереализационных доходов одним из следующих способов: (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв случае прекращения обязательств по такому договору займа в полном объеме без удовлетворения имущественных требований налогоплательщика в связи с окончанием работ на указанном зарубежном геолого-разведочном проекте и признанием такого проекта экономически нецелесообразным и (или) геологически бесперспективным не учитываются для целей налогообложения; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв случае несоответствия договора займа на финансирование зарубежного геолого-разведочного проекта одному из условий, указанных в пункте 11 статьи 261 настоящего Кодекса, учитываются в полном объеме на дату, когда такое условие было нарушено; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв иных случаях учитываются равномерно в течение двух лет начиная с месяца, следующего за месяцем, на который приходится дата принятия решения по зарубежному геолого-разведочному проекту. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nНачиная со дня, следующего за датой принятия решения по зарубежному геолого-разведочному проекту, пересчет требований, стоимость которых выражена в иностранной валюте, по соответствующему договору займа на финансирование зарубежного геолого-разведочного проекта в рубли производится в общем порядке, установленном абзацами первым - четвертым настоящего пункта. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\n(Пункт в редакции Федерального закона от 20.04.2014 № 81-ФЗ)","article_title":"Статья 271. Порядок признания доходов при методе начисления","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d75f6fb1ae23af42f793e23791f50d20c3b80b61a1b3209db02fe7c0e1e088f6"},{"code_id":"NK_RF_2","article_number":"272","version_date":"2000-07-31","article_text":"Расходы признаются в том отчетном (налоговом) периоде, в котором эти расходы возникают исходя из условий сделок. В случае, если сделка не содержит таких условий и связь между доходами и расходами не может быть определена четко или определяется косвенным путем, расходы распределяются налогоплательщиком самостоятельно. (В редакции федеральных законов от 31.12.2002 № 191-ФЗ; от 06.06.2005 № 58-ФЗ)\n\nВ случае, если условиями договора предусмотрено получение доходов в течение более чем одного отчетного периода и не предусмотрена поэтапная сдача товаров (работ, услуг), расходы распределяются налогоплательщиком самостоятельно с учетом принципа равномерности признания доходов и расходов. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nРасходы налогоплательщика, которые не могут быть непосредственно отнесены на затраты по конкретному виду деятельности, распределяются пропорционально доле соответствующего дохода в суммарном объеме всех доходов налогоплательщика. Данный порядок не применяется к расходам некоммерческих организаций, относящимся к уставной некоммерческой деятельности, которые должны осуществляться за счет средств целевого финансирования и (или) целевых поступлений, не учитываемых при определении налоговой базы. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nЕсли на участке недр выделено более одного нового морского месторождения углеводородного сырья, сумма расходов до даты выделения на участке недр новых морских месторождений углеводородного сырья, относящихся к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, осуществляемой на каждом новом морском месторождении на этом участке недр, определяется с учетом положений пункта 4 статьи 2994 настоящего Кодекса.\n\nУказанные в настоящем пункте расходы, выраженные в иностранной валюте, для целей налогообложения пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на даты, соответствующие датам признания аналогичных видов расходов в соответствии с пунктами 2 - 81 настоящей статьи, без учета положений абзаца первого настоящего пункта, а также положений пунктов 7 и 8 статьи 261 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nдата передачи в производство сырья и материалов - в части сырья и материалов, приходящихся на произведенные товары (работы, услуги);\n\nдата подписания налогоплательщиком акта приемки-передачи услуг (работ) - для услуг (работ) производственного характера.\n\nРасходы в виде капитальных вложений, предусмотренные пунктом 9 статьи 258 настоящего Кодекса, признаются в качестве косвенных расходов того отчетного (налогового) периода, на который в соответствии с настоящей главой приходится дата начала амортизации (дата изменения первоначальной стоимости) основных средств, в отношении которых были осуществлены капитальные вложения. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ) (В редакции Федерального закона от 22.07.2008 № 158-ФЗ)\n\nДенежные средства, переданные лицом, выпустившим цифровые финансовые активы и (или) цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права, при выкупе этих цифровых финансовых активов и (или) цифровых прав, признаются в составе расходов на дату выкупа этих цифровых финансовых активов и (или) цифровых прав.\n\nРасходы в виде денежных средств, переданных в оплату цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, лицу, выпустившему эти цифровые финансовые активы или цифровые права, по которым не предполагается выкуп, но решением о выпуске которых определен срок, по истечении которого права, удостоверенные этими цифровыми финансовыми активами или цифровыми правами, прекращаются, учитываются равномерно в течение указанного срока, если ранее не произойдет реализация этих цифровых финансовых активов или цифровых прав.\n\nРасходы на приобретение цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, по которым не предполагается выкуп, но решением о выпуске которых определен срок, по истечении которого права, удостоверенные этими цифровыми финансовыми активами и цифровыми правами, прекращаются, учитываются равномерно с даты приобретения этих цифровых финансовых активов или цифровых прав до даты прекращения прав, удостоверенных этими цифровыми финансовыми активами и (или) цифровыми правами, если ранее не произойдет реализация этих цифровых финансовых активов или цифровых прав.\n\nЕсли срок, указанный в абзацах третьем и четвертом настоящего пункта, не определен, данные расходы признаются на дату реализации цифровых финансовых активов или цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n1) дата начисления налогов (сборов, страховых взносов) - для расходов в виде сумм налогов (авансовых платежей по налогам), сборов, страховых взносов и иных обязательных платежей; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 30.11.2016 № 401-ФЗ)\n\n2) дата начисления в соответствии с требованиями настоящей главы - для расходов в виде сумм отчислений в резервы, признаваемые расходом в соответствии с настоящей главой; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n3) дата расчетов в соответствии с условиями заключенных договоров или дата предъявления налогоплательщику документов, служащих основанием для произведения расчетов, либо последнее число отчетного (налогового) периода - для расходов: (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nв виде сумм комиссионных сборов;\n\nв виде расходов на оплату сторонним организациям за выполненные ими работы (предоставленные услуги);\n\nв виде арендных (лизинговых) платежей за арендуемое (принятое в лизинг) имущество;\n\nв виде иных подобных расходов;\n\n(Подпункт в редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n4) дата перечисления денежных средств с расчетного счета, счета цифрового рубля (выплаты из кассы) налогоплательщика - для расходов: (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nв виде сумм выплаченных подъемных;\n\nв виде компенсации за использование для служебных поездок личных легковых автомобилей и мотоциклов; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nв виде процентов, начисляемых на сумму требований конкурсного кредитора в соответствии с законодательством о несостоятельности (банкротстве); (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n5) дата утверждения авансового отчета - для расходов:\n\nна командировки;\n\nна содержание служебного транспорта;\n\nна представительские расходы;\n\nна иные подобные расходы;\n\n(Подпункт в редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n6) дата перехода права собственности на иностранную валюту и драгоценные металлы при совершении операций с иностранной валютой и драгоценными металлами (в том числе по обезличенным металлическим счетам), а также последнее число текущего месяца - по расходам в виде отрицательной курсовой разницы по имуществу и требованиям (обязательствам), стоимость которых выражена в иностранной валюте (за исключением авансов), и отрицательной переоценки стоимости драгоценных металлов и требований (обязательств), выраженных в драгоценных металлах, осуществляемой в порядке, установленном нормативными актами Центрального банка Российской Федерации, если иное не предусмотрено подпунктами 61 и 62 настоящего пункта; (В редакции  федеральных законов от 28.11.2015 № 328-ФЗ, от 19.12.2022 № 523-ФЗ)\n\n61) дата прекращения (исполнения) требований (обязательств), выраженных в иностранной валюте, при уценке (дооценке) которых возникает отрицательная курсовая разница, - по расходам в виде отрицательной курсовой разницы, возникшей в 2023 - 2027 годах по требованиям (обязательствам), в том числе по требованиям по договору банковского вклада (депозита), стоимость которых выражена в иностранной валюте (за исключением авансов); (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 67-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n62) дата прекращения (исполнения) требований (обязательств), выраженных в иностранной валюте, при уценке (дооценке) которых возникает отрицательная курсовая разница, - по расходам в виде отрицательной курсовой разницы, возникшей в 2022 году, по не прекращенным по состоянию на 31 декабря 2022 года требованиям (обязательствам), в том числе по требованиям по договору банковского вклада (депозита), стоимость которых выражена в иностранной валюте (за исключением авансов), в случае, если налогоплательщиком принято решение о применении порядка учета расходов в соответствии с настоящим подпунктом и в срок, установленный для подачи налоговой декларации по налогу за налоговый период 2022 года, либо при подаче уточненной декларации за последний отчетный период 2022 года в налоговый орган направлено уведомление в произвольной форме о принятии такого решения. При этом принятое налогоплательщиком решение не может быть изменено. Применение налогоплательщиком указанного порядка, повлекшее увеличение сумм авансовых платежей по налогу за отчетные периоды 2022 года, не влечет начисление пеней за просрочку исполнения налогоплательщиком обязанности по уплате соответствующих авансовых платежей при условии уплаты налога за 2022 год не позднее установленного настоящей главой срока уплаты налога. Положения настоящего подпункта не применяются банками; (Дополнение подпунктом - Федеральный закон от 19.12.2022 № 523-ФЗ)\n\n7) дата реализации или иного выбытия ценных бумаг (частичного погашения номинальной стоимости ценной бумаги в период ее обращения, предусмотренного условиями выпуска), в том числе дата прекращения обязательств по передаче ценных бумаг зачетом встречных однородных требований - по расходам, связанным с приобретением ценных бумаг, включая их стоимость; (В редакции федеральных законов от 25.11.2009 № 281-ФЗ; от 28.12.2013 № 420-ФЗ)\n\n8) дата признания должником либо дата вступления в законную силу решения суда - по расходам в виде сумм штрафов, пеней и (или) иных санкций за нарушение договорных или д\n\nолговых обязательств, а также в виде сумм возмещения убытков (ущерба), если иное не предусмотрено подпунктом 81 настоящего пункта; (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n81) дата перечисления денежных средств с расчетного счета (выплаты из кассы), дата передачи имущества, имущественных прав - по расходам в виде сумм штрафов, пеней и (или) иных санкций за нарушение договорных или долговых обязательств, а также в виде сумм возмещения убытков (ущерба), подлежащих уплате на основании решения суда, вступившего в законную силу, но не ранее 5 марта 2022 года, в отношении российской организации, являющейся солидарным ответчиком иностранной организации, местом регистрации которой является государство, совершающее в отношении Российской Федерации, российских юридических и физических лиц недружественные действия; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n9) дата перехода права собственности на иностранную валюту - для расходов от продажи (покупки) иностранной валюты; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n10) дата реализации долей, паев - по расходам в виде стоимости приобретения долей, паев; (Дополнение подпунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\n11) дата передачи в государственную или муниципальную собственность объектов социальной, инженерной, коммунальной и транспортной инфраструктур - по расходам на создание объектов социальной, инженерной, коммунальной и транспортной инфраструктур, безвозмездно передаваемых в государственную или муниципальную собственность; (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 210-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n12) дата уплаты процентов для расходов в виде процентов по кредитному договору:\n\nпредусмотренная кредитным договором, заключенным специализированным застройщиком с уполномоченным банком, на предоставление целевого кредита в соответствии с Федеральным законом от 30 декабря 2004 года № 214-ФЗ \"Об участии в долевом строительстве многоквартирных домов и иных объектов недвижимости и о внесении изменений в некоторые законодательные акты Российской Федерации\";\n\nустановленная при изменении условий кредитного договора в соответствии с Федеральным законом от 3 апреля 2020 года № 106-ФЗ \"О внесении изменений в Федеральный закон \"О Центральном банке Российской Федерации (Банке России)\" и отдельные законодательные акты Российской Федерации в части особенностей изменения условий кредитного договора, договора займа\";\n\nпредусмотренная кредитным договором, указанным в подпункте 214 пункта 1 статьи 251 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 13.07.2020 № 204-ФЗ)\n\n13) дата передачи имущества - для расходов, указанных в подпунктах 195 и 196 пункта 1 статьи 265 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 08.06.2020 № 172-ФЗ)\n\n14) дата, на которую у лица, выпустившего цифровые финансовые активы и (или) цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права, возникают обязательства, предусмотренные решением о выпуске этих цифровых финансовых активов и (или) цифровых прав, для расходов в виде денежных средств, причитающихся к выплате обладателю этих цифровых финансовых активов и (или) цифровых прав, в связи с исполнением лицом, выпустившим эти цифровые финансовые активы и (или) цифровые права, обязательств, не связанных с выкупом этих цифровых финансовых активов и (или) цифровых прав; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n15) последняя дата месяца, в котором применяется налоговый вычет, предусмотренный пунктом 37 статьи 3432 настоящего Кодекса, - для расходов, указанных в подпункте 1910 пункта 1 статьи 265 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n151) последняя дата месяца, в котором применяется налоговый вычет, предусмотренный пунктом 39 статьи 3432 настоящего Кодекса, - для расходов, указанных в подпункте 1910-1 пункта 1 статьи 265 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 23.02.2023 № 36-ФЗ)\n\n16) дата расторжения соглашения о защите и поощрении капиталовложений по соглашению сторон, или дата расторжения соглашения о защите и поощрении капиталовложений, указанная в уведомлении о расторжении такого соглашения в одностороннем внесудебном порядке, направленном публично-правовым образованием, или дата вступления в законную силу решения суда о расторжении такого соглашения - для расходов, указанных в подпункте 1911 пункта 1 статьи 265 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\n17) дата, на которую в соответствии с соглашением о сервисных рисках либо соглашением об управлении финансированием распределяются добытые полезные ископаемые либо денежные средства или иное имущество, полученные от реализации добытых полезных ископаемых, - для расходов, указанных в подпункте 1913 пункта 1 статьи 265 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n18) последняя дата отчетного (налогового) периода, в котором заключено соглашение о сервисных рисках либо соглашение об управлении финансированием, - для расходов, указанных в подпункте 1914 пункта 1 статьи 265 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n19) дата подписания документа, подтверждающего непригодность для эксплуатации и восстановления имущества, полученного в обмен на аналогичное имущество, - для расходов в виде стоимости имущества, приобретенного по договору купли-продажи. (Дополнение подпунктом - Федеральный закон от 14.11.2023 № 538-ФЗ)\n\nВ случае, если договором займа или иным аналогичным договором (включая долговые обязательства, оформленные ценными бумагами) предусмотрено, что исполнение обязательства по такому договору зависит от стоимости (или иного значения) базового актива с начислением в период действия договора фиксированной процентной ставки, расходы, начисленные исходя из этой фиксированной ставки, признаются на последнее число каждого месяца соответствующего отчетного (налогового) периода, а расходы, фактически понесенные исходя из сложившейся стоимости (или иного значения) базового актива, признаются на дату исполнения обязательства по этому договору.\n\nВ случае прекращения действия договора (погашения долгового обязательства) в течение календарного месяца расход признается осуществленным и включается в состав соответствующих расходов на дату прекращения действия договора (погашения долгового обязательства).\n\nПоложения настоящего пункта не применяются к расходам в виде процентов, начисляемых на сумму требований конкурсного кредитора в соответствии с законодательством о несостоятельности (банкротстве).\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\n10. Расходы, выраженные в иностранной валюте, для целей налогообложения пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату признания соответствующего расхода, если иное не установлено настоящим пунктом.\n\nТребования (обязательства), стоимость которых выражена в иностранной валюте, имущество в виде валютных ценностей пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату перехода права собственности на указанное имущество, прекращения (исполнения) требований (обязательств) и (или) на последнее число текущего месяца в зависимости от того, что произошло раньше.\n\nЕсли при пересчете выраженной в иностранной валюте (условных денежных единицах) стоимости требований (обязательств), подлежащих оплате в рублях, применяется иной курс иностранной валюты, установленный законом или соглашением сторон, пересчет расходов, требований (обязательств) в соответствии с настоящим пунктом производится по такому курсу.\n\nВ случае перечисления аванса, задатка расходы, выраженные в иностранной валюте, пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату перечисления аванса, задатка (в части, приходящейся на аванс, задаток).\n\nТребования, стоимость которых выражена в иностранной валюте, по договору займа на финансирование зарубежного геолого-разведочного проекта (включая задолженность по начисленным процентам) пересчитываются в рубли по официальному курсу, установленному Центральным банком Российской Федерации на дату принятия решения по зарубежному геолого-разведочному проекту, определяемую в порядке, установленном пунктом 6 статьи 271 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nРасходы в виде отрицательной курсовой разницы, возникающей в результате пересчета требований по договору займа на финансирование зарубежного геолого-разведочного проекта на дату принятия решения по зарубежному геолого-разведочному проекту, признаются в составе внереализационных расходов одним из следующих способов: (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв случае прекращения обязательств по договору займа на финансирование зарубежного геолого-разведочного проекта в полном объеме без удовлетворения имущественных требований налогоплательщика в связи с окончанием работ на указанном зарубежном геолого-разведочном проекте и признанием такого проекта экономически нецелесообразным и (или) геологически бесперспективным не учитываются для целей налогообложения; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв случае несоответствия договора займа на финансирование зарубежного геолого-разведочного проекта любому из условий, указанных в пункте 11 статьи 261 настоящего Кодекса, учитываются в полном объеме на дату, когда такое условие было нарушено; (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nв иных случаях учитываются равномерно в течение двух лет начиная с месяца, следующего за месяцем, на который приходится дата принятия решения по зарубежному геолого-разведочному проекту. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nНачиная со дня, следующего за датой принятия решения по зарубежному геолого-разведочному проекту, пересчет требований, стоимость которых выражена в иностранной валюте, по соответствующему договору займа на финансирование зарубежного геолого-разведочного проекта в рубли производится в общем порядке, установленном абзацами первым - четвертым настоящего пункта. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 20.04.2014 № 81-ФЗ)","article_title":"Статья 272. Порядок признания расходов при методе начисления","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"42a5ee406a56bc5bb99600d7784bf4ea0dc449ca6db0b4147937d49962c5e401"},{"code_id":"NK_RF_2","article_number":"273","version_date":"2000-07-31","article_text":"Организации, получившие статус участника проекта по осуществлению исследований, разработок и коммерциализации их результатов в соответствии с Федеральным законом \"Об инновационном центре \"Сколково\" либо участника проекта в соответствии с Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\", определяют дату получения дохода (осуществления расхода) по кассовому методу без учета указанного в абзаце первом настоящего пункта ограничения. (Дополнение абзацем - Федеральный закон от 28.11.2011 № 339-ФЗ) (В редакции федеральных законов от 30.10.2018 № 373-ФЗ; от 29.09.2019 № 325-ФЗ)\n\nсубсидии, полученные на финансирование расходов, не связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, учитываются в течение не более трех налоговых периодов, считая налоговый период, в котором были получены указанные субсидии, по мере признания расходов, фактически осуществленных за счет этих средств. По окончании третьего налогового периода полученные субсидии, не учтенные в составе доходов, признаются внереализационными доходами на последнюю отчетную дату этого налогового периода;\n\nсубсидии, полученные на финансирование расходов, связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, учитываются по мере признания расходов, фактически осуществленных за счет этих средств. При реализации, ликвидации или ином выбытии указанного имущества, имущественных прав полученные субсидии, не учтенные в составе доходов, признаются внереализационными доходами на последнюю дату отчетного (налогового) периода, в котором произошли реализация, ликвидация или иное выбытие указанного имущества, имущественных прав;\n\nсубсидии, полученные на компенсацию ранее произведенных расходов, не связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, или недополученных доходов, учитываются единовременно на дату их зачисления;\n\nсубсидии, полученные на компенсацию ранее произведенных расходов, связанных с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав, учитываются единовременно на дату их зачисления в сумме, соответствующей сумме начисленной амортизации по ранее произведенным расходам, связанным с приобретением, созданием, реконструкцией, модернизацией, техническим перевооружением амортизируемого имущества, приобретением имущественных прав. Разница между суммой полученных субсидий и суммой, учтенной в составе доходов на дату их зачисления, отражается в составе доходов в порядке, аналогичном порядку, предусмотренному абзацем третьим настоящего пункта.\n\nВ случае нарушения условий получения субсидий, предусмотренных настоящим пунктом, суммы полученных субсидий в полном объеме отражаются в составе доходов налогового периода, в котором допущено нарушение.\n\n(Дополнение пунктом - Федеральный закон от 05.04.2010 № 41-ФЗ) (В редакции Федерального закона от 29.12.2014 № 465-ФЗ)\n\nПри этом расходы учитываются в составе расходов с учетом следующих особенностей:\n\n1) материальные расходы, а также расходы на оплату труда учитываются в составе расходов в момент погашения задолженности путем списания денежных средств с расчетного счета, счета цифрового рубля налогоплательщика, выплаты из кассы, а при ином способе погашения задолженности - в момент такого погашения. Аналогичный порядок применяется в отношении оплаты процентов за пользование заемными средствами (включая банковские кредиты) и при оплате услуг третьих лиц. При этом расходы по приобретению сырья и материалов учитываются в составе расходов по мере списания данного сырья и материалов в производство; (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 19.12.2023 № 610-ФЗ)\n\n2) амортизация учитывается в составе расходов в суммах, начисленных за отчетный (налоговый) период. При этом допускается амортизация только оплаченного налогоплательщиком амортизируемого имущества, используемого в производстве. Аналогичный порядок применяется в отношении капитализируемых расходов, предусмотренных статьями 261, 262 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n3) расходы на уплату налогов, сборов и страховых взносов учитываются в составе расходов в размере их фактической уплаты налогоплательщиком. При наличии задолженности по уплате налогов, сборов и страховых взносов расходы на ее погашение учитываются в составе расходов в пределах фактически погашенной задолженности и в те отчетные (налоговые) периоды, когда налогоплательщик погашает указанную задолженность. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nВ случае заключения договора доверительного управления имуществом или договора простого товарищества, договора инвестиционного товарищества участники указанных договоров, определяющие доходы и расходы по кассовому методу, обязаны перейти на определение доходов и расходов по методу начисления с начала налогового периода, в котором был заключен такой договор. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ) (В редакции Федерального закона от 28.11.2011 № 336-ФЗ)","article_title":"Статья 273. Порядок определения доходов и расходов при кассовом методе","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8645f25a33c1be36396b38bd0bbb7d2d3d87b185bd3199035b4c294073d7b94e"},{"code_id":"NK_RF_2","article_number":"274","version_date":"2000-07-31","article_text":"1. Налоговой базой дл\n\nя целей настоящей главы признается денежное выражение прибыли, определяемой в соответствии со статьей 247 настоящего Кодекса, подлежащей налогообложению.\n\nУбытки, полученные в отчетном (налоговом) периоде, принимаются в целях налогообложения в порядке и на условиях, установленных пунктом 1 статьи 2781 и статьей 283 настоящего Кодекса. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nНалогоплательщики, являющиеся организациями игорного бизнеса, а также организации, получающие доходы от деятельности, относящейся к игорному бизнесу, обязаны вести обособленный учет доходов и расходов по такой деятельности.\n\nПри этом расходы организаций, занимающихся игорным бизнесом, в случае невозможности их разделения определяются пропорционально доле доходов организации от деятельности, относящейся к игорному бизнесу, в общем доходе организации по всем видам деятельности.\n\nАналогичный порядок распространяется на организации, перешедшие на уплату налога на вмененный доход. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 24.07.2007 № 216-ФЗ)\n\n10. Налогоплательщики, применяющие в соответствии с настоящим Кодексом специальные налоговые режимы, при исчислении налоговой базы по налогу не учитывают доходы и расходы, относящиеся к таким режимам.\n\n11. Особенности определения налоговой базы по банкам устанавливаются с учетом положений статей 290 - 292 настоящего Кодекса.\n\n12. Особенности определения налоговой базы по страховщикам устанавливаются с учетом положений статей 293 и 294 настоящего Кодекса.\n\n13. Особенности определения налоговой базы по негосударственным пенсионным фондам устанавливаются с учетом положений статей 295 и 296 настоящего Кодекса.\n\n14. Особенности определения налоговой базы по профессиональным участникам рынка ценных бумаг устанавливаются с учетом положений статей 298 и 299 настоящего Кодекса.\n\nУказанный в настоящем пункте совокупный размер прибыли определяется как суммы прибыли (убытка), рассчитанные по итогам каждого предыдущего налогового периода. Для целей настоящего пункта при определении совокупного размера прибыли не учитывается прибыль (убыток), полученная по итогам налоговых периодов, предшествующих налоговому периоду, в котором годовой объем выручки, полученной участником проекта, превысил один миллиард рублей.\n\nФорма расчета совокупного размера прибыли устанавливается Министерством финансов Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 28.09.2010 № 243-ФЗ)","article_title":"Статья 274. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3e681a5b491fc6a6a0da9c9b55beb16c29b18ae0d49386cdb27ca80f0a231cc"},{"code_id":"NK_RF_2","article_number":"275","version_date":"2000-07-31","article_text":"1. Сумма налога на доходы от долевого участия в деятельности организаций определяется с учетом положений настоящей статьи.\n\nПри этом налогоплательщики, получающие дивиденды от иностранной организации, в том числе через постоянное представительство иностранной организации в Российской Федерации, не вправе уменьшить сумму налога, исчисленную в соответствии с настоящей главой, на сумму налога, исчисленную и уплаченную по месту нахождения источника дохода, если иное не предусмотрено международным договором Российской Федерации.\n\nН = К х Сн х (Д1 - Д2),\n\nгде Н - сумма налога, подлежащего удержанию;\n\nК - отношение суммы дивидендов, подлежащих распределению в пользу налогоплательщика - получателя дивидендов, к общей сумме дивидендов, подлежащих распределению российской организацией;\n\nСн - налоговая ставка, установленная подпунктами 1 - 21 пункта 3 статьи 284 настоящего Кодекса; (В редакции  Федерального закона от 26.03.2022 № 66-ФЗ)\n\nД1 - общая сумма дивидендов, подлежащая распределению российской организацией в пользу всех получателей;\n\nД2 - общая сумма дивидендов, полученных российской организацией в текущем отчетном (налоговом) периоде и предыдущих отчетных (налоговых) периодах (за исключением дивидендов, указанных в подпунктах 1, 11 и 21 пункта 3 статьи 284 настоящего Кодекса, дивидендов, полученных от иностранных организаций, фактическим источником выплаты которых являются российские организации, на которые налогоплательщик имеет фактическое право и к которым применялись налоговые ставки, установленные подпунктами 1, 11 и 21 пункта 3 статьи 284 настоящего Кодекса, дивидендов, указанных в подпункте 501 пункта 1 статьи 251 настоящего Кодекса, а также дивидендов, к которым в соответствии с международным договором Российской Федерации, регулирующим вопросы налогообложения, применена налоговая ставка в меньшем размере, чем налоговая ставка, установленная подпунктом 2 пункта 3 статьи 284 настоящего Кодекса) к моменту распределения дивидендов в пользу налогоплательщиков - получателей дивидендов, при условии, что указанная сумма дивидендов ранее не учитывалась при определении суммы налога по формуле, предусмотренной настоящим пунктом, и (или) при расчете величины зачета налога на прибыль организаций в соответствии с пунктом 31 статьи 214 настоящего Кодекса. (В редакции  федеральных законов от 23.11.2020 № 374-ФЗ, от 17.02.2021 № 8-ФЗ, от 26.03.2022 № 66-ФЗ)\n\nРоссийская организация, выплачивающая доходы в виде дивидендов, обязана предоставить соответствующему налоговому агенту значения показателей Д1 и Д2 в порядке, установленном пунктами 51 и (или) 52 настоящей статьи.\n\nВ случае, если значение Н составляет отрицательную величину, обязанность по уплате налога не возникает и возмещение из бюджета не производится.\n\n(Пункт в редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\n1) электронный документ, подписанный электронной подписью в соответствии с Федеральным законом от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\";\n\n2) документ на бумажном носителе, подписанный уполномоченным лицом российской организации - эмитента ценных бумаг, выплачивающей доход в виде дивидендов;\n\n3) публикация значений показателей Д1 и Д2 на официальном сайте российской организации - эмитента ценных бумаг, выплачивающей доход в виде дивидендов;\n\n4) дополнительная информация, содержащаяся в соответствующем платежном документе на перечисление дивидендов налоговому агенту.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n1) электронный документ, подписанный электронной подписью в соответствии с Федеральным законом от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\";\n\n2) документ на бумажном носителе, подписанный уполномоченным лицом российской организации, выплачивающей доход в виде дивидендов;\n\n3) публикация значений показателей Д1 и Д2 на официальном сайте российской организации, выплачивающей доход в виде дивидендов;\n\n4) дополнительная информация, содержащаяся в соответствующем платежном документе на перечисление дивидендов налоговому агенту.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\nВ случае, если получателями дохода в виде дивидендов, выплачиваемых иностранной организации, действующей в интересах третьих лиц, являются организации, признаваемые налоговыми резидентами Российской Федерации, сумма налога, удерживаемого из суммы таких дивидендов, определяется на основании пункта 5 настоящей статьи. (Дополнение абзацем - Федеральный закон от 28.11.2015 № 326-ФЗ) (В редакции Федерального закона от 17.02.2021 № 8-ФЗ)\n\n1) российская организация, осуществляющая выплату доходов в виде дивидендов по акциям, выпущенным российской организацией, права на которые учитываются в реестре ценных бумаг российской организации на дату, определенную в решении о выплате (об объявлении) дохода по таким ценным бумагам, на следующих счетах:\n\nлицевом счете владельца;\n\nдепозитном лицевом счете применительно к организации, которая имеет право на получение ценных бумаг с указанного счета;\n\nсчете неустановленных лиц применительно к организации, в отношении которой установлено право на получение такого дохода;\n\nлицевом счете доверительного управляющего, если этот доверительный управляющий не является профессиональным участником рынка ценных бумаг;\n\nлицевом счете иностранного номинального держателя, лицевом счете иностранного уполномоченного держателя, лицевом счете депозитарных программ, лицевом счете иностранного регистратора, открытых в соответствии с Федеральным законом от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\"; (Дополнение абзацем - Федеральный закон от 25.12.2018 № 490-ФЗ) (В редакции  Федерального закона от 26.03.2022 № 66-ФЗ)\n\n2) доверительный управляющий при выплате доходов в виде дивидендов по акциям, выпущенным российской организацией, права на которые учитываются на дату, определенную в решении о выплате (об объявлении) дохода по таким акциям, на лицевом счете или счете депо этого доверительного управляющего в случае, если этот доверительный управляющий на дату приобретения акций, указанных в настоящем подпункте, является профессиональным участником рынка ценных бумаг;\n\n3) депозитарий, осуществляющий выплату доходов в виде дивидендов по акциям, выпущенным российской организацией, права по которым учитываются в таком депозитарии на дату, определенную в решении о выплате (об объявлении) дохода по ценным бумагам, на следующих счетах (если иное не предусмотрено подпунктом 4 настоящего пункта): (В редакции Федерального закона от 25.12.2018 № 493-ФЗ)\n\nсчете депо владельца этих ценных бумаг, в том числе торговом счете депо владельца;\n\nоткрытом депозитарием счете неустановленных лиц применительно к организации, в отношении которой установлено право на получение такого дохода;\n\nсчете депо иностранного номинального держателя;\n\nсчете депо иностранного уполномоченного держателя;\n\nсчете депо депозитарных программ;\n\nдепозитном счете депо применительно к организации, которая имеет право на получение ценных бумаг с указанного счета;\n\nсубсчете депо, открытом в депозитарии в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\", за исключением субсчета депо номинального держателя;\n\nсубсчете депо, открытом в соответствии с Федеральным законом от 29 ноября 2001 года № 156-ФЗ \"Об инвестиционных фондах\";\n\n4) российская организация, выплата доходов в виде дивидендов по акциям которой осуществляется депозитарием, в случае, предусмотренном пунктом 16 статьи 312 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 25.12.2018 № 493-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\nналога, исчисленная для указанной иностранной организации.\n\nПолучателем доходов в виде дивидендов по имуществу, переданному в доверительное управление иностранного инвестиционного фонда (инвестиционной компании), который в соответствии с личным законом такого фонда (компании) относится к схемам коллективного инвестирования, признается соответствующий фонд (компания).\n\n(Статья в редакции Федерального закона от 02.11.2013 № 306-ФЗ)","article_title":"Статья 275. Особенности определения налоговой базы по доходам, полученным от долевого участия в других организациях","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fce1f6de03e4fcd60ac3386216d65c09c241d0a7121a6b1d39e790cb5d0173b8"},{"code_id":"NK_RF_2","article_number":"275.1","version_date":"2000-07-31","article_text":"Налогоплательщики, в состав которых входят подразделения, осуществляющие деятельность, связанную с использованием объектов обслуживающих производств и хозяйств, определяют налоговую базу по указанной деятельности отдельно от налоговой базы по иным видам деятельности. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nДля целей настоящей главы к обслуживающим производствам и хозяйствам относятся подсобное хозяйство, объекты жилищно-коммунального хозяйства, социально-культурной сферы, учебно-курсовые комбинаты и иные аналогичные хозяйства, производства и службы, осуществляющие реализацию товаров, работ, услуг как своим работникам, так и сторонним лицам. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nК объектам жилищно-коммунального хозяйства относятся жилой фонд, гостиницы (за исключением туристических), дома и общежития для приезжих, объекты внешнего благоустройства, искусственные сооружения, бассейны, сооружения и оборудование пляжей, а также объекты газо-, тепло- и электроснабжения населения, участки, цехи, базы, мастерские, гаражи, специальные машины и механизмы, складские помещения, предназначенные для технического обслуживания и ремонта объектов жилищно-коммунального хозяйства социально-культурной сферы, физкультуры и спорта.\n\nК объектам социально-культурной сферы относятся объекты здравоохранения, культуры, детские дошкольные объекты, детские лагеря отдыха, санатории (профилактории), базы отдыха, пансионаты, объекты физкультуры и спорта (в том числе треки, ипподромы, конюшни, теннисные корты, площадки для игры в гольф, бадминтон, оздоровительные центры), объекты непроизводственных видов бытового обслуживания населения (бани, сауны).\n\nВ случае, если подразделением налогоплательщика получен убыток при осуществлении деятельности, связанной с использованием указанных в настоящей статье объектов, такой убыток признается для целей налогообложения при соблюдении следующих условий: (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nесли стоимость товаров, работ, услуг, реализуемых налогоплательщиком, осуществляющим деятельность, связанную с использованием указанных в настоящей статье объектов, соответствует стоимости аналогичных услуг, оказываемых специализированными организациями, осуществляющими аналогичную деятельность, связанную с использованием таких объектов; (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nесли расходы на содержание объектов жилищно-коммунального хозяйства, социально-культурной сферы, а также подсобного хозяйства и иных аналогичных хозяйств, производств и служб не превышают обычных расходов на обслуживание аналогичных объектов, осуществляемое специализированными организациями, для которых эта деятельность является основной;\n\nесли условия оказания услуг, выполнения работ налогоплательщиком существенно не отличаются от условий оказания услуг, выполнения работ специализированными организациями, для которых эта деятельность является основной. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nЕсли не выполняется хотя бы одно из указанных условий, то убыток, полученный налогоплательщиком при осуществлении деятельности, связанной с использованием объектов обслуживающих производств и хозяйств, налогоплательщик вправе перенести на срок, не превышающий десять лет, и направить на его погашение только прибыль, полученную при осуществлении указанных видов деятельности.\n\nНалогоплательщики, численность работников которых составляет не менее 25 процентов численности работающего населения соответствующего населенного пункта и в состав которых входят структурные подразделения по эксплуатации объектов жилищного фонда, а также объектов, указанных в частях третьей и четвертой настоящей статьи, вправе принять для целей налогообложения фактически осуществленные расходы на содержание указанных объектов. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nЧасть. (Дополнение частью - Федеральный закон от 06.06.2005 № 58-ФЗ) (Утратила силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nЧасть. (Дополнение частью - Федеральный закон от 06.06.2005 № 58-ФЗ) (Утратила силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.05.2002 № 57-ФЗ)","article_title":"Статья 275.1. Особенности определения налоговой базы налогоплательщиками, осуществляющими деятельность, связанную с использованием объектов обслуживающих производств и хозяйств","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93ce0a20a248cd148a20572b623e9b054f36b906b84147196a65b360ff39664c"},{"code_id":"NK_RF_2","article_number":"275.2","version_date":"2000-07-31","article_text":"1. Особенности определения налоговой базы, установленные настоящей статьей, применяются:\n\n1) организациями, владеющими лицензиями на пользование участком недр, в границах которого расположено новое морское месторождение углеводородного сырья либо в границах которого предполагается осуществлять поиск, оценку и (или) разведку нового морского месторождения углеводородного сырья на основании лицензии на пользование недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых или для разведки и добычи полезных ископаемых; (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n2) операторами нового морского месторождения углеводородного сырья.\n\n2. Налогоплательщики, указанные в пункте 1 настоящей статьи, определяют налоговую базу при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, отдельно от налоговой базы, определяемой при осуществлении иных видов деятельности, в порядке, установленном настоящей статьей.\n\nВ случае, если налогоплательщиком, указанным в пункте 1 настоящей статьи, принято решение о прекращении работ на участке недр в связи с экономической нецелесообразностью, геологической бесперспективностью или по иным причинам и при этом на таком участке недр не выделено ни одного нового морского месторождения углеводородного сырья, для целей настоящей главы к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, приравнивается деятельность по поиску, оценке и (или) разведке новых морских месторождений углеводородного сырья на этом участке недр.\n\n3. Налогоплательщики, не указанные в пункте 1 настоящей статьи и осуществляющие деятельность, связанную с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, учитывают доходы и расходы, связанные с осуществлением такой деятельности, при определении налоговой базы, к которой применяется налоговая ставка, установленная пунктом 1 статьи 284 настоящего Кодекса.\n\n4. Прибыль от осуществления деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, не уменьшается на суммы убытков от осуществления такой деятельности в отношении иных месторождений, а также от осуществления иных видов деятельности.\n\n5. В случае, если налогоплательщик, указанный в пункте 1 настоящей статьи, осуществляет деятельность, связанную с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в отношении двух и более таких месторождений, налоговая база определяется отдельно по каждому такому месторождению с учетом особенностей, установленных настоящей статьей.\n\n6. Доходы налогоплательщика, указанного в пункте 1 настоящей статьи, полученные от осуществления деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, определяются с учетом положений статьи 2993 настоящего Кодекса.\n\n7. Расходы налогоплательщика, указанного в пункте 1 настоящей статьи, понесенные при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, определяются с учетом положений статьи 2994 настоящего Кодекса.\n\n8. В случае, если налогоплательщик, указанный в пункте 1 настоящей статьи, в течение отчетного (налогового) периода передает углеводородное сырье, добытое на новом морском месторождении углеводородного сырья, на переработку другим структурным подразделениям этого же налогоплательщика или передает такое сырье третьим лицам для переработки на давальческой основе и при этом такая переработка углеводородного сырья другими структурными подразделениями налогоплательщика или третьими лицами не относится к осуществлению деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, такой налогоплательщик при исчислении налоговой базы за соответствующий отчетный (налоговый) период проводит следующие корректировки доходов от реализации и расходов, связанных с производством и реализацией:\n\nпри исчислении налоговой базы при осуществлении деятельности, связанной с добычей углеводородного сырья на указанном новом морском месторождении углеводородного сырья, доходы от реализации увеличиваются на стоимость такого углеводородного сырья;\n\nпри исчислении налоговой базы, к которой применяется налоговая ставка, установленная пунктом 1 статьи 284 настоящего Кодекса, расходы, связанные с производством и реализацией, увеличиваются на стоимость такого углеводородного сырья.\n\nДля целей настоящего пункта стоимость углеводородного сырья, добытого на новом морском месторождении углеводородного сырья, принимается равной стоимости углеводородного сырья, определяемой в соответствии со статьями 340 и 3401 настоящего Кодекса.\n\n9. В случае получения убытка от осуществления деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, налогоплательщики, указанные в пункте 1 статьи 2752 настоящего Кодекса, вправе перенести этот убыток на будущее в соответствии с порядком, установленным статьей 283 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 268-ФЗ)","article_title":"Статья 275.2. Особенности определения налоговой базы при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2e2344f9d9f68e72ab82e4c2fcddeda44f934f9fd925d6ca8250dc8fc23420e"},{"code_id":"NK_RF_2","article_number":"275.3","version_date":"2000-07-31","article_text":"1. Международные компании и иностранные организации, признаваемые налоговыми резидентами Российской Федерации, формируют стоимость имущества (имущественных прав) соответственно на дату регистрации в качестве международной компании или на дату признания налоговым резидентом Российской Федерации с учетом следующих особенностей:\n\n1) если иное не предусмотрено настоящим пунктом, имущество (имущественные права), в том числе амортизируемое имущество, принимается для целей налогового учета исходя из документально подтвержденной стоимости объектов имущества (имущественных прав) по данным учета иностранной организации, регистрируемой в качестве международной компании, или иностранной организации, признаваемой налоговым резидентом Российской Федерации, на дату, предшествующую дате регистрации международной компании, или на дату, предшествующую дате признания иностранной организации налоговым резидентом Российской Федерации, но не выше рыночной стоимости такого имущества (имущественных прав), определяемой в соответствии со статьей 1053 настоящего Кодекса. При этом документально подтвержденной стоимостью объектов имущества (имущественных прав), подлежащих амортизации, признается остаточная стоимость соответствующих объектов основных средств и (или) нематериальных активов, определяемая по данным учета иностранной организации, регистрируемой в качестве международной компании, или иностранной организации, признаваемой налоговым резидентом Российской Федерации;\n\n2) если иное не предусмотрено подпунктом 4 настоящего пункта, ценные бумаги (обращающиеся и не обращающиеся на организованном рынке ценных бумаг) принимаются исходя из документально подтвержденных фактических затрат на их приобретение по данным финансового учета организации; (В редакции Федерального закона от 25.12.2018 № 490-ФЗ)\n\n3) если иное не предусмотрено подпунктом 4 настоящего пункта, стоимость долей участия в уставном (складочном) капитале (фонде) российских и иностранных организаций принимается исходя из документально подтвержденных фактических затрат на приобретение этих долей по данным финансового учета организации;\n\n4) стоимость акций или долей участия в организациях, не являющихся публичными компаниями, более 50 процентов активов которых на последнюю отчетную дату, предшествующую дате регистрации международной компании или дате признания иностранной организации налоговым резидентом Российской Федерации, прямо или косвенно состоят из недвижимого имущества, находящегося на территории Российской Федерации, при их принятии к учету определяется исходя из документально подтвержденных фактических затрат на приобретение таких акций (долей участия), но не выше их рыночной стоимости (котировки), рассчитанной в соответствии с настоящим подпунктом и подпунктом 3 настоящего пункта.\n\nВ случае, если стоимость акций (долей участия), указанных в настоящем подпункте, на дату их принятия к учету выражена в иностранной валюте, соответствующая стоимость в рублях определяется по официальному курсу Центрального банка Российской Федерации, действовавшему на дату приобретения в собственность иностранной организацией соответствующих акций (долей). (В редакции Федерального закона от 25.12.2018 № 490-ФЗ)\n\n2. Если иное не предусмотрено настоящей статьей, в случае, если стоимость имущества (имущественных прав) на дату его принятия к учету выражена в иностранной валюте, соответствующая стоимость в рублях определяется по официальному курсу Центрального банка Российской Федерации, действовавшему на дату регистрации международной компании или признания иностранной компании налоговым резидентом Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 03.08.2018 № 294-ФЗ)","article_title":"Статья 275.3. Особенности формирования стоимости имущества (имущественных прав) международными компаниями и иностранными организациями, признаваемыми налоговыми резидентами Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dfb8885a581ed91152b10d00a39c01e635bf1f25a46b283c5ef3e322401da2b0"},{"code_id":"NK_RF_2","article_number":"276","version_date":"2000-07-31","article_text":"1. Для целей настоящей главы имущество (в том числе имущественные права), переданное по договору доверительного управления имуществом, не признается доходом доверительного управляющего.\n\nВознаграждение, получаемое доверительным управляющим в соответствии с договором доверительного управления имуществом, является его доходом от реализации и подлежит налогообложению в установленном порядке. При этом расходы, связанные с осуществлением доверительного управления, признаются расходами доверительного управляющего, если в договоре доверительного управления имуществом не предусмотрено возмещение указанных расходов учредителем доверительного управления.\n\nДоверительный управляющий обязан определять ежемесячно нарастающим итогом доходы и расходы по доверительному управлению имуществом и представлять учредителю доверительного управления (выгодоприобретателю) сведения о полученных доходах и расходах для их учета учредителем доверительного управления (выгодоприобретателем) при определении налоговой базы в соответствии с настоящей главой.\n\nПри доверительном управлении ценными бумагами доверительный управляющий определяет доходы и расходы в порядке, предусмотренном статьей 280 настоящего Кодекса.\n\n2. В случае, если по условиям договора доверительного управления имуществом учредитель доверительного управления является выгодоприобретателем, определение налоговой базы такого учредителя осуществляется с учетом следующих особенностей:\n\n1) доходы учредителя доверительного управления в рамках договора доверительного управления имуществом включаются в состав его выручки или внереализационных доходов в зависимости от полученного вида дохода;\n\n2) расходы, связанные с осуществлением договора доверительного управления имуществом (включая амортизацию имущества, а также вознаграждение доверительного управляющего), признаются расходами, связанными с производством и реализацией, или внереализационными расходами учредителя доверительного управления в зависимости от вида осуществленных расходов;\n\n3) доходы (расходы) по операциям с ценными бумагами и по операциям с производными финансовыми инструментами (за исключением вознаграждения доверительного управляющего) включаются в состав доходов (расходов) по операциям с ценными бумагами и производными финансовыми инструментами соответствующей категории или внереализационных доходов (расходов) у учредителя договора доверительного управления в порядке, установленном статьями 275, 280 - 2821, 301 - 305 настоящего Кодекса. При этом расходы на вознаграждение доверительного управляющего учитываются отдельно и признаются расходами учредителя доверительного управления в составе внереализационных расходов. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n3. В случае, если по условиям договора доверительного управления имуществом учредитель доверительного управления не является выгодоприобретателем либо установлено более одного выгодоприобретателя, определение налоговой базы участников такого договора осуществляется с учетом следующих особенностей:\n\n1) доходы выгодоприобретателя по договору доверительного управления имуществом включаются в состав его доходов от реализации или внереализационных доходов в зависимости от полученного вида дохода и подлежат налогообложению в установленном порядке;\n\n2) расходы, связанные с осуществлением договора доверительного управления имуществом (за исключением вознаграждения доверительного управляющего в случае, если указанным договором предусмотрена выплата вознаграждения не за счет уменьшения доходов, полученных в рамках исполнения этого договора), не учитываются учредителем управления при определении налоговой базы, но учитываются для целей налогообложения в составе расходов у выгодоприобретателя. При этом расходы на вознаграждение доверительного управляющего (за исключением вознаграждения доверительного управляющего в случае, если указанным договором предусмотрена выплата вознаграждения за счет уменьшения доходов, полученных в рамках исполнения этого договора) учитываются отдельно и признаются расходами учредителя доверительного управления в составе внереализационных расходов;\n\n3) убытки, полученные в течение срока действия договора доверительного управления, от использования имущества, переданного в доверительное управление, не учитываются при определении налоговой базы по налогу учредителем управления и выгодоприобретателем;\n\n4) при наличии нескольких выгодоприобретателей по договору доверительного управления доходы и расходы учитываются у них в соответствии с настоящим пунктом пропорционально причитающейся им доле.\n\n4. При прекращении договора доверительного управления имущество (в том числе имущественные права), переданное в доверительное управление, по условиям указанного договора может быть либо возвращено учредителю управления, либо передано иному лицу.\n\nВ случае возврата имущества у учредителя управления не образуе\n\nтся дохода (убытка) независимо от возникновения положительной (отрицательной) разницы между стоимостью переданного в доверительное управление имущества на момент вступления в силу и на момент прекращения договора доверительного управления имуществом.\n\n5. Положения настоящей статьи (за исключением положений абзаца первого пункта 1 настоящей статьи) не распространяются на управляющую компанию и участников (учредителей) договора доверительного управления имуществом, составляющим обособленный имущественный комплекс - паевой инвестиционный фонд.\n\n(Статья в редакции Федерального закона от 28.12.2013 № 420-ФЗ)","article_title":"Статья 276. Особенности определения налоговой базы участников договора доверительного управления имуществом","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"820a0408f2d795387335edb7f217b4940576500260a5589e6370632685d5da58"},{"code_id":"NK_RF_2","article_number":"277","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 30.11.2016 № 401-ФЗ, от 30.09.2017 № 286-ФЗ, от 25.12.2018 № 490-ФЗ, от 14.02.2024 № 8-ФЗ)\n\n1. При размещении эмитированных акций (долей, паев) доходы и расходы налогоплательщика-эмитента и доходы и расходы налогоплательщика, приобретающего такие акции (доли, паи) (далее в настоящей статье - акционер (участник, пайщик), определяются с учетом следующих особенностей:\n\n1) у налогоплательщика-эмитента не возникает прибыли (убытка) при получении имущества (имущественных прав) в качестве оплаты за размещаемые им акции (доли, паи); (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\n2) у налогоплательщика-акционера (участника, пайщика) не возникает прибыли (убытка) при передаче имущества (имущественных прав) в качестве оплаты размещаемых акций (долей, паев). (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nПри этом стоимость приобретаемых акций (долей, паев) для целей настоящей главы признается равной стоимости (остаточной стоимости) вносимого имущества (имущественных прав или неимущественных прав, имеющих денежную оценку (далее в настоящей статье - имущественные права)), определяемой по данным налогового учета на дату перехода права собственности на указанное имущество (имущественные права), с учетом дополнительных расходов, которые для целей налогообложения признаются у передающей стороны при таком внесении. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 06.06.2005 № 58-ФЗ)\n\nПри этом имущество (имущественные права), полученное в виде взноса (вклада) в уставный (складочный) капитал организации, в целях налогообложения прибыли принимается по стоимости (остаточной стоимости) полученного в качестве взноса (вклада) в уставный (складочный) капитал имущества (имущественных прав). Стоимость (остаточная стоимость) определяется по данным налогового учета у передающей стороны на дату перехода права собственности на указанное имущество (имущественные права) с учетом дополнительных расходов, которые при таком внесении (вкладе) осуществляются передающей стороной при условии, что эти расходы определены в качестве взноса (вклада) в уставный (складочный) капитал. Если получающая сторона не может документально подтвердить стоимость вносимого имущества (имущественных прав) или какой-либо его части, то стоимость этого имущества (имущественных прав) либо его части признается равной нулю. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nПри внесении (вкладе) имущества (имущественных прав) физическими лицами и иностранными организациями его стоимостью (остаточной стоимостью) признаются документально подтвержденные расходы на его приобретение (создание) с учетом амортизации (износа), начисленной в целях налогообложения прибыли (дохода) в государстве, налоговым резидентом которого является передающая сторона, но не выше рыночной стоимости этого имущества (имущественных прав), подтвержденной независимым оценщиком, действующим в соответствии с законодательством указанного государства. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nПри внесении (вкладе) имущества (имущественных прав) физическими лицами, доходы от получения которого подлежат освобождению от налогообложения у физических лиц в соответствии с пунктом 602 статьи 217 настоящего Кодекса, стоимость (остаточная стоимость) такого имущества (имущественных прав) определяется по данным налогового учета иностранной организации, указанной в этом пункте. В случае, если стоимость (остаточная стоимость) такого имущества (имущественных прав) не определялась, в целях настоящего пункта она признается равной нулю. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nСтоимость имущества (имущественных прав), полученного в порядке приватизации государственного или муниципального имущества в виде вклада в уставный капитал организаций, признается для целей настоящей главы по стоимости (остаточной стоимости), определяемой на дату приватизации в соответствии с требованиями к бухгалтерскому учету. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ) (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nСтоимость имущества (имущественных прав), полученного государственными корпорациями, созданными на основании федеральных законов, в качестве имущественного взноса Российской Федерации, признается для целей настоящей главы по стоимости, определяемой на дату получения такого имущества (имущественных прав) в соответствии с требованиями к бухгалтерскому учету. (Дополнение абзацем - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\nПри передаче имущества в уставный фонд унитарного предприятия собственником его имущества стоимостью этого имущества признаются документально подтвержденные расходы на его приобретение (создание), осуществленные в соответствии с бюджетным законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n11. Имущество (имущественные права), полученное личным фондом от своих учредителей, принимается к учету по стоимости такого имущества (имущественных прав), равной документально подтвержденным расходам на его приобретение (создание), понесенным передающей стороной.\n\nПри получении личным фондом имущества (имущественных прав) от учредителей, доходы от получения которого подлежат освобождению от налогообложения у физических лиц в соответствии с пунктами 60, 601 и 602 статьи 217 настоящего Кодекса, стоимость (остаточная стоимость) такого имущества (имущественных прав) определяется по данным налогового учета иностранных организаций, указанных в этих пунктах, но не выше его рыночной цены, определяемой с учетом положений статьи 1053 настоящего Кодекса на дату получения физическим лицом такого имущества (имущественных прав) от этой иностранной организации (структуры без образования юридического лица).\n\nВ случае, если передающая сторона не может документально подтвердить стоимость передаваемого имущества (имущественных прав), то стоимость такого имущества (имущественных прав) признается равной нулю.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПри выходе (выбытии) акционера (участника) из организации доходы такого акционера (участника) определяются исходя из рыночной стоимости получаемого им имущества (имущественных прав) на момент получения данного имущества (имущественных прав) за вычетом фактически оплаченной (вне зависимости от формы оплаты) соответствующим акционером (участником) этой организации стоимости акций (долей) и величины внесенного им вклада в виде денежных средств, уменьшенных на сумму денежных средств, указанных в подпункте 111 пункта 1 статьи 251 настоящего Кодекса, в имущество организации. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 424-ФЗ) (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nПри этом имущество (имущественные права), полученное таким акционером (участником) при выходе (выбытии) или при ликвидации организации, в целях налогообложения прибыли принимается к учету по рыночной стоимости, определенной в соответствии с положениями абзаца второго настоящего пункта. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\nУстановленный настоящим пунктом порядок определения дохода и стоимости получаемого имущества (имущественных прав) в целях налогообложения прибыли также применяется налогоплательщиками, владеющими облигациями, при ликвидации организации - эмитента соответствующих облигаций. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\nЕсли иное не установлено пунктом 25 настоящей статьи, в случае, если налогоплательщик воспользовался правом, установленным абзацем первым настоящего пункта, стоимость такого имущества (имущественных прав) для целей настоящего пункта принимается к учету исходя из документально подтвержденной стоимости имущества (имущественных прав) по данным учета ликвидируемой иностранной организации (иностранной структуры без образования юридического лица) на дату получения такого имущества (имущественных прав), но не выше рыночной стоимости такого имущества (имущественных прав), определяемой с учетом положений статьи 1053 настоящего Кодекса. (В редакции Федерального закона от 25.12.2018 № 490-ФЗ)\n\nПри этом документально подтвержденной стоимостью объектов имущества (имущественных прав), подлежащих амортизации, признается остаточная стоимость данных объектов, определяемая по данным учета ликвидируемой иностранной организации (иностранной структуры без образования юридического лица).\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n23. Налогоплательщик вправе не учитывать при определении налоговой базы доходы в виде стоимости полученного имущества (имущественных прав) на основании пункта 22 настоящей статьи при условии, что процедура ликвидации иностранной организации (иностранной структуры без образования юридического лица) завершена до 1 января 2018 года, если иное не указано в подпунктах 1 - 3 настоящего пункта. Предельный срок завершения процедуры ликвидации иностранной организации (иностранной структуры без образования юридического лица) продлевается в следующих случаях:\n\n1) если решение акционеров (учредителей) или иных уполномоченных лиц о ликвидации иностранной организации (иностранной структуры без образования юридического лица) принято до 1 января 2017 года, но процедура ликвидации не может быть завершена до 1 января 2018 года в связи с ограничениями, установленными личным законом иностранной организации, либо участием иностранной организации (иностранной структуры без образования юридического лица) в судебном разбирательстве, процедура ликвидации иностранной организации (иностранной структуры без образования юридического лица) должна быть завершена не позднее окончания 365 последовательных календарных дней, считая с даты окончания таких ограничений и (или) судебных разбирательств;\n\n2) если личным законом иностранной организации (иностранной структуры без образования юридического лица) установлен минимальный период владения акциями (долями, паями) в иностранной организации (иностранной структуре без образования юридического лица) и (или) в ее дочерних организациях и (или) иностранных структурах без образования юридического лица, при несоблюдении которого возникает обязанность уплатить налог, установленный законодательством иностранного государства, и при этом начало такого периода приходится на дату до 1 января 2015 года, а окончание такого периода приходится на дату после 1 января 2018 года, процедура ликвидации иностранной организации (иностранной структуры без образования юридического лица) должна быть завершена не позднее окончания 365 последовательных календарных дней, считая с даты окончания минимального периода, указанного в настоящем подпункте;\n\n3) если решение о ликвидации иностранной организации (иностранной структуры без образования юридического лица) не может быть принято до 1 января 2018 года в связи с ограничениями, установленными условиями выпуска обращающихся облигаций, отвечающих требованиям, установленным подпунктом 1 пункта 21 статьи 310 настоящего Кодекса, процедура ликвидации иностранной организации (иностранной структуры без образования юридического лица) должна быть завершена не позднее окончания 365 последовательных календарных дней, считая с даты окончания действия таких ограничений для указанной организации (иностранной структуры без образования юридического лица).\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\n24. Налогоплательщик - акционер иностранной организации (участник, пайщик, учредитель, контролирующее лицо иностранной организации или контролирующее лицо иностранной структуры без образования юридического лица) вправе не учитывать при определении налоговой базы доходы в виде полученных в собственность ценных бумаг, долей в уставном капитале общества, имущественных прав, полученные в период до 31 декабря 2019 года от такой иностранной организации (иностранной структуры без образования юридического лица), при одновременном соблюдении следующих условий:\n\n1) в отношении физического лица, совокупная доля прямого и (или) косвенного участия которого в налогоплательщике составляет на дату получения доходов в виде полученных в собственность ценных бумаг, долей в уставном капитале общества, имущественных прав не менее 25 процентов, на указанную дату действовали меры ограничительного характера;\n\n2) полученные в собственность налогоплательщиком ценные бумаги, доли в уставном капитале общества, имущественные права находились в собственности передающей их иностранной организации (иностранной структуры без образования юридического лица) на дату начала действия в отношении физического лица, указанного в подпункте 1 настоящего пункта, мер ограничительного характера;\n\n3) налогоплательщик представил в налоговый орган одновременно с налоговой декларацией составленное в произвольной форме заявление об освобождении таких доходов от налогообложения с указанием характеристик полученного имущества (имущественных прав) и передающей их иностранной организации (иностранной структуры без образования юридического лица) и приложением документов, содержащих сведения о стоимости имущества (имущественных прав) по данным учета передающей иностранной организации (иностранной структуры без образования юридического лица) на дату получения имущества (имущественных прав) от такой иностранной организации;\n\n4) налогоплательщик представил в налоговый орган одновременно с налоговой декларацией информацию о ликвидации иностранной организации (прекращении иностранной структуры без образования юридического лица), от которой получены в собственность ценные бумаги, доли в уставном капитале общества, имущественные права. Условие, установленное настоящим подпунктом, должно соблюдаться в случае, если доходы, указанные в абзаце первом настоящего пункта, получены налогоплательщиком в результате ликвидации иностранной организации (прекращения иностранной структуры без образования юридического лица);\n\n5) налогоплательщик представил в налоговый орган одновременно с налоговой декларацией составленное в произвольной форме обязательство завершить процедуру ликвидации иностранной организации (процедуру прекращения иностранной структуры без образования юридического лица), от которой получены в собственность ценные бумаги, доли в уставном капитале общества, имущественные права, в течение 365 последовательных календарных дней, считая с более ранней из следующих дат:\n\nдаты окончания действия мер ограничительного характера в отношении физического лица, указанного в подпункте 1 настоящего пункта;\n\nдаты, начиная с которой совокупная доля прямого и (или) косвенного участия физического лица, указанного в подпункте 1 настоящего пункта, стала менее 25 процентов.\n\nОдновременно с обязательством, указанным в абзацах первом - третьем настоящего подпункта, для выполнения условия, установленного настоящим подпунктом, налогоплательщик также представляет в налоговый орган информацию о принятии решения акционеров (учредителей) или иных уполномоченных лиц о ликвидации указанной иностранной организации (прекращении иностранной структуры без образования юридического лица), если такое решение принято до 31 декабря 2019 года.\n\nВ случае невыполнения налогоплательщиком обязательства, указанного в настоящем подпункте, сумма налога, не уплаченная налогоплательщиком в бюджет в связи с использованием налогоплательщиком права, установленного настоящим пунктом, подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с налогоплательщика соответствующих сумм пеней вне зависимости от сроков принятия такого обязательства налогоплательщиком.\n\nУсловие, установленное настоящим подпунктом, должно соблюдаться в случае несоблюдения условия, установленного подпунктом 4 настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 25.12.2018 № 490-ФЗ)\n\n25. В случае, если налогоплательщик воспользовался правом не учитывать при определении налоговой базы доходы, указанные в пункте 24 настоящей статьи, в виде полученных в собственность акций (депозитарных расписок на акции) и (или) долей в уставном капитале общества и физическое лицо, указанное в подпункте 1 пункта 24 настоящей статьи, на дату введения в действие в отношении такого физического лица мер ограничительного характера прямо и (или) косвенно участвует в организации - эмитенте таких акций (акций, права на которые удостоверены такими депозитарными расписками) либо обществе, а совокупная доля его прямого и (или) косвенного участия\n\nв этой организации (обществе) составляет не менее 25 процентов, стоимость соответствующих акций (депозитарных расписок), долей в уставном капитале общества, полученных от иностранной организации (иностранной структуры без образования юридического лица), определяется для целей налогообложения в следующем порядке:\n\n1) для акций (депозитарных расписок на акции), обращающихся на организованном рынке ценных бумаг, стоимость признается равной средней рыночной стоимости таких акций (депозитарных расписок на акции), рассчитанной за шесть календарных месяцев, предшествующих месяцу введения мер ограничительного характера в отношении физического лица, указанного в подпункте 1 пункта 24 настоящей статьи. Рыночная стоимость таких акций (депозитарных расписок на акции) определяется в порядке, установленном статьей 280 настоящего Кодекса;\n\n2) для акций (депозитарных расписок на акции), не обращающихся на организованном рынке ценных бумаг, стоимость признается равной расчетной стоимости таких ценных бумаг по состоянию на последнее число месяца, предшествующего месяцу введения мер ограничительного характера в отношении физического лица, указанного в подпункте 1 пункта 24 настоящей статьи. Расчетная стоимость таких акций (депозитарных расписок на акции) определяется в порядке, установленном статьей 280 настоящего Кодекса;\n\n3) для долей в уставном капитале общества стоимость признается равной рыночной стоимости долей в уставном капитале общества по состоянию на последнее число месяца, предшествующего месяцу введения мер ограничительного характера в отношении физического лица, указанного в подпункте 1 пункта 24 настоящей статьи. Рыночная стоимость таких долей определяется на основании статьи 1053 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 25.12.2018 № 490-ФЗ)\n\n26. Стоимостью акций (долей в уставном капитале) экономически значимой организации, полученных налогоплательщиком пропорционально доле его косвенного владения в уставном капитале экономически значимой организации в порядке, предусмотренном Федеральным законом от 4 августа 2023 года № 470-ФЗ \"Об особенностях регулирования корпоративных отношений в хозяйственных обществах, являющихся экономически значимыми организациями\", признается для целей настоящей главы величина, равная произведению сформированной в налоговом учете стоимости акций (долей в уставном капитале) иностранной холдинговой компании, а также ценных бумаг иностранного эмитента, удостоверяющих права на акции иностранной холдинговой компании, указанной в статье 3 указанного Федерального закона, находящихся в собственности этого налогоплательщика, и доли балансовой стоимости акций (долей в уставном капитале) экономически значимой организации, принадлежащих указанной иностранной холдинговой компании, в балансовой стоимости ее активов по данным финансовой отчетности по состоянию на последнюю отчетную дату, предшествующую 1 марта 2022 года. В случае, если иностранная холдинговая компания является публичной компанией по состоянию на 1 марта 2022 года, расчет доли балансовой стоимости акций (долей в уставном капитале) экономически значимой организации, принадлежащих указанной иностранной холдинговой компании, в балансовой стоимости ее активов на указанную дату составления финансовой отчетности производится такой экономически значимой организацией и опубликовывается в течение 45 календарных дней с даты получения такой экономически значимой организацией собственных акций (долей в уставном капитале) на сайте экономически значимой организации или в печатном издании, предназначенном для опубликования данных о государственной регистрации юридических лиц.\n\nВ случае косвенного участия налогоплательщика в уставном капитале указанной в абзаце первом настоящего пункта иностранной холдинговой компании стоимость акций (долей в уставном капитале) экономически значимой организации, определенная в соответствии с абзацем первым настоящего пункта, увеличивается на величину (величины), определяемую (определяемые) в результате умножения стоимости акций (долей в уставном капитале) организации, через прямое участие в которой организовано соответствующее косвенное участие налогоплательщика в уставном капитале иностранной холдинговой компании, сформированной в налоговом учете налогоплательщика, на произведение долей, рассчитываемых в соответствии с абзацем третьим настоящего пункта. Эта величина определяется для каждой соответствующей последовательности косвенного участия налогоплательщика в уставном капитале иностранной холдинговой компании.\n\nДля каждой организации соответствующей последовательности косвенного участия налогоплательщика в уставном капитале иностранной холдинговой компании (включая иностранную холдинговую компанию) рассчитывается доля балансовой стоимости акций (долей в уставном капитале) прямого участия в следующей организации из указанной последовательности (с учетом участия иностранной холдинговой компании в экономически значимой организации) в балансовой стоимости ее активов по данным финансовой отчетности по состоянию на последнюю отчетную дату, предшествующую 1 марта 2022 года.\n\nПосле формирования стоимости акций (долей в уставном капитале) экономически значимой организации в соответствии с порядком, предусмотренным абзацами первым - третьим настоящего пункта, сформированная в налоговом учете стоимость соответствующих акций (долей в уставном капитале) иностранной холдинговой компании и (или) организации, через прямое участие в которой организовано косвенное участие налогоплательщика в уставном капитале иностранной холдинговой компании, уменьшается на стоимость (часть стоимости) акций (долей в уставном капитале) экономически значимой организации, определенную для прямого участия в уставном капитале иностранной холдинговой компании или для соответствующей последовательности косвенного участия налогоплательщика в уставном капитале иностранной холдинговой компании.\n\nВ аналогичном порядке определяется стоимость акций (долей в уставном капитале) организации, созданной в судебном порядке, полученных налогоплательщиком в соответствии с частью 2 статьи 11 Федерального закона от 4 августа 2023 года № 470-ФЗ \"Об особенностях регулирования корпоративных отношений в хозяйственных обществах, являющихся экономически значимыми организациями\". По этой же стоимости учитываются акции (доли в уставном капитале) экономически значимой организации, полученные организацией, созданной в судебном порядке, в собственность.\n\nПри частичном получении налогоплательщиком акций (долей в уставном капитале) экономически значимой организации стоимость этой части акций (долей в уставном капитале) экономически значимой организации рассчитывается как произведение стоимости акций (долей в уставном капитале) экономически значимой организации, определенной в соответствии с настоящим пунктом, и доли номинальной стоимости частично полученных акций (долей в уставном капитале) в номинальной стоимости акций (долей в уставном капитале) экономически значимой организации, по которым налогоплательщик обязан был вступить в прямое владение в соответствии с частями 1 и 9 статьи 7 Федерального закона от 4 августа 2023 года № 470-ФЗ \"Об особенностях регулирования корпоративных отношений в хозяйственных обществах, являющихся экономически значимыми организациями\". (Дополнение абзацем - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\nПри реорганизации негосударственного пенсионного фонда, являющегося некоммерческой организацией, в соответствии с Федеральным законом от 28 декабря 2013 года № 410-ФЗ \"О внесении изменений в Федеральный закон \"О негосударственных пенсионных фондах\" и отдельные законодательные акты Российской Федерации\" получение акций акционерного общества не приводит к образованию прибыли (убытка), учитываемой (учитываемого) в целях налогообложения, у следующих категорий налогоплательщиков: (Дополнение абзацем - Федеральный закон от 23.06.2014 № 167-ФЗ)\n\nучредители (лица, созданные в результате преобразования учредителей) реорганизуемого негосударственного пенсионного фонда; (Дополнение абзацем - Федеральный закон от 23.06.2014 № 167-ФЗ)\n\nиные лица (лица, созданные в результате их преобразования), которые внесли взнос в совокупный вклад учредителей негосударственного пенсионного фонда до даты принятия советом фонда решения о реорганизации негосударственного пенсионного фонда в соответствии с Федеральным законом от 28 декабря 2013 года № 410-ФЗ \"О внесении изменений в Федеральный закон \"О негосударственных пенсионных фондах\" и отдельные законодательные акты Российской Федерации\". (Дополнение абзацем - Федеральный закон от 23.06.2014 № 167-ФЗ)\n\nПри выделении активов из паевого инвестиционного фонда в дополнительный фонд не образуется доходов (расходов), учитываемых в целях налогообложения у налогоплательщиков - владельцев инвестиционных паев дополнительного фонда (паевого инвестиционного фонда, из которого осуществлено выделение активов в дополнительный фонд). (Дополнение абзацем - Федеральный закон от 14.02.2024 № 8-ФЗ)\n\nВ аналогичном порядке осуществляется оценка стоимости долей (паев), полученных в результате обмена долей (паев) реорганизуемой организации.\n\nПри реорганизации негосударственного пенсионного фонда, являющегося некоммерческой организацией, в соответствии с Федеральным законом от 28 декабря 2013 года № 410-ФЗ \"О внесении изменений в Федеральный закон \"О негосударственных пенсионных фондах\" и отдельные законодательные акты Российской Федерации\" стоимость получаемых налогоплательщиком акций, распределяемых в порядке, предусмотренном законодательством Российской Федерации, признается равной стоимости (остаточной стоимости) имущества (имущественных прав), внесенного в виде взноса в совокупный вклад учредителей реорганизуемого негосударственного пенсионного фонда, определенной по данным налогового учета у передающей стороны на дату перехода права собственности на указанное имущество (имущественные права). (Дополнение абзацем - Федеральный закон от 23.06.2014 № 167-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nСтоимость акций каждой из вновь созданной и реорганизованной организации, полученных акционером в результате реорганизации, определяется в следующем порядке.\n\nСтоимость акций каждой вновь создаваемой организации признается равной части стоимости принадлежащих акционеру акций реорганизуемой организации, пропорциональной отношению стоимости чистых активов созданной организации к стоимости чистых активов реорганизуемой организации.\n\nСтоимость акций реорганизуемой организации (реорганизованной после завершения реорганизации), принадлежащих акционеру, определяется как разница между стоимостью приобретения им акций реорганизуемой организации и стоимостью акций всех вновь созданных организаций, принадлежащих этому акционеру.\n\nСтоимость чистых активов реорганизуемой и вновь созданных организаций определяется по данным разделительного баланса на дату его утверждения акционерами в установленном порядке.\n\nВ аналогичном порядке осуществляется оценка стоимости долей (паев), полученных в результате обмена долей (паев) реорганизуемой организации.\n\nВ случае реорганизации в форме выделения, предусматривающей приобретение реорганизуемой организацией акций (доли, пая) выделяемой организации, стоимость этих акций (доли, пая) признается равной стоимости чистых активов выделенной организации на дату ее государственной регистрации.\n\nВ случае, если стоимость чистых активов одной или нескольких созданных (реорганизованной) с участием акционеров организаций является отрицательной величиной, стоимость приобретения полученных акционером в результате реорганизации акций каждой из созданных (реорганизованной) организаций признается равной части стоимости принадлежавших акционеру акций реорганизуемой организации, пропорциональной отношению величины уставного капитала каждой из созданных с участием акционеров организаций к величине уставного капитала реорганизуемой организации на последнюю отчетную дату, предшествующую реорганизации.\n\n(Дополнение пунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)","article_title":"Статья 277. Особенности признания доходов и расходов при передаче имущества (имущественных прав) в уставный (складочный) капитал (фонд, имущество фонда), в качестве имущественного взноса Российской Федерации в государственные корпорации, при реорганизации и ликвидации организации, при выделении активов из паевого инвестиционного фонда","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ee4fdb02306719bce555e194830e3a325a61c0d0f45f8360fa45bed2c1d9a48"},{"code_id":"NK_RF_2","article_number":"278","version_date":"2000-07-31","article_text":"1. Для целей настоящей главы не признается реализацией товаров (работ, услуг) передача налогоплательщиками имущества, в том числе имущественных прав, в качестве вкладов участников простых товариществ (далее в настоящей статье - товарищество).\n\n2. В случае, если хотя бы одним из участников товарищества является российская организация либо физическое лицо, являющееся налоговым резидентом Российской Федерации, ведение учета доходов и расходов такого товарищества для целей налогообложения должно осуществляться российским участником независимо от того, на кого возложено ведение дел товарищества в соответствии с договором.","article_title":"Статья 278. Особенности определения налоговой базы по доходам, полученным участниками договора простого товарищества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33a859ab7198bceb730db9f1f1c55580fbe470e06e7221fd38d3b525bc8e28d6"},{"code_id":"NK_RF_2","article_number":"278.1","version_date":"2000-07-31","article_text":"1. Налоговая база по консолидированной группе налогоплательщиков (далее в настоящей главе - консолидированная налоговая база) определяется как сумма всех налоговых баз участников консолидированной группы с учетом особенностей, установленных настоящей статьей. При этом налоговая база каждого участника консолидированной группы налогоплательщиков определяется в порядке, установленном статьей 274 настоящего Кодекса, с учетом положений статьи 283 настоящего Кодекса.\n\nВ налоговую базу каждого участника консолидированной группы налогоплательщиков, включаемую в консолидированную налоговую базу, не включаются доходы участников консолидированной группы налогоплательщиков, подлежащие обложению налогом у источника выплаты доходов.\n\nУбытки, полученные участниками консолидированной группы налогоплательщиков в отчетном (налоговом) периоде,\n\nподлежат суммированию. Консолидированная налоговая база текущего отчетного (налогового) периода определяется с учетом указанной суммы убытков. При этом такая сумма убытков учитывается в размере, не превышающем 50 процентов консолидированной налоговой базы текущего отчетного (налогового) периода. Порядок учета убытков участников консолидированной группы налогоплательщиков при определении консолидированной налоговой базы текущего отчетного (налогового) периода устанавливается в учетной политике для целей налогообложения консолидированной группы налогоплательщиков.\n\nСумма убытка участника консолидированной группы налогоплательщиков, оставшаяся не учтенной при определении консолидированной налоговой базы за налоговый период, принимается в целях налогообложения у такого участника в порядке и на условиях, которые установлены статьей 283 настоящего Кодекса.\n\nВ случае, если в отчетном (налоговом) периоде убытки получены всеми участниками консолидированной группы налогоплательщиков, в данном отчетном (налоговом) периоде консолидированная налоговая база признается равной нулю.\n\n(Пункт в редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n2. Налоговый учет операций, осуществляемых между участниками консолидированной группы налогоплательщиков, ведется в соответствии со статьей 3212 настоящего Кодекса.\n\n3. Участники консолидированной группы налогоплательщиков не формируют резервы по сомнительным долгам в соответствии со статьей 266 настоящего Кодекса в части задолженности одних участников этой группы перед другими участниками такой группы.\n\nУчастники консолидированной группы налогоплательщиков восстанавливают резерв по сомнительным долгам на сумму задолженности, относящейся к другим участникам этой группы. Соответствующие суммы включаются в состав внереализационных доходов в налоговом периоде, предшествующем налоговому периоду, в котором налогоплательщик стал участником консолидированной группы налогоплательщиков.\n\n4. Участники консолидированной группы налогоплательщиков не формируют резервы по гарантийному ремонту и гарантийному обслуживанию в соответствии со статьей 267 настоящего Кодекса в части реализации товаров (работ) другим участникам этой группы.\n\nПри вхождении налогоплательщика в состав консолидированной группы налогоплательщиков резерв по гарантийному ремонту и гарантийному обслуживанию восстанавливается в части сумм резервов, относящихся к товарам (работам), реализованным другим участникам этой группы. При этом производится корректировка определяемого в соответствии с пунктом 3 статьи 267 настоящего Кодекса предельного размера резерва, исключающая операции между участниками одной консолидированной группы налогоплательщиков при определении показателей фактически осуществленных налогоплательщиком расходов по гарантийному ремонту и гарантийному обслуживанию, в объеме выручки от реализации указанных товаров (работ) за предыдущие три года, а также выручки от реализации указанных товаров (работ) за отчетный (налоговый) период.\n\nКорректировка показателя выручки от реализации товаров (работ) за предыдущие три года до начала налогового периода, в котором налогоплательщик стал участником консолидированной группы налогоплательщиков, не производится. В налоговых периодах, в которых налогоплательщик является участником консолидированной группы налогоплательщиков, этот показатель не включает выручку от реализации указанных товаров (работ) другим участникам такой группы.\n\nСуммы восстановленных резервов по гарантийному ремонту и гарантийному обслуживанию, в том числе в результате уменьшения предельного размера резерва, включаются в состав внереализационных доходов в налоговом периоде, предшествующем налоговому периоду, в котором налогоплательщик стал участником консолидированной группы налогоплательщиков.\n\n5. Банки, являющиеся участниками консолидированной группы налогоплательщиков, не формируют резервы на возможные потери по ссудам по ссудной и приравненной к ней задолженности, включая задолженность по межбанковским кредитам и депозитам, в соответствии со статьей 292 настоящего Кодекса в части задолженности одних участников консолидированной группы налогоплательщиков перед другими участниками этой группы.\n\nБанки восстанавливают резерв на возможные потери по ссудам по ссудной и приравненной к ней задолженности, включая задолженность по межбанковским кредитам и депозитам, на сумму задолженности, относящейся к другим участникам этой группы. Соответствующие суммы включаются в состав внереализационных доходов в налоговом периоде, предшествующем налоговому периоду, в котором банк стал участником консолидированной группы налогоплательщиков.\n\n6. Участники консолидированной группы налогоплательщиков, понесшие убытки, исчисленные в соответствии с настоящей главой, в налоговых периодах, предшествующих налоговому периоду их вхождения в состав этой группы, не вправе уменьшить консолидированную налоговую базу на всю сумму понесенного ими убытка (на часть этой суммы) (перенести убыток на будущее) в порядке, установленном статьями 2751 и 283 настоящего Кодекса, начиная с налогового периода, в котором они вошли в состав такой группы.\n\nНе допускается суммирование убытков участников консолидированной группы налогоплательщиков (включая убытки, понесенные от использования объектов обслуживающих производств и хозяйств, в соответствии со статьей 2751 настоящего Кодекса), понесенных ими до вхождения в состав этой группы, с консолидированной налоговой базой. Указанное положение распространяется также на убытки, понесенные организациями, которые вошли в состав консолидированной группы налогоплательщиков путем присоединения к участнику этой группы или слияния с участником такой группы.\n\n7. Нормативы принимаемых для целей налогообложения расходов, предусмотренные пунктами 16 и 241 части второй статьи 255, подпунктом 6 пункта 2 статьи 262, подпунктами 11 и 482 пункта 1, пунктами 2 и 4 статьи 264, пунктом 4 статьи 266, подпунктом 4 пункта 2 статьи 296 настоящего Кодекса, применяются каждым участником консолидированной группы налогоплательщиков.\n\nУчастники консолидированной группы налогоплательщиков самостоятельно в соответствии с настоящей главой определяют налоговую базу, к которой применяются иные налоговые ставки. Указанная в настоящем абзаце налоговая база не учитывается при исчислении налога по консолидированной группе налогоплательщиков.\n\n(Дополнение статьей - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 278.1. Особенности определения налоговой базы по доходам, полученным участниками консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a8464ed46209f1277135d97dfcebcfd100a54c69d394d9992f83d92ef1571ff"},{"code_id":"NK_RF_2","article_number":"278.2","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 10.07.2023 № 318-ФЗ)\n\n1. Ведение учета доходов и расходов инвестиционного товарищества для целей налогообложения должно осуществляться являющейся налоговым резидентом Российской Федерации организацией - участником договора инвестиционного товарищества в соответствии с настоящей главой.\n\nВедение учета доходов и расходов инвестиционного товарищества для целей налогообложения может осуществляться иностранной организацией, только если ее деятельность создает постоянное представительство в Российской Федерации.\n\nПри определении прибыли (убытка) инвестиционного товарищества управляющий товарищ, ответственный за ведение налогового учета, не учитывает выплачиваемые участникам договора инвестиционного товарищества доходы в виде дивидендов по акциям, долям участия в уставном капитале организаций, входящим в состав общего имущества товарищей. Указанные доходы включаются в доходы от долевого участия в деятельности организаций у участников инвестиционного товарищества. (В редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\n1) по операциям с ценными бумагами, не обращающимися на организованном рынке ценных бумаг, и с производными финансовыми инструментами, не обращающимися на организованном рынке ценных бумаг;\n\n2) по прочим операциям.\n\n(Пункт в редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\nЕсли выплата вознаграждения участникам договора инвестиционного товарищества - управляющим товарищам осуществляется за счет средств на счете инвестиционного товарищества, сумма соответствующих расходов налогоплательщика определяется им на основании сведений, предоставляемых управляющим товарищем, ответственным за ведение налогового учета.\n\nАбзац. (Утратил силу - Федеральный закон от 10.07.2023 № 318-ФЗ)\n\nПрибыль (убыток) участника договора инвестиционного товарищества от участия в инвестиционном товариществе применительно к операциям, указанным в пункте 4 настоящей статьи, учитывается в составе внереализационных доходов (расходов) при определении соответствующей налоговой базы по указанным операциям, осуществленным таким участником вне рамок инвестиционного товарищества.\n\n(Пункт в редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\n10. Прибыль (убыток) налогоплательщика при выходе из инвестиционного товарищества, в том числе в результате уступки прав и обязанностей по договору инвестиционного товарищества, передачи доли в праве собственности на общее имущество участников договора инвестиционного товарищества, выдела доли из имущества, находящегося в общей собственности товарищей, либо при прекращении договора инвестиционного товарищества определяется в соответствии с настоящим пунктом.\n\nДоходы, полученные налогоплательщиком при выходе из инвестиционного товарищества либо прекращении договора инвестиционного товарищества:\n\nуменьшаются на величину прибыли участника договора инвестиционного товарищества от участия в инвестиционном товариществе, ранее учтенной при определении соответствующих налоговых баз;\n\nуменьшаются на величину вклада налогоплательщика в инвестиционное товарищество, оплаченную им к моменту выхода из инвестиционного товарищества (прекращения договора инвестиционного товарищества), если иное не установлено пунктом 7 статьи 2861 настоящего Кодекса, и (или) расходов налогоплательщика на приобретение прав и обязанностей по договору инвестиционного товарищества; (В редакции  Федерального закона от 30.09.2024 № 337-ФЗ)\n\nувеличиваются на величину ранее учтенных налогоплательщиком при определении соответствующих налоговых баз убытков участника договора инвестиционного товарищества от участия в инвестиционном товариществе.\n\nПрибыль (убыток) участника договора инвестиционного товарищества от участия в инвестиционном товариществе, относящаяся к ранее осуществленным фактическим выплатам, связанным с распределением прибыли инвестиционного товарищества, не учитывается при определении прибыли (убытка) налогоплательщика при выходе из инвестиционного товарищества либо прекращении договора инвестиционного товарищества.\n\nДоходы, полученные в виде имущества и (или) имущественных прав, определяются по рыночной стоимости данных имущества и (или) имущественных прав на дату признания таких доходов.\n\nПрибыль (убыток) налогоплательщика при выходе из инвестиционного товарищества либо прекращении договора инвестиционного товарищества учитывается налогоплательщиком при определении налоговой базы по операциям с ценными бумагами, не обращающимися на организованном рынке ценных бумаг, и с производными финансовыми инструментами, не обращающимися на организованном рынке ценных бумаг.\n\nВ случае возврата причитающейся налогоплательщику части вклада в общее имущество товарищей прибыль (убыток) участника договора инвестиционного товарищества при таком возврате определяется в порядке, предусмотренном настоящим пунктом. При этом соответствующие прибыль, убыток и расходы определяются исходя из доли возвращаемой части вклада в общей стоимости вклада в общее имущество товарищей. В этом случае доля участия каждого участника договора инвестиционного товарищества в прибыли инвестиционного товарищества подлежит пересчету.\n\n(Пункт в редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.11.2011 № 336-ФЗ)","article_title":"Статья 278.2. Особенности определения налоговой базы участниками договора инвестиционного товарищества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"021e8444a74a8ad288d92cc8f94cd93718c6848675500fcb00d63169cd957ab3"},{"code_id":"NK_RF_2","article_number":"279","version_date":"2000-07-31","article_text":"1. При уступке налогоплательщиком - продавцом товаров (работ, услуг), осуществляющим исчисление доходов (расходов) по методу начисления, права требования долга третьему лицу до наступления предусмотренного договором о реализации товаров (работ, услуг) срока платежа отрицательная разница между доходом от реализации права требования долга и стоимостью реализованных товаров (работ, услуг) признается убытком налогоплательщика.\n\nПри этом размер убытка для целей налогообложения не может превышать сумму процентов, которую налогоплательщик уплатил бы исходя из максимальной ставки процента, установленной для соответствующего вида валюты пунктом 12 статьи 269 настоящего Кодекса, либо по выбору налогоплательщика исходя из ставки процента, подтвержденной в соответствии с методами, установленными разделом V1 настоящего Кодекса по долговому обязательству, равному доходу от уступки права требования, за период от даты уступки до даты платежа, предусмотренного договором на реализацию товаров (работ, услуг). Положения настоящего пункта и абзаца первого пункта 4 настоящей статьи также применяются к налогоплательщику-кредитору по долговому обязательству. Порядок учета убытка в соответствии с настоящим пунктом должен быть закреплен в учетной политике налогоплательщика.\n\nПоложения абзаца второго настоящего пункта в части ограничения размера убытка не применяются при уступке налогоплательщиком-банком прав (требований) в случае, если такая уступка прав (требований) осуществляется в рамках реализации мероприятий, предусмотренных планом участия Банка России в осуществлении мер по предупреждению банкротства банка, либо если уступка прав (требований), перечень которых определен актом Правительства Российской Федерации, принятым на основании части 1 статьи 5 Федерального закона от 29 июля 2018 года № 263-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации\", осуществляется в соответствии с порядком, определенным частью 1 статьи 5 указанного Федерального закона. (Дополнение абзацем - Федеральный закон от 06.06.2019 № 125-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\nПоложения настоящего пункта также применяются к налогоплательщику-кредитору по долговому обязательству. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nЕсли предусмотренная пунктом 2 или 3 настоящей статьи сделка по уступке права требования долга признается контролируемой согласно разделу V1 настоящего Кодекса, цена такой сделки определяется с учетом положений раздела V1 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)","article_title":"Статья 279. Особенности определения налоговой базы при уступке (переуступке) права требования","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1fe22a7810d2ba40bef6fe8bbe94442314042e2222b83739a8790f8d372e5963"},{"code_id":"NK_RF_2","article_number":"280","version_date":"2000-07-31","article_text":"1. Порядок отнесения объектов гражданских прав к ценным бумагам, а также порядок отнесения ценных бумаг к эмиссионным ценным бумагам устанавливается гражданским законодательством Российской Федерации и применимым законодательством иностранных государств.\n\nПри этом ценные бумаги, выпущенные в соответствии с применимым законодательством иностранных государств, относятся к эмиссионным ценным бумагам в случае их соответствия критериям, установленным Федеральным законом \"О рынке ценных бумаг\".\n\nВ случае, если операция с ценными бумагами соответствует критериям операции с производными финансовыми инструментами, налогоплательщик самостоятельно относит указанную операцию в целях налогообложения к операции с ценными бумагами либо к операции с производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nВ целях настоящей статьи под общей налоговой базой понимается налоговая база по прибыли, облагаемой по ставке, указанной в пункте 1 статьи 284 настоящего Кодекса, и по такой налоговой базе в соответствии с настоящей главой не предусмотрен отличный от общего порядок учета прибыли и убытка с учетом особенностей, предусмотренных пунктом 10 статьи 3091 или пунктом 22 статьи 277 настоящего Кодекса. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nВ целях настоящей статьи под применимым законодательством понимается законодательство государства, на территории которого осуществляется обращение ценных бумаг (заключение налогоплательщиком гражданско-правовых сделок, влекущих переход права собственности на ценные бумаги). В случаях невозможности однозначно определить, на территории какого государства заключались сделки с ценными бумагами вне организованного рынка ценных бумаг, включая сделки, заключаемые посредством электронных торговых систем, налогоплательщик вправе самостоятельно установить в своей учетной политике порядок определения применимого законодательства. При этом, если ценные бумаги признаются обращающимися на российском организованном рынке ценных бумаг, под применимым законодательством понимается законодательство Российской Федерации.\n\n2. Доходы налогоплательщика от операций по реализации или от иного выбытия ценных бумаг (в том числе от погашения или частичного погашения их номинальной стоимости) определяются исходя из цены реализации или иного выбытия ценной бумаги, а также суммы накопленного процентного (купонного) дохода, уплаченной налогоплательщику покупателем, и суммы процентного (купонного) дохода, выплаченной налогоплательщику эмитентом (векселедателем). При этом в доход налогоплательщика от реализации или иного выбытия ценных бумаг не включаются суммы процентного (купонного) дохода, ранее учтенные при налогообложении.\n\nДоходы налогоплательщика от операций по реализации или от иного выбытия ценных бумаг (в том числе от погашения или частичного погашения их номинальной стоимости), цена реализации которых выражена в иностранной валюте, определяются по официальному курсу Центрального банка Российской Федерации, действовавшему на дату перехода права собственности либо на дату фактического погашения или фактического получения налогоплательщиком сумм частичного погашения номинальной стоимости.\n\nПри определении расходов при реализации или ином выбытии (в том числе при погашении или частичном погашении номинальной стоимости) ценных бумаг, цена приобретения которых выражена в иностранной валюте (включая расходы на их приобретение), такая цена определяется по официальному курсу Центрального банка Российской Федерации, действовавшему на дату принятия указанной ценной бумаги к учету с учетом положений пункта 10 статьи 272 настоящего Кодекса.\n\nРасходы по реализации ценных бумаг определяются в соответствии с настоящим пунктом также в следующих случаях:\n\nликвидация организации - эмитента ценных бумаг;\n\nликвидация организации - заемщика, в целях финансирования займа (кредита) которого выпускались облигации;\n\nотсутствие по иным основаниям, предусмотренным условиями выпуска ценных бумаг, обязательств организации - эмитента ценных бумаг производить платежи по таким ценным бумагам при их погашении.\n\nДанное положение применяется держателями еврооблигаций или еврооблигаций Российской Федерации, если такие ценные бумаги принадлежали им на праве собственности или ином вещном праве на 1 марта 2022 года.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n1) прекращение обязательств налогоплательщика передать (принять) соответствующие ценные бумаги зачетом встречных однородных требований, в том числе в случае прекращения таких обязательств при осуществлении клиринга в соответствии с законодательством Российской Федерации;\n\n2) зачет встречных требований, вытекающих из договоров, заключенных на условиях генерального соглашения (единого договора), которое соответствует примерным условиям договоров, предусмотренным Федеральным законом \"О рынке ценных бумаг\", если такой зачет произведен в целях определения суммы нетто-обязательства;\n\n3) зачет встречных требований, вытекающих из договоров, заключенных на условиях правил организованных торгов или правил клиринга, если такой зачет произведен в целях определения суммы нетто-обязательства.\n\nРасходы налогоплательщика при реализации или ином выбытии депозитарных расписок, полученных в результате их размещения, определяются исходя из цены приобретения представляемых ценных бумаг, переданных при размещении депозитарных расписок (включая расходы, связанные с их приобретением), расходов, связанных с такой передачей, а также расходов, связанных с реализацией (выбытием) депозитарных расписок. При этом в случае, если представляемые ценные бумаги были приобретены налогоплательщиком при погашении депозитарных расписок, цена приобретения таких представляемых ценных бумаг определяется исходя из цены приобретения депозитарных расписок, расходов, связанных с таким приобретением, а также расходов, связанных с погашением депозитарных расписок.\n\nВ целях настоящей главы не признается реализацией или иным выбытием ценных бумаг:\n\nпогашение депозитарных расписок при получении представляемых ценных бумаг;\n\nпередача представляемых ценных бумаг при размещении депозитарных расписок, удостоверяющих права на представляемые ценные бумаги.\n\nпогашение клиринговых сертификатов участия при получении от клиринговой организации соответствующих таким сертификатам ценных бумаг и иного имущества, внесенных в имущественный пул клиринговой организации;\n\nпередача клиринговой организации ценных бумаг в счет выдаваемых такой клиринговой организацией клиринговых сертификатов участия;\n\nпризнание акций иностранной организации акциями международной компании, зарегистрированной в соответствии с Федеральным законом от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\". При этом расходами на приобретение акций международной компании и (или) их стоимостью в целях настоящей главы признаются соответственно расходы на приобретение акций иностранной организации, в порядке редомициляции которой создана такая международной компания, и (или) их стоимость. (Дополнение абзацем - Федеральный закон от 25.12.2018 № 490-ФЗ) (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n1) если они допущены к обращению хотя бы одним организатором торговли, имеющим на это право в соответствии с применимым законодательством;\n\n2) если информация об их ценах (котировках) публикуется в средствах массовой информации (в том числе электронных) либо может быть представлена организатором торговли или иным уполномоченным лицом любому заинтересованному лицу в течение трех лет после даты совершения операций с ценными бумагами;\n\n3) если по ним в течение последовательных трех месяцев, предшествующих дате совершения налогоплательщиком сделки с этими ценными бумагами, хотя бы один раз рассчитывалась рыночная котировка (за исключением случая расчета рыночной котировки при первичном размещении ценных бумаг эмитентом).\n\nдля ценных бумаг, допущенных к торгам российского организатора торговли (включая биржу), - средневзвешенная цена ценной бумаги по сделкам, совершенным в течение торгового дня через такого организатора торговли;\n\nдля ценных бумаг, допущенных к торгам иностранного организатора торговли (включая биржу), - цена закрытия по ценной бумаге, рассчитываемая таким организатором торговли по сделкам, совершенным через него в течение торгового дня.\n\nЕсли по одной и той же ценной бумаге сделки совершались через двух и более организаторов торговли, налогоплательщик вправе самостоятельно выбрать рыночную котировку, сложившуюся у одного из организаторов торговли.\n\nВ случае, если средневзвешенная цена организатором торговли не рассчитывается, в целях настоящей главы средневзвешенной ценой признается половина суммы максимальной и минимальной цен сделок, совершенных в течение торгового дня через этого организатора торговли.\n\n1) датой совершения сделки признается дата проведения торгов, на которых была заключена соответствующая сделка с ценной бумагой;\n\n2) для целей налогообложения признается фактическая цена реализации (приобретения) или иного выбытия ценных бумаг, если иное не предусмотрено подпунктом 3 настоящего пункта; (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n3) по сделкам, совершенным на основании адресных заявок, признаваемым контролируемыми в соответствии с разделом V1 настоящего Кодекса, для целей налогообложения признается цена реализации (приобретения) или иного выбытия ценных бумаг, определяемая в порядке, предусмотренном подпунктами 2 и 3 пункта 12 настоящей статьи. (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n1) датой совершения сделки признается дата договора, определяющего все существенные условия передачи ценной бумаги;\n\n2) если иное не установлено настоящей статьей, рыночной ценой обращающейся ценной бумаги для целей налогообложения признается фактическая цена реализации (приобретения) или иного выбытия ценной бумаги при соблюдении одного из следующих условий:\n\nесли на дату совершения сделки было зарегистрировано более одной сделки с ценной бумагой, ее рыночной ценой признается фактическая цена совершенной сделки при условии, что эта цена на дату совершения сделки находится в интервале между максимальной и минимальной ценами сделок (интервал цен) с указанной ценной бумагой, зарегистрированной организатором (организаторами) торговли на эту дату;\n\nесли на дату совершения сделки была зарегистрирована одна сделка с ценной бумагой, ее рыночной ценой признается фактическая цена совершенной сделки, если она соответствует цене одной другой сделки с указанной ценной бумагой на дату совершения сделки, в отношении которой определяется рыночная цена;\n\n3) в целях применения подпункта 2 настоящего пункта:\n\nмаксимальная и минимальная цены сделок (цена одной сделки), зарегистрированные организатором торговли, определяются по сделкам, совершенным на основании безадресных заявок;\n\nпри отсутствии информации об интервале цен (цене одной сделки) у организаторов торговли на дату совершения сделки в целях настоящего пункта принимается интервал цен (цена одной сделки) при реализации этих ценных бумаг по данным организаторов торговли на дату ближайших торгов, состоявшихся до дня совершения соответствующей сделки, если торги по этим ценным бумагам проводились у организатора торговли хотя бы один раз в течение трех последовательных месяцев, предшествующих дате совершения сделки;\n\nесли по одной и той же ценной бумаге сделки на указанную дату совершались через двух и более организаторов торговли, налогоплательщик вправе самостоятельно выбрать организатора торговли, значения интервала цен (цена одной сделки) которого будут использованы для определения ее цены для целей налогообложения, если иное не установлено настоящим пунктом. При этом в случае, если у некоторых из организаторов торговли, указанных в настоящем абзаце, было зарегистрировано более одной сделки с этой ценной бумагой, а у других организаторов торговли была зарегистрирована только одна сделка с этой ценной бумагой, налогоплательщик вправе самостоятельно выбрать организатора торговли, значения интервала цен которого будут использованы для определения ее цены для целей налогообложения, из числа тех организаторов торговли, у кого было зарегистрировано более одной сделки с этой ценной бумагой.\n\nВ случае приобретения обращающихся ценных бумаг по цене выше максимальной цены сделок на организованном рынке ценных бумаг при определении финансового результата принимается максимальная цена сделки на организованном рынке ценных бумаг.\n\nВ целях настоящего пункта при совершении единственной сделки на организованном рынке ценных бумаг цена такой сделки признается максимальной (минимальной) ценой.\n\nинвестиционного фонда, в том числе в случае их приобретения (погашения) у управляющей компании, осуществляющей доверительное управление имуществом, составляющим соответствующий открытый паевой инвестиционный фонд, фактическая цена сделки признается рыночной и принимается для целей налогообложения, если она равна расчетной стоимости инвестиционного пая, определенной в порядке, установленном законодательством Российской Федерации об инвестиционных фондах.\n\nВ целях настоящей статьи предельное отклонение цен необращающихся ценных бумаг устанавливается в размере 20 процентов в сторону повышения или понижения от расчетной цены ценной бумаги.\n\nВ случае реализации необращающихся ценных бумаг по цене ниже минимальной цены, определенной исходя из расчетной цены ценной бумаги и предельного отклонения цен, при определении финансового результата для целей налогообложения принимается минимальная цена, определенная исходя из расчетной цены ценной бумаги и предельного отклонения цен.\n\nВ случае приобретения необращающихся ценных бумаг по цене выше максимальной цены, определенной исходя из расчетной цены ценной бумаги и предельного отклонения цен, при определении финансового результата для целей налогообложения принимается максимальная цена, определенная исходя из расчетной цены ценной бумаги и предельного отклонения цен.\n\nПорядок определения расчетной цены необращающихся ценных бумаг устанавливается в целях настоящей главы Центральным банком Российской Федерации по согласованию с Министерством финансов Российской Федерации.\n\nПо операциям с необращающимися инвестиционными паями закрытых и интервальных паевых инвестиционных фондов, в том числе в случае их приобретения у управляющей компании, осуществляющей доверительное управление имуществом, составляющим соответствующий паевой инвестиционный фонд, для целей налогообложения принимается фактическая цена сделки, если она равна расчетной стоимости инвестиционного пая, определенной в порядке, установленном законодательством Российской Федерации об инвестиционных фондах.\n\nЕсли в соответствии с законодательством Российской Федерации об инвестиционных фондах выдача, погашение или обмен инвестиционных паев паевых инвестиционных фондов, ограниченных в обороте, осуществляется не по расчетной стоимости инвестиционного пая, для целей налогообложения принимается фактическая цена сделки, если она равна сумме денежных средств, на которую выдается один инвестиционный пай и которая определена в соответствии с правилами доверительного управления паевым инвестиционным фондом без учета предельной границы колебаний.\n\nРасчетная цена необращающихся инвестиционных паев для целей налогообложения определяется на предшествующую дату, на которую определяется расчетная стоимость инвестиционного пая, ближайшую к дате совершения сделки.\n\n1) покупатель ценных бумаг (совместно с аффилированными лицами) становится владельцем более 5 процентов соответствующего выпуска ценных бумаг;\n\n2) количество ценных бумаг превышает 1 процент соответствующего выпуска ценных бумаг;\n\n3) цена ценных бумаг установлена по решению органов государственной власти или органов местного самоуправления;\n\n4) покупатель (продавец) ценных бумаг является эмитентом этих ценных бумаг, в том числе по оферте.\n\n20. Налогоплательщик-акционер, реализующий акции, полученные им при увеличении уставного капитала акционерного общества, определяет доход как разницу между ценой реализации и первоначально оплаченной стоимостью акции, скорректированной с учетом изменения количества акций в результате увеличения уставного капитала.\n\n21. Доходы (расходы) по операциям с обращающимися ценными бумагами учитываются в общеустановленном порядке в общей налоговой базе.\n\nЕсли иное не установлено настоящей статьей или статьей 304 настоящего Кодекса, доходы, полученные от операций с обращающимися ценными бумагами за отчетный (налоговый) период, не могут быть уменьшены на расходы либо убытки от операций с необращающимися ценными бумагами, а также на расходы либо убытки от операций с необращающимися производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nДоходы (расходы) по операциям с инвестиционными паями дополнительного фонда, которые были получены налогоплательщиком при его формировании путем выделения активов из паевого инвестиционного фонда, инвестиционные паи которого в целях настоящей главы относились на дату такого выделения к ценным бумагам, обращающимся на организованном рынке ценных бумаг, и инвестиционными паями паевого инвестиционного фонда, тип которого был изменен на закрытый паевой инвестиционный фонд в соответствии с Федеральным законом от 14 июля 2022 года № 319-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации\" и инвестиционные паи которого на дату такого изменения принадлежали налогоплательщику на праве собственности или ином вещном праве и в целях настоящей главы относились к ценным бумагам, обращающимся на организованном рынке ценных бумаг, учитываются таким налогоплательщиком в установленном порядке в общей налоговой базе. (Дополнение абзацем - Федеральный закон от 14.02.2024 № 8-ФЗ)\n\nПри этом убытки от операций с необращающимися ценными бумагами и необращающимися производными финансовыми инструментами, полученные в предыдущем налоговом периоде (предыдущих налоговых периодах), могут быть отнесены на уменьшение налоговой базы от операций с такими ценными бумагами и производными финансовыми инструментами, определенной в отчетном (налоговом) периоде, с учетом ограничения, установленного пунктом 21 статьи 283 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n23. Если иное не установлено настоящей главой, при реализации или ином выбытии ценных бумаг налогоплательщик самостоятельно в соответствии с принятой в целях налогообложения учетной политикой выбирает один из следующих методов списания на расходы стоимости выбывших ценных бумаг:\n\n1) по стоимости первых по времени приобретений (ФИФО);\n\n2) по стоимости единицы.\n\nУказанный убыток увеличивается на сумму накопленного процентного (купонного) дохода по таким ценным бумагам, ранее учтенную при определении налоговой базы в соответствии со статьями 271 и 328 настоящего Кодекса, но фактически не полученную налогоплательщиком вследствие ликвидации организации-эмитента, если под него не создавался резерв по сомнительным долгам, и учитывается при определении налоговой базы, в которой учитывался соответствующий накопленный процентный (купонный) доход, на дату ликвидации организации-эмитента.\n\nПравила учета убытка при ликвидации организации, установленные настоящим пунктом, применяются также в отношении убытка, полученного при ликвидации:\n\nорганизации-заемщика в случае прекращения обязательств по ценным бумагам, выпущенным в целях финансирования займа (кредита);\n\nорганизации - эмитента базовых ценных бумаг, если по условиям выпуска ценных бумаг исполнение обязательств по ним, включая их погашение, поставлено в зависимость от исполнения обязательств по базовым ценным бумагам.\n\nУправляющими компаниями для целей настоящего Кодекса признаются управляющие компании, осуществляющие деятельность в соответствии с Федеральным законом от 29 ноября 2001 года № 156-ФЗ \"Об инвестиционных фондах\".\n\nКлиринговыми организациями, осуществляющими функции центрального контрагента, для целей настоящего Кодекса признаются клиринговые организации, осуществляющие деятельность в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\".\n\nК профессиональным участникам рынка ценных бумаг в целях настоящей главы приравниваются кредитные организации, имеющие соответствующую лицензию профессионального участника рынка ценных бумаг, выданную Центральным банком Российской Федерации.\n\nНалогоплательщики, указанные в абзаце первом настоящего пункта, уменьшают общую налоговую базу на сумму убытков, полученных по операциям с необращающимися ценными бумагами и необращающимися производными финансовыми инструментами. В течение налогового периода перенос на будущее убытков, полученных налогоплательщиками, указанными в абзаце первом настоящего пункта, в соответствующем отчетном периоде текущего налогового периода, может быть осуществлен только в пределах суммы полученной ими прибыли. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n27. В целях настоящей главы накопленным процентным (купонным) доходом признается часть процентного (купонного) дохода, выплата которого предусмотрена условиями выпуска такой ценной бумаги, рассчитываемая пропорционально количеству календарных дней, прошедших от даты выпуска ценной бумаги или даты выплаты предшествующего купонного дохода до даты передачи ценной бумаги.\n\n28. По операциям с закладными налоговая база определяется в соответствии с пунктами 1 и 3 статьи 279 настоящего Кодекса.\n\n29. Положения подпунктов 2 и 3 пункта 12 и пунктов 14 - 17 и 19 настоящей статьи в части определения цен ценных бумаг (инвестиционных паев) в целях налогообложения применяются исключительно в отношении сделок, признаваемых контролируемыми в соответствии с разделом V1 настоящего Кодекса.\n\nВ отношении сделок, не признаваемых контролируемыми в соответствии с разделом V1 настоящего Кодекса, для целей налогообложения применяется фактическая цена этих сделок.\n\n(Статья в редакции Федерального закона от 28.12.2013 № 420-ФЗ)","article_title":"Статья 280. Особенности определения налоговой базы по операциям с ценными бумагами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"98341465006ce3d842f316a97163a08c0b7d568fddc973fe9027df7da9e1a187"},{"code_id":"NK_RF_2","article_number":"281","version_date":"2000-07-31","article_text":"При размещении государственных ценных бумаг государств - участников Союзного государства, государственных ценных бумаг субъектов Российской Федерации и муниципальных ценных бумаг (далее - государственные и муниципальные ценные бумаги) процентным доходом признается доход, заявленный (установленный) эмитентом, в виде процентной ставки к номинальной стоимости указанных ценных бумаг, а по ценным бумагам, по которым не установлена процентная ставка, - доход в виде разницы между номинальной стоимостью ценной бумаги и стоимостью ее первичного размещения, исчисленной как средневзвешенная цена на дату, когда выпуск ценных бумаг в соответствии с установленным порядком признан размещенным. (Дополнение частью - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 05.04.2010 № 41-ФЗ)\n\nПри налогообложении сделок по реализации или иного выбытия ценных бумаг цена эмиссионных государственных и муниципальных ценных бумаг учитывается без процентного (купонного) дохода, который облагается по ставке иной, чем предусмотрена пунктом 1 статьи 284 настоящего Кодекса, приходящегося на время владения налогоплательщиком этими ценными бумагами, выплата которого предусмотрена условиями выпуска такой ценной бумаги. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nНалогообложение процентов, начисленных за время нахождения государственной и муниципальной ценной бумаги на балансе налогоплательщика, осуществляется в порядке и на условиях, которые установлены настоящей главой. По государственным и муниципальным ценным бумагам, при обращении которых в цену сделки включается часть накопленного купонного дохода, выручка уменьшается на доход в размере накопленного купонного дохода, причитающегося за время владения налогоплательщиком указанной ценной бумагой.","article_title":"Статья 281. Особенности определения налоговой базы по операциям с государственными и муниципальными ценными бумагами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"041c2b5b8bfd988c5ea3019c4b4e3c7362a2233156691e45a5138bf2c7ad2585"},{"code_id":"NK_RF_2","article_number":"282","version_date":"2000-07-31","article_text":"1. Операцией РЕПО признается договор, отвечающий требованиям, предъявляемым к договорам репо Федеральным законом \"О рынке ценных бумаг\". При этом первой и второй частями РЕПО признаются первая и вторая части договора репо соответственно. Покупателем по первой части РЕПО и продавцом по первой части РЕПО признаются покупатель по договору репо и продавец по договору репо соответственно. В целях настоящей статьи обязательства по второй части РЕПО должны возникать при условии исполнения первой части РЕПО.\n\nЕсли условиями операции РЕПО предусматривается право продавца по первой части РЕПО до даты исполнения второй части РЕПО передавать покупателю по первой части РЕПО в обмен на ценные бумаги, переданные по первой части РЕПО, или на ценные бумаги, в которые они конвертированы, иные ценные бумаги и (или) предусматривается право покупателя по первой части РЕПО потребовать от продавца по первой части РЕПО такой передачи, порядок налогообложения по такой операции РЕПО, установленный настоящей статьей, не меняется. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nПравила настоящей статьи применяются также к операциям РЕПО налогоплательщика, совершенным за его счет комиссионерами, поверенными, агентами, доверительными управляющими (в том числе через организатора торговли на рынке ценных бумаг и на торгах биржи) на основании соответствующих гражданско-правовых договоров. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nВ целях настоящей статьи датами исполнения первой или второй части РЕПО считаются предусмотренные договором репо сроки исполнения участниками операции РЕПО своих обязательств по соответствующей части РЕПО. В случае исполнения обязательств по поставке ценных бумаг и по их оплате по первой или второй части РЕПО в разные даты датой первой и датой второй частей РЕПО соответственно признается наиболее поздняя из дат исполнения обязательств по оплате или поставке ценных бумаг.\n\nВ случае, если дата исполнения первой или второй части РЕПО, определенная договором, приходится на выходной и (или) нерабочий праздничный день в соответствии с законодательством Российской Федерации, датой исполнения первой или второй части РЕПО признается следующий за ним рабочий день. При этом применяется фактическая цена реализации (приобретения) ценной бумаги как по первой части РЕПО, так и по второй части РЕПО независимо от рыночной (расчетной) стоимости таких ценных бумаг. Такая цена реализации (приобретения) по обеим частям РЕПО исчисляется с учетом накопленного процентного (купонного) дохода на дату фактического исполнения каждой части РЕПО.\n\nДата исполнения обязательств по второй части РЕПО может быть изменена как в сторону сокращения срока РЕПО, так и в сторону его увеличения. Операции, по которым дата исполнения второй части РЕПО определена моментом востребования, признаются операциями РЕПО, если договором репо установлен порядок определения цены второй части РЕПО и если вторая часть РЕПО исполнена в течение одного года с даты исполнения сторонами обязательств по первой части РЕПО.\n\nДля операций РЕПО, совершаемых через организатора торговли на рынке ценных бумаг (биржу) либо с исполнением через клиринговую организацию, любое изменение даты исполнения второй части РЕПО, осуществляемое в соответствии с правилами организатора торговли на рынке ценных бумаг (биржи) или клиринговой организации, в целях настоящей статьи признается изменением срока РЕПО. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nВ целях настоящей статьи ставка РЕПО определяется при заключении операции РЕПО и может быть фиксированной или расчетной. Ставка РЕПО должна позволять определить величину процентов на конец отчетного (налогового) периода и может быть изменена по соглашению сторон договора репо.\n\nЕсли на дату исполнения второй части РЕПО обязательство по реализации (приобретению) ценных бумаг по второй части РЕПО полностью или частично не исполнено (далее в настоящей главе - ненадлежащее исполнение второй части РЕПО), но при этом взаиморасчеты между сторонами произведены в порядке, предусмотренном абзацем первым пункта 6 настоящей статьи (проведение процедуры урегулирования в\n\nзаимных требований), то налоговая база по такой операции РЕПО определяется в порядке, предусмотренном пунктом 6 настоящей статьи. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nВ иных случаях ненадлежащего исполнения второй части РЕПО операция РЕПО подлежит переквалификации в целях определения налоговой базы в порядке, предусмотренном пунктом 11 настоящей статьи. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nДля целей настоящей статьи не признается ненадлежащим исполнением второй части РЕПО: (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nисполнение обязательств по второй части РЕПО в течение 10 дней с согласованной сторонами даты исполнения второй части РЕПО; (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nисполнение (прекращение) обязательств путем зачета встречных требований в следующих случаях: (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nв случаях, если такие требования вытекают из договоров, заключенных на условиях генерального соглашения (единого договора), которое соответствует примерным условиям договоров, утвержденным в соответствии с Федеральным законом \"О рынке ценных бумаг\", и зачет встречных требований произведен в целях определения суммы нетто-обязательства; (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nв случаях, если такие требования вытекают из договоров, заключенных на условиях правил организованных торгов и (или) правил клиринга, и зачет встречных требований произведен в целях определения суммы нетто-обязательства. (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nРасходы на приобретение ценных бумаг, не переданных по второй части РЕПО, признаются покупателем по первой части РЕПО согласно подпункту 7 пункта 7 статьи 272 настоящего Кодекса на дату исполнения второй части РЕПО, если процедура урегулирования взаимных требований не предусмотрена договором репо, или на последний день истечения срока, предусмотренного договором репо для проведения сторонами договора репо процедуры урегулирования взаимных требований, если процедура урегулирования взаимных требований не осуществлена надлежащим образом, или на дату досрочного расторжения операции РЕПО по соглашению сторон и определяются исходя из рыночных цен, действовавших на дату перехода права собственности на ценные бумаги при совершении первой части РЕПО, а в случае, если в обмен на ценные бумаги, переданные по первой части РЕПО, или ценные бумаги, в которые они конвертированы, покупателю по первой части РЕПО были переданы иные ценные бумаги, - на дату их передачи покупателю по первой части РЕПО.\n\nПри реализации ценных бумаг по первой части РЕПО и по второй части РЕПО финансовый результат для целей налогообложения в соответствии со статьей 280 настоящего Кодекса не определяется. Расходы на приобретение ценных бумаг, сформированные в налоговом учете до даты исполнения первой части РЕПО, учитываются при реализации (выбытии) ценных бумаг в соответствии со статьями 280, 302 и 303 настоящего Кодекса. При этом налогоплательщик самостоятельно в соответствии с принятой им в целях налогообложения учетной политикой определяет порядок учета выбывающих (возвращающихся) по операции РЕПО ценных бумаг.\n\nПри исполнении (прекращении) обязательств по первой и (или) по второй частям РЕПО зачетом встречных однородных требований (за исключением зачета однородных требований по первой и второй частям в рамках одной операции РЕПО) порядок налогообложения, установленный настоящей статьей, не изменяется. Однородными признаются требования по передаче имеющих одинаковый объем прав ценных бумаг одного эмитента, одного вида, одной категории (типа) или одного паевого инвестиционного фонда (для инвестиционных паев инвестиционных фондов) или требования по уплате денежных средств в той же валюте.\n\nВ случае, если в период между датами исполнения первой и второй частей РЕПО осуществлены конвертация ценных бумаг, являющихся объектом операции РЕПО, в том числе в связи с их дроблением, или консолидацией, или изменением их номинальной стоимости, либо аннулирование индивидуального номера (кода) дополнительного выпуска таких ценных бумаг, либо изменение индивидуального государственного регистрационного номера выпуска (индивидуального номера (кода) дополнительного выпуска), индивидуального идентификационного номера (индивидуального номера (кода) дополнительного выпуска) таких ценных бумаг, то такие действия не изменяют порядок налогообложения по данной операции РЕПО.\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n11. Переквалификация операции РЕПО в целях определения налоговой базы осуществляется налогоплательщиком самостоятельно в следующих случаях:\n\n1) при несоблюдении требований, предъявляемых к договорам репо Федеральным законом \"О рынке ценных бумаг\", и (или) требований, предъявляемых настоящей статьей к операции РЕПО;\n\n2) при расторжении операции РЕПО;\n\n3) при ненадлежащем исполнении второй части РЕПО (за исключением случая, предусмотренного абзацем десятым пункта 1 настоящей статьи).\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n12. Переквалификация операции РЕПО в целях определения налоговой базы осуществляется на наиболее раннюю из дат наступления одного из условий, являющихся основанием для такой переквалификации в соответствии с настоящим пунктом.\n\nПри переквалификации операции РЕПО в целях определения налоговой базы участники операции РЕПО обязаны:\n\nучесть расходы по приобретению (доходы от реализации) ценных бумаг по первой и второй частям РЕПО при определении соответствующей налоговой базы с учетом положений статьи 280 настоящего Кодекса;\n\nвосстановить доходы (расходы) по операции РЕПО, учтенные ранее с учетом положений настоящей статьи.\n\nВ результате переквалификации операции РЕПО в целях определения налоговой базы налогоплательщик в отчетном периоде, в котором осуществляется переквалификация, восстанавливает доходы и расходы, ранее признанные при определении налоговой базы по операции РЕПО в соответствии с настоящей статьей, и признает реализацию (приобретение) соответствующих ценных бумаг с учетом требований статьи 280 настоящего Кодекса. При этом рыночная цена (расчетная цена) для целей определения налоговой базы по операциям с ценными бумагами в соответствии со статьей 280 настоящего Кодекса определяется на дату перехода права собственности на ценные бумаги по первой части РЕПО, а в случае, если в обмен на ценные бумаги, переданные по первой части РЕПО, или на ценные бумаги, в которые они конвертированы, покупателю по первой части РЕПО были переданы иные ценные бумаги, - на дату передачи таких ценных бумаг покупателю по первой части РЕПО.\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n2. По операции РЕПО выплаты по ценным бумагам, право на получение которых возникло у покупателя по первой части РЕПО в период между датами исполнения первой и второй частей РЕПО, могут приниматься в уменьшение суммы денежных средств, подлежащих уплате продавцом по первой части РЕПО при последующем приобретении ценных бумаг по второй части РЕПО, либо перечисляться покупателем по первой части РЕПО продавцу по первой части РЕПО в соответствии с договором репо. В указанных случаях такие выплаты не признаются доходами покупателя по первой части РЕПО и включаются в доходы продавца по первой части РЕПО в порядке, установленном настоящей главой.\n\nПроцентный (купонный) доход по ценным бумагам, являющимся объектом операции РЕПО, учитывается при определении налоговой базы продавца по первой части РЕПО в порядке, установленном статьями 271, 273 и 328 настоящего Кодекса, и не учитывается при определении налоговой базы по процентному (купонному) доходу по ценным бумагам, являющимся объектом операции РЕПО, у покупателя по первой части РЕПО с учетом особенностей, установленных абзацем первым настоящего пункта.\n\nНалогообложение доходов, определяемых в соответствии с настоящим пунктом, осуществляется по налоговым ставкам, установленным статьей 284 настоящего Кодекса. При этом указанные налоговые ставки применяются в зависимости от вида ценных бумаг (долговых обязательств), если иное не предусмотрено настоящей статьей. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\nВ случае, если операция РЕПО совершена между иностранной организацией (продавец по первой части РЕПО) и российской организацией (покупатель по первой части РЕПО) и в период между датами исполнения первой и второй частей РЕПО по акциям (депозитарным распискам, дающим право на получение дивидендов), являющимся объектом операции РЕПО, выплачены дивиденды (составляется список лиц, имеющих право на получение дивидендов), российская организация признается налоговым агентом в отношении доходов в виде дивидендов, по которым у источника выплаты дивидендов налоговым агентом не был удержан налог или налог был удержан в сумме меньшей, чем сумма налога, исчисленная с доходов в виде дивидендов для указанной иностранной организации. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nВ случае, если покупателем по первой части РЕПО является Центральный банк Российской Федерации или управляющая компания паевого инвестиционного фонда, действующая в интересах этого фонда, обязанность по уплате налога на дивиденды возлагается на продавца по первой части РЕПО, который признается получателем такого дохода в соответствии с настоящим пунктом, за исключением случаев, когда налог был удержан налоговым агентом. (В редакции Федерального закона от 02.11.2013 № 306-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nПоложения настоящего пункта не распространяются на продавца по первой части РЕПО в случае, если проданные ценные бумаги получены им по другой операции РЕПО или операции займа ценными бумагами.\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n3. В целях настоящего Кодекса для продавца по первой части РЕПО разница между ценой приобретения по второй части РЕПО и ценой реализации по первой части РЕПО признается:\n\n1) расходами по выплате процентов по привлеченным средствам, которые включаются в состав расходов в порядке, предусмотренном статьями 265, 269 и 272 настоящего Кодекса, - если такая разница положительная;\n\n2) доходами в виде процентов по займу, предоставленному ценными бумагами, которые включаются в состав доходов в соответствии со статьями 250 и 271 настоящего Кодекса (для банков - в соответствии со статьей 290 настоящего Кодекса), - если такая разница отрицательная.\n\n4. В целях настоящего Кодекса для покупателя по первой части РЕПО разница между ценой реализации по второй части РЕПО и ценой приобретения по первой части РЕПО признается:\n\n1) доходами в виде процентов по размещенным средствам, которые включаются в состав доходов в соответствии со статьями 250 и 271 настоящего Кодекса (для банков - в соответствии со статьей 290 настоящего Кодекса), - если такая разница положительная. Такие доходы, полученные иностранной организацией, которые не связаны с ее предпринимательской деятельностью на территории Российской Федерации, относятся к доходам иностранной организации от источников в Российской Федерации и подлежат обложению налогом, удерживаемым у источника выплаты доходов на основании подпункта 3 пункта 1 статьи 309 настоящего Кодекса на дату исполнения второй части РЕПО; (В редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n2) расходами в виде процентов по займу, полученному ценными бумагами, которые включаются в состав расходов в соответствии со статьями 265, 269 и 272 настоящего Кодекса, - если такая разница отрицательная.\n\n5. В целях настоящей статьи датой признания доходов (расходов) по операции РЕПО является дата исполнения (прекращения) обязательств участников по второй части РЕПО с учетом особенностей, установленных пунктами 3 и 4 настоящей статьи.\n\nРасходы, связанные с заключением и исполнением операций РЕПО, относятся к внереализационным расходам и учитываются в соответствии со статьями 265, 272 и 273 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\n6. В случае ненадлежащего исполнения второй части РЕПО при условии, что обязательства сторон прекращены в течение 30 дней с согласованной сторонами даты исполнения второй части РЕПО в порядке, предусмотренном соглашением сторон и соответствующем Федеральному закону \"О рынке ценных бумаг\", налоговая база по такой операции РЕПО определяется в следующем порядке:\n\nпродавец по первой части РЕПО признает для целей налогообложения исполнение второй части РЕПО и одновременно реализацию ценных бумаг, не выкупленных по второй части РЕПО, исходя из цены, определяемой для целей прекращения обязательств по операции РЕПО договором репо или иным соглашением сторон операции РЕПО с учетом требований к определению рыночной цены ценных бумаг для целей налогообложения, установленных статьей 280 настоящего Кодекса, на дату исполнения второй части РЕПО согласно условиям договора либо на дату купли-продажи ценной бумаги в рамках проведения взаимных расчетов. Признание доходов (расходов) от реализации ценных бумаг для целей налогообложения осуществляется с учетом положений статьи 280 настоящего Кодекса;\n\nпокупатель по первой части РЕПО признает для целей налогообложения исполнение второй части РЕПО и одновременно приобретение ценных бумаг, не проданных по второй части РЕПО, исходя из цены, определяемой для целей прекращения обязательств по операции РЕПО договором репо или иным соглашением сторон операции РЕПО с учетом требований к определению рыночной цены ценных бумаг для целей налогообложения, установленных статьей 280 настоящего Кодекса, на дату исполнения второй части РЕПО согласно условиям договора либо на дату купли-продажи ценной бумаги в рамках проведения взаимных расчетов.\n\nНе признаются доходами (расходами) продавца (покупателя) по первой части РЕПО суммы денежных средств, перечисляемые в качестве остаточных обязательств по результатам взаиморасчетов по обязательствам сторон в порядке, предусмотренном соглашением сторон и соответствующем Федеральному закону \"О рынке ценных бумаг\".\n\nОсобенности порядка определения налоговой базы при ненадлежащем исполнении (неисполнении) второй части РЕПО в случае, если предметом соответствующего договора репо являются клиринговые сертификаты участия, устанавливаются пунктом 61 настоящей статьи. (Дополнение абзацем - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\n61. При осуществлении урегулирования взаимных требований вследствие ненадлежащего исполнения (неисполнения) второй части РЕПО в случае, если предметом соответствующего договора репо являются клиринговые сертификаты участия, порядок определения налоговой базы, установленный пунктом 1 настоящей статьи, применяется с учетом следующих особенностей:\n\n1) рыночная стоимость клиринговых сертификатов участия, являющихся предметом договора репо, определяется исходя из номинальной стоимости таких сертификатов, установленной клиринговой организацией, выдавшей эти сертификаты, в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\";\n\n2) при определении дохода (убытка) от реализации клиринговых сертификатов участия, не выкупленных по второй части РЕПО, расходы продавца по первой части РЕПО признаются равными номинальной стоимости таких сертификатов, установленной клиринговой организацией, выдавшей эти сертификаты, в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\".\n\n(Дополнение пунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n7. В случае, если в период между датами исполнения первой и второй частей РЕПО у покупателя по первой части РЕПО возникает обязанность передать продавцу по первой части РЕПО выплаты (купонная выплата, частичное погашение номинальной стоимости ценных бумаг) по ценным бумагам, являющимся объектом операции РЕПО, и если договором репо предусмотрено уменьшение на суммы соответствующих выплат обязательств продавца по первой части РЕПО по уплате денежных средств при последующем приобретении ценных бумаг по второй части РЕПО (цены реализации (приобретения) по второй части РЕПО) вместо осуществления таких выплат, суммы, подлежащие выплате, включаются в цену реализации (приобретения) по второй части РЕПО при расчете доходов (расходов) в порядке, определенном пунктами 3 и 4 настоящей статьи.\n\nВ случае, если в соответствии с договором репо такие выплаты не учитываются при определении обязательств по второй части РЕПО, суммы таких выплат не включаются в цену реализации (приобретения) по второй части РЕПО при расчете доходов (расходов), определяемых в соответствии с пунктами 3 и 4 настоящей статьи.\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n8. В случае, если договором репо предусмотрено осуществление в период между датами исполнения первой и второй частей РЕПО расчетов (перечисление денежных средств и (или) передача ценных бумаг) между участниками операции РЕПО в случае изменения цены ценных бумаг, являющихся объектом операции РЕПО, или в иных случаях, предусмотренных указанным договором, и этим договором предусмотрено при осуществлении расчетов уменьшение обязательств продавца по первой части РЕПО по уплате денежных средств на суммы перечислений при последующем приобретении ценных бумаг по второй части РЕПО, суммы таких перечислений включаются в цену реализации (приобретения) по второй части РЕПО при расчете доходов (расходов), определяемых в соответствии с пунктами 3 и 4 настоящей статьи.\n\nВ случае, если такое получение (передача) денежных средств и (или) ценных бумаг не учитывается при определении обязательств по второй части РЕПО, суммы таких перечислений не включаются в цену реализации (приобретения) по второй части РЕПО при расчете доходов (расходов), определяемых в соответствии с пунктами 3 и 4 настоящей статьи.\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\nОткрытием короткой позиции не являются:\n\nреализация ценной бумаги по первой (второй) части РЕПО;\n\nпередача ценной бумаги заемщику (возврат заимодавцу) по договору займа ценными бумагами;\n\nпередача ценной бумаги по договору (соглашению) об обеспечительном платеже; (Дополнение абзацем - Федеральный закон от 16.04.2022 № 96-ФЗ)\n\nпередача ценной бумаги на возвратной основе в соответствии с условиями, определенными пунктом 8 настоящей статьи;\n\nконвертация ценных бумаг, являющихся объектом операции РЕПО, в том числе в связи с их дроблением или консолидацией или изменением их номинальной стоимости, либо аннулирование индивидуального номера (кода) дополнительного выпуска таких ценных бумаг, либо изменение индивидуального государственного регистрационного номера выпуска (индивидуального номера (кода) дополнительного выпуска), индивидуального идентифика\n\nционного номера (индивидуального номера (кода) дополнительного выпуска) таких ценных бумаг;\n\nпогашение депозитарной расписки при получении представляемых ценных бумаг;\n\nиное выбытие ценной бумаги, доход по которому не включается в налоговую базу.\n\nКороткая позиция открывается в количестве ценных бумаг, не превышающем количества ценных бумаг, полученных налогоплательщиком по первой части РЕПО, а также полученных в соответствии с пунктом 8 настоящей статьи, если такое получение не учитывается при определении обязательств по второй части РЕПО, и (или) договорам (соглашениям) об обеспечительном платеже, и (или) договорам займа в качестве заемщика. (В редакции  федеральных законов от 28.12.2013 № 420-ФЗ, от 16.04.2022 № 96-ФЗ)\n\nДатой открытия короткой позиции является дата перехода права собственности на ценные бумаги от продавца, осуществляющего открытие короткой позиции, к покупателю по сделке по реализации (выбытию) ценной бумаги.\n\nЗакрытие короткой позиции осуществляется путем приобретения (получения в собственность по иным основаниям, за исключением получения в собственность по операции РЕПО, договору займа, договору (соглашению) об обеспечительном платеже, получения на возвратной основе в соответствии с условиями, определенными пунктом 8 настоящей статьи) ценных бумаг того же выпуска (дополнительного выпуска), инвестиционных паев того же паевого инвестиционного фонда, по которым открыта короткая позиция. (В редакции  Федерального закона от 16.04.2022 № 96-ФЗ)\n\nВ случае, если в течение одного дня одновременно осуществлялись сделки по приобретению и реализации (выбытию) ценных бумаг, закрытие короткой позиции происходит по итогам этого дня только в случае превышения количества приобретенных ценных бумаг над количеством реализованных ценных бумаг. Налогоплательщик вправе в принятой им учетной политике в целях налогообложения предусмотреть закрытие короткой позиции в течение одного дня с учетом последовательности сделок по приобретению и реализации (выбытию) ценных бумаг.\n\nПод датой закрытия короткой позиции понимается дата перехода к налогоплательщику права собственности на ценные бумаги, получение которых приводит к закрытию короткой позиции, в порядке, предусмотренном настоящим пунктом.\n\nАбзац. (Утратил силу - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nПоследовательность закрытия коротких позиций по ценным бумагам одного выпуска (дополнительного выпуска), инвестиционных паев того же паевого инвестиционного фонда определяется налогоплательщиком самостоятельно в соответствии с принятой им учетной политикой в целях налогообложения одним из следующих методов:\n\nв первую очередь осуществляется закрытие короткой позиции, которая была открыта первой;\n\nзакрытие короткой позиции осуществляется налогоплательщиком по стоимости ценных бумаг по конкретной открытой короткой позиции.\n\nДоходы (расходы) налогоплательщика при реализации (приобретении) или выбытии ценной бумаги при открытии (закрытии) короткой позиции определяются в соответствии со статьями 280, 302, 303, 305, 326 и 329 настоящего Кодекса (в части доходов от поставки базисного актива и расходов в виде стоимости базисного актива) с учетом особенностей, установленных настоящей статьей в отношении процентного (купонного) дохода, и учитываются при определении налоговой базы на дату закрытия короткой позиции по этой ценной бумаге.\n\nВ случае открытия короткой позиции по ценным бумагам, по которым предусмотрено начисление процентного (купонного) дохода, налогоплательщик, открывший такую короткую позицию, производит начисление процентного расхода, определяемого как разница между суммой накопленного процентного (купонного) дохода на дату закрытия короткой позиции (включая суммы процентного (купонного) дохода, которые были выплачены эмитентом в период между датой открытия и датой закрытия короткой позиции) и суммой накопленного процентного (купонного) дохода на дату открытия короткой позиции. Начисление процентного (купонного) дохода осуществляется за время открытия короткой позиции с признанием сумм накопленного расхода на дату закрытия этой короткой позиции или на последнее число отчетного (налогового) периода, если в отчетном (налоговом) периоде не произошло закрытия короткой позиции. В случае, если налогообложение процентного (купонного) дохода осуществляется по налоговым ставкам, предусмотренным пунктом 4 статьи 284 настоящего Кодекса, указанные выше суммы начисленного процентного (купонного) дохода относятся на уменьшение суммы процентного (купонного) дохода, облагаемой по соответствующей налоговой ставке.\n\nВ случае, если в период между датой открытия и датой закрытия короткой позиции у налогоплательщика возникло обязательство по компенсации сумм частичного погашения номинальной стоимости ценной бумаги или сумм дивидендов в соответствии со статьей 513 Федерального закона \"О рынке ценных бумаг\" или в соответствии с условиями договора займа ценных бумаг, при закрытии короткой позиции в состав расходов по приобретению ценной бумаги включаются суммы, выплаченные (подлежащие выплате или относящиеся на уменьшение суммы денежных средств, подлежащих уплате продавцом по первой части РЕПО при последующем приобретении ценных бумаг по второй части РЕПО) продавцу по первой части РЕПО (заимодавцу по договору займа ценными бумагами) в пределах суммы частичного погашения номинальной стоимости ценных бумаг по условиям выпуска или сумм дивидендов. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nАналитический учет коротких позиций в целях налогообложения ведется налогоплательщиком по каждой открытой короткой позиции.\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n(Статья в редакции Федерального закона от 06.06.2005 № 58-ФЗ)","article_title":"Статья 282. Особенности определения налоговой базы по операциям РЕПО с ценными бумагами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"de72222b5af3cfaba136ea487c986b1ea1bfd0c4dc3c1d72677524f311ce4367"},{"code_id":"NK_RF_2","article_number":"282.1","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 16.04.2022 № 96-ФЗ)\n\n1. Передача ценных бумаг в заем осуществляется на основании договора займа, заключенного в соответствии с законодательством Российской Федерации или законодательством иностранных государств, удовлетворяющего условиям, определенным настоящим пунктом (далее также - договор займа).\n\nПравила настоящей статьи применяются к операциям займа ценными бумагами налогоплательщика, совершенным за его счет комиссионерами, поверенными, агентами, доверительными управляющими на основании соответствующих гражданско-правовых договоров.\n\nВ целях настоящей главы договор займа, выданного (полученного) ценными бумагами, должен предусматривать выплату процентов в денежной форме.\n\nСтавка процента или порядок ее определения устанавливаются условиями договора займа. Для целей определения процентов по договору займа, если иное не предусмотрено настоящим пунктом, стоимость ценных бумаг, переданных по договору займа, принимается равной рыночной цене соответствующих ценных бумаг на дату заключения договора, а при отсутствии рыночной цены - расчетной цене. При этом рыночная цена и расчетная цена ценных бумаг определяются в соответствии со статьей 280 настоящего Кодекса. (В редакции федеральных законов от 28.12.2013 № 420-ФЗ; от 28.11.2015 № 326-ФЗ)\n\nПри передаче (получении) облигаций федерального займа, внесенных Российской Федерацией в качестве имущественного взноса в имущество организации, осуществляющей в соответствии с федеральным законом функции по обязательному страхованию вкладов физических лиц в банках Российской Федерации, в субординированные займы банкам при осуществлении мер по поддержанию стабильности банковской системы и защиты законных интересов вкладчиков и кредиторов банков на основании статей 3 и 31 Федерального закона от 29 декабря 2014 года № 451-ФЗ \"О внесении изменений в статью 11 Федерального закона \"О страховании вкладов физических лиц в банках Российской Федерации\" и статью 46 Федерального закона \"О Центральном банке Российской Федерации (Банке России)\" для целей определения процентов по договору займа стоимость ценных бумаг, переданных по договору займа, принимается равной их номинальной стоимости. (Дополнение абзацем - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\nВ случаях, предусмотренных договором займа, стоимость ценных бумаг, переданных комиссионером, поверенным, агентом клиенту по договору займа, также может определяться по правилам оценки обеспечения клиента по предоставленным займам, установленным Центральным банком Российской Федерации. При этом стоимость ценных бумаг определяется исходя из последней цены ценной бумаги, рассчитанной по указанным правилам в торговый день, определенный в соответствии с документами биржи. (В редакции федеральных законов от 23.07.2013 № 251-ФЗ; от 28.12.2013 № 420-ФЗ)\n\nДатой начала займа является дата перехода права собственности на ценные бумаги при их передаче кредитором заемщику, датой окончания займа является дата перехода права собственности на ценные бумаги при их передаче заемщиком кредитору.\n\nВ целях настоящей главы срок договора займа, выданного (полученного) ценными бумагами, не должен превышать один год (за исключением случаев передачи (получения) облигаций федерального займа, внесенных Российской Федерацией в качестве имущественного взноса в имущество организации, осуществляющей в соответствии с федеральным законом функции по обязательному страхованию вкладов физических лиц в банках Российской Федерации, в субординированные займы банкам при осуществлении мер по поддержанию стабильности банковской системы и защиты законных интересов вкладчиков и кредиторов банков на основании статей 3 и 31 Федерального закона от 29 декабря 2014 года № 451-ФЗ \"О внесении изменений в статью 11 Федерального закона \"О страховании вкладов физических лиц в банках Российской Федерации\" и статью 46 Федерального закона \"О Центральном банке Российской Федерации (Банке России)\"). (В редакции федеральных законов от 28.11.2015 № 326-ФЗ; от 29.12.2015 № 396-ФЗ)\n\n2. В случае, если договором займа не установлен срок возврата ценных бумаг или указанный срок определен моментом востребования (договор займа с открытой датой) и в течение года с даты начала займа ценные бумаги не были возвращены заемщиком кредитору, по истечении одного года с даты начала займа для целей налогообложения признаются:\n\nу кредитора - доходы от реализации ценных бумаг, переданных по договору займа, которые рассчитываются исходя из рыночной цены (расчетной цены) ценных бумаг, определяемой в соответствии со статьей 280 настоящего Кодекса, на дату начала займа. Расходы кредитора в этом случае определяются в порядке, установленном статьей 280 настоящего Кодекса; (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nу заемщика - внереализационные доходы в сумме, исчисленной исходя из рыночной цены (расчетной цены) ценных бумаг, определяемой в соответствии со статьей 280 настоящего Кодекса, на дату начала займа. При последующей реализации ценных бумаг, полученных по договору займа, расходы на их приобретение признаются равными сумме дохода, включенного в налоговую базу в соответствии со статьей 250 настоящего Кодекса.\n\nПоложения настоящего пункта применяются также в следующих случаях:\n\nесли договором займа был определен срок возврата займа, но по истечении одного года с даты начала займа ценные бумаги не были возвращены заемщиком кредитору (за исключением случаев передачи (получения) облигаций федерального займа, внесенных Российской Федерацией в качестве имущественного взноса в имущество организации, осуществляющей в соответствии с федеральным законом функции по обязательному страхованию вкладов физических лиц в банках Российской Федерации, в субординированные займы банкам при осуществлении мер по поддержанию стабильности банковской системы и защиты законных интересов вкладчиков и кредиторов банков на основании статей 3 и 31 Федерального закона от 29 декабря 2014 года № 451-ФЗ \"О внесении изменений в статью 11 Федерального закона \"О страховании вкладов физических лиц в банках Российской Федерации\" и статью 46 Федерального закона \"О Центральном банке Российской Федерации (Банке России)\"); (В редакции федеральных законов от 28.11.2015 № 326-ФЗ; от 29.12.2015 № 396-ФЗ)\n\nесли обязательство по возврату ценных бумаг было прекращено выплатой кредитору денежных средств или передачей иного отличного от ценных бумаг имущества.\n\n3. В случае неисполнения или исполнения не в полном объеме обязательств по возврату ценных бумаг по операциям займа ценными бумагами применяется порядок налогообложения, установленный пунктом 1 статьи 282 настоящего Кодекса для операции РЕПО, в отношении которой было допущено ненадлежащее исполнение и не была проведена процедура урегулирования взаимных требований.\n\nПоложения настоящего пункта не применяются к случаям прекращения обязательств банка по договорам субординированного займа (облигационного займа) по основаниям, предусмотренным статьей 251 Федерального закона \"О банках и банковской деятельности\", при осуществлении в отношении такого банка мер по предупреждению банкротства с участием Центрального банка Российской Федерации или государственной корпорации \"Агентство по страхованию вкладов\". (Дополнение абзацем - Федеральный закон от 23.04.2018 № 105-ФЗ)\n\n4. При передаче ценных бумаг в заем и при возврате ценных бумаг из займа финансовый результат для целей налогообложения в соответствии со статьей 280 настоящего Кодекса кредитором не определяется, за исключением случаев, установленных настоящей статьей. При этом расходы на приобретение ценных бумаг, переданных по договору займа, учитываются кредитором при дальнейшей (после возврата займа) реализации (выбытии) указанных ценных бумаг с учетом положений статьи 280 настоящего Кодекса.\n\n5. По договору займа выплаты по ценным бумагам, право на получение которых возникло в период действия договора займа, не признаются доходами заемщика и включаются в доходы кредитора.\n\nПроцентный (купонный) доход учитывается при расчете налоговой базы кредитора в порядке, установленном статьями 250, 271, 273 и 328 настоящего Кодекса, и не учитывается при определении налоговой базы заемщика по процентному (купонному) доходу по ценным бумагам, являющимся объектом займа.\n\nНалогообложение доходов, определенных настоящим пунктом, осуществляется по налоговым ставкам, установленным статьей 284 настоящего Кодекса. При этом указанные налоговые ставки применяются в зависимости от вида ценных бумаг (долгового обязательства).\n\nПоложения настоящего пункта не распространяются на кредитора в случае, если ценные бумаги получены по другому договору займа и (или) первой части операции РЕПО.\n\n6. В случае, если договор займа заключен между иностранной организацией (кредитор) и российской организацией (заемщик) и в период действия договора займа по ценным бумагам выплачен процентный (дисконтный) доход либо по акциям (депозитарным распискам, дающим право на получение дивидендов), являющимся предметом займа, выплачены дивиденды, российская организация признается налоговым агентом в отношении доходов в виде дивидендов или процентного (дисконтного) дохода, по которым у источника их выплаты налоговым агентом не был удержан налог или налог был удержан в сумме меньшей, чем сумма налога, исчисленная для указанной иностранной организации.\n\n7. Проценты, подлежащие получению кредитором по договору займа, признаются внереализационным доходом кредитора, учитываемым в соответствии со статьями 250, 271 и 290 настоящего Кодекса.\n\nПроценты, подлежащие уплате заемщиком по договору займа, признаются внереализационным расходом, учитываемым при определении налоговой базы с учетом статей 265, 269 и 272 настоящего Кодекса.\n\nПри получении банками по договору субординированного займа при осуществлении мер по поддержанию стабильности банковской системы и защиты законных интересов вкладчиков и кредиторов банков на основании статей 3 и 31 Федерального закона от 29 декабря 2014 года № 451-ФЗ \"О внесении изменений в статью 11 Федерального закона \"О страховании вкладов физических лиц в банках Российской Федерации\" и статью 46 Федерального закона \"О Центральном банке Российской Федерации (Банке России)\" облигаций федерального займа, внесенных Российской Федерацией в качестве имущественного взноса в имущество организации, осуществляющей в соответствии с федеральным законом функции по обязательному страхованию вкладов физических лиц в банках Российской Федерации, сумма процентов, подлежащих уплате заемщиком по договору займа, включается в состав внереализационных расходов в соответствии с настоящим пунктом в размере, уменьшенном на сумму купонного дохода по указанным облигациям, не признаваемого доходом заемщика на основании пункта 5 настоящей статьи. (Дополнение абзацем - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n8. При реализации (выбытии) ценных бумаг, полученных по договору займа, применяются положения пункта 9 статьи 282 настоящего Кодекса.\n\n9. В случае, если между датами начала и окончания займа осуществлены конвертация ценных бумаг, являющихся объектом займа, в том числе в связи с их дроблением, или консолидацией, или изменением их номинальной стоимости, либо аннулирование индивидуального номера (кода) дополнительного выпуска таких ценных бумаг, либо изменение индивидуального государственного регистрационного номера выпуска (индивидуального номера (кода) дополнительного выпуска), индивидуального идентификационного номера (индивидуального номера (кода) дополнительного выпуска) таких ценных бумаг, такие действия не изменяют порядок налогообложения, установленный настоящей статьей.\n\n10. Налогоплательщики ведут обособленный налоговый учет по ценным бумагам, переданным (полученным) в рамках займов ценными бумагами. Аналитический учет по займам ценными бумагами ведется по каждому предоставленному (полученному) займу.\n\n11. Обязательства (требования) по возврату займа ценными бумагами, предметом которого выступают ценные бумаги, номинированные в иностранной валюте, возникающие у заемщика (заимодавца), не подлежат переоценке в связи с изменением официальных курсов иностранных валют к рублю Российской Федерации, установленных Центральным банком Российской Федерации.\n\n12. К операциям с ценными бумагами в рамках обеспечительного платежа применяются правила, предусмотренные пунктами 4, 5, 9, 10 и 11 настоящей статьи для договора займа.\n\nВ случае, если договор (соглашение) об обеспечительном платеже заключен не на условиях, определенных генеральным соглашением (единым договором), к указанным в абзаце первом настоящего пункта операциям также применяются правила, предусмотренные пунктом 2 настоящей статьи для договора займа.\n\n(Дополнение пунктом - Федеральный закон от 16.04.2022 № 96-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 25.11.2009 № 281-ФЗ)","article_title":"Статья 282.1. Особенности налогообложения при осуществлении операций займа ценными бумагами и операций с ценными бумагами в рамках обеспечительного платежа","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"786c9cae1a277e0b341060bcdcf4649fb6f8a8f62dd0d19aba7ed00d8dc2302e"},{"code_id":"NK_RF_2","article_number":"282.2","version_date":"2000-07-31","article_text":"1. Налоговая база по операциям с цифровыми финансовыми активами и (или) цифровыми правами, включающими одновременно цифровые финансовые активы и утилитарные цифровые права, определяется совокупно с операциями с необращающимися ценными бумагами и необращающимися производными финансовыми инструментами в порядке, уста\n\nновленном настоящей статьей и статьей 304 настоящего Кодекса, и отдельно от общей налоговой базы, если иное не предусмотрено настоящей статьей.\n\n2. Доходы (расходы) налогоплательщика, полученные по операциям с цифровыми правами, включающими одновременно цифровые финансовые активы и утилитарные цифровые права, выкуп по которым в соответствии с решением о выпуске таких цифровых прав осуществлен путем передачи товаров, исключительных прав на результаты интеллектуальной деятельности и (или) прав использования результатов интеллектуальной деятельности, выполнения работ, оказания услуг, учитываются в общей налоговой базе. Положения настоящего пункта применяются к лицу, выпустившему цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права.\n\n3. В случае, если налогоплательщик приобретает обращающиеся ценные бумаги в целях уменьшения (компенсации) неблагоприятных для налогоплательщика последствий (полностью или частично), обусловленных увеличением обязательств по выпущенным налогоплательщиком цифровым финансовым активам и (или) цифровым правам, включающим одновременно цифровые финансовые активы и утилитарные цифровые права, доходы (расходы), связанные с операциями с такими обращающимися ценными бумагами, учитываются при определении налоговой базы в соответствии с пунктом 1 настоящей статьи.\n\nДля подтверждения обоснованности отнесения операций, указанных в абзаце первом настоящего пункта, к операциям, совершаемым в целях уменьшения (компенсации) неблагоприятных для налогоплательщика последствий (полностью или частично), обусловленных увеличением обязательств по выпущенным налогоплательщиком цифровым финансовым активам и (или) цифровым правам, включающим одновременно цифровые финансовые активы и утилитарные цифровые права, налогоплательщик составляет на дату заключения этих сделок (первой из сделок при заключении нескольких сделок) справку, подтверждающую, что исходя из прогнозов налогоплательщика совершение данной операции (совокупности операций) позволяет уменьшить неблагоприятные последствия (полностью или частично), обусловленные увеличением обязательств по выпущенным налогоплательщиком цифровым финансовым активам и (или) цифровым правам, включающим одновременно цифровые финансовые активы и утилитарные цифровые права.\n\nК справке, указанной в абзаце втором настоящего пункта, применяются положения статьи 326 настоящего Кодекса в части требований к справке, составляемой налогоплательщиком в связи с осуществлением операций хеджирования.\n\n4. В случае, если налогоплательщик выпускает цифровые финансовые активы и (или) цифровые права, включающие одновременно цифровые финансовые активы и утилитарные цифровые права, либо приобретает указанные цифровые финансовые активы и (или) цифровые права в целях уменьшения (компенсации) неблагоприятных для налогоплательщика последствий (полностью или частично), обусловленных возникновением убытка, недополучением прибыли, уменьшением выручки, уменьшением рыночной стоимости имущества, включая имущественные права (права требования), увеличением обязательств налогоплательщика вследствие изменения цены, процентной ставки, валютного курса, в том числе курса иностранной валюты к валюте Российской Федерации, или иного показателя (совокупности показателей) объекта (объектов) хеджирования, как он определен (они определены) абзацем вторым пункта 5 статьи 301 настоящего Кодекса, такие операции с указанными цифровыми финансовыми активами и (или) цифровыми правами признаются операциями хеджирования при условии подтверждения обоснованности отнесения таких операций к операциям хеджирования в порядке, предусмотренном статьями 301 и 326 настоящего Кодекса. В этом случае доходы (расходы) по операциям с указанными цифровыми финансовыми активами и (или) цифровыми правами учитываются при определении налоговой базы, при расчете которой в соответствии с положениями статьи 274 настоящего Кодекса учитываются доходы и расходы, связанные с объектом (объектами) хеджирования.\n\n5. Если решением о выпуске цифрового финансового актива предусмотрена выплата дохода в сумме, равной сумме дивидендов, полученных лицом, выпустившим этот цифровой финансовый актив, сумма налога, исчисленная в отношении указанного дохода налогоплательщиком, являющимся российской организацией, уменьшается на величину, которая определяется как произведение суммы, равной указанному доходу, и ставки налога, примененной к доходам в виде дивидендов при их получении лицом, выпустившим указанный цифровой финансовый актив.\n\n6. В целях налогообложения текущая переоценка цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, не производится.\n\n7. При определении налоговой базы по операциям с цифровыми финансовыми активами и (или) цифровыми правами, включающими одновременно цифровые финансовые активы и утилитарные цифровые права, учитываются доходы (расходы) по всем операциям с этими цифровыми финансовыми активами и (или) цифровыми правами за отчетный (налоговый) период.\n\nПри реализации (выкупе) цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, налогоплательщиками - обладателями этих цифровых финансовых активов и утилитарных цифровых прав налоговая база определяется в соответствии с подпунктом 21 пункта 1 статьи 268 настоящего Кодекса и учитывается в налоговой базе, формируемой в соответствии с пунктом 1 настоящей статьи, за исключением случая, предусмотренного абзацем третьим настоящего пункта.\n\nДля целей настоящей главы у налогоплательщика - последнего обладателя цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, не возникает прибыли (убытка) при выкупе этих цифровых финансовых активов и (или) цифровых прав путем передачи товаров (в том числе эмиссионных ценных бумаг), исключительных прав на результаты интеллектуальной деятельности и (или) прав использования результатов интеллектуальной деятельности, выполнения работ, оказания услуг. При этом стоимость полученных налогоплательщиком товаров (работ, услуг, исключительных прав на результаты интеллектуальной деятельности и (или) прав использования результатов интеллектуальной деятельности) определяется исходя из цены приобретения этих цифровых финансовых активов и (или) цифровых прав, при выкупе которых получены указанные товары (работы, услуги, исключительные права на результаты интеллектуальной деятельности и (или) права использования результатов интеллектуальной деятельности), а также исходя из сумм налога на добавленную стоимость, уплаченных при приобретении этих цифровых прав. При этом доходы, предусмотренные пунктом 27 части второй статьи 250 настоящего Кодекса, учитываются данным налогоплательщиком в общей налоговой базе.\n\n(Дополнение статьей - Федеральный закон от 14.07.2022 № 324-ФЗ)","article_title":"Статья 282.2. Особенности определения налоговой базы по операциям с цифровыми финансовыми активами и (или) цифровыми правами, включающими одновременно цифровые финансовые активы и утилитарные цифровые права","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27afa0a218b39efbc8db8003fa6d4939dc3ff097f5dfde1d65c2378636af3c8d"},{"code_id":"NK_RF_2","article_number":"282.3","version_date":"2000-07-31","article_text":"1. Налоговая база по операциям с цифровой валютой определяется в соответствии с положениями настоящей статьи и отдельно от общей налоговой базы (если иное не предусмотрено настоящей статьей).\n\n2. Доходы в виде цифровой валюты, полученной в результате осуществления майнинга цифровой валюты, определяются исходя из рыночной котировки такой цифровой валюты на дату признания дохода.\n\nРыночной котировкой цифровой валюты в целях настоящего Кодекса признается цена закрытия, рассчитываемая иностранным организатором торговли (включая биржу) по сделкам, совершенным через него в течение торгового дня. Иностранным организатором торговли (включая биржу) может быть лицо, объем торгов по сделкам с цифровой валютой которого превышает 100 миллиардов рублей за соответствующий торговый день, при условии, что информация о рыночных котировках цифровой валюты размещается на его официальном сайте в информационно-телекоммуникационной сети \"Интернет\" в течение трех лет, предшествующих дате совершения операций с цифровой валютой.\n\nЕсли по одной и той же цифровой валюте сделки совершались через двух и более иностранных организаторов торговли (включая биржу), налогоплательщик вправе самостоятельно выбрать рыночную котировку, сложившуюся у одного из указанных иностранных организаторов торговли (включая биржу).\n\nЕсли по одной и той же цифровой валюте сделки совершались по ценам в разных валютах и (или) в иностранных цифровых правах, курс которых привязан к курсу иностранной валюты (далее - торговые пары), налогоплательщик вправе самостоятельно выбрать торговую пару, цена закрытия которой будет признаваться рыночной котировкой цифровой валюты.\n\nЦена закрытия цифровой валюты, выраженная в иностранной валюте, пересчитывается в рубли по официальному курсу Центрального банка Российской Федерации, действовавшему на дату признания дохода.\n\nЦена закрытия цифровой валюты, выраженная в иностранных цифровых правах, курс которых привязан к курсу иностранной валюты, пересчитывается в рубли по официальному курсу Центрального банка Российской Федерации, действовавшему на дату признания дохода.\n\n3. Доход (выручка) от реализации цифровой валюты определяется исходя из фактической цены реализации такой цифровой валюты, но не ниже рыночной котировки такой цифровой валюты, уменьшенной на 20 процентов.\n\nПри приобретении цифровой валюты ее стоимость определяется исходя из цены приобретения, но не выше рыночной котировки цифровой валюты, увеличенной на 20 процентов.\n\nСтоимость цифровой валюты, полученной в результате осуществления майнинга цифровой валюты, равна сумме дохода, определенного в соответствии с пунктом 2 настоящей статьи.\n\n4. При реализации (безвозмездной передаче) цифровой валюты налогоплательщик определяет налоговую базу как доход (выручку) от реализации цифровой валюты, уменьшенный на ее стоимость и затраты на реализацию такой цифровой валюты.\n\nПри безвозмездной передаче доход от реализации цифровой валюты определяется исходя из рыночной котировки такой цифровой валюты на дату передачи с учетом положений пункта 2 настоящей статьи.\n\nПри реализации или ином выбытии цифровой валюты налогоплательщик самостоятельно в соответствии с принятой в целях налогообложения учетной политикой выбирает один из следующих методов списания на расходы стоимости выбывшей цифровой валюты:\n\nпо стоимости первой по времени приобретения (ФИФО);\n\nпо стоимости единицы.\n\n5. Расходы налогоплательщика, связанные с осуществлением майнинга цифровой валюты, независимо от их состава признаются косвенными расходами.\n\n6. В целях налогообложения текущая переоценка цифровой валюты не производится.\n\n7. Убытки от операций с цифровыми валютами прошлых налоговых периодов могут быть отнесены на уменьшение налоговой базы по операциям с цифровой валютой, исчисленной отдельно от общей налоговой базы текущего налогового (отчетного) периода с учетом ограничения, установленного пунктом 21 статьи 283 настоящего Кодекса.\n\n8. Доходы и расходы по операциям с цифровыми валютами (за исключением доходов и расходов, связанных с осуществлением майнинга цифровой валюты) в рамках экспериментального правового режима в сфере цифровых инноваций, предусматривающего использование цифровой валюты в качестве средства платежа по внешнеторговым договорам (контрактам) и установленного в соответствии со статьей 11 Федерального закона от 31 июля 2020 года № 259-ФЗ \"О цифровых финансовых активах, цифровой валюте и о внесении изменений в отдельные законодательные акты Российской Федерации\", учитываются в общей налоговой базе.\n\n(Дополнение статьей - Федеральный закон от 29.11.2024 № 418-ФЗ)","article_title":"Статья 282.3. Особенности определения налоговой базы по операциям с цифровой валютой","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8371c1bae93d9f804d955c72d186c6a5264988d1fce04932f912a7b7ef3d09d1"},{"code_id":"NK_RF_2","article_number":"283","version_date":"2000-07-31","article_text":"Положения настоящего пункта не распространяются на убытки, полученные налогоплательщиком в рамках деятельности, прибыль от которой в соответствии с положениями настоящего Кодекса подлежит налогообложению по ставке 0 процентов. Положения настоящего пункта также не распространяются на убытки, полученные налогоплательщиком от реализации или иного выбытия указанных в статьях 2842 и 2842-1 настоящего Кодекса акций (долей участия в уставном капитале), облигаций российских организаций, инвестиционных паев. (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nПоложение настоящего пункта также не распространяется на убытки от участия в инвестиционном товариществе, полученные в налоговом периоде, в котором налогоплательщик присоединился к ранее заключенному другими участниками договору инвестиционного товарищества, в том числе в результате уступки прав и обязанностей по договору иным лицом.\n\n(Пункт в редакции Федерального закона от 28.11.2011 № 336-ФЗ)\n\nВ аналогичном порядке убыток, не перенесенный на ближайший следующий год, может быть перенесен целиком или частично на следующие годы.\n\n(Пункт в редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nОрганизация, являвшаяся участником консолидированной группы налогоплательщиков, после выхода из состава этой группы (прекращения действия этой группы):\n\n1) не вправе уменьшить налоговую базу текущего налогового периода на сумму убытка, полученного указанной группой в период ее действия (на часть этой суммы), если иное не предусмотрено подпунктом 3 настоящего пункта; (В редакции Федерального закона от 09.11.2020 № 368-ФЗ);\n\n2) вправе уменьшить налоговую базу текущего налогового периода на сумму убытка, полученного указанной организацией по итогам налоговых периодов (на часть этой суммы), в которых она не являлась участником консолидированной группы налогоплательщиков, в порядке и на условиях, которые предусмотрены настоящей статьей; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n3) вправе уменьшить налоговую базу текущего налогового (отчетного) периода на сумму (часть суммы) убытка, полученного указанной организацией в период, в котором указанная организация являлась участником консолидированной группы налогоплательщиков, определенного в порядке, установленном пунктом 1 статьи 2781 настоящего Кодекса, и не учтенного при определении консолидированной налоговой базы на основании абзаца третьего пункта 1 статьи 2781 настоящего Кодекса. Уменьшение налоговой базы текущего периода осуществляется в порядке и на условиях, которые предусмотрены настоящей статьей. При этом налоговая база не может быть уменьшена на сумму убытка, указанного в настоящем пункте, более чем на 50 процентов. (Дополнение абзацем - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nВ случае, если организация, являвшаяся участником консолидированной группы налогоплательщиков, в период своего участия в указанной группе была реорганизована в форме слияния или присоединения, после выхода из состава указанной группы (прекращения действия этой группы) эта организация вправе также уменьшить налоговую базу текущего налогового периода на сумму убытка, полученного организациями (на часть этой суммы), правопреемником которых является организация, вышедшая из состава группы, по итогам налоговых периодов, в которых такие реорганизованные организации не являлись участниками консолидированной группы налогоплательщиков, в порядке и на условиях, которые предусмотрены настоящей статьей.\n\nВ случае, если организация, являвшаяся участником консолидированной группы налогоплательщиков, в период своего участия в указанной группе была вновь создана путем разделения организации, после выхода из состава указанной группы (прекращения действия этой группы) эта организация также вправе уменьшить налоговую базу текущего налогового периода на сумму убытка, полученного организацией (на часть этой суммы), правопреемником которой является организация, вышедшая из состава этой группы, по итогам налоговых периодов, в которых такая реорганизованная организация не являлась участником консолидированной группы налогоплательщиков, в порядке и на условиях, которые предусмотрены настоящей статьей, с учетом статьи 50 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 283. Перенос убытков на будущее","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2da757d7ef773502981001b2d93e295c83df607a84f11c139fad00832adaec2"},{"code_id":"NK_RF_2","article_number":"284","version_date":"2000-07-31","article_text":"сумма налога, исчисленная по налоговой ставке в размере 7 процентов (8 процентов в 2025 - 2030 годах), зачисляется в федеральный бюджет, если иное не установлено настоящей главой; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nсумма налога, исчисленная по налоговой ставке в размере 18 процентов (17 п\n\nроцентов в 2017 - 2030 годах), зачисляется в бюджеты субъектов Российской Федерации, в бюджет федеральной территории \"Сириус\". (В редакции  федеральных законов от 30.12.2008 № 305-ФЗ, от 30.11.2016 № 401-ФЗ, от 03.08.2018 № 301-ФЗ, от 11.06.2021 № 199-ФЗ, от 21.11.2022 № 443-ФЗ)\n\nНалоговая ставка налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, законами субъектов Российской Федерации может быть понижена для отдельных категорий налогоплательщиков в случаях, предусмотренных настоящей главой. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nПониженные налоговые ставки по налогу на прибыль организаций, подлежащему зачислению в бюджеты субъектов Российской Федерации, установленные законами субъектов Российской Федерации, принятыми до дня вступления в силу Федерального закона от 3 августа 2018 года № 302-ФЗ \"О внесении изменений в части первую и вторую Налогового кодекса Российской Федерации\", подлежат применению налогоплательщиками до даты окончания срока их действия, но не позднее 1 января 2025 года. При этом указанные пониженные налоговые ставки могут быть повышены законами субъектов Российской Федерации на налоговые периоды 2019 - 2022 годов. Положения настоящего абзаца не применяются в отношении пониженных налоговых ставок по налогу на прибыль организаций, подлежащему зачислению в бюджеты субъектов Российской Федерации, установленных законами субъектов Российской Федерации для отдельных категорий налогоплательщиков в случаях, предусмотренных настоящей главой. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 302-ФЗ) (В редакции федеральных законов от 27.11.2018 № 424-ФЗ, от 29.09.2019 № 325-ФЗ, от 28.06.2022 № 211-ФЗ, от 21.11.2022 № 443-ФЗ)\n\nДля организаций - резидентов особой экономической зоны законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка налога на прибыль, подлежащего зачислению в бюджеты субъектов Российской Федерации, от деятельности, осуществляемой на территории особой экономической зоны, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) от деятельности, осуществляемой на территории особой экономической зоны, и доходов (расходов), полученных (понесенных) при осуществлении деятельности за пределами территории особой экономической зоны. (Дополнение абзацем - Федеральный закон от 03.06.2006 № 75-ФЗ) (В редакции федеральных законов от 30.11.2011 № 365-ФЗ; от 23.11.2015 № 321-ФЗ)\n\nДля организаций - участников Особой экономической зоны в Магаданской области законом Магаданской области может устанавливаться пониженная налоговая ставка налога на прибыль, подлежащего зачислению в бюджет Магаданской области от видов деятельности, осуществляемых на территории Магаданской области и определенных соглашением об осуществлении деятельности на территории Особой экономической зоны в Магаданской области, заключаемым в соответствии с Федеральным законом от 31 мая 1999 года № 104-ФЗ \"Об Особой экономической зоне в Магаданской области\" (далее в настоящей статье - соглашение об осуществлении деятельности), при условии ведения раздельного учета доходов (расходов), полученных (понесенных) от видов деятельности, осуществляемых на территории Магаданской области и определенных таким соглашением, и доходов (расходов), полученных (понесенных) при осуществлении иных видов деятельности. (Дополнение абзацем - Федеральный закон от 23.11.2015 № 321-ФЗ)\n\nРазмер налоговой ставки налога, указанной в абзацах шестом и седьмом настоящего пункта, не может быть выше 13,5 процента. (Дополнение абзацем - Федеральный закон от 23.11.2015 № 321-ФЗ) (В редакции федеральных законов от 30.11.2016 № 401-ФЗ; от 27.11.2017 № 348-ФЗ; от 27.11.2018 № 424-ФЗ)\n\nДля организаций - участников региональных инвестиционных проектов законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, в соответствии с положениями пункта 3 статьи 2843 либо пункта 3 статьи 2843-1 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 30.09.2013 № 267-ФЗ) (В редакции Федерального закона от 23.05.2016 № 144-ФЗ)\n\nДля налогоплательщиков - участников специальных инвестиционных контрактов законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, в соответствии с положениями пункта 3 статьи 2849 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 02.08.2019 № 269-ФЗ)\n\nДля налогоплательщиков - участников специальных инвестиционных контрактов, указанных в пункте 2 статьи 2516 настоящего Кодекса, законами субъектов Российской Федерации с 1 января 2026 года может устанавливаться пониженная налоговая ставка налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, в отношении прибыли, полученной от реализации специального инвестиционного контракта, в случае, если указанный специальный инвестиционный контракт в качестве меры стимулирования предусматривает льготу по налогу на прибыль организаций. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 328-ФЗ)\n\nПоложения настоящего пункта не применяются: (Дополнение абзацем - Федеральный закон от 30.09.2013 № 268-ФЗ) (В редакции Федерального закона от 24.11.2014 № 376-ФЗ)\n\nналогоплательщиками, указанными в пункте 1 статьи 2752 настоящего Кодекса, при исчислении налоговой базы при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nпри исчислении налоговой базы налогоплательщиками - контролирующими лицами по прибыли контролируемых ими иностранных компаний. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nДля целей настоящей главы термины \"бюджет субъекта Российской Федерации\" и \"территория субъекта Российской Федерации\" применяются также соответственно к бюджету федеральной территории \"Сириус\" и к территории, расположенной в границах федеральной территории \"Сириус\". (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.07.2004 № 95-ФЗ)\n\n12. Для организаций - резидентов особых экономических зон налоговая ставка по налогу, подлежащему зачислению в федеральный бюджет, устанавливается в размере 2 процентов.\n\nУказанная налоговая ставка применяется к прибыли от деятельности, осуществляемой на территории особой экономической зоны, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) от деятельности, осуществляемой на территории особой экономической зоны, и доходов (расходов), полученных (понесенных) при осуществлении деятельности за пределами территории особой экономической зоны.\n\n(Дополнение пунктом - Федеральный закон от 30.11.2011 № 365-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n12-1. (Дополнение пунктом - Федеральный закон от 27.11.2017 № 348-ФЗ) (Утратил силу  - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nК налоговой базе, определяемой налогоплательщиками, указанными в пункте 1 статьи 2752 настоящего Кодекса, при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, указанном в абзаце втором подпункта 5 пункта 1 статьи 111 настоящего Кодекса, применяется налоговая ставка 50 процентов. (Дополнение абзацем - Федеральный закон от 28.05.2022 № 142-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nК налоговой базе, определяемой налогоплательщиками, указанными в пункте 1 статьи 2752 настоящего Кодекса, при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, указанном в абзаце втором подпункта 2 пункта 6 статьи 338 настоящего Кодекса, в течение пяти последовательных налоговых периодов начиная с налогового периода (но не ранее 2025 года), в котором истекли семь лет с даты начала промышленной добычи углеводородного сырья на новом морском месторождении углеводородного сырья, устанавливается налоговая ставка в размере 40 процентов. (Дополнение абзацем - Федеральный закон от 29.10.2024 № 362-ФЗ) (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n15-1. Для указанных в подпункте 2 пункта 1 статьи 259 настоящего Кодекса организаций - участников региональных инвестиционных проектов налоговая ставка по налогу, подлежащему зачислению в федеральный бюджет, устанавливается в размере 0 процентов и применяется в порядке, предусмотренном пунктом 2 статьи 2843-1 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\nналоговая ставка по налогу, подлежащему зачислению в федеральный бюджет, устанавливается в размере 0 процентов в отношении прибыли, полученной от реализации инвестиционного проекта в свободной экономической зоне, информация о котором содержится в инвестиционной декларации, соответствующей требованиям, установленным Федеральным законом от 29 ноября 2014 года № 377-ФЗ \"О развитии Республики Крым и города федерального значения Севастополя и свободной экономической зоне на территориях Республики Крым и города федерального значения Севастополя\", и применяется в течение десяти последовательных налоговых периодов начиная с налогового периода, в котором в соответствии с данными налогового учета была получена первая прибыль от реализации указанного инвестиционного проекта в свободной экономической зоне;\n\nзаконами Республики Крым и города федерального значения Севастополя налоговая ставка по налогу, подлежащему зачислению в бюджет соответствующего субъекта Российской Федерации, может устанавливаться в размере от 0 процентов до 13,5 процента в зависимости от вида осуществляемой деятельности в свободной экономической зоне в отношении прибыли, полученной от реализации инвестиционного проекта в свободной экономической зоне, информация о котором содержится в инвестиционной декларации, соответствующей требованиям, установленным Федеральным законом от 29 ноября 2014 года № 377-ФЗ \"О развитии Республики Крым и города федерального значения Севастополя и свободной экономической зоне на территориях Республики Крым и города федерального значения Севастополя\". При этом указанная налоговая ставка применяется в течение периода действия договора об условиях деятельности в свободной экономической зоне.\n\nУказанные в настоящем пункте налоговые ставки применяются при условии ведения налогоплательщиком раздельного учета доходов (расходов), полученных (произведенных) при реализации каждого инвестиционного проекта в свободной экономической зоне, и доходов (расходов), полученных (произведенных) при осуществлении иной хозяйственной деятельности.\n\nВ случае расторжения договора об условиях деятельности в свободной экономической зоне по решению суда сумма налога подлежит исчислению и уплате в бюджет. Исчисление налога производится без учета применения пониженных ставок, предусмотренных настоящим пунктом, за весь период реализации инвестиционного проекта в свободной экономической зоне. Исчисленная сумма налога подлежит уплате по истечении отчетного или налогового периода, в котором был расторгнут договор об условиях деятельности в свободной экономической зоне, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период в соответствии с абзацами первым и вторым пункта 1 статьи 287 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 379-ФЗ) (В редакции Федерального закона от 03.08.2018 № 297-ФЗ)\n\n17-1. Для организаций - участников свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях: (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nналоговая ставка по налогу, подлежащему зачислению в федеральный бюджет, устанавливается в размере 0 процентов в отношении прибыли, полученной от реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, информация о котором содержится в инвестиционной декларации, соответствующей требованиям, установленным Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\", и применяется в течение десяти последовательных налоговых периодов начиная с налогового периода, в котором в соответствии с данными налогового учета была получена первая прибыль от реализации указанного инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях; (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nзаконами Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и иных субъектов Российской Федерации, отдельные территории которых включены в свободную экономическую зону, налоговая ставка по налогу, подлежащему зачислению в бюджет соответствующего субъекта Российской Федерации, может устанавливаться в размере от 0 процентов до 13,5 процента в зависимости от вида осуществляемой деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях в отношении прибыли, полученной от реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, информация о котором содержится в инвестиционной декларации, соответствующей требованиям, установленным Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\". При этом указанная налоговая ставка применяется в течение периода действия договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nУказанные в настоящем пункте налоговые ставки применяются при условии ведения налогоплательщиком раздельного учета доходов (расходов), полученных (произведенных) при реализации каждого инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, и доходов (расходов), полученных (произведенных) при осуществлении иной хозяйственной деятельности. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nВ случае расторжения договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области в одностороннем порядке (в свободной экономической зоне на прилегающих территориях - по соглашению сторон или по решению суда) по основаниям, предусмотренным Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\", сумма налога подлежит исчислению и уплате в бюджет. Исчисление налога производится без учета применения пониженных ставок, предусмотренных настоящим пунктом, за весь период реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. Исчисленная сумма налога подлежит уплате по истечении отчетного или налогового периода, в котором был расторгнут указанный договор, не позднее чем в сроки, установленные для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период в соответствии с абзацами первым и вторым пункта 1 статьи 287 настоящего Кодекса. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 24.06.2023 № 268-ФЗ)\n\nДля организаций, указанных в абз\n\nаце первом настоящего пункта, законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка по налогу, подлежащему зачислению в бюджеты субъектов Российской Федерации, в соответствии с положениями статьи 2844 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 380-ФЗ) (В редакции Федерального закона от 13.07.2020 № 195-ФЗ)\n\n18-1. Для организаций, владеющих лицензиями на пользование участками недр, указанными в подпункте 5 пункта 1 статьи 33345 настоящего Кодекса, и исчисляющих в отношении углеводородного сырья, добытого на таких участках недр, налог на дополнительный доход от добычи углеводородного сырья, законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка по налогу, подлежащему зачислению в бюджеты субъектов Российской Федерации, в отношении прибыли, полученной от деятельности по освоению указанных участков недр, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) в рамках такой деятельности, осуществляемой на территории соответствующего субъекта Российской Федерации, и доходов (расходов), полученных (понесенных) от иной деятельности.\n\nВ целях настоящего пункта понятия \"деятельность по освоению участка недр\", \"углеводородное сырье\" используются в значениях, указанных в статье 33343 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 18.03.2020 № 65-ФЗ)\n\n18-2. Для налогоплательщиков, осуществляющих деятельность по производству сжиженного природного газа и (или) по переработке углеводородного сырья в товары, являющиеся продукцией нефтехимии, на новых производственных мощностях, законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка по налогу, подлежащему зачислению в бюджеты субъектов Российской Федерации, в отношении прибыли, полученной от указанной деятельности. Налоговая ставка, предусмотренная настоящим абзацем, подлежит применению при условии ведения раздельного учета доходов (расходов), полученных (понесенных) в рамках такой деятельности, осуществляемой на территории соответствующего субъекта Российской Федерации, и доходов (расходов), полученных (понесенных) от иной деятельности.\n\nПри этом в целях настоящего пункта:\n\nновыми производственными мощностями признаются мощности по производству сжиженного природного газа и (или) по переработке углеводородного сырья в товары, являющиеся продукцией нефтехимии, впервые введенные в эксплуатацию после 1 января 2017 года;\n\nпонятие \"продукция нефтехимии\" используется в значении, указанном в пункте 1 статьи 1793 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 18.03.2020 № 65-ФЗ)\n\n18-3. Для налогоплательщиков - российских организаций, осуществляющих деятельность по предоставлению по лицензионному договору прав использования результатов интеллектуальной деятельности, исключительные права на которые принадлежат таким налогоплательщикам, законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка по налогу, подлежащему зачислению в бюджеты субъектов Российской Федерации, в отношении прибыли, полученной от указанной деятельности.\n\nДействие положений настоящего пункта распространяется на случаи предоставления по лицензионному договору прав использования следующих результатов интеллектуальной деятельности:\n\nизобретения, полезные модели и промышленные образцы, если они удостоверены патентами, выданными федеральным органом исполнительной власти по интеллектуальной собственности, или патентами, имеющими силу на территории Российской Федерации в соответствии с международными договорами Российской Федерации, или патентами, выданными уполномоченными органами иностранных государств или межправительственными организациями, которые осуществляют экспертизу национальных и (или) региональных заявок и выдачу охранных документов (патентов) на объекты интеллектуальной собственности в соответствующих государствах или регионах, а также промышленные образцы, правовая охрана которым предоставлена в соответствии с международными договорами Российской Федерации;\n\nселекционные достижения, если они удостоверены патентами, выданными федеральным органом исполнительной власти по селекционным достижениям;\n\nзарегистрированные федеральным органом исполнительной власти по интеллектуальной собственности программы для электронных вычислительных машин, базы данных, топологии интегральных микросхем.\n\nНалоговая ставка, предусмотренная настоящим пунктом, подлежит применению при условии ведения раздельного учета доходов (расходов), полученных (понесенных) в рамках осуществления деятельности, указанной в абзаце первом настоящего пункта, и доходов (расходов), полученных (понесенных) от иной деятельности.\n\nРазмер налоговой ставки, предусмотренной настоящим пунктом, и дополнительные условия применения указанной налоговой ставки устанавливаются законом соответствующего субъекта Российской Федерации.\n\nПеречень уполномоченных органов иностранных государств и межправительственных организаций, указанных в абзаце третьем настоящего пункта, определяется Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ) (В редакции  Федерального закона от 28.04.2023 № 166-ФЗ)\n\n18-4. Для налогоплательщиков, осуществляющих деятельность по производству аммиака и (или) водорода на новых производственных мощностях, законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка по налогу, подлежащему зачислению в бюджеты субъектов Российской Федерации, в отношении прибыли, полученной от такой деятельности. Налоговая ставка, предусмотренная настоящим пунктом, подлежит применению при условии ведения раздельного учета доходов (расходов), полученных (понесенных) в рамках такой деятельности, осуществляемой на территории соответствующего субъекта Российской Федерации, и доходов (расходов), полученных (понесенных) от иной деятельности.\n\nВ целях настоящего пункта новыми производственными мощностями признаются мощности по производству аммиака и (или) водорода, впервые введенные в эксплуатацию после 1 января 2025 года.\n\n(Дополнение пунктом - Федеральный закон от 24.07.2023 № 356-ФЗ)\n\n18-5. Для налогоплательщиков - российских организаций, включенных в реестр малых технологических компаний в соответствии с Федеральным законом от 4 августа 2023 года № 478-ФЗ \"О развитии технологических компаний в Российской Федерации\", законами субъектов Российской Федерации в 2025 - 2030 годах может устанавливаться пониженная налоговая ставка по налогу, подлежащему зачислению в бюджеты субъектов Российской Федерации.\n\nВ случае, если в течение налогового периода сведения о налогоплательщике из реестра малых технологических компаний исключаются, такой налогоплательщик утрачивает право на применение налоговой ставки, предусмотренной настоящим пунктом, с начала налогового периода, в котором произошло исключение сведений о нем из указанного реестра.\n\nЗаконом субъекта Российской Федерации могут устанавливаться различные размеры пониженных налоговых ставок в зависимости от отнесения налогоплательщика, указанного в абзаце первом настоящего пункта, к соответствующему виду малых технологических компаний, дополнительные условия для применения этих ставок, а также дополнительные требования к таким налогоплательщикам.\n\n(Дополнение пунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nУказанная налоговая ставка применяется к прибыли от видов деятельности, осуществляемых на территории Магаданской области и определенных соглашением об осуществлении деятельности, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) от видов деятельности, осуществляемых на территории Магаданской области и определенных таким соглашением, и доходов (расходов), полученных (понесенных) при осуществлении иных видов деятельности.\n\nОрганизации, указанные в настоящем пункте, вправе применять налоговую ставку 0 процентов налога, подлежащего зачислению в федеральный бюджет, с 1-го числа отчетного периода, следующего за отчетным (налоговым) периодом, в котором организация в соответствии с Федеральным законом от 31 мая 1999 года № 104-ФЗ \"Об Особой экономической зоне в Магаданской области\" приобрела статус участника Особой экономической зоны в Магаданской области. Право на применение указанной налоговой ставки утрачивается с 1-го числа отчетного (налогового) периода, в котором организация в соответствии с Федеральным законом от 31 мая 1999 года № 104-ФЗ \"Об Особой экономической зоне в Магаданской области\" утратила статус участника Особой экономической зоны в Магаданской области.\n\nПри нарушении участником Особой экономической зоны в Магаданской области существенных условий соглашения об осуществлении деятельности сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой соответствующих пеней, начисляемых со дня, следующего за установленным статьей 287 настоящего Кодекса днем уплаты налога (авансового платежа по налогу), исчисленного без учета статуса участника Особой экономической зоны в Магаданской области за весь период нахождения его в реестре участников Особой экономической зоны в Магаданской области.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2015 № 321-ФЗ)\n\nУказанные налоговые ставки применяются к прибыли регионального оператора по обращению с твердыми коммунальными отходами от деятельности в рамках договора на оказание услуг по обращению с твердыми коммунальными отходами.\n\n(Дополнение пунктом - Федеральный закон от 26.07.2019 № 211-ФЗ)\n\n114-1. Для организаций, являющихся стороной специального инвестиционного контракта, заключенного в соответствии с Федеральным законом от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\", если Российская Федерация не является другой стороной этого контракта, законами субъектов Российской Федерации может устанавливаться пониженная налоговая ставка по налогу, подлежащему зачислению в бюджеты субъектов Российской Федерации.\n\nКатегории лиц, которые применяют указанную пониженную налоговую ставку, и особенности ее применения определяются законами субъектов Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПорядок государственной аккредитации российских организаций, осуществляющих деятельность в области информационных технологий, устанавливается Правительством Российской Федерации по согласованию с высшим исполнительным органом субъекта Российской Федерации, осуществляющего функции столицы Российской Федерации. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nУказанная в настоящем пункте налоговая ставка применяется при условии, что по итогам отчетного (налогового) периода в сумме всех доходов организации, осуществляющей деятельность в области информационных технологий, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой, не менее 70 процентов составляют доходы:\n\nот реализации экземпляров разработанных, адаптированных и (или) модифицированных данной организацией либо лицом, входящим в одну группу лиц с данной организацией, программ для электронных вычислительных машин, баз данных (далее в настоящей статье - собственные программы для ЭВМ, базы данных);\n\nот передачи исключительных прав на собственные программы для ЭВМ, базы данных;\n\nот предоставления данной организацией прав использования собственных программ для ЭВМ, баз данных, в том числе путем предоставления удаленного доступа к собственным программам для ЭВМ, базам данных, включая обновления к ним и дополнительные функциональные возможности, через информационно-телекоммуникационную сеть, в том числе через информационно-телекоммуникационную сеть \"Интернет\" (далее в настоящей статье - сеть \"Интернет\") (за исключением доходов от предоставления прав использования программ для ЭВМ, баз данных (в том числе путем предоставления удаленного доступа к ним через сеть \"Интернет\"), если такие права состоят в получении возможности размещать предложения о приобретении (реализации) товаров (работ, услуг), имущественных прав в сети \"Интернет\", осуществлять поиск информации о потенциальных покупателях (продавцах) и (или) заключать сделки);\n\nот предоставления данной организацией прав использования собственных программ для ЭВМ, баз данных, в том числе путем предоставления удаленного доступа к собственным программам для ЭВМ, базам данных, включая обновления к ним и дополнительные функциональные возможности, через информационно-телекоммуникационную сеть, в том числе через информационно-телекоммуникационную сеть \"Интернет\" (далее в настоящей статье - сеть \"Интернет\") (за исключением доходов от предоставления указанных прав, если указанные права состоят в получении возможности в отношении определенного товара разместить в сети \"Интернет\" предложение, объявление о заключении договора купли-продажи товара и заключить договор купли-продажи, произвести предварительную оплату такого товара, при этом данная организация также обеспечивает возможность хранения, упаковки, доставки, выдачи такого товара покупателю с использованием недвижимого имущества и (или) транспортных средств, находящихся у нее на праве собственности, аренды или на ином праве, либо с привлечением данной организацией по гражданско-правовому договору взаимозависимого лица, которое признается таковым в соответствии с пунктом 2 статьи 1051 настоящего Кодекса и у которого эти объекты находятся на праве собственности, аренды или на ином праве; в получении возможности участвовать в процедуре закупок, предусмотренных Федеральным законом от 5 апреля 2013 года № 44-ФЗ \"О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд\" и Федеральным законом от 18 июля 2011 года № 223-ФЗ \"О закупках товаров, работ, услуг отдельными видами юридических лиц\"; в получении возможности участвовать в организованных торгах на товарном рынке; в получении возможности инициировать и осуществлять операции по безналичному переводу денежных средств; в получении банковских, финансовых услуг, в том числе услуг финансирования под уступку денежного требования, услуг на рынке ценных бумаг (дилерская деятельность, брокерская деятельность, деятельность форекс-дилеров), предоставляемых (оказываемых) банками, кредитными организациями, небанковскими кредитными организациями и иными организациями; в получении услуг, связанных с совершением сделок с недвижимым имуществом, в отношении объектов недвижимости продавцов и (или) застройщиков и (или) объектов долевого строительства; в получении возможности разместить информацию о потенциальном спросе на услуги по перевозке пассажиров и багажа легковым такси, а также в получении возможности ознакомиться с информацией о предложениях лиц, оказывающих услуги в указанной сфере, и осуществить поиск этих предложений по заданным пользователем параметрам; в получении возможности размещать информацию об услугах общественного питания, предложение заключить договор о реализации определенного товара (блюда), изготовленного лицом, оказывающим услуги общественного питания, заключить договор купли-продажи, произвести предварительную оплату такого товара (блюда), при этом организация-налогоплательщик также обеспечивает возможность доставки, выдачи такого товара (блюда) покупателю; в получении возможности формировать средства идентификации (коды маркировки), предоставляемой оператором государственной информационной системы мониторинга за оборотом товаров, подлежащих обязательной маркировке средствами идентификации; в получении возможности осуществлять хранение данных в центрах обработки данных; в получении возможности получать услуги связи по передаче данных в целях передачи голосовой информации, предоставляемой оператором связи); (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nот оказания услуг (выполнения работ) по разработке, адаптации и модификации программ для ЭВМ, баз данных (программных средств и информационных продуктов вычислительной техники) (далее в настоящей статье - заказные программы для ЭВМ, базы данных);\n\nот оказания услуг (выполнения работ) по установке, тестированию и сопровождению собственных программ для ЭВМ, баз данных и заказных программ для ЭВМ, баз данных;\n\nот оказания услуг (выполнения работ) по разработке (включая тестирование и сопровождение) программно-аппаратных комплексов при наличии документа, подтверждающего отнесение предусмотренных договором услуг (работ) к разработке программно-аппаратных комплексов и выданного федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере информационных технологий, в порядке, устан\n\nовленном указанным федеральным органом исполнительной власти, а также по адаптации, модификации, тестированию и сопровождению программно-аппаратных комплексов, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nот реализации разработанных данной организацией программно-аппаратных комплексов, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных;\n\nот оказания данной организацией услуг с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), по распространению рекламной информации в сети \"Интернет\" и (или) получению доступа к такой информации;\n\nот оказания услуг с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), по предоставлению доступа к аудиовизуальным произведениям и (или) сообщениям телепередач на аудиовизуальном сервисе, включенном в реестр аудиовизуальных сервисов;\n\nот оказания услуг и (или) предоставления прав использования, заключающихся в предоставлении доступа к отдельным фонограммам, совокупности фонограмм, объектам авторского и смежных прав, связанных с фонограммами, с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных);\n\nот оказания услуг в сети \"Интернет\" с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), по размещению и (или) продвижению предложений, объявлений о приобретении (реализации) товаров (работ, услуг), имущественных прав, предложений о трудоустройстве, услуг по осуществлению поиска таких предложений, объявлений (доступа к таким предложениям, объявлениям) и (или) по заключению договоров (за исключением доходов от оказания услуг, указанных в настоящем абзаце, если эти услуги состоят в предоставлении возможности в отношении определенного товара разместить в сети \"Интернет\" предложение, объявление о заключении договора купли-продажи товара и заключить договор купли-продажи, произвести предварительную оплату такого товара, при этом данная организация также обеспечивает возможность хранения, упаковки, доставки, выдачи такого товара покупателю с использованием недвижимого имущества и (или) транспортных средств, находящихся у нее на праве собственности, аренды или на ином праве, либо с привлечением данной организацией по гражданско-правовому договору взаимозависимого лица, которое признается таковым в соответствии с пунктом 2 статьи 1051 настоящего Кодекса и у которого эти объекты находятся на праве собственности, аренды или на ином праве; от оказания данной организацией услуг, указанных в настоящем абзаце, если такие услуги состоят в получении возможности разместить информацию о потенциальном спросе на услуги по перевозке пассажиров и багажа легковым такси, а также в получении возможности ознакомиться с информацией о предложениях лиц, оказывающих услуги в указанной сфере, и осуществить поиск этих предложений по заданным параметрам; в получении возможности разместить информацию об услугах общественного питания, предложение заключить договор о реализации определенного товара (блюда), изготовленного лицом, оказывающим услуги общественного питания, заключить договор купли-продажи, произвести предварительную оплату такого товара (блюда), при этом организация-налогоплательщик также обеспечивает возможность доставки, выдачи такого товара (блюда) покупателю; в получении возможности участвовать в процедуре закупок, предусмотренных Федеральным законом от 5 апреля 2013 года № 44-ФЗ \"О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд\" и Федеральным законом от 18 июля 2011 года № 223-ФЗ \"О закупках товаров, работ, услуг отдельными видами юридических лиц\"; в получении возможности участвовать в организованных торгах на товарном рынке; в получении возможности инициировать и осуществлять операции по безналичному переводу денежных средств; в получении банковских, финансовых услуг, в том числе услуг финансирования под уступку денежного требования, услуг на рынке ценных бумаг (дилерская деятельность, брокерская деятельность, деятельность форекс-дилеров), предоставляемых (оказываемых) банками, кредитными организациями, небанковскими кредитными организациями и иными организациями; в получении услуг, связанных с совершением сделок с недвижимым имуществом, в отношении объектов недвижимости продавцов и (или) застройщиков и (или) объектов долевого строительства; в получении возможности формировать средства идентификации (коды маркировки), предоставляемой оператором государственной информационной системы мониторинга за оборотом товаров, подлежащих обязательной маркировке средствами идентификации; в получении возможности осуществлять хранение данных в центрах обработки данных; в получении возможности получать услуги связи по передаче данных для целей передачи голосовой информации, предоставляемой оператором связи); (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nот оказания данной организацией, имеющей лицензию на осуществление образовательной деятельности, с использованием собственных программ для ЭВМ, баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных (либо в случае, если составная часть собственной программы для ЭВМ включена в единый реестр российских программ для электронных вычислительных машин и баз данных), в том числе путем предоставления удаленного доступа к собственным программам для ЭВМ, базам данных, услуг по предоставлению доступа к электронной образовательной и (или) просветительской информации (сервисам).\n\nВ целях настоящего пункта сумма доходов определяется по данным налогового учета организации в соответствии со статьей 248 настоящего Кодекса, при этом в нее не включаются доходы, указанные в пунктах 2 и 11 части второй статьи 250 и пункте 41 статьи 271 настоящего Кодекса, а также доходы от уступки прав требования долга, возникшего при признании доходов, указанных в настоящем пункте.\n\nВ случае, если по итогам налогового периода налогоплательщик не выполняет условие настоящего пункта, а также в случае лишения его государственной аккредитации такой налогоплательщик лишается права применять налоговую ставку, предусмотренную настоящим пунктом, с начала налогового периода, в котором допущено несоответствие указанному условию либо он лишен государственной аккредитации.\n\nВне зависимости от выполнения иных условий, установленных настоящим пунктом, налоговая ставка, установленная настоящим пунктом, не подлежит применению:\n\nорганизациями, созданными в результате реорганизации (кроме преобразования) или реорганизованными в форме присоединения к ним другого юридического лица либо выделения из его состава одного или нескольких юридических лиц после 1 июля 2022 года;\n\nорганизациями (в том числе кредитными организациями), в которых прямо и (или) косвенно участвует Российская Федерация и доля такого участия составляет не менее 50 процентов.\n\nВ целях настоящего пункта лицом, входящим в одну группу лиц с данной организацией, признается лицо, которое прямо участвует в данной организации, либо в котором прямо участвует данная организация, либо в котором и в данной организации прямо участвует третье лицо и доля участия во всех случаях составляет более 50 процентов. Указанным лицом не может быть иностранная организация (за исключением иностранной организации, контролирующим лицом которой является российская организация или гражданин Российской Федерации) либо иностранный гражданин или лицо без гражданства. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 31.07.2020 № 265-ФЗ) (В редакции Федерального закона от 14.07.2022 № 321-ФЗ)\n\nУказанные в настоящем пункте налоговые ставки применяются при условии, что по итогам отчетного (налогового) периода в сумме всех доходов организации, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой, не менее 70 процентов составляют доходы:\n\nот реализации услуг (работ) по проектированию и (или) разработке электронной компонентной базы (электронных модулей), электронной (радиоэлектронной) продукции и (или) материалов и технологий для производства электронной компонентной базы (электронных модулей) в соответствии с перечнем таких материалов и технологий, утверждаемым Правительством Российской Федерации;\n\nот реализации услуг (работ) по производству электронной (радиоэлектронной) продукции в соответствии с перечнем, утверждаемым Правительством Российской Федерации, и (или) по производству электронной компонентной базы (электронных модулей);\n\nот передачи исключительного права на результаты интеллектуальной деятельности и (или) предоставления права использования результатов интеллектуальной деятельности, созданных при проектировании и (или) разработке электронной компонентной базы (электронных модулей) и (или) электронной (радиоэлектронной) продукции;\n\nот реализации организацией электронной компонентной базы (электронных модулей), произведенной на основе собственных разработок или разработок лица, входящего в одну группу лиц с данной организацией;\n\nот реализации (передачи в аренду) произведенной на основе собственных разработок электронной (радиоэлектронной) продукции в соответствии с перечнем, утверждаемым Правительством Российской Федерации;\n\nот реализации произведенного организацией оборудования для производства электронной компонентной базы (электронных модулей), электронной (радиоэлектронной) продукции в соответствии с перечнем такого оборудования, утверждаемым Правительством Российской Федерации;\n\nот реализации услуг (работ) по ремонту и (или) техническому обслуживанию произведенной на основе собственных разработок электронной (радиоэлектронной) продукции в соответствии с перечнем, утверждаемым Правительством Российской Федерации.\n\nВ целях настоящего пункта сумма доходов определяется по данным налогового учета организации в соответствии со статьей 248 настоящего Кодекса, при этом в нее не включаются доходы, указанные в пунктах 2 и 11 части второй статьи 250 и пункте 41 статьи 271 настоящего Кодекса, а также доходы от уступки права требования долга, возникшего при признании доходов, указанных в настоящем пункте.\n\nВ случае, если по итогам налогового периода налогоплательщик не выполняет условие, установленное настоящим пунктом, а также в случае его исключения из реестра организаций, осуществляющих деятельность в сфере радиоэлектронной промышленности, такой налогоплательщик лишается права применять налоговые ставки, предусмотренные настоящим пунктом, с начала налогового периода, в котором допущено несоответствие установленному условию либо произошло исключение из указанного реестра.\n\nВ целях настоящего пункта лицом, входящим в одну группу лиц с данной организацией, признается лицо, которое прямо участвует в данной организации, либо в котором прямо участвует данная организация, либо в котором и в данной организации прямо участвует третье лицо, и при этом доля участия во всех случаях составляет более 50 процентов. Указанным лицом не может быть иностранная организация (за исключением иностранной организации, контролирующим лицом которой является российская организация или гражданин Российской Федерации) либо иностранный гражданин или лицо без гражданства.\n\nПорядок формирования и ведения реестра организаций, осуществляющих деятельность в сфере радиоэлектронной промышленности, в том числе основания для включения организаций в указанный реестр и исключения из него, требования к организациям для целей включения в указанный реестр, устанавливается Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2020 № 265-ФЗ) (В редакции  Федерального закона от 29.11.2024 № 417-ФЗ)\n\n117-1. Для организаций, владеющих лицензиями на пользование участками недр, указанными в подпункте 5 пункта 1 статьи 33345 и пункте 2 статьи 3435 настоящего Кодекса, в отношении прибыли, полученной от деятельности по освоению указанных участков недр, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) в рамках такой деятельности, осуществляемой на территории соответствующего субъекта Российской Федерации, и доходов (расходов), полученных (понесенных) от иной деятельности, налоговая ставка устанавливается в размере 20 процентов, если иное не установлено настоящим пунктом. При этом сумма налога, исчисленная по налоговой ставке в размере 2 процентов (3 процентов в 2025 - 2030 годах), зачисляется в федеральный бюджет, а сумма налога, исчисленная по налоговой ставке в размере 18 процентов (17 процентов в 2025 - 2030 годах), если иное не установлено законом субъекта Российской Федерации для указанной категории налогоплательщиков в соответствии с пунктом 18-1 настоящей статьи, зачисляется в бюджеты субъектов Российской Федерации.\n\nПоложения настоящего пункта применяются в течение налоговых периодов, в которых такой организацией в соответствии с подпунктом 4 пункта 2 статьи 3426 настоящего Кодекса при расчете коэффициента КНДД применяется коэффициент КГ менее 1.\n\nВ целях настоящего пункта понятие \"деятельность по освоению участка недр\" используется в значении, указанном в статье 33343 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n1) 25 процентов - со всех доходов, за исключением указанных в подпунктах 2 - 4 настоящего пункта и пунктах 3, 4 и 43 настоящей статьи с учетом положений статьи 310 настоящего Кодекса; (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 26.03.2022 № 66-ФЗ, от 27.11.2023 № 539-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n2) 10 процентов - от использования, содержания или сдачи в аренду (фрахта) судов, самолетов или других подвижных транспортных средств или контейнеров (включая трейлеры и вспомогательное оборудование, необходимое для транспортировки) в связи с осуществлением международных перевозок;\n\n3) 0 процентов - по доходам, полученным иностранными организациями по договорам об урегулировании страховых и (или) претензионных требований, возникающих из заключенных с иностранными организациями - лизингодателями до 5 марта 2022 года договоров аренды (лизинга) воздушных судов, зарегистрированных или подлежащих регистрации в Государственном реестре гражданских воздушных судов Российской Федерации, включая вспомогательные силовые установки и (или) авиационные двигатели, при условии, что указанные договоры об урегулировании страховых и (или) претензионных требований предусматривают переход права собственности на такие воздушные суда, вспомогательные силовые установки и (или) авиационные двигатели к российской организации.\n\nПоложения настоящего подпункта не применяются, если иностранная организация - получатель дохода является взаимозависимым лицом в соответствии со статьей 1051 настоящего Кодекса с российской организацией, к которой в соответствии с договорами об урегулировании страховых (претензионных) требований переходит право собственности на такие воздушные суда, вспомогательные силовые установки и (или) авиационные двигатели, либо с российской организацией - лизингополучателем в соответствии с договорами аренды (лизинга) таких воздушных судов, вспомогательных силовых установок и (или) авиационных двигателей.\n\nНалоговая ставка, установленная настоящим подпунктом, применяется при условии представления иностранной организацией, получающей доход, налоговому агенту подтверждений, предусмотренных пунктом 1 статьи 312 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n4) 15 процентов - по доходам, указанным в подпункте 94 пункта 1 стат\n\nьи 309 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) 0 процентов - по доходам, полученным российскими организациями в виде дивидендов при условии, что на день принятия решения о выплате дивидендов (на день принятия решения о выходе из организации или ликвидации организации соответственно) получающая дивиденды организация в течение не менее 365 календарных дней непрерывно владеет на праве собственности не менее чем 50-процентным вкладом (долей) в уставном (складочном) капитале (фонде) выплачивающей дивиденды организации или депозитарными расписками, дающими право на получение дивидендов, в сумме, соответствующей не менее 50 процентам общей суммы выплачиваемых организацией дивидендов. (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\nПри этом в случае, если выплачивающая дивиденды организация является иностранной, установленная настоящим подпунктом налоговая ставка применяется, если иное не предусмотрено законодательством о налогах и сборах, в отношении организаций, государство постоянного местонахождения которых не включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны). (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nНалоговая ставка, установленная настоящим подпунктом, не применяется в отношении доходов, полученных иностранными организациями, признаваемыми налоговыми резидентами Российской Федерации в порядке, установленном статьей 2462 настоящего Кодекса, если иное не установлено законодательством Российской Федерации о налогах и сборах; (Дополнение абзацем - Федеральный закон от 15.02.2016 № 32-ФЗ) (В редакции федеральных законов от 27.11.2018 № 424-ФЗ, от 23.11.2020 № 374-ФЗ)\n\n11) 0 процентов - по доходам, полученным международной холдинговой компанией в виде дивидендов при условии, что на день принятия решения о выплате дивидендов международная холдинговая компания в течение не менее 365 календарных дней непрерывно владеет на праве собственности не менее чем 15-процентным вкладом (долей) в уставном (складочном) капитале (фонде) выплачивающей дивиденды организации или депозитарными расписками, дающими право на получение дивидендов, в сумме, соответствующей не менее 15 процентам общей суммы выплачиваемых организацией дивидендов.\n\nНалоговая ставка, установленная настоящим подпунктом, применяется в случае признания международной компании (организации, указанной в пункте 11 статьи 242 настоящего Кодекса) международной холдинговой компанией в соответствии со статьей 242 настоящего Кодекса на дату выплаты дохода, а также при выполнении условий, установленных статьей 28410 настоящего Кодекса. (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\nПри этом в случае, если выплачивающая дивиденды организация является иностранной, установленная настоящим подпунктом налоговая ставка применяется, если иное не предусмотрено законодательством о налогах и сборах, в отношении организаций, государство (территория) постоянного местонахождения которых не включено в перечень государств и территорий, утверждаемый Министерством финансов Российской Федерации, в соответствии с подпунктом 1 настоящего пункта. (В редакции  федеральных законов от 26.03.2022 № 66-ФЗ, от 19.12.2023 № 595-ФЗ)\n\nПри применении положений настоящего подпункта международная компания (организация, указанная в пункте 11 статьи 242 настоящего Кодекса), получающая доход в виде дивидендов, должна предоставить налоговому агенту, выплачивающему такой доход, подтверждение того, что на дату выплаты дохода выполняются условия признания такой международной компании (организации, указанной в пункте 11 статьи 242 настоящего Кодекса) международной холдинговой компанией, предусмотренные статьей 242 настоящего Кодекса. (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\nПредоставление указанного подтверждения налоговому агенту, выплачивающему доход, до даты выплаты дохода является основанием для применения ставки, предусмотренной настоящим подпунктом; (В редакции  Федерального закона от 26.03.2022 № 66-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 03.08.2018 № 294-ФЗ)\n\n12) 5 процентов - по доходам, полученным иностранными лицами в виде дивидендов по акциям (долям) международных холдинговых компаний, которые являются публичными компаниями на день принятия решения такой компании о выплате дивидендов.\n\nНалоговая ставка, установленная настоящим подпунктом, применяется в случае признания международной компании (организации, указанной в пункте 11 статьи 242 настоящего Кодекса) международной холдинговой компанией в соответствии со статьей 242 настоящего Кодекса на день принятия решения такой компании о выплате дивидендов, а также при выполнении условий, установленных статьей 28410 настоящего Кодекса. (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\nДля применения положений настоящего подпункта иностранное лицо, доля прямого участия которого в международной холдинговой компании превышает 5 процентов, получающее доход в виде дивидендов, должно предоставить налоговому агенту, выплачивающему такой доход, подтверждение того, что на дату выплаты дохода такое иностранное лицо имеет фактическое право на получение дохода, до даты выплаты дохода, если иной порядок не предусмотрен статьей 3101 настоящего Кодекса. В случае, если такое иностранное лицо признает отсутствие фактического права на доход в виде дивидендов, положения настоящего подпункта могут применяться к другому иностранному лицу в порядке, предусмотренном пунктами 11 и 12 статьи 312 настоящего Кодекса.\n\nНалоговая ставка, установленная настоящим подпунктом, применяется по доходам, полученным до 1 января 2029 года, и при условии, что иностранные организации, в порядке редомициляции которых зарегистрированы такие компании, или организации, указанные в пункте 11 статьи 242 настоящего Кодекса, являлись публичными компаниями по состоянию на 1 января 2018 года; (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 03.08.2018 № 294-ФЗ) (В редакции Федерального закона от 25.12.2018 № 490-ФЗ)\n\n13) 10 процентов - по доходам в виде дивидендов по акциям (долям) международных холдинговых компаний, не указанным в подпункте 12 настоящего пункта, а также по доходам, полученным в виде дивидендов по акциям международных холдинговых компаний, права на которые удостоверены депозитарными расписками, при одновременном соблюдении следующих условий:\n\nна дату выплаты дохода международная холдинговая компания соответствует условиям, установленным статьей 28410 настоящего Кодекса;\n\nлицо, имеющее фактическое право на доход, не является лицом, государство (территория) постоянного местонахождения которого включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны).\n\nНалоговая ставка, установленная настоящим подпунктом, применяется по доходам, полученным до 1 января 2036 года.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим подпунктом, лицо, получающее доход, должно представить налоговому агенту, выплачивающему указанный доход, документы, подтверждающие наличие фактического права на получение соответствующего дохода.\n\nВ случае, если фактическое право на получение дохода принадлежит иностранной организации, такая организация должна представить налоговому агенту, выплачивающему указанный доход, документы, подтверждающие, что ее постоянным местонахождением не является государство, которое включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны). В случае, если такие подтверждающие документы составлены на иностранном языке, налоговому агенту предоставляется также перевод на русский язык.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим подпунктом, налоговый агент одновременно с налоговым расчетом представляет в налоговый орган документы, подтверждающие соблюдение условий, установленных настоящим подпунктом;\n\n(Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n14) 15 процентов - по доходам, полученным личным фондом в виде дивидендов, вне зависимости от условий, предусмотренных подпунктами 1 - 13, 2, 21, 3 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n15) 0 процентов - по доходам, полученным российскими организациями в виде дивидендов по акциям (долям) российской организации при условии, что на день принятия решения о выплате дивидендов (на день принятия решения о выходе из организации или ликвидации организации соответственно) выплачивающая дивиденды организация в течение не менее 365 календарных дней непрерывно владеет на праве собственности не менее чем 50-процентным вкладом (долей) в уставном (складочном) капитале (фонде) получающей дивиденды организации.\n\nПоложения настоящего подпункта применяются при условии, что денежные средства в размере дивидендов по акциям (долям) российской организации выплачены получившей их российской организацией в адрес выплачивающей такие дивиденды российской организации в течение 120 календарных дней, следующих за днем получения, в виде дивидендов и (или) в виде имущества, имущественных прав безвозмездно в соответствии с подпунктом 11 пункта 1 статьи 251 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n2) 13 процентов - по доходам, полученным в виде дивидендов от российских и иностранных организаций российскими организациями, не указанными в подпункте 1 настоящего пункта, а также по доходам в виде дивидендов, полученных по акциям, права на которые удостоверены депозитарными расписками, если иное не предусмотрено подпунктом 13 настоящего пункта; (В редакции  федеральных законов от 28.12.2013 № 420-ФЗ, от 24.11.2014 № 366-ФЗ, от 26.03.2022 № 66-ФЗ)\n\n21) 5 процентов - по доходам, полученным международной холдинговой компанией, не указанным в подпункте 11 настоящего пункта, в виде дивидендов от российских и иностранных организаций, а также по доходам, полученным в виде дивидендов по акциям, права на которые удостоверены депозитарными расписками, при выполнении условий, установленных статьей 28410 настоящего Кодекса.\n\nНалоговая ставка, установленная настоящим подпунктом, применяется по доходам, полученным до 1 января 2036 года.\n\nПри применении положений настоящего подпункта международная холдинговая компания, получающая доход в виде дивидендов, должна предоставить налоговому агенту, выплачивающему такой доход, подтверждение того, что на дату выплаты дохода такая международная холдинговая компания выполняет условия, установленные статьей 28410 настоящего Кодекса.\n\nПредоставление указанного подтверждения налоговому агенту, выплачивающему доход, до даты выплаты дохода является основанием для применения ставки, предусмотренной настоящим подпунктом.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим подпунктом, налоговый агент одновременно с налоговым расчетом представляет в налоговый орган документы, подтверждающие соблюдение условий, установленных настоящим подпунктом;\n\n(Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n3) 15 процентов - по доходам, полученным иностранной организацией в виде дивидендов по акциям российских организаций, а также дивидендов от участия в капитале организации в иной форме, если иное не предусмотрено подпунктом 13 настоящего пункта. (В редакции  федеральных законов от 02.11.2013 № 306-ФЗ, от 26.03.2022 № 66-ФЗ)\n\nПри этом налог исчисляется с учетом особенностей, предусмотренных статьей 275 настоящего Кодекса.\n\nДля подтверждения права на применение налоговой ставки, установленной подпунктом 1 настоящего пункта, налогоплательщики обязаны предоставить в налоговые органы документы, содержащие сведения о дате (датах) приобретения (получения) права собственности на вклад (долю) в уставном (складочном) капитале (фонде) выплачивающей дивиденды организации или на депозитарные расписки, дающие право на получение дивидендов. (В редакции Федерального закона от 27.12.2009 № 368-ФЗ)\n\nТакими документами могут, в частности, являться договоры купли-продажи (мены), решения о размещении эмиссионных ценных бумаг, договоры о реорганизации в форме слияния или присоединения, решения о реорганизации в форме разделения, выделения или преобразования, ликвидационные (разделительные) балансы, передаточные акты, свидетельства о государственной регистрации организации, планы приватизации, решения о выпуске ценных бумаг, отчеты об итогах выпуска ценных бумаг, проспекты эмиссии, судебные решения, уставы, учредительные договоры (решения об учреждении) или их аналоги, выписки из лицевого счета (счетов) в системе ведения реестра акционеров (участников), выписки по счету (счетам) \"депо\" и иные документы, содержащие сведения о дате (датах) приобретения (получения) права собственности на вклад (долю) в уставном (складочном) капитале (фонде) выплачивающей дивиденды организации или на депозитарные расписки, дающие право на получение дивидендов. Указанные документы или их копии, если они составлены на иностранном языке, должны быть легализованы в установленном порядке и переведены на русский язык. (В редакции Федерального закона от 27.12.2009 № 368-ФЗ)\n\n(Пункт в редакции Федерального закона от 16.05.2007 № 76-ФЗ)\n\n1) 20 процентов - по доходу в виде процентов по следующим видам ценных бумаг, условиями выпуска и обращения которых предусмотрено получение дохода в виде процентов (за исключением ценных бумаг, указанных в подпунктах 2 и 3 настоящего пункта, и процентного дохода, полученного российскими организациями по государственным и муниципальным ценным бумагам, размещаемым за пределами Российской Федерации, за исключением процентного дохода, полученного первичными владельцами государственных ценных бумаг Российской Федерации, которые были получены ими в обмен на государственные краткосрочные бескупонные облигации в порядке, установленном Правительством Российской Федерации): (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nгосударственным ценным бумагам государств - участников Союзного государства;\n\nгосударственным ценным бумагам субъектов Российской Федерации и муниципальным ценным бумагам;\n\nоблигациям с ипотечным покрытием, эмитированным после 1 января 2007 года;\n\nоблигациям российских организаций (за исключением облигаций иностранных организаций, признаваемых налоговыми резидентами Российской Федерации), которые на соответствующие даты признания процентного дохода по ним признаются обращающимися на организованном рынке ценных бумаг, номинированным в рублях и эмитированным начиная с 1 января 2017 года. (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nНалоговая ставка, установленная настоящим подпунктом, применяется также к налоговой базе в виде доходов учредителей доверительного управления ипотечным покрытием, полученных на основании приобретения ипотечных сертификатов участия, выданных управляющим ипотечным покрытием после 1 января 2007 года;\n\n(Подпункт в редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n2) 9 процентов - по доходам в виде процентов по муниципальным ценным бумагам, эмитированным на срок не менее трех лет до 1 января 2007 года, а также по доходам в виде процентов по облигациям с ипотечным покрытием, эмитированным до 1 января 2007 года, и доходам учредителей доверительного управления ипотечным покрытием, полученным на основании приобретения ипотечных сертификатов участия, выданных управляющим ипотечным покрытием до 1 января 2007 года;\n\n3) 0 процентов - по доходу в виде процентов по государственным и муниципальным облигациям, эмитированным до 20 января 1997 года включительно, а также по доходу в виде процентов по облигациям государственного валютного облигационного займа 1999 года, эмитированным при осуществлении новации облигаций внутреннего государственного валютного займа серии III, эмитированных в целях обеспечения условий, необходимых для урегулирования внутреннего валютного долга бывшего Союза ССР и внутреннего и внешнего валютного долга Российской Федерации;\n\n4) 10 процентов - по доходам в виде процентов по долговым обязательствам любого вида, являющимся обязательствами международных холдинговых компаний, при одновременном соблюдении следующих условий:\n\nна дату получения дохода международная холдинговая компания выполняет условия, установленные статьей 28410 настоящего Кодекса;\n\nлицо, имеющее фактическое право на доход, не является лицом, государство (территория) постоянного местонахождения которого включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны).\n\nНалоговая ставка, установленная настоящим подпунктом, применяется по доходам, полученным до 1 января 2036 года.\n\nПри применении положений настоящего подпункта международная холдинговая компания, выплачивающая доход в виде процентов по долговым обязательствам, не являющаяся налоговым агентом по таким выплатам, должна предоставить лицу, получающему доход, подтверждение того, что на дату получения этим лицом дохода указанная международная холдинговая компания выполняет условия, установленные статьей 28410 настоящего Кодекса.\n\nПредставление указанных документов осуществляется по итогам отчетного (налогового) периода, в котором осуществляется выплата дохода.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим подпунктом, иностранное лицо, получающее доход, должно представить налоговому агенту, выплачивающему указанный доход, документы, подтверждающие наличие фактического права на получение соответствующего дохода.\n\nВ случае, если фактическое право на получение дохода принадлежит иностранной организации, такая организация должна представить налоговому агенту, выплачивающему указанный доход, документы, подтверждающие, что ее постоянным местонахождением не является государство, которое включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны). В случае, если такие документы составлены на иностранном языке, налоговому агенту предоставляется также перевод на русский язык.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим подпунктом, налогоплательщик (налоговый агент) одновременно с налоговой декларацией (налоговым расчетом) по налогу представляет в налоговый орган документы, подтверждающие соблюдение условий, установленных настоящим подпунктом;\n\n(Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n5) 5 процентов - по доходам в виде процентов по долговым обязательствам любого вида, полученным международной холдинговой компанией, при выполнении условий, установленных статьей 28410 настоящего Кодекса, и при условии непредставления в налоговый орган заявления об\n\nотказе от применения указанной налоговой ставки. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nНалоговая ставка, установленная настоящим подпунктом, применяется по доходам, полученным до 1 января 2036 года.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим подпунктом, налогоплательщик одновременно с налоговой декларацией по налогу представляет в налоговый орган документы, подтверждающие соблюдение условий, установленных настоящим подпунктом.\n\nУказанное в абзаце первом настоящего подпункта заявление вправе представить международная холдинговая компания, являющаяся международной компанией. Такое заявление, составленное в произвольной форме, представляется в налоговый орган в срок не позднее трех месяцев с даты регистрации международной компании, при этом отзыв такого заявления не допускается. (Дополнение абзацем - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\nВ случае представления указанного в абзаце первом настоящего подпункта заявления международная холдинговая компания, являющаяся международной компанией, не применяет налоговую ставку, установленную настоящим подпунктом, начиная с налогового периода, в котором представлено такое заявление. (Дополнение абзацем - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n(Пункт в редакции Федерального закона от 20.08.2004 № 107-ФЗ)\n\nК налоговой базе, определяемой по доходам от операций по реализации или иного выбытия (в том числе погашения) акций, облигаций российских организаций, инвестиционных паев, являющихся ценными бумагами высокотехнологичного (инновационного) сектора экономики, применяется налоговая ставка 0 процентов с учетом особенностей, установленных статьей 2842.1 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 396-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2010 № 395-ФЗ)\n\n41-1. К налоговой базе, определяемой в 2024 году по доходам от операций по реализации долей участия в уставном капитале лиц, которым выдана лицензия на осуществление исключительного права на экспорт газа в соответствии с пунктом 2 части 11 статьи 3 Федерального закона от 18 июля 2006 года № 117-ФЗ \"Об экспорте газа\", применяется налоговая ставка в размере 20 процентов. Положения данного пункта применяются организациями, прямо или косвенно участвующими в уставном капитале указанных лиц, если доля такого участия на дату реализации, определенная в соответствии с положениями статьи 1052 настоящего Кодекса, составляет более 50 процентов. Сумма налога, исчисленная по налоговой ставке, указанной в настоящем пункте, зачисляется в федеральный бюджет. (Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n41-2. Если иное не предусмотрено пунктом 41 настоящей статьи, к налоговой базе, определяемой по доходам от операций по реализации или иного выбытия (в том числе погашения) акций (долей участия в уставном капитале) российских организаций, имеющих документ о государственной аккредитации организации, осуществляющей деятельность в области информационных технологий, применяется налоговая ставка 5 процентов при одновременном соблюдении следующих условий:\n\nна дату реализации или иного выбытия (в том числе погашения) таких акций (долей участия в уставном капитале) они непрерывно принадлежат налогоплательщику на праве собственности или на ином вещном праве более трех лет;\n\nтакие акции (доли) составляют уставный капитал указанных организаций, не более 50 процентов активов которых, по данным финансовой отчетности на последний день месяца, предшествующего месяцу реализации, прямо или косвенно состоит из недвижимого имущества, находящегося на территории Российской Федерации;\n\nтакие акции (доли) составляют уставный капитал указанных организаций, которые по итогам расчетного периода по страховым взносам, предшествующего году, на который приходится дата реализации или иного выбытия (в том числе погашения) таких акций (долей участия в уставном капитале), применяют тариф страховых взносов в размере, установленном пунктом 22 статьи 427 настоящего Кодекса, для плательщиков, указанных в подпункте 3 пункта 1 статьи 427 настоящего Кодекса.\n\nПри этом если указанные акции российской организации на дату их реализации относятся к ценным бумагам, обращающимся на организованном рынке ценных бумаг, и в налоговом периоде количество реализованных налогоплательщиком акций не превышает 1 процента общего количества акций этой организации, то налоговая ставка, предусмотренная настоящим пунктом, применяется независимо от состава активов этой организации.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2024 № 416-ФЗ)\n\nна дату получения дохода международная холдинговая компания выполняет условия, установленные статьей 28410 настоящего Кодекса;\n\nлицо, имеющее фактическое право на доход, не является лицом, государство (территория) постоянного местонахождения которого включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны).\n\nНалоговая ставка, установленная настоящим пунктом, применяется по доходам, полученным до 1 января 2036 года.\n\nПри применении положений настоящего пункта международная холдинговая компания, выплачивающая доход от использования ею прав на объекты интеллектуальной собственности, не являющаяся налоговым агентом по таким выплатам, должна предоставить лицу, получающему доход, подтверждение того, что на дату получения этим лицом дохода указанная компания выполняет условия, установленные статьей 28410 настоящего Кодекса.\n\nПредоставление указанного подтверждения осуществляется по итогам отчетного (налогового) периода, в котором осуществляется выплата дохода.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим пунктом, иностранное лицо, получающее доход, должно представить налоговому агенту, выплачивающему указанный доход, документы, подтверждающие наличие фактического права на получение соответствующего дохода.\n\nВ случае, если фактическое право на получение дохода принадлежит иностранной организации, она должна представить налоговому агенту, выплачивающему указанный доход, документы, подтверждающие, что ее постоянным местонахождением не является государство, которое включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны). В случае, если такие подтверждающие документы составлены на иностранном языке, налоговому агенту предоставляется также перевод на русский язык.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим пунктом, налогоплательщик (налоговый агент) одновременно с налоговой декларацией (налоговым расчетом) по налогу представляет в налоговый орган документы, подтверждающие соблюдение условий, установленных настоящим пунктом.\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nНалоговая ставка, установленная настоящим пунктом, применяется по доходам, полученным до 1 января 2036 года.\n\nДля подтверждения права на применение налоговой ставки, установленной настоящим пунктом, налогоплательщик одновременно с налоговой декларацией по налогу представляет в налоговый орган документы, подтверждающие соблюдение условий, установленных настоящим пунктом.\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nК налоговой базе, определяемой по доходам, полученным иностранными организациями - обладателями цифровых финансовых активов в случае, если решением о выпуске таких цифровых финансовых активов предусмотрена выплата дохода в сумме, равной сумме дивидендов, полученных лицом, выпустившим такие цифровые финансовые активы, применяется ставка налога в размере 15 процентов.\n\nЛицо, выпустившее указанные цифровые финансовые активы, обязано довести до сведения налогоплательщика - обладателя таких цифровых финансовых активов информацию о сумме полученных дивидендов и примененных к ним ставках налога в одной из следующих форм:\n\nэлектронный документ, подписанный электронной подписью в соответствии с Федеральным законом от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\";\n\nдокумент на бумажном носителе, подписанный уполномоченным лицом российской организации, выпустившей цифровые финансовые активы.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nПрибыль, полученная Центральным банком Российской Федерации от осуществления деятельности, не связанной с выполнением им функций, предусмотренных Федеральным законом \"О Центральном банке Российской Федерации (Банке России)\", облагается налогом по налоговой ставке, предусмотренной пунктом 1 настоящей статьи.\n\nВ налоговом периоде, в котором совокупный размер прибыли, полученной участником проекта нарастающим итогом начиная с 1-го числа года, в котором участник проекта прекратил использование права на освобождение от исполнения обязанностей налогоплательщика в соответствии с абзацем третьим пункта 2 статьи 2461 настоящего Кодекса, превысил 300 миллионов рублей и (или) в котором участник проекта утратил статус участника проекта, полученная таким участником проекта прибыль подлежит налогообложению по налоговой ставке, установленной пунктом 1 настоящей статьи, с начислением пеней за несвоевременную уплату налога и авансовых платежей по нему. При этом положения настоящего абзаца не распространяются на прибыль, полученную в период с 1 января 2017 года по 31 декабря 2021 года включительно. (В редакции федеральных законов от 28.11.2011 № 339-ФЗ; от 28.12.2016 № 475-ФЗ)\n\nВ налоговом периоде, в котором совокупный размер прибыли, полученной участником проекта нарастающим итогом начиная с 1-го числа года, в котором участник проекта прекратил использование права на освобождение от исполнения обязанностей налогоплательщика в соответствии с абзацем третьим пункта 2 статьи 2461 настоящего Кодекса, превысил 300 миллионов рублей (для участника проекта - исследовательского корпоративного центра - один миллиард рублей), и (или) в котором участник проекта утратил статус участника проекта, и (или) в котором доходы исследовательского корпоративного центра от реализации взаимозависимым лицам товаров (работ, услуг), передачи имущественных прав составили менее 50 процентов в общей сумме доходов исследовательского корпоративного центра, полученная таким участником проекта прибыль подлежит налогообложению по налоговой ставке, установленной пунктом 1 настоящей статьи, с начислением пеней за несвоевременную уплату налога и авансовых платежей по нему. При этом положения настоящего абзаца распространяются на прибыль, полученную в период с 1 января 2017 года по 31 декабря 2021 года включительно. (Дополнение абзацем - Федеральный закон от 28.12.2016 № 475-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.09.2010 № 243-ФЗ)","article_title":"Статья 284. Налоговые ставки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6a7ec3b432108a6cfefdd4e87879e4695d33caabe7ca2458c420f508c188fdb"},{"code_id":"NK_RF_2","article_number":"284.1","version_date":"2000-07-31","article_text":"1. Организации, осуществляющие образовательную и (или) медицинскую деятельность в соответствии с законодательством Российской Федерации, вправе применять налоговую ставку 0 процентов при соблюдении условий, установленных настоящей статьей.\n\nДля целей настоящей статьи образовательной и медицинской деятельностью признается деятельность, включенная в Перечень видов образовательной и медицинской деятельности, установленный Правительством Российской Федерации. При этом деятельность, связанная с санаторно-курортным лечением, не относится к медицинской деятельности.\n\n1) если организация имеет лицензию (лицензии) на осуществление образовательной и (или) медицинской деятельности, предоставленную (предоставленные) в соответствии с законодательством Российской Федерации; (В редакции Федерального закона от 29.11.2021 № 383-ФЗ)\n\n2) если доходы организации за налоговый период от осуществления образовательной деятельности, присмотра и ухода за детьми и (или) медицинской деятельности, а также от выполнения научных исследований и (или) опытно-конструкторских разработок, учитываемые при определении налоговой базы в соответствии с настоящей главой, составляют не менее 90 процентов ее доходов, учитываемых при определении налоговой базы в соответствии с настоящей главой, либо если организация за налоговый период не имеет доходов, учитываемых при определении налоговой базы в соответствии с настоящей главой; (В редакции Федерального закона от 02.05.2015 № 110-ФЗ)\n\n3) если в штате организации, осуществляющей медицинскую деятельность, численность медицинского персонала, имеющего сертификат специалиста или свидетельство об аккредитации специалиста, в общей численности работников непрерывно в течение налогового периода составляет не менее 50 процентов; (В редакции Федерального закона от 18.03.2020 № 62-ФЗ)\n\n4) если в штате организации непрерывно в течение налогового периода числятся не менее 15 работников;\n\n5) если организация не совершает в налоговом периоде операций с векселями и производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nОрганизация вправе уточнить сведения, указанные в абзаце первом настоящего пункта, и представить их в налоговый орган вместе со сведениями, указанными в пункте 6 настоящей статьи, по окончании первого налогового периода, в течение которого она применяет налоговую ставку 0 процентов в соответствии с настоящей статьей.\n\nо доле доходов организации от осуществления образовательной деятельности, присмотра и ухода за детьми и (или) медицинской\n\nдеятельности, а также от выполнения научных исследований и (или) опытно-конструкторских разработок, учитываемых при определении налоговой базы в соответствии с настоящей главой, в общей сумме доходов организации, учитываемых при определении налоговой базы в соответствии с настоящей главой; (В редакции Федерального закона от 02.05.2015 № 110-ФЗ)\n\nо численности работников в штате организации.\n\nОрганизации, осуществляющие медицинскую деятельность, дополнительно представляют сведения о численности медицинского персонала, имеющего сертификат специалиста или свидетельство об аккредитации специалиста, в штате организации. (В редакции Федерального закона от 18.03.2020 № 62-ФЗ)\n\nПри непредставлении в установленные сроки сведений, указанных в настоящем пункте, в налоговый орган по месту нахождения налогоплательщика с начала налогового периода, данные за который не были представлены в установленном порядке, применяется налоговая ставка, установленная пунктом 1 статьи 284 настоящего Кодекса. При этом сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с налогоплательщика соответствующих сумм пеней, начисляемых со дня, следующего за установленным статьей 287 настоящего Кодекса днем уплаты налога (авансового платежа по налогу).\n\nФорма представления сведений, указанных в настоящем пункте, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 395-ФЗ)","article_title":"Статья 284.1. Особенности применения налоговой ставки 0 процентов организациями, осуществляющими образовательную и (или) медицинскую деятельность","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"db5ad266a3858e6273f299bb44c42948b4fb2f367979ba836e54a78d00ecd944"},{"code_id":"NK_RF_2","article_number":"284.10","version_date":"2000-07-31","article_text":"1. Международная холдинговая компания применяет пониженные налоговые ставки по налогу, предусмотренные для международных холдинговых компаний настоящей главой, при выполнении условий, установленных настоящей статьей.\n\n2. Международная холдинговая компания применяет пониженные налоговые ставки по налогу, предусмотренные для международных холдинговых компаний настоящей главой, если в течение всего отчетного (налогового) периода по налогу на прибыль организаций она удовлетворяет следующим условиям:\n\n1) хотя бы одно контролирующее лицо международной холдинговой компании признается налоговым резидентом Российской Федерации и (или) является гражданином Российской Федерации; (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n11) на 1-е число налогового периода совокупная доля прямого и (или) косвенного участия контролирующих лиц международной холдинговой компании составляет не менее 75 процентов от совокупной доли прямого и (или) косвенного участия контролирующих лиц организации, являвшихся таковыми на 1 марта 2022 года и (или) ставших таковыми в период с 1 марта 2022 года до 1-го числа соответствующего отчетного (налогового) периода в результате наследования лиц, являвшихся контролирующими лицами этой компании по состоянию на 1 марта 2022 года. При этом совокупная доля прямого и (или) косвенного участия контролирующих лиц международной холдинговой компании, являвшихся таковыми по состоянию на 1 марта 2022 года, должна быть не менее 75 процентов уставного капитала этой компании по состоянию на указанную дату. Положения настоящего подпункта не применяются к международной холдинговой компании, являющейся международной компанией; (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n2) доля доходов, указанных в пункте 4 статьи 3091 настоящего Кодекса, за отчетный (налоговый) период составляет более 90 процентов в общей сумме доходов международной холдинговой компании, учитываемых при определении налоговой базы по налогу. При исчислении показателя, предусмотренного настоящим подпунктом, не учитываются доходы, указанные в подпункте 63 пункта 1 и пункте 4 статьи 251 настоящего Кодекса; (В редакции  Федерального закона от 26.03.2022 № 66-ФЗ)\n\n3) доля расходов, понесенных международной холдинговой компанией на приобретение товаров (работ, услуг) на территории Российской Федерации, за отчетный (налоговый) период составляет более 70 процентов от общей суммы понесенных ею расходов на приобретение товаров (работ, услуг). В целях настоящего подпункта расходами на приобретение товаров (работ, услуг) на территории Российской Федерации признаются расходы, связанные с приобретением международной холдинговой компанией товаров, работ (услуг), местом реализации которых в соответствии с главой 21 настоящего Кодекса является Российская Федерация. При исчислении показателя, предусмотренного настоящим подпунктом, не учитываются расходы, указанные в пункте 4828 статьи 270 настоящего Кодекса; (В редакции  Федерального закона от 26.03.2022 № 66-ФЗ)\n\n4) управление международной холдинговой компанией и принятие управленческих решений осуществляются на территории Российской Федерации. (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\nДля целей настоящей статьи управление международной холдинговой компанией и принятие управленческих решений осуществляются на территории Российской Федерации, если одновременно выполняются следующие условия: (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nработа единоличного или коллегиального исполнительного органа, общего собрания акционеров (участников) или совета директоров (наблюдательного совета) международной холдинговой компании осуществляется только на территории Российской Федерации; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nпри принятии указанных решений единоличным исполнительным органом международной холдинговой компании лицо, осуществляющее функции единоличного исполнительного органа международной холдинговой компании, фактически присутствует на территории Российской Федерации; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nво время каждого заседания коллегиального исполнительного органа, общего собрания акционеров (участников) или совета директоров (наблюдательного совета) международной холдинговой компании в Российской Федерации лица, входящие в состав соответствующих органов управления международной холдинговой компании, в количестве, достаточном для принятия управленческих решений, фактически присутствуют на территории Российской Федерации; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nпротоколы заседаний коллегиального исполнительного органа, общего собрания акционеров (участников) или совета директоров (наблюдательного совета) международной холдинговой компании и другие документы международной холдинговой компании соответствуют законодательству Российской Федерации; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n5) в штате международной холдинговой компании непрерывно числятся не менее 15 работников, которые на условиях полного рабочего времени осуществляют функции, относящиеся хотя бы к одному из видов деятельности международной холдинговой компании, направленной на получение доходов, указанных в пункте 4 статьи 3091 настоящего Кодекса, в частности таких, как оказание консультационных, юридических, бухгалтерских, аудиторских, инжиниринговых, рекламных, маркетинговых услуг, услуг по обработке информации, проведение научно-исследовательских и опытно-конструкторских работ, и которые являются налоговыми резидентами Российской Федерации, постоянно (временно) проживающими на территории субъекта Российской Федерации, в котором расположено место нахождения международной холдинговой компании;\n\n6) международной холдинговой компании принадлежит на праве собственности или на ином законном основании офисное помещение общей площадью не менее 50 квадратных метров, находящееся в пределах территории специального административного района, в котором расположено место нахождения международной холдинговой компании;\n\n7) (Подпункт утратил силу - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n8) международная компания (организация, указанная в пункте 11 статьи 242 настоящего Кодекса) отвечает условиям ее признания международной холдинговой компанией в соответствии со статьей 242 настоящего Кодекса.\n\n3. В целях подтверждения выполнения условий, установленных пунктом 2 настоящей статьи, международная холдинговая компания одновременно с налоговой декларацией по налогу на прибыль организаций за налоговый период представляет в налоговый орган документы, подтверждающие соблюдение указанных условий.\n\nВ качестве документального подтверждения соблюдения условий, установленных подпунктами 1 - 5 пункта 2 настоящей статьи, международная холдинговая компания представляет следующие сведения: (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nо контролирующих лицах международной холдинговой компании; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nо доле доходов, указанных в пункте 4 статьи 3091 настоящего Кодекса, в общей сумме доходов международной холдинговой компании, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nо доле расходов, понесенных международной холдинговой компанией на территории Российской Федерации, от общей суммы понесенных ею расходов; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nо подтверждении фактов проведения заседаний коллегиального исполнительного органа или совета директоров (наблюдательного совета) только на территории Российской Федерации, фактического присутствия на территории Российской Федерации лиц, входящих в состав соответствующих органов управления международной холдинговой компании, в количестве, достаточном для принятия управленческих решений, и соответствия оформляемых документов законодательству Российской Федерации; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nо численности работников в штате международной холдинговой компании, об осуществляемых ими функциях и о месте их постоянного (временного) проживания. (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nФорма (формат) представления сведений, указанных в абзацах третьем - седьмом настоящего пункта, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n4. Международная холдинговая компания, применяющая пониженные налоговые ставки по налогу, предусмотренные для международных холдинговых компаний настоящей главой, в течение трех лет с 1 января года начала применения таких налоговых ставок обязана осуществить инвестиции в объеме не менее 300 миллионов рублей (включая налог на добавленную стоимость) на территории того субъекта Российской Федерации, в котором расположено место нахождения международной холдинговой компании, в одной или нескольких из следующих форм:\n\nв форме капитальных вложений в строительство объекта (объектов) социально-культурной, транспортной, энергетической, жилищно-коммунальной и (или) инженерной инфраструктур с последующей передачей такого объекта (объектов) в собственность указанных субъекта Российской Федерации либо муниципального образования, расположенного на территории указанного субъекта Российской Федерации, в течение шести месяцев со дня истечения срока, установленного абзацем первым настоящего пункта;\n\nв форме капитальных вложений в реконструкцию и (или) техническое перевооружение объекта (объектов) социально-культурной, транспортной, энергетической, жилищно-коммунальной и (или) инженерной инфраструктур, принадлежащего указанным субъекту Российской Федерации либо муниципальному образованию, расположенному на территории указанного субъекта Российской Федерации, с последующей передачей результатов работ и (или) имущества в собственность соответствующих субъекта Российской Федерации либо муниципального образования в течение шести месяцев со дня истечения срока, установленного абзацем первым настоящего пункта;\n\nв форме передачи в собственность указанных субъекта Российской Федерации либо муниципального образования, расположенного на территории указанного субъекта Российской Федерации, машин (за исключением легковых автомобилей), оборудования, инструмента, инвентаря для использования на объекте (объектах) социально-культурной, транспортной, энергетической, жилищно-коммунальной и (или) инженерной инфраструктур, принадлежащем соответствующим субъекту Российской Федерации либо муниципальному образованию;\n\nв форме пожертвований, назначением использования которых международной холдинговой компанией опре\n\nделены строительство, реконструкция и (или) перевооружение объектов социально-культурной, транспортной, энергетической, жилищно-коммунальной и (или) инженерной инфраструктур и получателем которых является указанные субъект Российской Федерации, муниципальное образование, расположенное на территории указанного субъекта Российской Федерации, либо организация, учрежденная указанным субъектом Российской Федерации в целях поддержки реализации инвестиционных проектов, предусматривающих строительство, реконструкцию и (или) перевооружение объектов социально-культурной, транспортной, энергетической, жилищно-коммунальной и (или) инженерной инфраструктур. В целях настоящего пункта высший исполнительный орган субъекта Российской Федерации определяет перечень указанных в настоящем абзаце организаций, а также порядок публикации этими организациями информации о реализуемых при их поддержке инвестиционных проектах и результатах использования полученных от международных холдинговых компаний пожертвований.\n\nВыбранная в соответствии с настоящим пунктом форма (формы), в которой международная холдинговая компания планирует исполнить обязанность, установленную настоящим пунктом, согласовывается с высшим исполнительным органом субъекта Российской Федерации. В целях настоящего абзаца международная холдинговая компания обращается в высший исполнительный орган субъекта Российской Федерации с заявлением о начале исполнения обязанности, установленной настоящим пунктом, с указанием формы (форм) ее исполнения. Такое заявление подается международной холдинговой компанией не позднее шести месяцев со дня начала течения срока, установленного абзацем первым настоящего пункта, а в случае применения международной холдинговой компанией, являющейся международной компанией, пониженных налоговых ставок по налогу, предусмотренных для международных холдинговых компаний настоящей главой, начиная с первого налогового (отчетного) периода не позднее шести месяцев с даты ее регистрации в качестве международной компании. В срок не позднее одного месяца со дня получения такого заявления высший исполнительный орган субъекта Российской Федерации принимает решение о согласовании формы (форм) исполнения международной холдинговой компанией обязанности, установленной настоящим пунктом, либо сообщает о невозможности согласования данной формы (форм) с указанием причин.\n\nНе позднее трех месяцев со дня истечения срока, установленного абзацем первым настоящего пункта, а в случаях, указанных в абзацах втором и третьем настоящего пункта, не позднее трех месяцев со дня истечения сроков, установленных указанными абзацами настоящего пункта, международная холдинговая компания обращается в высший исполнительный орган субъекта Российской Федерации с заявлением о подтверждении факта исполнения ею обязанности, предусмотренной настоящим пунктом, по форме, установленной высшим исполнительным органом субъекта Российской Федерации.\n\nВ срок не позднее трех месяцев со дня получения указанного в абзаце седьмом настоящего пункта заявления высший исполнительный орган субъекта Российской Федерации принимает решение о признании обязанности международной холдинговой компании, предусмотренной настоящим пунктом, исполненной (неисполненной) (далее в настоящей статье - решение об исполнении (неисполнении) обязанности). Порядок и условия принятия решения об исполнении (неисполнении) обязанности устанавливаются высшим исполнительным органом субъекта Российской Федерации. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nВ течение трех рабочих дней со дня принятия решения об исполнении (неисполнении) обязанности высший исполнительный орган субъекта Российской Федерации информирует о принятом решении об исполнении (неисполнении) обязанности налоговый орган по месту нахождения международной холдинговой компании. Форма (формат) и порядок направления указанной информации утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПо согласованию с высшим исполнительным органом субъекта Российской Федерации срок, установленный абзацем первым настоящего пункта, может быть продлен на один год. До истечения срока, установленного абзацем первым настоящего пункта, международная холдинговая компания может обратиться в высший исполнительный орган субъекта Российской Федерации с заявлением о продлении срока осуществления инвестиций по форме, установленной высшим исполнительным органом субъекта Российской Федерации. В срок не позднее одного месяца со дня получения такого заявления высший исполнительный орган субъекта Российской Федерации принимает решение о продлении срока осуществления инвестиций либо сообщает о невозможности продления срока осуществления инвестиций с указанием причин. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n5. В случае несоблюдения международной холдинговой компанией хотя бы одного из условий, установленных пунктом 2 настоящей статьи, либо неисполнения международной холдинговой компанией обязанности, предусмотренной пунктом 4 настоящей статьи, сумма налога, не уплаченная в результате неправомерного применения ею пониженных налоговых ставок, подлежит уплате в бюджет с уплатой соответствующих пеней.\n\n(Дополнение статьей - Федеральный закон от 25.02.2022 № 18-ФЗ)","article_title":"Статья 284.10. Условия применения международными холдинговыми компаниями пониженных налоговых ставок","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bf8c0a31759589da2cd56ba1382e696c756920c46ca402dc557e2a570060bd8"},{"code_id":"NK_RF_2","article_number":"284.11","version_date":"2000-07-31","article_text":"1. Международная холдинговая компания и налогоплательщики, получающие доход от такой международной холдинговой компании, либо налоговые агенты, выплачивающие доход международной холдинговой компании или выплачивающие доход, источником которого является международная холдинговая компания, несут солидарную ответственность по исполнению обязанности по уплате налога, исчисленного в соответствии с настоящей главой в отношении такого дохода.\n\n2. В целях настоящего Кодекса устанавливается, что в качестве лица, исполняющего обязанности по исчислению и уплате налога в отношении доходов, источником которых является международная холдинговая компания, либо в отношении доходов, выплаченных международной холдинговой компании налоговым агентом, в случае несоблюдения международной холдинговой компанией хотя бы одного из условий, установленных пунктом 2 статьи 28410 настоящего Кодекса, и (или) неисполнения международной холдинговой компанией обязанности, предусмотренной пунктом 4 статьи 28410 настоящего Кодекса, в сроки, указанные настоящим Кодексом, признается соответствующая международная холдинговая компания.\n\nУказанная международная холдинговая компания имеет все права и исполняет обязанности налогоплательщика, предусмотренные настоящим Кодексом, в отношении уплаты суммы налога по доходам, источником которых является такая компания, и по доходам, выплаченным такой компании налоговым агентом.\n\n3. При полном и своевременном исполнении международной холдинговой компанией обязанности по уплате налога в отношении доходов, источником которых является такая компания, либо в отношении доходов, выплаченных международной холдинговой компании налоговым агентом, обязанность по уплате налога налогоплательщиком, получившим такие доходы, либо налоговым агентом, выплатившим такие доходы, считается исполненной.\n\n(Дополнение статьей - Федеральный закон от 26.03.2022 № 66-ФЗ)","article_title":"Статья 284.11. Особенности исполнения обязанностей налогоплательщика международной холдинговой компанией и лицами, получающими или выплачивающими доход, источником которого является международная холдинговая компания (лицами, выплачивающими доход международной холдинговой компании)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b9d0cafd9c360d8872e1dc639140412eda2a4b0e51a6a5403fe42ad3d381cf91"},{"code_id":"NK_RF_2","article_number":"284.12","version_date":"2000-07-31","article_text":"1. Личные фонды применяют налоговую ставку в размере 15 процентов, установленную пунктом 118 статьи 284 настоящего Кодекса, при выполнении условия, установленного настоящей статьей.\n\n2. Личный фонд применяет налоговую ставку в размере 15 процентов при условии, что за отчетный (налоговый) период в общей сумме доходов личного фонда, учитываемых при определении налоговой базы по налогу (за исключением доходов в виде положительной курсовой разницы), более 90 процентов в совокупности составляют следующие доходы:\n\n1) дивиденды;\n\n2) доходы, получаемые в результате распределения прибыли или имущества организаций, иных лиц или их объединений, в том числе при их ликвидации;\n\n3) процентный доход от долговых обязательств любого вида, включая облигации с правом на участие в прибыли и конвертируемые облигации;\n\n4) доходы от реализации акций (долей) и (или) уступки прав в иностранной организации, не являющейся юридическим лицом по иностранному праву;\n\n5) доходы по операциям с производными финансовыми инструментами;\n\n6) доходы от реализации (в том числе погашения) инвестиционных паев паевых инвестиционных фондов;\n\n7) доходы от реализации недвижимого имущества;\n\n8) доходы от сдачи в аренду недвижимого имущества, за исключением следующих доходов:\n\nот предоставления в аренду или субаренду морских судов, судов смешанного (река - море) плавания или воздушных судов и (или) транспортных средств;\n\nот предоставления в аренду или субаренду подземных хранилищ газа и трубопроводов, используемых для транспортировки углеводородов.\n\n3. Личный фонд одновременно с налоговой декларацией по налогу на прибыль организаций за отчетный (налоговый) период представляет в налоговый орган расчет доли доходов, указанных в пункте 2 настоящей статьи.\n\nФорма (формат) представления расчета доли доходов, указанного в настоящем пункте, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n4. В случае, если по итогам налогового периода налогоплательщик не выполняет условие, установленное пунктом 2 настоящей статьи, сумма налога за такой налоговый период подлежит исчислению с применением налоговой ставки, установленной пунктом 1 статьи 284 настоящего Кодекса, и уплате в бюджет в установленном порядке с уплатой соответствующих сумм пеней, начисляемых со дня, следующего за установленным статьей 287 настоящего Кодекса днем уплаты налога (авансового платежа по налогу).\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 284.12. Условие и порядок применения налоговой ставки в размере 15 процентов личными фондами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5174543abd9867f8c4593742d80ce98664d90ac20f9f024c80c5656eabf8c8c9"},{"code_id":"NK_RF_2","article_number":"284.2","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nЕсли акции российских организаций на дату их реализации или иного выбытия (в том числе погашения) относятся к ценным бумагам, обращающимся на организованном рынке ценных бумаг, и на эту же дату являются акциями высокотехнологичного (инновационного) сектора экономики, то налоговая ставка 0 процентов, предусмотренная пунктом 41 статьи 284 настоящего Кодекса, применяется независимо от состава активов этих российских организаций.\n\nЕсли акции организации на дату их реализации относятся к ценным бумагам, обращающимся на организованном рынке ценных бумаг, и в налоговом периоде количество реализованных налогоплательщиком акций не превышает 1 процента общего количества акций этой организации, то налоговая ставка 0 процентов, предусмотренная пунктом 41 статьи 284 настоящего Кодекса, применяется независимо от состава активов этой организации. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nв отношении акций (долей участия в уставном капитале) указанных организаций, полученных налогоплательщиком-правопреемником в результате реорганизации, - с даты приобретения таких акций (долей) реорганизованной организацией (реорганизованными организациями);\n\nв отношении акций (долей участия в уставном капитале) указанных организаций, созданных в результате реорганизации в форме преобразования, выделения или разделения, - с даты приобретения налогоплательщиком акций (долей участия в уставном капитале) реорганизованной организации.\n\nПри этом положения настоящего пункта не применяются, если в ходе мероприятий налогового контроля будет установлено, что основной целью реорганизации является применение налоговой ставки, установленной пунктом 1 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n1) непрерывный срок владения иностранной холдинговой компанией неизменной долей акций (долей в уставном капитале) экономически значимой организации до дня получения налогоплательщиком акций (долей в уставном капитале) экономически значимой организации;\n\n2) непрерывный срок владения налогоплательщиком неизменной долей акций (долей в уставном капитале) иностранной холдинговой компании до дня получения налогоплательщиком акций (долей в уставном капитале) экономически значимой организации. Срок, указанный в настоящем подпункте, не применяется в отношении налогоплательщика при отсутствии владения им акциями (долями в уставном капитале) иностранной холдинговой компании;\n\n3) наименьший из непрерывных сроков владения структурой без образования юридического лица либо номинальным владельцем, действующими в интересах налогоплательщика, неизменной долей акций (долей в уставном капитале) иностранной холдинговой компании до дня получения налогоплательщиком акций (долей в уставном капитале) экономически значимой организации. Срок, указанный в настоящем подпункте, не применяется в отношении налогоплательщика при отсутствии владения структурой без образования юридического лица и номинальным владельцем, действующими в интересах налогоплательщика, акциями (долями в уставном капитале) иностранной холдинговой компании;\n\n4) наименьший из непрерывных сроков владения неизменной долей косвенного участия соответствующей последовательности косвенного участия налогоплательщика в уставном капитале иностранной холдинговой компании до дня получения налогоплательщиком акций (долей в уставном капитале) экономически значимой организации. Срок, указанный в настоящем подпункте, не применяется в отношении налогоплательщика при отсутствии у него указанного косвенного участия в уставном капитале иностранной холдинговой компании;\n\n5) наименьший из непрерывных сроков владения структурой без образования юридического лица или номинальным владельцем, действующими в интересах налогоплательщика, неизменной долей косвенного участия соответствующей последовательности косвенного участия в уставном капитале иностранной холдинговой компании до дня получения налогоплательщиком акций (долей в уставном капитале) экономически значимой организации. Срок, указанный в настоящем подпункте, не применяется в отношении налогоплательщика при отсутствии владения структурой без образования юридического лица и номинальным владельцем, действующими в интересах налогоплательщика, указанным косвенным участием в уставном капитале иностранной холдинговой компании.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\nПоложения настоящего пункта применяются налогоплательщиком при условии, если на момент реализации или иного выбытия (в том числе погашения) указанных в абзаце первом настоящего пункта акций (долей участия в уставном капитале) российских организаций физическое лицо, указанное в абзаце первом настоящего пункта, непрерывно является единственным акционером (участником) налогоплательщика с момента внесения таких акций (долей участия в уставном капитале) в уставный капитал налогоплательщика.\n\n(Дополнение пунктом - Федеральный закон от 29.05.2024 № 121-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 395-ФЗ)","article_title":"Статья 284.2. Особенности применения налоговой ставки 0 процентов к налоговой базе, определяемой по операциям с акциями (долями участия в уставном капитале) российских организаций и (или) иностранных организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1104decbbc4e05135f93a9cab16b7cc06634f4f66d4a1af229f8e2d0a3e5b575"},{"code_id":"NK_RF_2","article_number":"2842.1","version_date":"2000-07-31","article_text":"1. Налоговая ставка 0 процентов, предусмотренная абзацем вторым пункта 41 статьи 284 настоящего Кодекса, применяется к налоговой базе, определяемой по доходам от операций по реализации или иного выбытия (в том числе погашения) акций, облигаций российских организаций, инвестиционных паев, при условии, что на дату их реализации или иного выбытия (в том числе погашения) они непрерывно принадлежат налогоплательщику на праве собственности или ином вещном праве более одного года и в отношении указанных акций, облигаций, инвестиционных паев соблюдается одно из следующих условий:\n\n1) акции, облигации российских организаций, инвестиционные паи относятся к ценным бумагам, обращающимся на организованном рынке ценных бумаг, и в течение всего срока владения налогоплательщиком такими ценными бумагами являются ценными бумагами высокотехнологичного (инновационного) сектора экономики;\n\n2) акции, облигации российских организаций, инвестиционные паи на дату их приобретения налогоплательщиком относятся к ценным бумагам, не обращающимся на организованном рынке ценных бумаг, и на дату их реализации указанным налогоплательщиком или иного выбытия (в том числе погашения) у указанного налогоплательщика относятся к ценным бумагам, обращающимся на организованном рынке ценных бумаг и являющимся ценными бумагами высокотехнологичного (инновационного) сектора экономики.\n\n2. Порядок отнесения акций российских организаций, обращающихся на организованном рынке ценных бумаг, к ценным бумагам высокотехнологичного (инновационного) сектора экономики определяется в соответствии с пунктом 3 статьи 2842 настоящего Кодекса.\n\nПорядок отнесения облигаций российских организаций и инвестиционных паев, обращающихся на организованном рынке ценных бумаг, к ценным бумагам высокотехнологичного (инновационного) сектора экономики устанавливается Правительством Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 396-ФЗ)","article_title":"Статья 2842.1. Особенности применения налоговой ставки 0 процентов к налоговой базе, определяемой по операциям с акциями, облигациями российских организаций, инвестиционными паями, являющимися ценными бумагами высокотехнологичного (инновационного) сектора экономики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b5b40d8551a05a2573922c41dd813b93b44fcd59d2500eb47cdda1d5f33b4dc"},{"code_id":"NK_RF_2","article_number":"284.3","version_date":"2000-07-31","article_text":"1. Налогоплательщик - участник регионального инвестиционного проекта, указанный в подпункте 1 пункта 1 статьи 259 настоящего Кодекса (далее также в настоящей статье - участник), применяет налоговые ставки в размерах, предусмотренных настоящей статьей:\n\nко всей налоговой базе, определяемой в соответствии с настоящей главой, в случае, если доходы от реализации товаров, произведенных в рамках реализации инвестиционного проекта, в отношении которого установлен статус регионального инвестиционного проекта, составляют не менее 90 процентов всех доходов, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой (без учета доходов в виде положительной курсовой разницы, предусмотренных пунктом 11 части второй статьи 250 настоящего Кодекса, и доходов в виде субсидий, признаваемых в порядке, установленном пунктом 41 статьи 271 настоящего Кодекса, при безвозмездной передаче в государственную и (или) муниципальную собственность имущества (имущественных прав); (В редакции Федерального закона от 15.10.2020 № 335-ФЗ)\n\nк налоговой базе от деятельности, осуществляемой в рамках реализации инвестиционного проекта, который имеет статус регионального инвестиционного проекта, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) от деятельности, осуществляемой в рамках реализации указанного инвестиционного проекта, и доходов (расходов), полученных (понесенных) при осуществлении иной деятельности.\n\nПри этом выбранный способ определения налоговой базы должен быть закреплен в учетной политике и не подлежит изменению в течение срока действия статуса участника регио\n\nнального инвестиционного проекта.\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n1) в течение десяти налоговых периодов начиная с налогового периода, в котором в соответствии с данными налогового учета была получена первая прибыль от реализации товаров, произведенных в результате реализации регионального инвестиционного проекта, если иное не предусмотрено настоящей статьей. Налоговая ставка в соответствии с настоящим подпунктом применяется участниками региональных инвестиционных проектов, удовлетворяющих требованию, установленному подпунктом 1 пункта 1 статьи 258 настоящего Кодекса;\n\n2) в течение периода применения пониженной налоговой ставки налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, в соответствии с подпунктом 2 пункта 3 настоящей статьи. Налоговая ставка в соответствии с настоящим подпунктом применяется участниками, для которых законами субъектов Российской Федерации установлена пониженная налоговая ставка налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, в соответствии с подпунктом 2 пункта 3 настоящей статьи;\n\n3) (Подпункт утратил силу - Федеральный закон от 02.08.2019 № 269-ФЗ)\n\n1) для участников региональных инвестиционных проектов, удовлетворяющих требованию, установленному подпунктом 1 пункта 1 статьи 258 настоящего Кодекса, законами субъектов Российской Федерации может быть установлена пониженная налоговая ставка налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, в размере, не превышающем 10 процентов в течение пяти налоговых периодов начиная с налогового периода, в котором в соответствии с данными налогового учета была получена первая прибыль от реализации товаров, произведенных в результате реализации регионального инвестиционного проекта, и в размере не менее 10 процентов в течение следующих пяти налоговых периодов;\n\n2) размер налоговой ставки налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, законами субъектов Российской Федерации для участников может быть понижен до 10 процентов начиная с налогового периода, в котором в соответствии с данными налогового учета была получена первая прибыль от реализации товаров, произведенных в результате реализации регионального инвестиционного проекта, и заканчивая отчетным (налоговым) периодом, в котором разница между суммой налога, рассчитанной исходя из ставки налога в размере 25 процентов (20 процентов - для налоговых периодов до 2024 года включительно), и суммой налога, исчисленного с применением пониженных налоговых ставок налога, установленных законами субъектов Российской Федерации в соответствии с настоящим подпунктом и пунктом 15 статьи 284 настоящего Кодекса, определенная нарастающим итогом за указанные отчетные (налоговые) периоды, составила величину, равную объему осуществленных в целях реализации инвестиционного проекта капитальных вложений, определяемому в соответствии с пунктом 8 настоящей статьи. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nПри этом законами субъектов Российской Федерации срок применения пониженной налоговой ставки для всех или отдельных категорий участников может быть сокращен по сравнению со сроком применения пониженной налоговой ставки, установленным настоящим подпунктом;\n\n3) (Подпункт утратил силу - Федеральный закон от 02.08.2019 № 269-ФЗ)\n\nВ случае, если налогоплательщик - участник регионального инвестиционного проекта применил положения, предусмотренные пунктом 61 статьи 3423 настоящего Кодекса, последним налоговым периодом применения налоговой ставки, предусмотренной пунктом 15 статьи 284 настоящего Кодекса, и пониженных налоговых ставок, установленных законами субъектов Российской Федерации в соответствии с пунктом 3 настоящей статьи, будет являться налоговый период, предшествующий календарному году, в котором в соответствии с пунктом 61 статьи 3423 настоящего Кодекса коэффициент КТД принимается равным 1.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nне превышающий трех лет со дня включения организации в реестр участников региональных инвестиционных проектов, либо за период с 1 января 2016 года до 1 января 2019 года по выбору налогоплательщика, при условии, что инвестиционной декларацией предусмотрено осуществление капитальных вложений в объеме от 50 миллионов до 500 миллионов рублей;\n\nне превышающий пяти лет со дня включения организации в реестр участников региональных инвестиционных проектов, либо за период с 1 января 2016 года до 1 января 2021 года по выбору налогоплательщика, при условии, что инвестиционной декларацией предусмотрено осуществление капитальных вложений в объеме не менее 500 миллионов рублей.\n\nПри определении объема капитальных вложений в целях настоящего пункта не учитываются затраты на приобретение амортизируемого имущества, ранее учитываемого в составе объектов амортизируемого имущества.\n\nПоложения настоящего пункта не применяются участниками региональных инвестиционных проектов, удовлетворяющих требованию, установленному подпунктом 1 пункта 1 статьи 258 настоящего Кодекса, и включенных в реестр участников региональных инвестиционных проектов до 1 января 2019 года. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 267-ФЗ) (В редакции Федерального закона от 23.05.2016 № 144-ФЗ)","article_title":"Статья 284.3. Особенности применения налоговой ставки к налоговой базе, определяемой налогоплательщиками - участниками региональных инвестиционных проектов, включенными в реестр участников региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43b47187183959330cf2a4b6a1343b923e2aba203248a12d0b28ee9a21120e0c"},{"code_id":"NK_RF_2","article_number":"284.3-1","version_date":"2000-07-31","article_text":"1. Налогоплательщик - участник регионального инвестиционного проекта, указанный в подпункте 2 пункта 1 статьи 259 настоящего Кодекса (далее также в настоящей статье - участник), применяет налоговые ставки в размерах, предусмотренных настоящей статьей:\n\nко всей налоговой базе, определяемой в соответствии с настоящей главой, в случае, если доходы от реализации товаров, произведенных в рамках реализации инвестиционного проекта, в отношении которого установлен статус регионального инвестиционного проекта, составляют не менее 90 процентов всех доходов, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой (без учета доходов в виде положительной курсовой разницы, предусмотренных пунктом 11 части второй статьи 250 настоящего Кодекса, и доходов в виде субсидий, признаваемых в порядке, установленном пунктом 41 статьи 271 настоящего Кодекса, при безвозмездной передаче в государственную и (или) муниципальную собственность имущества (имущественных прав); (В редакции Федерального закона от 15.10.2020 № 335-ФЗ)\n\nк налоговой базе от деятельности, осуществляемой в рамках реализации инвестиционного проекта, который имеет статус регионального инвестиционного проекта, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) от деятельности, осуществляемой в рамках реализации указанного инвестиционного проекта, и доходов (расходов), полученных (понесенных) при осуществлении иной деятельности.\n\nПри этом выбранный способ определения налоговой базы должен быть закреплен в учетной политике и не подлежит изменению в течение срока действия статуса участника регионального инвестиционного проекта.\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n1) в соответствии с данными налогового учета признана прибыль от реализации товаров, произведенных в результате реализации регионального инвестиционного проекта;\n\n2) налогоплательщиком - участником регионального инвестиционного проекта выполнено требование к минимальному объему капитальных вложений, установленное подпунктом 41 пункта 1 статьи 258 настоящего Кодекса;\n\n3) налогоплательщик - участник регионального инвестиционного проекта обратился в налоговый орган с заявлением о применении налоговой льготы, указанным в пункте 1 статьи 2512-1 настоящего Кодекса.\n\nВ случае, если налогоплательщик - участник регионального инвестиционного проекта применил положения, предусмотренные пунктом 4 статьи 3423-1 настоящего Кодекса, то последним налоговым периодом применения налоговой ставки, предусмотренной пунктом 15-1 статьи 284 настоящего Кодекса, и пониженных налоговых ставок, установленных законами субъектов Российской Федерации в соответствии с пунктом 3 настоящей статьи, будет являться налоговый период, предшествующий календарному году, в котором в соответствии с пунктом 4 статьи 3423-1 настоящего Кодекса коэффициент Ктд принимается равным 1.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 23.05.2016 № 144-ФЗ)","article_title":"Статья 284.3-1. Особенности применения налоговой ставки к налоговой базе, определяемой налогоплательщиками - участниками региональных инвестиционных проектов, для которых не требуется включение в реестр участников региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce76a479ec4990d26c8c0f6045d962e228fa6f6734f0b09bad8adc9d0a15f331"},{"code_id":"NK_RF_2","article_number":"284.4","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 14.07.2022 № 334-ФЗ)\n\n1) государственная регистрация юридического лица осуществлена соответственно на территории опережающего развития, на территории свободного порта Владивосток, в Арктической зоне Российской Федерации; (В редакции  Федерального закона от 14.07.2022 № 334-ФЗ)\n\n2) организация не имеет в своем составе обособленных подразделений, расположенных за пределами соответственно территории опережающего развития (за исключением обособленных подразделений, расположенных на других территориях опережающего развития), территории свободного порта Владивосток, Арктической зоны Российской Федерации; (В редакции  федеральных законов от 23.11.2020 № 374-ФЗ, от 14.07.2022 № 334-ФЗ)\n\n3) организация не применяет специальных налоговых режимов, предусмотренных настоящим Кодексом;\n\n4) организация не является участником консолидированной группы налогоплательщиков (данное требование не распространяется на резидентов Арктической зоны Российской Федерации);\n\n5) организация не является некоммерческой организацией, банком, страховой организацией (страховщиком), негосударственным пенсионным фондом, профессиональным участником рынка ценных бумаг, клиринговой организацией;\n\n6) организация не является резидентом особой экономической зоны любого типа;\n\n7) организация не является участником региональных инвестиционных проектов;\n\n8) для организаций - резидентов Арктической зоны Российской Федерации - организация не осуществляет деятельность по добыче полезных ископаемых, производству сжиженного природного газа, переработке углеводородного сырья в товары, являющиеся продукцией нефтехимии.\n\n1) доходы от деятельности, осуществляемой при исполнении одного из соглашений об осуществлении деятельности соответственно на территории опережающего развития, на территории свободного порта Владивосток либо соглашения об осуществлении инвестиционной деятельности в Арктической зоне Российской Федерации (далее в настоящей статье - соглашение об осуществлении деятельности), составляют не менее 90 процентов всех доходов, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой, без учета доходов в виде положительной курсовой разницы, предусмотренных пунктом 11 части второй статьи 250 настоящего Кодекса, либо в совокупности за три налоговых периода, предшествующих текущему налоговому периоду, доходы от деятельности, осуществляемой при исполнении одного из соглашени\n\nй об осуществлении деятельности, составляют не менее 90 процентов суммы всех доходов, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой, без учета доходов в виде положительной курсовой разницы, предусмотренных пунктом 11 части второй статьи 250 настоящего Кодекса; (В редакции  федеральных законов от 23.11.2020 № 374-ФЗ, от 14.07.2022 № 334-ФЗ)\n\n2) налогоплательщиком ведется раздельный учет доходов, полученных от деятельности, осуществляемой при исполнении соглашения об осуществлении деятельности, и доходов, полученных при осуществлении иной деятельности, в течение всего периода действия соглашения об осуществлении деятельности.\n\n1) налогоплательщиком ведется раздельный учет доходов (расходов), полученных (понесенных) от деятельности, осуществляемой при исполнении каждого из соглашений об осуществлении деятельности, и доходов (расходов), полученных (понесенных) при осуществлении иной деятельности, в течение всего периода действия такого соглашения; (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n2) налогоплательщиком до налогового периода, в котором в соответствии с данными налогового учета была получена первая прибыль от деятельности, осуществляемой при исполнении соглашения об осуществлении деятельности, в учетной политике для целей налогообложения установлен порядок применения налоговых ставок, предусмотренных пунктом 18 статьи 284 настоящего Кодекса, в отношении прибыли, полученной от деятельности, осуществляемой при исполнении соглашения об осуществлении деятельности, в течение всего периода действия такого соглашения.\n\nНалогоплательщик-резидент применяет налоговую ставку, предусмотренную абзацем первым пункта 18 статьи 284 настоящего Кодекса, при условии установления субъектами Российской Федерации в отношении прибыли, полученной от деятельности, осуществляемой налогоплательщиком при исполнении соглашения об осуществлении деятельности, пониженных ставок налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, по месту нахождения налогоплательщика, а также по месту нахождения каждого из его обособленных подразделений.\n\nВ целях настоящей статьи под первой прибылью от деятельности, осуществляемой при исполнении соглашения об осуществлении деятельности, понимается положительная разница между доходами и расходами, исчисленными нарастающим итогом за период с даты включения налогоплательщика в реестр резидентов территории опережающего развития, в реестр резидентов свободного порта Владивосток либо в реестр резидентов Арктической зоны Российской Федерации до окончания налогового периода, в котором данная разница становится положительной. Разница между указанными доходами и расходами определяется на последний день каждого налогового периода, пока данная разница не станет положительной. Для исчисления этой разницы учитываются доходы и расходы, которые признаются с даты включения налогоплательщика в соответствующий реестр и определяются в соответствии с настоящей главой в рамках деятельности, осуществляемой при исполнении соглашения об осуществлении деятельности, без учета доходов и расходов в виде курсовых разниц, предусмотренных пунктом 11 части второй статьи 250 и подпунктом 5 пункта 1 статьи 265 настоящего Кодекса. (В редакции  Федерального закона от 14.07.2022 № 334-ФЗ)\n\nВ случае нарушения налогоплательщиком-резидентом в течение налогового периода условий, установленных пунктом 1 настоящей статьи, налогоплательщик считается утратившим право на применение налоговых ставок, предусмотренных пунктом 18 статьи 284 настоящего Кодекса, с налогового периода, предшествующего налоговому периоду, в котором им допущено указанное нарушение. При этом сумма налога, не уплаченная в связи с применением пониженных налоговых ставок, предусмотренных пунктом 18 статьи 284 настоящего Кодекса, подлежит исчислению и уплате в бюджет. Исчисление суммы неуплаченного налога производится начиная с налогового периода, предшествующего налоговому периоду, в котором допущено нарушение условий, установленных пунктом 1 настоящей статьи.\n\n(Дополнение статьей - Федеральный закон от 29.11.2014 № 380-ФЗ) (В редакции Федерального закона от 13.07.2020 № 195-ФЗ)","article_title":"Статья 284.4. Особенности применения налоговой ставки к налоговой базе, определяемой налогоплательщиками, получившими статус резидента территории опережающего развития в соответствии с Федеральным законом \"О территориях опережающего развития в Российской Федерации\", статус резидента свободного порта Владивосток в соответствии с Федеральным законом \"О свободном порте Владивосток\" либо статус резидента Арктической зоны Российской Федерации в соответствии с Федеральным законом \"О государственной поддержке предпринимательской деятельности в Арктической зоне Российской Федерации\"","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"99b64ee10a4dffa8780a519aec3f15033c544c7ac7ca30cc4eb42f3fc6ba4431"},{"code_id":"NK_RF_2","article_number":"284.5","version_date":"2000-07-31","article_text":"1. Организации, осуществляющие социальное обслуживание граждан, вправе применять налоговую ставку 0 процентов при соблюдении условий, установленных настоящей статьей.\n\nДля целей настоящей статьи деятельностью по осуществлению социального обслуживания граждан признается деятельность по предоставлению гражданам социальных услуг, включенных в перечень социальных услуг по видам социальных услуг для применения налоговой ставки 0 процентов организациями, осуществляющими социальное обслуживание граждан, утверждаемый Правительством Российской Федерации.\n\n2. Налоговая ставка 0 процентов в соответствии с настоящей статьей применяется организациями, осуществляющими социальное обслуживание граждан, ко всей налоговой базе, определяемой такими налогоплательщиками (за исключением налоговой базы, налоговые ставки по которой установлены пунктами 3 и 4 статьи 284 настоящего Кодекса), в течение всего налогового периода.\n\n3. Организации, осуществляющие социальное обслуживание граждан, вправе применять налоговую ставку 0 процентов, если в течение налогового периода применения установленной пунктом 19 статьи 284 настоящего Кодекса налоговой ставки они удовлетворяют следующим условиям:\n\n1) организация включена в реестр поставщиков социальных услуг субъекта Российской Федерации;\n\n2) доходы организации за налоговый период от деятельности по предоставлению гражданам социальных услуг, учитываемые при определении налоговой базы в соответствии с настоящей главой, составляют не менее 90 процентов ее доходов, учитываемых при определении налоговой базы в соответствии с настоящей главой, либо организация, осуществляющая социальное обслуживание граждан, за налоговый период не имеет доходов, учитываемых при определении налоговой базы в соответствии с настоящей главой;\n\n3) в штате организации непрерывно в течение налогового периода числятся не менее 15 работников;\n\n4) организация не совершает в налоговом периоде операций с векселями и производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n4. При несоблюдении организацией, осуществляющей социальное обслуживание граждан, перешедшей на применение налоговой ставки 0 процентов в соответствии с настоящей статьей, хотя бы одного из условий, установленных пунктом 3 настоящей статьи, с начала налогового периода, в котором имело место несоблюдение указанных условий, применяется налоговая ставка, установленная пунктом 1 статьи 284 настоящего Кодекса. При этом сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой соответствующих сумм пеней, начисляемых со дня, следующего за установленным статьей 287 настоящего Кодекса днем уплаты налога (авансового платежа по налогу).\n\n5. Организации, осуществляющие социальное обслуживание граждан, изъявившие желание применять налоговую ставку 0 процентов в соответствии с настоящей статьей, не позднее чем за один месяц до начала налогового периода, начиная с которого применяется налоговая ставка 0 процентов, подают в налоговый орган по месту своего нахождения заявление в письменной форме, а также сведения, подтверждающие выполнение условий, установленных пунктом 3 настоящей статьи.\n\n6. Организации, осуществляющие социальное обслуживание граждан, применяющие налоговую ставку 0 процентов в соответствии с настоящей статьей, по окончании каждого налогового периода, в течение которого они применяют налоговую ставку 0 процентов, в сроки, установленные настоящей главой для представления налоговой декларации, представляют в налоговый орган по месту своего нахождения:\n\n1) выписку из реестра поставщиков социальных услуг;\n\n2) сведения о доле доходов организации от осуществления деятельности по предоставлению социальных услуг гражданам, учитываемых при определении налоговой базы в соответствии с настоящей главой, в общей сумме доходов организации, учитываемых при определении налоговой базы в соответствии с настоящей главой;\n\n3) сведения о численности работников в штате организации.\n\n7. При непредставлении в установленные сроки сведений, указанных в пункте 6 настоящей статьи, в налоговый орган по месту нахождения налогоплательщика с начала налогового периода, данные за который не были представлены в установленном порядке, применяется налоговая ставка, установленная пунктом 1 статьи 284 настоящего Кодекса. При этом сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с налогоплательщика соответствующих сумм пеней, начисляемых со дня, следующего за установленным статьей 287 настоящего Кодекса днем уплаты налога (авансового платежа по налогу). Форма представления сведений, указанных в пункте 6 настоящей статьи, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n8. Организации, осуществляющие социальное обслуживание граждан, применяющие налоговую ставку 0 процентов в соответствии с настоящей статьей, вправе перейти на применение налоговой ставки, установленной пунктом 1 статьи 284 настоящего Кодекса, направив в налоговый орган по месту своего нахождения соответствующее заявление в письменной форме. При этом, если указанный переход начинается не с начала нового налогового периода, сумма налога за соответствующий налоговый период подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой сумм пеней, начисляемых со дня, следующего за установленным статьей 287 настоящего Кодекса днем уплаты налога (авансового платежа по налогу).\n\n9. Организации, осуществляющие социальное обслуживание граждан, применявшие налоговую ставку 0 процентов в соответствии с настоящей статьей и перешедшие на применение налоговой ставки, установленной пунктом 1 статьи 284 настоящего Кодекса, в том числе в связи с несоблюдением условий, установленных пунктом 3 настоящей статьи, не вправе повторно перейти на применение налоговой ставки 0 процентов.\n\n(Дополнение статьей - Федеральный закон от 29.12.2014 № 464-ФЗ)","article_title":"Статья 284.5. Особенности применения налоговой ставки 0 процентов организациями, осуществляющими социальное обслуживание граждан","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b83996a176122a937e54380f2dbfed6ae5cbb84f795be508b9de050afb6b052e"},{"code_id":"NK_RF_2","article_number":"284.6","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 18.07.2017 № 168-ФЗ) (Утратила силу - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 284.6. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7d3a5e2aef03baa42df37fe158ec6b286ca10d9ac5af0ec5d35ce2dc06895615"},{"code_id":"NK_RF_2","article_number":"284.7","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n1. Налоговая ставка 0 процентов, установленная пунктом 41 статьи 284 настоящего Кодекса, применяется к налоговой базе, определяемой по доходам от реализации или иного выбытия (в том числе погашения) акций (долей участия в уставном капитале) российских или иностранных организаций, полученным международной холдинговой компанией, при одновременном соблюдении в отношении указанных акций (долей участия) следующих условий:\n\n1) акции (доли участия в уставном капитале) российской или иностранной организации на дату их реализации или иного выбытия (в том числе погашения) непрерывно принадлежат международной холдинговой компании, признаваемой таковой в соответствии со статьей 242 настоящего Кодекса, на праве собственности или на ином вещном праве в течение не менее 365 календарных дней и составляют не менее чем 15-процентный вклад (долю) в уставном (складочном) капитале (фонде) такой организации;\n\n2) акции (доли участия) составляют уставный капитал организаций, не более 50 процентов активов которых на последнюю отчетную дату, предшествующую дате реализации или иного выбытия (в том числе погашения), прямо или косвенно состоят из недвижимого имущества, находящегося на территории Российской Федерации;\n\n3) акции (доли участия в уставном капитале) российской или иностранной организации не были внесены (переданы) в уставный капитал международной холдинговой компании, признаваемой таковой в соответствии со статьей 242 настоящего Кодекса в течение 365 календарных дней до или после даты регистрации такой компании в качестве международной компании (до или после даты подачи организацией заявления, указанного в пункте 11 статьи 242 настоящего Кодекса), а также приобретены такой компанией в результате реорганизации в течение 365 календарных дней до или после даты регистрации такой компании в качестве международной компании (до или после даты подачи организацией заявления, указанного в пункте 11 статьи 242 настоящего Кодекса), за исключением случаев, если реорганизация произведена в связи с ограничениями, установленными законодательством иностранного государства (территории) в отношении изменения налоговыми резидентами такого государства (территории) своего личного закона посредством регистрации в Российской Федерации в порядке редомициляции. (В редакции  федеральных законов от 25.12.2018 № 490-ФЗ, от 25.02.2022 № 18-ФЗ, от 26.03.2022 № 66-ФЗ)\n\nв отношении акций (долей участия в уставном капитале) указанных организаций, полученных международной холдинговой компанией - правопреемником в результате реорганизации в форме присоединения или слияния с другой международной холдинговой компанией, с даты приобретения таких акций (долей участия в уставном капитале) реорганизованной международной холдинговой компанией (реорганизованными международными холдинговыми компаниями);\n\nв отношении акций (долей участия в уставном капитале) указанных организаций, созданных в результате реорганизации в форме преобразования, выделения или разделения, с даты приобретения международной холдинговой компанией акций (долей участия в уставном капитале) реорганизованной организации.\n\nПоложения настоящего пункта не применяются, если в ходе мероприятий налогового контроля будет установлено, что основной целью реорганизации является применение налоговой ставки, установленной пунктом 41 статьи 284 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 03.08.2018 № 294-ФЗ)","article_title":"Статья 284.7. Особенности применения международными холдинговыми компаниями налоговой ставки 0 процентов к налоговой базе, определяемой по операциям с акциями (долями участия в уставном капитале) организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1033342e698041e080817bf2e353efbd1b2e2ecf2f695cfc1f0fe6594c2efe94"},{"code_id":"NK_RF_2","article_number":"284.8","version_date":"2000-07-31","article_text":"я налоговой ставки 0 процентов музеями, театрами, библиотеками, учредителями которых являются субъекты Российской Федерации или муниципальные образования, домами и дворцами культуры, клубами, учредителями которых являются муниципальные образования (за исключением указанных домов и дворцов культуры, клубов, располагающихся в городах, районных центрах (кроме административных центров муниципальных районов, являющихся единственным населенным пунктом муниципального района), поселках городского типа)\n\n(Наименование в редакции Федерального закона от 26.03.2022 № 68-ФЗ)\n\nДля целей настоящей статьи деятельностью музеев, театров, библиотек, учредителями которых являются субъекты Российской Федерации или муниципальные образования, домов и дворцов культуры, клубов, учредителями которых являются муниципальные образования (за исключением указанных домов и дворцов культуры, клубов, располагающихся в городах, районных центрах (кроме административных центров муниципальных районов, являющихся единственным населенным пунктом муниципального района), поселках городского типа), признается деятельность, включенная в Перечень видов культурной деятельности, установленный Правительством Российской Федерации. (В редакции Федерального закона от 26.03.2022 № 68-ФЗ)\n\nФорма представления сведений, указанных в настоящем пункте, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 210-ФЗ)","article_title":"Статья 284.8. Особенности применени","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c98911839049c8c3b46ef423f7e7e41101f3f17dcbf6e0a43d3b4ccfb5b2bf8b"},{"code_id":"NK_RF_2","article_number":"284.9","version_date":"2000-07-31","article_text":"1. Налогоплательщики - участники специальных инвестиционных контрактов применяют налоговые ставки в размерах, предусмотренных настоящей статьей:\n\nко всей налоговой базе, определяемой в соответствии с настоящей главой, в случае, если доходы от реализации товаров, произведенных в рамках реализации инвестиционного проекта, в отношении которого заключен специальный инвестиционный контракт, составляют не менее 90 процентов всех доходов, учитываемых при определении налоговой базы по налогу в соответствии с настоящей главой (без учета доходов в виде положительной курсовой разницы, предусмотренных пунктом 11 части второй статьи 250 настоящего Кодекса);\n\nк налоговой базе от деятельности, осуществляемой в рамках реализации инвестиционного проекта, в отношении которого заключен специальный инвестиционный контракт, при условии ведения раздельного учета доходов (расходов), полученных (понесенных) от деятельности, осуществляемой в рамках реализации указанного инвестиционного проекта, и доходов (расходов), полученных (понесенных) при осуществлении иной деятельности.\n\nПри этом выбранный способ определения налоговой базы должен быть закреплен в учетной политике и не подлежит изменению в течение срока, на который заключен специальный инвестиционный контракт.\n\n2. Налоговая ставка, предусмотренная пунктом 114 статьи 284 настоящего Кодекса, применяется в течение периода применения пониженной налоговой ставки налога, подлежащего зачислению в бюджет субъекта Российской Федерации, установленной в соответствии с пунктом 3 настоящей статьи.\n\n3. Размер налоговой ставки налога, подлежащего зачислению в бюджеты субъектов Российской Федерации, законами субъектов Российской Федерации для налогоплательщиков - участников специальных инвестиционных контрактов может быть понижен до 0 процентов.\n\nНалоговая ставка, предусмотренная настоящим пунктом, действует начиная с налогового периода, в котором в соответствии с данными налогового учета была получена первая прибыль от реализации товаров, произведенных в рамках реализации инвестиционного проекта, в отношении которого заключен специальный инвестиционный контракт, до отчетного (налогового) периода, в котором организация утратит статус налогоплательщика - участника специального инвестиционного контракта, но не позднее отчетного (налогового) периода, в котором совокупный объем расходов и недополученных доходов бюджетов бюджетной системы Российской Федерации, образующихся в связи с применением мер стимулирования деятельности в сфере промышленности в отношении инвестиционного проекта, реализуемого в соответствии со специальным инвестиционным контрактом, превысил 50 процентов объема капитальных вложений в инвестиционный проект, размер которых предусмотрен специальным инвестиционным контрактом.\n\nПорядок расчета совокупного объема расходов и недополученных доходов бюджетов бюджетной системы Российской Федерации, образующихся в связи с применением мер стимулирования деятельности в сфере промышленности в отношении инвестиционного проекта, реализуемого в соответствии со специальным инвестиционным контрактом, устанавливается методикой, указанной в пункте 8 части 2 статьи 183 Федерального закона от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\".\n\n4. В случае расторжения специального инвестиционного контракта в связи с неисполнением (ненадлежащим исполнением) организацией обязательств по специальному инвестиционному контракту по решению суда или в случае отказа Российской Федерации, субъекта Российской Федерации, муниципального образования от исполнения специального инвестиционного контракта в соответствии с частью 9 статьи 186 Федерального закона от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\" сумма налога, не уплаченная в связи с применением пониженных налоговых ставок, предусмотренных настоящей статьей, подлежит исчислению и уплате в бюджет. Исчисление налога производится без учета применения пониженных налоговых ставок, предусмотренных настоящей статьей, за весь период реализации инвестиционного проекта, в отношении которого заключен специальный инвестиционный контракт. Исчисленная сумма налога подлежит уплате по истечении отчетного или налогового периода, в котором специальный инвестиционный контракт был расторгнут, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период в соответствии с абзацами первым и вторым пункта 1 статьи 287 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 02.08.2019 № 269-ФЗ)","article_title":"Статья 284.9. Особенности применения налоговой ставки к налоговой базе, определяемой организациями, имеющими статус налогоплательщика - участника специального инвестиционного контракта","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"754493bd160984837cae73f5359fb59d7b1bf70dc0dd1a09440d9c54dea1a5ef"},{"code_id":"NK_RF_2","article_number":"285","version_date":"2000-07-31","article_text":"1. Налоговым периодом по налогу признается календарный год.\n\n2. Отчетными периодами по налогу признаются первый квартал, полугодие и девять месяцев календарного года.\n\nОтчетными периодами для налогоплательщиков, исчисляющих ежемесячные авансовые платежи исходя из фактически полученной прибыли, признаются месяц, два месяца, три месяца и так далее до окончания календарного года. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)","article_title":"Статья 285. Налоговый период. Отчетный период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a332f67951a52744d7ab6f5ad318c534669ca054734ad87991be3fdc60562f83"},{"code_id":"NK_RF_2","article_number":"286","version_date":"2000-07-31","article_text":"1. Налог определяется как соответствующая налоговой ставке процентная доля налоговой базы, определяемой в соответствии со статьей 274 настоящего Кодекса.\n\nПо итогам каждого отчетного (налогового) периода, если иное не предусмотрено настоящей статьей, налогоплательщики исчисляют сумму авансового платежа (налога), исходя из ставки налога и прибыли, подлежащей налогообложению, рассчитанной нарастающим итогом с начала налогового периода до окончания отчетного (налогового) периода. В течение отчетного периода налогоплательщики исчисляют сумму ежемесячного авансового платежа в порядке, установленном настоящей статьей.  (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nСумма ежемесячного авансового платежа, подлежащего уплате в первом квартале текущего налогового периода, принимается равной сумме ежемесячного авансового платежа, подлежащего уплате налогоплательщиком в последнем квартале предыдущего налогового периода. Сумма ежемесячного авансового платежа, подлежащего уплате во втором квартале текущего налогового периода, принимается равной одной трети суммы авансового платежа, исчисленного за первый отчетный период текущего года. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nСумма ежемесячного авансового платежа, подлежащего уплате в третьем квартале текущего налогового периода, принимается равной одной трети разницы между суммой авансового платежа, рассчитанной по итогам полугодия, и суммой авансового платежа, рассчитанной по итогам первого квартала. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nСумма ежемесячного авансового платежа, подлежащего уплате в четвертом квартале текущего налогового периода, принимается равной одной трети разницы между суммой авансового платежа, рассчитанной по итогам девяти месяцев, и суммой авансового платежа, рассчитанной по итогам полугодия. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nЕсли рассчитанная таким образом сумма ежемесячного авансового платежа отрицательна или равна нулю, указанные платежи в соответствующем квартале не осуществляются. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nНалогоплательщики имеют право перейти на исчисление ежемесячных авансовых платежей исходя из фактически полученной прибыли, подлежащей исчислению. В этом случае исчисление сумм авансовых платежей производится налогоплательщиками исходя из ставки налога и фактически полученной прибыли, рассчитываемой нарастающим итогом с начала налогового периода до окончания соответствующего месяца.\n\nПри этом сумма авансовых платежей (сумма налога), подлежащая уплате в бюджет, определяется с учетом ранее начисленных сумм авансовых платежей. Если иное не предусмотрено пунктами 21, 22 и 23 настоящей статьи, налогоплательщик вправе перейти на уплату ежемесячных авансовых платежей исходя из фактической прибыли, уведомив об этом налоговый орган не позднее 31 декабря года, предшествующего налоговому периоду, в котором происходит переход на эту систему уплаты авансовых платежей. При этом система уплаты авансовых платежей не может изменяться налогоплательщиком в течение налогового периода (за исключением случаев, указанных в пунктах 21, 22 и 23 настоящей статьи). Указанный в настоящем абзаце порядок применяется также и в случае перехода с уплаты ежемесячных авансовых платежей исходя из фактической прибыли на уплату ежемесячных авансовых платежей в течение отчетного периода. (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 24.11.2014 № 366-ФЗ, от 22.04.2020 № 121-ФЗ, от 26.03.2022 № 67-ФЗ, от 21.11.2022 № 443-ФЗ)\n\nВ консолидированной группе налогоплательщиков сумма авансового платежа по этой группе исчисляется и уплачивается ответственным участником в соответствии с правилами, установленными настоящей статьей. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nПри переходе налогоплательщика, исчислявшего ежемесячные авансовые платежи исходя из фактически полученной прибыли, на уплату ежемесячных авансовых платежей в течение отчетного периода сумма указанного ежемесячного платежа, подлежащего уплате в первом квартале налогового периода, принимается равной одной трети разницы между суммой авансового платежа, рассчитанной по итогам девяти месяцев, и суммой авансового платежа, рассчитанной по итогам полугодия предыдущего налогового периода. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\n21. Налогоплательщики, уплачивающие в налоговом периоде 2020 года ежемесячные авансовые платежи в течение отчетного (налогового) периода, вправе перейти до окончания налогового периода 2020 года на уплату ежемесячных авансовых платежей исходя из фактической прибыли. При этом указанные налогоплательщики вправе перейти на уплату ежемесячных авансовых платежей исходя из фактической прибыли начиная с отчетного периода четыре месяца, пять месяцев и так далее до окончания календарного года. Сумма авансовых платежей, подлежащих уплате в бюджет, определяется с учетом ранее начисленных сумм авансовых платежей.\n\nИзменение порядка исчисления авансовых платежей по налогу должно быть отражено в учетной политике организации. Чтобы воспользоваться предусмотренным настоящим пунктом правом, налогоплательщик обязан уведомить об этом налоговый орган по месту нахождения организации (по месту учета в качестве крупнейшего налогоплательщика) не позднее 20-го числа месяца, на который приходится окончание отчетного периода, начиная с которого он переходит на уплату ежемесячных авансовых платежей исходя из фактической прибыли. При переходе на уплату ежемесячных авансовых платежей исходя из фактической прибыли начиная с отчетного периода четыре месяца налогоплательщик обязан уведомить об этом налоговый орган не позднее 8 мая 2020 года.\n\n(Дополнение пунктом - Федеральный закон от 22.04.2020 № 121-ФЗ)\n\n22. Налогоплательщики, уплачивающие в налоговом периоде 2022 года ежемесячные авансовые платежи в течение отчетного (налогового) периода, вправе перейти до окончания налогового периода 2022 года на уплату ежемесячных авансовых платежей исходя из фактической прибыли. При этом указанные налогоплательщики вправе перейти на уплату ежемесячных авансовых платежей исходя из фактической прибыли начиная с отчетного периода три месяца, четыре месяца и так далее до окончания календарного года. Сумма авансовых платежей, подлежащих уплате в бюджет, определяется с учетом ранее начисленных сумм авансовых платежей.\n\nИзменение порядка исчисления авансовых платежей по налогу должно быть отражено в учетной политике организации. Чтобы воспользоваться правом, предусмотренным настоящим пунктом, налогоплательщик обязан уведомить об этом налоговый орган по месту нахождения организации (по месту учета в качестве крупнейшего налогоплательщика) не позднее 20-го числа месяца, на который приходится окончание отчетного периода, начиная с которого он переходит на уплату ежемесячных авансовых платежей исходя из фактической прибыли. При переходе на уплату ежемесячных авансовых платежей исходя из фактической прибыли начиная с отчетного периода три месяца налогоплательщик обязан уведомить об этом налоговый орган не позднее 15 апреля 2022 года.\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\n23. Организация, являвшаяся участником консолидированной группы налогоплательщиков, после прекращения действия этой группы в связи с окончанием с 1 января 2023 года срока действия договора о создании консолидированной группы налогоплательщиков признается налогоплательщиком, перешедшим начиная с налогового периода 2023 года на исчисление ежемесячных авансовых платежей исходя из фактически полученной прибыли, независимо от факта уведомления налогового органа о переходе такой организации на указанную систему уплаты авансовых платежей.\n\nНалогоплательщики, указанные в абзаце первом настоящего пункта, начиная с 1 апреля 2023 года и далее с 1-го числа любого последующего квартала 2023 года вправе перейти на уплату ежемесячных авансовых платежей при условии уведомления об этом налогового органа по месту нахождения организации (по месту учета в качестве крупнейшего налогоплательщика) не позднее 20-го числа месяца, начиная с которого указанные налогоплательщики переходят на уплату ежемесячных авансовых платежей.\n\nПри переходе налогоплательщика, указанного в абзаце первом настоящего пункта, на уплату ежемесячных авансовых п\n\nлатежей начиная с 1 апреля 2023 года сумма ежемесячного авансового платежа, подлежащего уплате во втором квартале 2023 года, принимается равной одной трети суммы авансового платежа, исчисленного за отчетный период три месяца 2023 года.\n\nПри переходе налогоплательщика, указанного в абзаце первом настоящего пункта, на уплату ежемесячных авансовых платежей начиная с 1 июля 2023 года сумма ежемесячного авансового платежа, подлежащего уплате в третьем квартале 2023 года, принимается равной одной трети разницы между суммой авансового платежа, рассчитанной по итогам отчетного периода шесть месяцев 2023 года, и суммой авансового платежа, исчисленной за отчетный период три месяца 2023 года.\n\nПри переходе налогоплательщика, указанного в абзаце первом настоящего пункта, на уплату ежемесячных авансовых платежей начиная с 1 октября 2023 года сумма ежемесячного авансового платежа, подлежащего уплате в четвертом квартале 2023 года, принимается равной одной трети разницы между суммой авансового платежа, рассчитанной по итогам отчетного периода девять месяцев 2023 года, и суммой авансового платежа, исчисленной за отчетный период шесть месяцев 2023 года.\n\nПри этом налогоплательщик, указанный в абзаце первом настоящего пункта, не позднее 28-го числа месяца, следующего за месяцем, на который приходится окончание последнего отчетного периода, по итогам которого исчисление сумм авансовых платежей производилось указанным налогоплательщиком исходя из ставки налога и фактически полученной прибыли, уплачивает сумму авансового платежа, исчисленную по итогам этого последнего отчетного периода.\n\n(Дополнение пунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\nТеатры, музеи, библиотеки, концертные организации, являющиеся бюджетными учреждениями, не исчисляют и не уплачивают авансовые платежи. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 215-ФЗ)\n\nНалоговый агент определяет сумму налога по каждой выплате (перечислению) денежных средств или иному получению дохода.\n\n1) если источником доходов налогоплательщика является российская организация, обязанность удержать налог из доходов налогоплательщика и перечислить его в бюджет возлагается на этот источник доходов.\n\nВ этом случае налог в виде авансовых платежей удерживается из доходов налогоплательщика при каждой выплате таких доходов;\n\n2) при реализации государственных и муниципальных ценных бумаг, при обращении которых предусмотрено признание доходом, полученным продавцом в виде процентов, сумм накопленного процентного дохода (накопленного купонного дохода), налогоплательщик - получатель дохода самостоятельно осуществляет исчисление и уплату налога с таких доходов. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПри реализации (выбытии) государственных и муниципальных ценных бумаг, при обращении которых не предусмотрено признание доходом, полученным продавцом в виде процентов, сумм накопленного процентного дохода (накопленного купонного дохода), налогоплательщик - получатель дохода самостоятельно осуществляет начисление и уплату налога с таких доходов, облагаемых по налоговой ставке, установленной пунктом 1 статьи 284 настоящего Кодекса, если иное не предусмотрено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\nИнформация о видах ценных бумаг, по которым применяется порядок, установленный настоящим пунктом, доводится до налогоплательщиков уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти.\n\nПоложения настоящего пункта не применяются в случае непредставления налогоплательщиком в отношении объекта осуществления предпринимательской деятельности, по которому уплачен торговый сбор, уведомления о постановке на учет в качестве плательщика торгового сбора.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)","article_title":"Статья 286. Порядок исчисления налога и авансовых платежей","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"589d65b8eea9a69cd66af8bdf9f2d9456c5be0663cade5e78b63696b69da6505"},{"code_id":"NK_RF_2","article_number":"286.1","version_date":"2000-07-31","article_text":"1) не более 90 процентов суммы расходов, составляющей первоначальную стоимость основного средства в соответствии с абзацем вторым пункта 1 статьи 257 настоящего Кодекса, за исключением расходов, предусмотренных подпунктом 21 настоящего пункта; (В редакции  федеральных законов от 26.07.2019 № 210-ФЗ, от 25.12.2023 № 629-ФЗ)\n\n2) не более 90 процентов суммы расходов, составляющей величину изменения первоначальной стоимости основного средства в случаях, указанных в пункте 2 статьи 257 настоящего Кодекса (за исключением частичной ликвидации основного средства), за исключением расходов, предусмотренных подпунктом 21 настоящего пункта; (В редакции  федеральных законов от 26.07.2019 № 210-ФЗ, от 25.12.2023 № 629-ФЗ)\n\n21) не более 25 процентов суммы расходов, составляющих первоначальную стоимость основного средства в соответствии с абзацем вторым пункта 1 статьи 257 настоящего Кодекса и (или) величину изменения первоначальной стоимости основного средства в случаях, указанных в пункте 2 статьи 257 настоящего Кодекса (за исключением частичной ликвидации основного средства), и осуществленных в рамках заключенного с уполномоченным исполнительным органом субъекта Российской Федерации соглашения о реализации инвестиционного проекта (далее в настоящей статье - инвестиционное соглашение), информация о котором включена в реестр инвестиционных проектов с государственной (муниципальной) поддержкой в форме инвестиционного налогового вычета (далее в настоящей статье - реестр инвестиционных проектов). Инвестиционное соглашение заключается в отношении инвестиционного проекта, включенного в реестр проектов технологического суверенитета и проектов структурной адаптации экономики Российской Федерации, или в отношении инвестиционного проекта, соответствующего критериям, устанавливаемым Правительством Российской Федерации. Форма, существенные условия, порядок заключения и расторжения инвестиционного соглашения, внесения в него изменений устанавливаются Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\n3) не более 100 процентов суммы расходов в виде пожертвований, перечисленных государственным и муниципальным учреждениям, осуществляющим деятельность в области культуры, а также перечисленных некоммерческим организациям (фондам) на формирование целевого капитала в целях поддержки указанных учреждений;\n\n4) не более 85 процентов суммы расходов в виде денежных средств, перечисленных по договорам финансирования деятельности по созданию на территории предоставившего инвестиционный налоговый вычет субъекта Российской Федерации или в прилегающей к нему акватории объектов инфраструктуры, которые в соответствии с законодательством Российской Федерации могут находиться исключительно в федеральной собственности (далее в настоящей статье - расходы на создание объектов инфраструктуры); (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n5) не более 80 процентов суммы расходов на создание объектов транспортной, коммунальной и социальной инфраструктур, в том числе расходы на их приобретение, сооружение, доведение до состояния, в котором они пригодны для использования, с учетом налога на добавленную стоимость и акцизов, не принимаемых к вычету в соответствии с положениями глав 21 и 22 настоящего Кодекса. При этом создание указанных объектов транспортной, коммунальной и социальной инфраструктур является обязательством, предусмотренным условиями договора о комплексном развитии территории, предусматривающего строительство многоквартирного дома (домов) или дома (домов) блокированной застройки, либо договора о комплексном освоении территории в целях строительства стандартного жилья, заключенного с налогоплательщиком до дня вступления в силу Федерального закона от 30 декабря 2020 года № 494-ФЗ \"О внесении изменений в Градостроительный кодекс Российской Федерации и отдельные законодательные акты Российской Федерации в целях обеспечения комплексного развития территорий\" в соответствии с положениями Градостроительного кодекса Российской Федерации; (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 210-ФЗ) (В редакции  федеральных законов от 02.07.2021 № 305-ФЗ, от 14.07.2022 № 323-ФЗ)\n\n6) не более 90 процентов суммы расходов на научные исследования и (или) опытно-конструкторские разработки, указанных в подпунктах 1 - 5 пункта 2 статьи 262 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n7) не более 100 процентов суммы расходов на оплату работ (услуг) по установке, тестированию, адаптации, модификации программ для ЭВМ и баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных, и (или) объектов основных средств, включенных в единый реестр российской радиоэлектронной продукции, не учитываемой при формировании первоначальной стоимости соответствующих нематериальных активов (при наличии исключительных прав) и объектов основных средств, а также суммы расходов на обучение работников, обслуживающих указанные программы для ЭВМ и базы данных и (или) объекты основных средств; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n8) не более 42,5 процента суммы расходов в виде имущества (в том числе денежных средств), переданного технологическим партнером и (или) его дочерними обществами, в которых доля его прямого и (или) косвенного участия, определенная в соответствии с положениями статьи 1052 настоящего Кодекса, составляет не менее 50 процентов (далее в настоящей статье - лица, передающие имущество в целях развития генетических технологий в Российской Федерации), в адрес некоммерческих организаций, указанных в подпункте 22 пункта 2 статьи 251 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n9) не более 100 процентов суммы расходов в виде стоимости имущества (включая денежные средства), безвозмездно переданного образовательным организациям, реализующим основные образовательные программы, имеющие государственную аккредитацию; (Дополнение подпунктом - Федеральный закон от 04.11.2022 № 430-ФЗ)\n\n10) не более 100 процентов суммы расходов в виде денежных средств, внесенных в качестве вклада в инвестиционное товарищество, деятельность в рамках которого направлена на осуществление венчурных и (или) прямых инвестиций в организации, имеющие статус малой технологической компании, полученный в соответствии с Федеральным законом от 4 августа 2023 года № 478-ФЗ \"О развитии технологических компаний в Российской Федерации\", при условии, что информация о таком инвестиционном товариществе включена в региональный реестр инвестиционных товариществ для осуществления венчурных и (или) прямых инвестиций в инновационные проекты и (или) инновационную деятельность (далее в настоящей статье - региональный реестр инвестиционных товариществ). Порядок формирования и ведения регионального реестра инвестиционных товариществ, в том числе основания для включения инвестиционных товариществ в региональный реестр инвестиционных товариществ и исключения инвестиционных товариществ из него, требования к договорам инвестиционных товариществ для целей включения в региональный реестр инвестиционных товариществ (в том числе категории (виды) инновационных проектов и инновационной деятельности, в отношении которых заключен договор инвестиционного товарищества), устанавливается нормативным правовым актом соответствующего субъекта Российской Федерации. (Дополнение подпунктом - Федеральный закон от 30.09.2024 № 337-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.11.2018 № 426-ФЗ)\n\nПредельная величина инвестиционного налогового вычета определяется в размере, равном разнице между расчетной суммой налога, подлежащей зачислению в бюджет соответствующего субъекта Российской Федерации за налоговый (отчетный) период, определенной налогоплательщиком без учета положений настоящей статьи, и расчетной суммой налога, подлежащей зачислению в бюджет соответствующего субъекта Российской Федерации за налоговый (отчетный) период, определенной без учета положений настоящей статьи, при условии применения ставки налога в размере, составляющем 5 процентов, если иной размер ставки не определен решением субъекта Российской Федерации. При этом расчетная сумма налога, подлежащая зачислению в бюджет соответствующего субъекта Российской Федерации за налоговый (отчетный) период, определяется также без учета расходов, указанных в пункте 9 статьи 258 настоящего Кодекса, и соответствующей суммы амортизации в отношении объектов основных средств, указанных в абзаце первом пункта 4 настоящей статьи. (В редакции Федерального закона от 26.07.2019 № 210-ФЗ)\n\nПредельная величина инвестиционного налогового вычета в части расходов, указанных в подпункте 21 пункта 2 настоящей статьи, определяется в порядке, предусмотренном абзацем вторым настоящего пункта. При этом размер ставки налога, применяемой для расчета предельной величины инвестиционного налогового вычета, определенный решением субъекта Российской Федерации, не может быть более 10 процентов. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.11.2018 № 426-ФЗ)\n\nх документов лица, передающие имущество в целях развития генетических технологий в Российской Федерации, понесшие указанные расходы, в части указанных расходов инвестиционный налоговый вычет не применяют. (Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nЕсли налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в части расходов, указанных в подпункте 6 пункта 2 настоящей статьи, он также вправе уменьшить сумму налога (авансового платежа), подлежащую зачислению в федеральный бюджет, на величину, составляющую 10 процентов суммы указанных расходов. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nПри этом сумма налога (авансового платежа), подлежащая зачислению в федеральный бюджет в текущем налоговом (отчетном) периоде, не может быть уменьшена на величину большую, чем расчетная сумма налога, исчисленная исходя из величины прибыли, приходящейся на соответствующее обособленное подразделение (соответствующие обособленные подразделения) и определяемой в соответствии с пунктом 2 статьи 288 настоящего Кодекса, и ставки налога, установленной абзацем вторым пункта 1 статьи 284 настоящего Кодекса, уменьшенной на 5 процентных пунктов. В целях настоящего абзаца под соответствующими обособленными подразделениями понимаются обособленные подразделения (в том числе организация), расположенные на территории субъекта Российской Федерации, законом которого установлено право на применение инвестиционного налогового вычета, которым воспользовался налогоплательщик. (В редакции  федеральных законов от 09.11.2020 № 368-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nУменьшение суммы налога, подлежащего зачислению в федеральный бюджет, на величину расходов, предусмотренных абзацем первым настоящего пункта, осуществляется в налоговом (отчетном) периоде, в котором введены в эксплуатацию объекты основных средств и (или) изменена их первоначальная стоимость, а на величину расходов, предусмотренных абзацем вторым настоящего пункта, - в налоговом (отчетном) периоде, в котором завершены научные исследования и (или) опытно-конструкторские разработки (отдельные этапы работ) либо подписан акт их сдачи-приемки. При этом такое уменьшение может быть осуществлено также в последующие налоговые (отчетные) периоды с учетом положения пункта 9 настоящей статьи. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nСумма налога (авансового платежа), подлежащая зачислению в федеральный бюджет, подлежит уменьшению на величину, составляющую 15 процентов суммы расходов на создание объектов инфраструктуры, при условии, что в отношении таких платежей налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в части расходов, указанных в подпункте 4 пункта 2 настоящей статьи.\n\nЕсли налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в части расходов, указанных в подпункте 8 пункта 2 настоящей статьи, он также вправе уменьшить сумму налога (авансового платежа), подлежащую зачислению в федеральный бюджет, на величину, составляющую 7,5 процента суммы указанных расходов. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nПри этом в результате такого уменьшения сумма налога (авансового платежа), подлежащая уплате налогоплательщиком в федеральный бюджет, не может быть меньше расчетной суммы налога за налоговый (отчетный) период, определенной налогоплательщиком без учета положений настоящей статьи, при условии применения ставки налога в размере 5 процентов. При этом расчетная сумма налога, подлежащая зачислению в федеральный бюджет за налоговый (отчетный) период, определяется также без учета расходов, указанных в пункте 9 статьи 258 настоящего Кодекса, и соответствующей суммы амортизации в отношении объектов основных средств, указанных в абзацах первом и втором пункта 4 настоящей статьи. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 26.07.2019 № 210-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 21 пункта 2 настоящей статьи, применяется к объектам основных средств, сведения о которых содержатся в реестре инвестиционных проектов и которые введены в эксплуатацию либо первоначальная стоимость которых изменена не позднее чем через пять лет с даты заключения инвестиционного соглашения, по месту нахождения организации, заключившей инвестиционное соглашение, и (или) по месту нахождения ее обособленных подразделений, к которым относятся указанные объекты. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\nПри этом инвестиционный налоговый вычет в виде расходов, указанных в подпунктах 1, 2 и 6 пункта 2 настоящей статьи, и инвестиционный налоговый вычет в виде расходов, указанных в подпункте 21 пункта 2 настоящей статьи, не могут применяться к одним и тем же объектам основных средств, а также к объектам основных средств и нематериальным активам, указанным в пункте 3 статьи 2862 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 629-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 3 пункта 2 настоящей статьи, применяется по месту нахождения организации и (или) по месту нахождения ее обособленных подразделений с учетом положений пункта 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 426-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов на создание объектов инфраструктуры применяется по месту нахождения организации в отношении объекта инфраструктуры, создаваемого на территории субъекта Российской Федерации, который предоставил право на применение вычета в отношении этого объекта, или в прилегающей к этому субъекту Российской Федерации акватории, при условии, что организация и создаваемый объект инфраструктуры находятся на территории одного субъекта Российской Федерации или в прилегающей к нему акватории. (Дополнение абзацем - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 5 пункта 2 настоящей статьи, применяется к объектам транспортной, коммунальной и   социальной инфраструктур по месту нахождения организации и (или) по месту нахождения ее обособленных подразделений, к которым относятся указанные объекты, с учетом положений пункта 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 6 пункта 2 настоящей статьи, применяется в отношении научных исследований и (или) опытно-конструкторских разработок по месту нахождения организации и (или) по месту нахождения ее обособленных подразделений с учетом положений пункта 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 7 пункта 2 настоящей статьи, применяется к программам для ЭВМ и базам данных и (или) объектам основных средств по месту нахождения организации и (или) по месту нахождения ее обособленных подразделений, которые осуществили соответствующие расходы, с учетом положений пункта 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 8 пункта 2 настоящей статьи, применяется по месту нахождения организации и (или) по месту нахождения ее обособленных подразделений с учетом положений пункта 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 9 пункта 2 настоящей статьи, применяется по месту нахождения организации и (или) по месту нахождения ее обособленных подразделений при условии, что организация (ее обособленные подразделения) и образовательная организация, которой безвозмездно передано имущество, находятся на территории того субъекта Российской Федерации, который предоставил право на применение указанного вычета, с учетом положений пункта 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 04.11.2022 № 430-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 10 пункта 2 настоящей статьи, применяется по месту нахождения организации и (или) по месту нахождения ее обособленных подразделений при условии, что организация и (или) ее обособленные подразделения находятся на территории того субъекта Российской Федерации, который предоставил право на применение указанного вычета, с учетом положений пункта 6 настоящей статьи. (Дополнение абзацем - Федеральный закон от 30.09.2024 № 337-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 3 пункта 2 настоящей статьи, применяется к налогу, исчисленному за налоговый (отчетный) период, в котором перечислены соответствующие пожертвования, а также за последующие налоговые (отчетные) периоды с учетом положений пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 426-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов на создание объектов инфраструктуры применяется к налогу, исчисленному за налоговый (отчетный) период, в котором перечислены денежные средства, формирующие указанные расходы. (Дополнение абзацем - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 5 пункта 2 настоящей статьи, применяется к налогу, исчисленному за налоговый (отчетный) период, в котором налогоплательщиком осуществлена безвозмездная передача в государственную или муниципальную собственность объектов транспортной, коммунальной и социальной инфраструктур, а также за последующие налоговые (отчетные) периоды с учетом положений пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 6 пункта 2 настоящей статьи, применяется к налогу, исчисленному за налоговый (отчетный) период, в котором завершены научные исследования и (или) опытно-конструкторские разработки (отдельные этапы работ) либо подписан акт их сдачи-приемки, и за последующие налоговые (отчетные) периоды с учетом положений пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 7 пункта 2 настоящей статьи, применяется к налогу, исчисленному за налоговый (отчетный) период, в котором налогоплательщику переданы результаты выполненных работ (оказаны услуги), направленные на обеспечение функционирования соответствующих программ для ЭВМ и баз данных и (или) объектов основных средств, а также за последующие налоговые (отчетные) периоды с учетом положений пункта 9 настоящей статьи.  (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 8 пункта 2 настоящей статьи, применяется к налогу (авансовому платежу), исчисленному за налоговый (отчетный) период, в котором произведены соответствующие расходы, а также за последующие налоговые (отчетные) периоды с учетом положений пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 9 пункта 2 настоящей статьи, применяется к налогу (авансовому платежу), исчисленному за налоговый (отчетный) период, в котором безвозмездно передано имущество, а также за последующие налоговые (отчетные) периоды, с учетом положений пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 04.11.2022 № 430-ФЗ)\n\nВ случае, если налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в виде расходов, указанных в подпункте 21 пункта 2 настоящей статьи, к налогу (авансовому платежу) с этого налогового (отчетного) периода не применяется инвестиционный налоговый вычет в виде расходов, указанных в других подпунктах пункта 2 настоящей статьи, до налогового периода (включительно), в котором налогоплательщик в последний раз воспользовался инвестиционным налоговым вычетом в виде расходов, указанных в подпункте 21 пункта 2 настоящей статьи, применительно к конкретному инвестиционному соглашению. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\nИнвестиционный налоговый вычет в виде расходов, указанных в подпункте 10 пункта 2 настоящей статьи, применяется к налогу (авансовому платежу), исчисленному за налоговый (отчетный) период, в котором перечислены денежные средства, формирующие указанные расходы, а также за последующие налоговые (отчетные) периоды, с учетом положений пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 30.09.2024 № 337-ФЗ)\n\n1) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпунктах 1 и 2 пункта 2 настоящей статьи, применительно к объектам основных средств, относящимся к организациям или обособленным подразделениям организаций, расположенным на территории этого субъекта Российской Федерации; (В редакции Федерального закона от 27.11.2018 № 426-ФЗ)\n\n2) предельные размеры расходов, указанных в подпунктах 1 и 2 пункта 2 настоящей статьи и учитываемых при определении размера инвестиционного налогового вычета текущего налогового (отчетного) периода, право на применение которого предоставляется в соответствии с подпунктом 1 настоящего пункта, а также размер ставки налога, применяемой для расчета предельной величины инвестиционного налогового вычета в соответствии с абзацем вторым пункта 21 настоящей статьи; (В редакции  федеральных законов от 09.11.2020 № 368-ФЗ, от 25.12.2023 № 629-ФЗ)\n\n3) категории налогоплательщиков, которым предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 1 настоящего пункта;\n\n4) категории объектов основных средств, в отношении которых налогоплательщикам предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 1 настоящего пункта;\n\n41) объекты основных средств в виде зданий, сооружений, передаточных устройств, относящихся к восьмой - десятой амортизационным группам, в отношении которых налогоплательщикам предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 1 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n42) минимальные сроки фактического использования объектов основных средств (категорий объектов основных средств), до истечения которых реализация или иное выбытие (за исключением ликвидации) объекта основных средств, в отношении которого налогоплательщик использовал право на применение инвестиционного налогового вычета, предусмотренного подпунктами 1 и 43 настоящего пункта, сопровождается восстановлением и уплатой в бюджет суммы налога, не уплаченной в связи с применением такого вычета в отношении этого объекта основных средств, с уплатой соответствующих сумм пеней; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 629-ФЗ)\n\n43) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпункте 21 пункта 2 настоящей статьи, применительно к объектам основных средств, сведения о которых содержатся в реестре инвестиционных проектов и которые относятся к организациям, заключившим инвестиционные соглашения, или обособленным подразделениям таких организаций, расположенным на территории этого субъекта Российской Федерации; (Дополнение подпунктом - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\n44) размер ставки налога, применяемой для расчета предельной величины инвестиционного налогового вычета в соответствии с абзацем третьим пункта 21 настоящей статьи в части расходов, указанных в подпункте 21 пункта 2 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\n5) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпункте 3 пункта 2 настоящей статьи, применительно к государственным, муниципальным учреждениям, осуществляющим деятельность в области культуры, и некоммерческим организациям (фондам), местом нахождения которых является территория этого субъекта Российской Федерации; (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 426-ФЗ)\n\n6) предельные суммы расходов в виде пожертвований, перечисленных государственным и муниципальным учреждениям, осуществляющим деятельность в области культуры, а также перечисленных некоммерческим организациям (фондам) на формирование целевого капитала в целях поддержки указанных учреждений, учитываемых при определении инвестиционного налогового вычета; (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 426-ФЗ)\n\n7) категории государственных, муниципальных учреждений, осуществляющих деятельность в области культуры, и некоммерческих организаций (фондов) - собственников целевого капитала, пожертвования которым учитываются при определении инвестиционного налогового вычета; (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 426-ФЗ)\n\n8) право на применение инвестиционного налогового вычета в отношении расходов на создание объектов инфраструктуры; (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n9) размеры инвестиционного налогового вычета, право на применение которого предоставляется в соответствии с подпунктом 8 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n10) виды объектов инфраструктуры, в отношении расходов на создание которых предоставляется право, предусмотренное подпунктом 8 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n11) право на применение инвестиционного налогового вычета в отношении расходов налогопла\n\nтельщика, указанных в подпункте 5 пункта 2 настоящей статьи, применительно к объектам транспортной, коммунальной и социальной инфраструктур, расположенным на территории этого субъекта Российской Федерации; (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\n12) предельный размер расходов на создание объектов транспортной, коммунальной и социальной инфраструктур, безвозмездно передаваемых в государственную или муниципальную собственность налогоплательщиком; (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\n13) категории налогоплательщиков, которым предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 11 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\n14) категории объектов транспортной, коммунальной и социальной инфраструктур, в отношении расходов на создание которых налогоплательщику предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 11 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\n15) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпункте 6 пункта 2 настоящей статьи, применительно к объектам амортизируемого имущества, амортизация по которым учитывается в составе указанных расходов, и (или) работникам, расходы на оплату труда которых учитываются в составе указанных расходов, относящимся к организации или ее обособленным подразделениям, расположенным на территории этого субъекта Российской Федерации; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n16) предельный размер расходов на научные исследования и (или) опытно-конструкторские разработки, учитываемых при определении инвестиционного налогового вычета; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n17) категории налогоплательщиков, которым предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 15 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n18) виды научных исследований и (или) опытно-конструкторских разработок, в отношении расходов на осуществление которых налогоплательщикам предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 15 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n19) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпункте 7 пункта 2 настоящей статьи, осуществленных на территории этого субъекта Российской Федерации; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n20) предельный размер расходов, указанных в подпункте 7 пункта 2 настоящей статьи, учитываемых при определении инвестиционного налогового вычета; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n21) категории налогоплательщиков, которым предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 19 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n22) категории объектов основных средств, включенных в единый реестр российской радиоэлектронной продукции, и (или) категории программ для ЭВМ и баз данных, включенных в единый реестр российских программ для электронных вычислительных машин и баз данных, в целях функционирования которых налогоплательщик несет расходы, указанные в подпункте 7 пункта 2 настоящей статьи, в отношении которых ему предоставляется (не предоставляется) право на применение инвестиционного налогового вычета, предусмотренное подпунктом 19 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n23) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпункте 8 пункта 2 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n24) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпункте 9 пункта 2 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 04.11.2022 № 430-ФЗ)\n\n25) предельные суммы расходов в виде стоимости имущества и (или) виды имущества, безвозмездно переданного образовательным организациям, указанным в подпункте 9 пункта 2 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 04.11.2022 № 430-ФЗ)\n\n26) перечень основных образовательных программ, реализуемых образовательными организациями, указанными в подпункте 9 пункта 2 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 04.11.2022 № 430-ФЗ)\n\n27) право на применение инвестиционного налогового вычета в отношении расходов налогоплательщика, указанных в подпункте 10 пункта 2 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 30.09.2024 № 337-ФЗ)\n\n28) предельный размер расходов, указанных в подпункте 10 пункта 2 настоящей статьи, учитываемых при определении инвестиционного налогового вычета. (Дополнение подпунктом - Федеральный закон от 30.09.2024 № 337-ФЗ)\n\nОбъекты основных средств не подлежат амортизации в части их первоначальной стоимости, сформированной за счет расходов, понесенных в случаях приобретения, создания, сооружения, достройки, дооборудования, реконструкции, модернизации, технического перевооружения, в отношении которых налогоплательщик использовал право на применение инвестиционного налогового вычета в соответствии с настоящей статьей. (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nРасходы на достройку, дооборудование, реконструкцию, модернизацию, техническое перевооружение объекта основных средств, в отношении которого налогоплательщик воспользовался правом на применение инвестиционного налогового вычета в соответствии с настоящей статьей, понесенные после окончания использования налогоплательщиком права на применение инвестиционного налогового вычета в отношении данного объекта, в том числе в связи с отменой соответствующего закона субъекта Российской Федерации, учитываются в общем порядке, установленном настоящей главой. (Дополнение абзацем - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nНалогоплательщик, использовавший право на применение инвестиционного налогового вычета в отношении научного исследования и (или) опытно-конструкторской разработки, указанных в абзаце седьмом пункта 4 настоящей статьи, не вправе учитывать при определении налоговой базы расходы на такие исследования и (или) разработки, а также применять в отношении их положения статьи 2672 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 629-ФЗ)\n\nОбъекты основных средств не подлежат амортизации в части их первоначальной стоимости, сформированной за счет расходов, понесенных в случаях приобретения, создания, сооружения, достройки, дооборудования, реконструкции, модернизации, технического перевооружения, которые указаны в отчете, предусмотренном в пункте 13 настоящей статьи. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nНалогоплательщик, использовавший право на применение инвестиционного налогового вычета в отношении суммы вклада по договору инвестиционного товарищества, указанного в подпункте 10 пункта 2 настоящей статьи, не вправе учитывать ее при определении прибыли (убытка) при выходе из инвестиционного товарищества либо прекращении договора инвестиционного товарищества в соответствии с пунктом 10 статьи 2782 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 30.09.2024 № 337-ФЗ)\n\nИспользование (отказ от использования) права на применение инвестиционного налогового вычета допускается с начала очередного налогового периода. При этом налогоплательщик вправе изменить ранее принятое решение об использовании (отказе от использования) права на применение инвестиционного налогового вычета по истечении трех последовательных налоговых периодов применения такого решения, если иной срок не определен решением субъекта Российской Федерации.\n\nРешение налогоплательщика об использовании права на применение инвестиционного налогового вычета действует применительно к объектам основных средств, научным исследованиям и (или) опытно-конструкторским разработкам, относящимся к организациям или обособленным подразделениям организаций, расположенным на территориях субъектов Российской Федерации, которые предоставили право на применение в отношении таких объектов, исследований и (или) разработок инвестиционного налогового вычета в соответствии с пунктом 6 настоящей статьи, в период действия соответствующего закона. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nИнвестиционный налоговый вычет текущего налогового (отчетного) периода в отношении расходов, указанных в подпункте 21 пункта 2 настоящей статьи, в части, превышающей предельную величину инвестиционного налогового вычета (неиспользованный инвестиционный налоговый вычет), рассчитанную в соответствии с абзацем третьим пункта 21 настоящей статьи, может быть использован для уменьшения сумм налога (авансового платежа), подлежащих зачислению в доходную часть бюджетов субъектов Российской Федерации, в последующих налоговых (отчетных) периодах. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\nОпределенная в соответствии с пунктом 3 настоящей статьи сумма уменьшения налога (авансового платежа), подлежащего зачислению в федеральный бюджет, в части превышения над расчетной суммой налога, определенной в соответствии с абзацем третьим пункта 3 или абзацем третьим пункта 10 настоящей статьи, может быть использована для уменьшения суммы налога (авансового платежа), подлежащей зачислению в федеральный бюджет, в последующих налоговых (отчетных) периодах, если в соответствии с абзацем первым настоящего пункта аналогичное право применяется к инвестиционному налоговому вычету. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n10. При уплате налога (авансового платежа) по консолидированной группе налогоплательщиков ответственным участником консолидированной группы налогоплательщиков может быть применен инвестиционный налоговый вычет, уменьшена сумма налога, подлежащая уплате в федеральный бюджет, в порядке и на условиях, которые установлены настоящей статьей, с учетом следующих особенностей.\n\nИнвестиционный налоговый вычет применяется ответственным участником консолидированной группы налогоплательщиков в отношении суммы налога, подлежащей зачислению в доходную часть бюджета субъекта Российской Федерации, приходящейся на соответствующего участника консолидированной группы налогоплательщиков (соответствующее обособленное подразделение участника консолидированной группы налогоплательщиков), понесшего расходы, предусмотренные подпунктами 1 и 2 пункта 2 настоящей статьи, и определяемой в порядке, установленном пунктом 6 статьи 288 настоящего Кодекса.\n\nСумма налога (авансового платежа), подлежащая уплате в федеральный бюджет, не может быть уменьшена ответственным участником консолидированной группы налогоплательщиков на величину большую, чем расчетная сумма налога, исчисленная исходя из величины прибыли, приходящейся на соответствующего участника (участников) консолидированной группы налогоплательщиков (соответствующие обособленные подразделения участника (участников) консолидированной группы налогоплательщиков) и определяемой в порядке, установленном пунктом 6 статьи 288 настоящего Кодекса, и ставки налога, установленной абзацем вторым пункта 1 статьи 284 настоящего Кодекса.\n\nРешение об использовании права на применение инвестиционного налогового вычета принимается ответственным участником консолидированной группы налогоплательщиков отдельно по каждому субъекту Российской Федерации, на территории которого расположены участники этой группы (обособленные подразделения участников этой группы), и применяется ко всем участникам консолидированной группы налогоплательщиков (обособленным подразделениям участников этой группы), расположенным на территории соответствующего субъекта Российской Федерации.\n\n(Пункт в редакции Федерального закона от 26.07.2019 № 210-ФЗ)\n\n1) организации - участники региональных инвестиционных проектов;\n\n2) организации - резиденты особых экономических зон;\n\n3) организации - участники Особой экономической зоны в Магаданской области;\n\n4) организации, осуществляющие деятельность, связанную с добычей углеводородного сырья на новом морском месторождении углеводородного сырья;\n\n5) организации - участники свободной экономической зоны;\n\n6) налогоплательщики - резиденты территории опережающего развития, резиденты свободного порта Владивосток либо резиденты Арктической зоны Российской Федерации; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n7) организации - участники проекта по осуществлению исследований, разработок и коммерциализации их результатов в соответствии с Федеральным законом \"Об инновационном центре \"Сколково\", либо участники проекта в соответствии с Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\", либо участники Технополиса; (В редакции  федеральных законов от 30.10.2018 № 373-ФЗ, от 23.11.2024 № 399-ФЗ)\n\n8) иностранные организации, признаваемые налоговыми резидентами Российской Федерации;\n\n9) организации, признаваемые налогоплательщиками - участниками соглашения о защите и поощрении капиталовложений, применяющие налоговый вычет для СЗПК в порядке, предусмотренном статьей 2884 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\nОрганизации, указанные в подпункте 4 настоящего пункта, вправе применять инвестиционный налоговый вычет в виде расходов, указанных в подпункте 8 пункта 2 настоящей статьи, применительно к сумме налога, исчисленного в отношении налоговой базы, определяемой при осуществлении видов деятельности, не относящихся к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nОрганизации, признаваемые налогоплательщиками - участниками соглашения о защите и поощрении капиталовложений, не вправе применять инвестиционный налоговый вычет в виде расходов, указанных в подпункте 21 пункта 2 настоящей статьи. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 629-ФЗ)\n\nВ случае возврата налогоплательщику денежных средств, перечисленных им по договору финансирования, предусмотренному подпунктом 4 пункта 2 настоящей статьи, сумма налога, не уплаченная в связи с применением инвестиционного налогового вычета в отношении соответствующих расходов на создание объектов инфраструктуры, подлежит восстановлению и уплате в бюджет с уплатой сумм пеней, начисляемых со дня истечения установленного статьей 287 настоящего Кодекса срока уплаты налога. (Дополнение абзацем - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nВ случае возврата налогоплательщику имущества, которое перечислено им в виде пожертвований либо на формирование целевого капитала и расходы по передаче которого предусмотрены подпунктом 3 пункта 2 настоящей статьи, сумма налога, не уплаченная в связи с применением инвестиционного налогового вычета в отношении соответствующих расходов, подлежит восстановлению и уплате в бюджет с уплатой сумм пеней, начисляемых со дня истечения установленного статьей 287 настоящего Кодекса срока уплаты налога. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случаях расторжения или прекращения договора инвестиционного товарищества до истечения пяти лет с даты заключения договора инвестиционного товарищества, в отношении вклада в которое налогоплательщик использовал право на применение инвестиционного налогового вычета, исключения информации о договоре инвестиционного товарищества из регионального реестра инвестиционных товариществ, уступки прав и обязанностей или выдела доли из имущества, находящегося в общей собственности товарищей по договору инвестиционного товарищества, сумма налога, не уплаченная в связи с применением такого вычета, подлежит восстановлению и упл\n\nате в бюджет с уплатой сумм пеней, начисляемых со дня истечения установленного статьей 287 настоящего Кодекса срока уплаты налога. (Дополнение абзацем - Федеральный закон от 30.09.2024 № 337-ФЗ)\n\n13. В целях применения инвестиционного налогового вычета по расходам, указанным в подпункте 8 пункта 2 настоящей статьи, некоммерческая организация, указанная в подпункте 22 пункта 2 статьи 251 настоящего Кодекса, и (или) организация, доля участия в которой такой некоммерческой организации составляет не менее 50 процентов, ежегодно не позднее 28 марта года, следующего за отчетным налоговым периодом, представляют лицам, передающим имущество в целях развития генетических технологий в Российской Федерации, отчеты о расходах, связанных с осуществлением мероприятий, предусмотренных программой развития генетических технологий и (или) соглашением о развитии генетических технологий (с копиями подтверждающих документов), произведенных за счет денежных средств, полученных от лиц, передающих имущество в целях развития генетических технологий в Российской Федерации, или от такой некоммерческой организации.\n\nВ отчетах, указанных в абзаце первом настоящего пункта, должно быть также отражено имущество (его стоимость, сформированная по правилам главы 25 настоящего Кодекса), полученное от лиц, передающих имущество в целях развития генетических технологий в Российской Федерации, или от некоммерческой организации, указанной в подпункте 22 пункта 2 статьи 251 настоящего Кодекса, и используемое для осуществления мероприятий, предусмотренных программой развития генетических технологий и (или) соглашением о развитии генетических технологий.\n\nВ случае, если сумма осуществленных расходов (с учетом стоимости имущества, указанного в абзаце втором настоящего пункта) в представленных отчетах суммарно меньше, чем сумма расходов, учтенная лицами, передающими имущество в целях развития генетических технологий в Российской Федерации, в составе инвестиционного налогового вычета, сумма расходов, учтенная лицами, передающими имущество в целях развития генетических технологий в Российской Федерации в составе инвестиционного налогового вычета, может быть подтверждена документами о расходах этих организаций, указанных в отчетах за следующий налоговый период.\n\nВ случае, если сумма расходов, учтенная лицами, передающими имущество в целях развития генетических технологий в Российской Федерации, при определении инвестиционного налогового вычета, не может быть подтверждена в порядке, указанном в абзацах первом - третьем настоящего пункта, сумма налога, не уплаченная в связи с применением инвестиционного налогового вычета в отношении расходов, предусмотренных подпунктом 8 пункта 2 настоящей статьи, в соответствующей части подлежит восстановлению и уплате в бюджет лицами, передающими имущество в целях развития генетических технологий в Российской Федерации, с уплатой сумм пеней, начисляемых со дня истечения установленного статьей 287 настоящего Кодекса срока уплаты налога.\n\nВ случае, если некоммерческая организация, указанная в подпункте 22 пункта 2 статьи 251 настоящего Кодекса, и (или) организация, доля участия в которой такой некоммерческой организации составляет не менее 50 процентов, использовали имущество, указанное в подпункте 22 пункта 2 статьи 251 настоящего Кодекса или пункте 4832 статьи 270 настоящего Кодекса, на реализацию мероприятий, отличных от мероприятий, предусмотренных программой развития генетических технологий и (или) соглашением о развитии генетических технологий, сумма налога, не уплаченная в связи с применением инвестиционного налогового вычета в отношении расходов, предусмотренных подпунктом 8 пункта 2 настоящей статьи, в соответствующей части подлежит восстановлению и уплате в бюджет лицами, передающими имущество в целях развития генетических технологий в Российской Федерации, с уплатой сумм пеней, начисляемых со дня истечения установленного статьей 287 настоящего Кодекса срока уплаты налога.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 335-ФЗ)","article_title":"Статья 286.1. Инвестиционный налоговый вычет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9a2a797192eccf5f3f6d28032f01062b298d1982947f8e7fba00b8018b92b8ad"},{"code_id":"NK_RF_2","article_number":"286.2","version_date":"2000-07-31","article_text":"1. Налогоплательщик, осуществивший расходы, предусмотренные пунктом 4 настоящей статьи, если иное не предусмотрено настоящей статьей, имеет право уменьшить сумму налога (авансового платежа), исчисленную им в качестве налогоплательщика в соответствии со статьей 286 настоящего Кодекса по налоговой ставке, установленной абзацем вторым пункта 1 статьи 284 настоящего Кодекса, и подлежащую зачислению в федеральный бюджет, на установленный настоящей статьей федеральный инвестиционный налоговый вычет в порядке, установленном настоящей статьей.\n\n2. Федеральный инвестиционный налоговый вычет может быть также применен налогоплательщиками, входящими в одну группу с лицом, указанным в пункте 1 настоящей статьи, при условии передачи этим лицом таким налогоплательщикам данных налогового учета и копий документов, подтверждающих суммы осуществленных расходов, указанных в пункте 4 настоящей статьи.\n\n3. Категории налогоплательщиков, которые могут применять федеральный инвестиционный налоговый вычет, категории объектов основных средств и нематериальных активов, к которым применяется федеральный инвестиционный налоговый вычет, характеристики группы, в которую входят лица, указанные в пункте 2 настоящей статьи, порядок и условия применения федерального инвестиционного налогового вычета, порядок определения величины федерального инвестиционного налогового вычета устанавливаются Правительством Российской Федерации.\n\n4. Федеральный инвестиционный налоговый вычет текущего налогового (отчетного) периода не может превышать 50 процентов от суммы расходов, составляющей первоначальную стоимость основного средства в соответствии с абзацем вторым пункта 1 статьи 257 настоящего Кодекса, и (или) суммы расходов, составляющей первоначальную стоимость амортизируемого нематериального актива в соответствии с абзацем одиннадцатым пункта 3 статьи 257 настоящего Кодекса, и (или) суммы расходов, составляющей величину изменения первоначальной стоимости основного средства или нематериального актива в случаях, указанных в пункте 2 статьи 257 настоящего Кодекса (за исключением расходов на частичную ликвидацию), в совокупности.\n\nПри этом федеральный инвестиционный налоговый вычет не применяется к объектам основных средств и нематериальным активам, при формировании первоначальной стоимости которых соответствующие расходы учитываются с применением повышающего коэффициента.\n\n5. Неиспользованный федеральный инвестиционный налоговый вычет предыдущих налоговых (отчетных) периодов, определяемый с учетом положений пункта 9 настоящей статьи, может уменьшить сумму налога (авансового платежа), подлежащую зачислению в федеральный бюджет, текущего налогового (отчетного) периода.\n\n6. Уменьшение суммы налога, подлежащей зачислению в федеральный бюджет, на величину расходов, предусмотренных пунктом 4 настоящей статьи, осуществляется в налоговом (отчетном) периоде, в котором введены в эксплуатацию объекты основных средств или нематериальные активы и (или) изменена их первоначальная стоимость.\n\nПри этом такое уменьшение может быть осуществлено также в последующие налоговые (отчетные) периоды с учетом положения пункта 9 настоящей статьи.\n\nСумма налога (авансового платежа), подлежащая зачислению в федеральный бюджет, в результате уменьшения на федеральный инвестиционный налоговый вычет не может быть ниже суммы налога, исчисленной по ставке 2 процента (3 процента - в 2025 - 2030 годах).\n\n(Пункт в редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n1) иностранные организации, признаваемые налоговыми резидентами Российской Федерации;\n\n2) организации, признаваемые налогоплательщиками - участниками соглашения о защите и поощрении капиталовложений;\n\n3) кредитные организации;\n\n4) организации, осуществляющие производство подакцизных товаров, указанных в подпунктах 1, 2, 3, 31, 5, 16, 17, 23 пункта 1 статьи 181 настоящего Кодекса.\n\nЕсли федеральный инвестиционный налоговый вычет был применен третьими лицами в соответствии с положениями настоящей статьи, налогоплательщик, в собственности которого находился указанный в абзаце первом настоящего пункта объект основных средств (нематериальный актив), обязан в течение 10 дней сообщить о его выбытии налогоплательщику, использовавшему право на применение федерального инвестиционного налогового вычета в отношении указанного объекта основных средств (нематериального актива).\n\nВ случае нарушения налогоплательщиком применения федерального инвестиционного налогового вычета сумма налога, не уплаченная в связи с применением этого вычета, подлежит восстановлению и уплате в бюджет с уплатой сумм пеней, начисляемых со дня истечения установленного статьей 287 настоящего Кодекса срока уплаты налога.\n\n(Дополнение статьей - Федеральный закон от 12.07.2024 № 176-ФЗ)","article_title":"Статья 286.2. Федеральный инвестиционный налоговый вычет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47c9f502b5bcf3289326be3143855fa9e594ff39207bb71b9df07325ce14a012"},{"code_id":"NK_RF_2","article_number":"287","version_date":"2000-07-31","article_text":"Авансовые платежи по итогам отчетного периода уплачиваются не позднее 28-го числа месяца, следующего за соответствующим отчетным периодом. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nЕжемесячные авансовые платежи, подлежащие уплате в течение отчетного периода, уплачиваются в срок не позднее 28-го числа каждого месяца этого отчетного периода, если иное не установлено настоящей статьей.  (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 02.07.2021 № 305-ФЗ)\n\nНалогоплательщики, исчисляющие ежемесячные авансовые платежи по фактически полученной прибыли, уплачивают авансовые платежи не позднее 28-го числа месяца, следующего за месяцем, по итогам которого производится исчисление налога. (В редакции федеральных законов от 31.12.2001 № 198-ФЗ; от 29.05.2002 № 57-ФЗ)\n\nПо итогам отчетного (налогового) периода суммы ежемесячных авансовых платежей, уплаченных в течение отчетного (налогового) периода, засчитываются при уплате авансовых платежей по итогам отчетного периода. Авансовые платежи по итогам отчетного периода засчитываются в счет уплаты налога по итогам следующего отчетного (налогового) периода. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nНалоговый агент обязан перечислить соответствующую сумму налога не позднее 28-го числа месяца, следующего за месяцем выплаты (перечисления) денежных средств иностранной организации или иного получения доходов иностранной организацией. (В редакции  федеральных законов от 27.07.2010 № 229-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nНалог с доходов по государственным и муниципальным ценным бумагам, при обращении которых предусмотрено признание доходом, полученным продавцом в виде процентов, сумм накопленного процентного дохода (накопленного купонного дохода), подлежащих налогообложению в соответствии с пунктом 4 статьи 284 настоящего Кодекса у получателя доходов, уплачивается в бюджет налогоплательщиком - получателем дохода не позднее 28-го числа месяца, следующего за соответствующим месяцем отчетного (налогового) периода, в котором получен доход, исходя из дат, признаваемых датами получения дохода в соответствии со статьями 271 и 273 настоящего Кодекса. (В редакции  федеральных законов от 29.05.2002 № 57-ФЗ, от 06.06.2005 № 58-ФЗ, от 28.12.2022 № 565-ФЗ)","article_title":"Статья 287. Сроки и порядок уплаты налога и налога в виде авансовых платежей","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b740af1a6cc81342072d0b5e03e836b4b7f5f216c2a102d9a1f15a98f6510a4"},{"code_id":"NK_RF_2","article_number":"288","version_date":"2000-07-31","article_text":"1. Налогоплательщики - российские организации, имеющие обособленные подразделения, исчисление и уплату в федеральный бюджет сумм авансовых платежей, а также сумм налога, исчисленного по итогам налогового периода, производят по месту своего нахождения без распределения указанных сумм по обособленным подразделениям.\n\nЕсли налогоплательщик имеет несколько обособленных подразделений на территории одного субъекта Российской Федерации, то распределение прибыли по каждому из этих подразделений может не производиться. Сумма налога, подлежащая уплате в бюджет этого субъекта Российской Федерации, в таком случае определяется исходя из доли прибыли, исчисленной из совокупности показателей обособленных подразделений, находящихся на территории субъекта Российской Федерации. При этом налогоплательщик самостоятельно выбирает то обособленное подразделение, через которое осуществляется уплата налога в бюджет этого субъекта Российской Федерации, уведомив о принятом решении до 31 декабря года, предшествующего налоговому периоду, налоговые органы, в которых налогоплательщик состоит на налоговом учете по месту нахождения своих обособленных подразделений. Уведомления представляются в налоговый орган в случае, если налогоплательщик изменил порядок уплаты налога, изменилось количество структурных подразделений на терр\n\nитории субъекта Российской Федерации или произошли другие изменения, влияющие на порядок уплаты налога. (Дополнение абзацем - Федеральный закон от 06.06.2005 № 58-ФЗ) (В редакции федеральных законов от 24.07.2007 № 216-ФЗ; от 22.07.2008 № 158-ФЗ)\n\nУказанные в настоящем пункте удельный вес среднесписочной численности работников и удельный вес остаточной стоимости амортизируемого имущества определяются исходя из фактических показателей среднесписочной численности работников (расходов на оплату труда) и остаточной стоимости основных средств указанных организаций и их обособленных подразделений за отчетный (налоговый) период. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nПри этом налогоплательщики самостоятельно определяют, какой из показателей должен применяться - среднесписочная численность работников или сумма расходов на оплату труда. Выбранный налогоплательщиком показатель должен быть неизменным в течение налогового периода.\n\nАбзац. (Исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nВместо показателя среднесписочной численности работников налогоплательщик с сезонным циклом работы либо иными особенностями деятельности, предусматривающими сезонность привлечения работников, по согласованию с налоговым органом по месту своего нахождения может применять показатель удельного веса расходов на оплату труда, определяемых в соответствии со статьей 255 настоящего Кодекса. При этом определяется удельный вес расходов на оплату труда каждого обособленного подразделения, в общих расходах налогоплательщика, на оплату труда.\n\nСуммы авансовых платежей, а также суммы налога, подлежащие зачислению в доходную часть бюджетов субъектов Российской Федерации, исчисляются по ставкам налога, действующим на территориях, где расположены организация и ее обособленные подразделения. (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nВ случае создания новых или ликвидации обособленных подразделений в течение текущего налогового периода налогоплательщик в течение 10 дней после окончания отчетного периода обязан уведомить налоговые органы на территории того субъекта Российской Федерации, в котором созданы новые или ликвидированы обособленные подразделения, о выборе того обособленного подразделения, через которое будет осуществляться уплата налога в бюджет этого субъекта Российской Федерации. (Дополнение абзацем - Федеральный закон от 22.07.2008 № 158-ФЗ)\n\nУплата налога осуществляется в сроки, установленные настоящим Кодексом, начиная с отчетного (налогового) периода, следующего за отчетным (налоговым) периодом, в котором такое обособленное подразделение было создано или ликвидировано. (Дополнение абзацем - Федеральный закон от 22.07.2008 № 158-ФЗ)\n\nДля целей настоящей статьи организации, перешедшие на начисление амортизации нелинейным методом в составе амортизационных групп, вправе определять остаточную стоимость амортизируемого имущества по данным бухгалтерского учета. (Дополнение абзацем - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\nАбзац. (Исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nСведения о суммах авансовых платежей по налогу, а также суммах налога, исчисленных по итогам налогового периода, налогоплательщик сообщает своим обособленным подразделениям, а также налоговым органам по месту нахождения обособленных подразделений не позднее срока, установленного настоящей статьей для подачи налоговых деклараций за соответствующий отчетный или налоговый период.\n\nДоля прибыли каждого участника консолидированной группы налогоплательщиков и каждого из их обособленных подразделений в совокупной прибыли этой группы определяется ответственным участником консолидированной группы налогоплательщиков как средняя арифметическая величина удельного веса среднесписочной численности работников (расходов на оплату труда) и удельного веса остаточной стоимости амортизируемого имущества этого участника или обособленного подразделения соответственно в среднесписочной численности работников (расходах на оплату труда) и остаточной стоимости амортизируемого имущества, определенной в соответствии с пунктом 1 статьи 257 настоящего Кодекса, в целом по консолидированной группе налогоплательщиков.\n\nОтветственный участник консолидированной группы налогоплательщиков определяет величину прибыли, приходящейся на каждого из участников консолидированной группы налогоплательщиков и на каждое из их обособленных подразделений, путем умножения определенной в соответствии с абзацем вторым настоящего пункта доли прибыли каждого из участников или каждого обособленного подразделения участника консолидированной группы налогоплательщиков на совокупную прибыль этой группы.\n\nОтветственный участник консолидированной группы налогоплательщиков исчисление и уплату в федеральный бюджет сумм авансовых платежей, а также сумм налога, исчисленного по итогам налогового периода, производит по месту своего нахождения без распределения указанных сумм по участникам этой группы и их обособленным подразделениям.\n\nСуммы налога (авансовых платежей), подлежащие зачислению в бюджеты субъектов Российской Федерации, приходящиеся на каждого из участников консолидированной группы налогоплательщиков и на каждое из их обособленных подразделений, исчисляются по налоговым ставкам, действующим на территориях, где расположены соответствующие участники консолидированной группы налогоплательщиков и (или) их обособленные подразделения.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n1) показатели d и р для каждого субъекта Российской Федерации, рассчитываемые по следующим формулам:\n\nгде d* - определенная в соответствии с пунктом 6 настоящей статьи величина прибыли, приходящейся на каждого из участников консолидированной группы налогоплательщиков и на каждое из их обособленных подразделений;\n\nD - величина совокупной прибыли консолидированной группы налогоплательщиков;\n\np* - сумма налога, исчисленная по каждой из организаций, вступивших в консолидированную группу налогоплательщиков, и по каждому из их обособленных подразделений за 2011 год, подлежащая зачислению в бюджет соответствующего субъекта Российской Федерации и заявленная в налоговой декларации, представленной в налоговые органы в срок не позднее 28 марта 2012 года (без учета изменений, внесенных в налоговую декларацию после указанной даты);\n\nР - совокупная сумма налога всех участников консолидированной группы налогоплательщиков, исчисленная за 2011 год по ставкам, установленным в соответствии с абзацами третьим и четвертым пункта 1 статьи 284 настоящего Кодекса, и определяемая на основании сведений, указанных в налоговых декларациях, представленных организациями, вступившими в консолидированную группу налогоплательщиков, в налоговые органы в срок не позднее 28 марта 2012 года (без учета изменений, внесенных в налоговые декларации после указанной даты);\n\n2) долю прибыли каждого из участников консолидированной группы налогоплательщиков и каждого из их обособленных подразделений в совокупной прибыли этой группы как показатель g, рассчитываемый по следующим формулам:\n\nв 2012 году: g = 0,2 х d + 0,8 х р;\n\nв 2013 году: g = 0,4 х d + 0,6 х р;\n\nв 2014 году: g = 0,6 х d + 0,4 х р;\n\nв 2015 году: g = 0,8 х d + 0,2 х р;\n\n3) величину прибыли, приходящейся на каждого из участников консолидированной группы налогоплательщиков и на каждое из их обособленных подразделений, путем умножения рассчитанного в соответствии с подпунктом 2 настоящего пункта показателя g на совокупную прибыль группы;\n\n4) сумму налога (авансовых платежей), приходящуюся на каждого из участников консолидированной группы налогоплательщиков и на каждое из их обособленных подразделений, по которым налог (авансовые платежи) уплачивается в бюджет соответствующего субъекта Российской Федерации, исчисляемую исходя из величины прибыли, рассчитанной в соответствии с подпунктом 3 настоящего пункта, и ставки налога, действующей на территории, где расположены участник консолидированной группы налогоплательщиков или его обособленное подразделение.\n\n(Дополнение пунктом - Федеральный закон от 30.03.2012 № 19-ФЗ)","article_title":"Статья 288. Особенности исчисления и уплаты налога налогоплательщиком, имеющим обособленные подразделения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27128adb6b34c978eebe0332f1adfaf3e54b3aedd7f2d8baa7878218c24b92dd"},{"code_id":"NK_RF_2","article_number":"288.1","version_date":"2000-07-31","article_text":"1. Резиденты Особой экономической зоны в Калининградской области (далее также - резиденты) уплачивают налог на прибыль организаций в соответствии с настоящей главой, за исключением случаев, установленных настоящей статьей.\n\n1) сумма налога на прибыль организаций в отношении налоговой базы по налогу на прибыль организаций от реализации инвестиционного проекта в соответствии с Федеральным законом \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", исчисленная по уменьшенной на 50 процентов налоговой ставке в размере, установленном абзацем вторым пункта 1 статьи 284 настоящего Кодекса, зачисляется в федеральный бюджет;\n\n2) сумма налога на прибыль организаций в отношении налоговой базы по налогу на прибыль организаций от реализации инвестиционного проекта в соответствии с Федеральным законом \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", исчисленная по уменьшенной на 50 процентов налоговой ставке в размере, установленном абзацем третьим пункта 1 статьи 284 настоящего Кодекса, зачисляется в бюджет Калининградской области.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 353-ФЗ)\n\nтьей, и суммой налога на прибыль организаций, исчисляемой в соответствии с настоящей статьей резидентом в отношении прибыли, полученной от реализации инвестиционного проекта в соответствии с Федеральным законом \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", не включается в налоговую базу по налогу на прибыль организаций для резидентов. (В редакции Федерального закона от 27.11.2017 № 353-ФЗ)\n\n10. В случае исключения резидента из единого реестра резидентов Особой экономической зоны в Калининградской области до получения им свидетельства о выполнении условий инвестиционной декларации резидент считается утратившим право на применение особого порядка уплаты налога на прибыль организаций, установленного настоящей статьей, с начала того квартала, в котором он был исключен из указанного реестра.\n\nВ этом случае резидент обязан исчислить сумму налога в отношении прибыли, полученной от реализации инвестиционного проекта в соответствии с Федеральным законом \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", по налоговой ставке, установленной пунктом 1 статьи 284 настоящего Кодекса. (В редакции Федерального закона от 27.11.2017 № 353-ФЗ)\n\nИсчисление суммы налога производится на основании раздельного учета доходов (расходов), полученных (произведенных) при реализации данного инвестиционного проекта, и доходов (расходов), полученных (произведенных) при осуществлении иной хозяйственной деятельности, за период применения особого порядка налогообложения.\n\nИсчисленная сумма налога подлежит уплате резидентом по истечении отчетного или налогового периода, в котором он был исключен из единого реестра резидентов Особой экономической зоны в Калининградской области, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период в соответствии с абзацами первым и вторым пункта 1 статьи 287 настоящего Кодекса.\n\nПри проведении выездной налоговой проверки резидента, исключенного из единого реестра резидентов Особой экономической зоны в Калининградской области, в части правильности исчисления и полноты уплаты суммы налога в отношении прибыли, полученной от реализации инвестиционного проекта, ограничения, установленные абзацем вторым пункта 4 и пунктом 5 статьи 89 настоящего Кодекса, не действуют при условии, если решение о назначении такой проверки вынесено не позднее чем в течение трех месяцев с момента уплаты резидентом указанной суммы налога.\n\n(Дополнение пунктом - Федеральный закон от 17.05.2007 № 84-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 10.01.2006 № 16-ФЗ)","article_title":"Статья 288.1. Особенности исчисления и уплаты налога на прибыль организаций резидентами Особой экономической зоны в Калининградской области","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f13be0c2b4215c953b53ab4064023f824275816516132cb6c5642626579baac"},{"code_id":"NK_RF_2","article_number":"288.2","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 23.05.2016 № 144-ФЗ)\n\n1) при прекращении статуса участника регионального инвестиционного проекта по основаниям, указанным в подпунктах 1, 3, 4 и 5 пункта 4 статьи 2512 настоящего Кодекса, и при невыполнении условия осуществления им капитальных вложений в объеме, предусмотренном региональным инвестиционным проектом; (В редакции Федерального закона от 19.11.2021 № 371-ФЗ)\n\n2) при прекращении статуса участника регионального инвестиционного проекта в соответствии с подпунктом 2 пункта 4 статьи 2512 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 267-ФЗ)","article_title":"Статья 288.2. Особенности исчисления налога участниками региональных инвестиционных проектов, включенными в реестр участников региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b93726d6da3181064c0a8c4827db54a70be9742a0ab5d256389173dee2ef2c1"},{"code_id":"NK_RF_2","article_number":"288.3","version_date":"2000-07-31","article_text":"1. В целях настоящей статьи доходы (расходы), полученные (произведенные) при осуществлении иной хозяйственной деятельности участником регионального инвестиционного проекта, для которого не требуется включение в реестр участников региональных инвестиционных проектов, учитываются при исчислении налоговой базы только при выполнении условия, предусмотренного пунктом 1 статьи 2843-1 настоящего Кодекса.\n\n2. Сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой соответствующих пеней, начисляемых со дня, следующего за установленным статьей 287 настоящего Кодекса днем уплаты налога (авансового платежа по налогу), исчисленного без учета применения налоговых льгот, указанных в пункте 15-1 статьи 284 и пункте 3 статьи 2843-1 настоящего Кодекса, за период применения таких налоговых льгот, начиная с налогового периода, с которого прекращено применение таких налоговых льгот по основанию, указанному в пункте 3 статьи 2512-1 настоящего Кодекса.\n\n3. При определении налоговой базы, к которой применяются налоговые ставки, предусмотренные пунктом 15-1 статьи 284 и пунктом 3 статьи 2843-1 настоящего Кодекса, не учитываются доходы и расходы, признанные участником регионального инвестиционного проекта в порядке правопреемства при присоединении к нему другой организации.\n\n(Дополнение статьей - Федеральный закон от 23.05.2016 № 144-ФЗ)","article_title":"Статья 288.3. Особенности исчисления налога участниками региональных инвестиционных проектов, для которых не требуется включение в реестр участников региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88c7980aebe71d098c6ba0eb098d0d1e788b44c3cf4001b05bde4637a57175a2"},{"code_id":"NK_RF_2","article_number":"288.4","version_date":"2000-07-31","article_text":"1. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений определяет налоговую базу от осуществления деятельности, связанной с реализацией инвестиционного проекта, являющегося предметом соглашения о защите и поощрении капиталовложений, отдельно от налоговой базы, определяемой при осуществлении иных видов деятельности.\n\nНалогоплательщик - участник соглашения о защите и поощрении капиталовложений, являющийся стороной нескольких соглашений о защите и поощрении капиталовложений, определяет налоговую базу от осуществления деятельности, связанной с реализацией инвестиционного проекта, являющегося предметом каждого соглашения о защите и поощрении капиталовложений, отдельно от налоговой базы, определяемой при реализации других соглашений о защите и поощрении капиталовложений, и отдельно от налоговой базы, определяемой при осуществлении иных видов деятельности.\n\nПорядок ведения раздельного учета доходов и расходов для определения налоговой базы, предусмотренного настоящей статьей, закрепляется в учетной политике, принятой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, и применяется в течение срока, на который заключено соглашение о защите и поощрении капиталовложений.\n\n2. Убыток, полученный при осуществлении деятельности, связанной с реализацией инвестиционного проекта, являющегося предметом соглашения о защите и поощрении капиталовложений, может быть перенесен на будущее в соответствии с порядком, установленным статьей 283 настоящего Кодекса, в уменьшение налоговой базы, определенной при осуществлении деятельности, связанной с реализацией инвестиционного проекта, являющегося предметом только этого соглашения о защите и поощрении капиталовложений.\n\n3. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений вправе уменьшить суммы налога (авансового платежа по налогу), исчисленные в отношении налоговой базы по налогу на прибыль организаций от осуществления деятельности, связанной с реализацией инвестиционного проекта, являющегося предметом соглашения о защите и поощрении капиталовложений, на сумму налогового вычета для СЗПК в порядке и на условиях, которые установлены настоящей статьей.\n\nПри наличии у налогоплательщика - участника соглашения о защите и поощрении капиталовложений обособленных подразделений уменьшается только налог, подлежащий уплате в бюджет того субъекта Российской Федерации, который является стороной такого соглашения о защите и поощрении капиталовложений. Данное ограничение не распространяется на налог, подлежащий уплате в федеральный бюджет.\n\nПри наличии оснований у налогоплательщика - участника соглашения о защите и поощрении капиталовложений применять при исчислении и уплате суммы налога (авансового платежа по налогу) пониженные ставки по налогу налоговый вычет для СЗПК применяется к сумме налога (авансового платежа по налогу), рассчитанной с учетом применения этих ставок.\n\n4. Размер налогового вычета для СЗПК определяется суммой, отраженной в уведомлении о налоговом вычете для СЗПК, представляемом в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в соответствии со статьей 2518 настоящего Кодекса (далее в настоящей статье - уведомление), применительно к налогу, зачисляемому в соответствующий бюджет.\n\n5. Налоговый вычет для СЗПК применяется начиная с налогового периода, следующего за годом представления уведомления в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов.\n\n6. В результате применения налогового вычета для СЗПК сумма налога (авансового платежа по налогу), зачисляемого в соответствующий бюджет, может быть снижена до нуля.\n\nНеиспользованная часть налогового вычета для СЗПК уменьшает сумму налога (авансового платежа по налогу) в последующие отчетные (налоговые) периоды, если применение налогового вычета в этих последующих отчетных (налоговых) периодах предусмотрено уведомлением.\n\n7. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений имеет право уменьшать сумму налога (авансового платежа по налогу) до наступления хотя бы одного из следующих оснований:\n\n1) общая сумма налога (авансового платежа по налогу), не уплаченная в связи с применением налогового вычета для СЗПК, стала равна сумме, отраженной в уведомлении применительно к налогу, зачисляемому в соответствующий бюджет;\n\n2) истек срок применения налогового вычета для СЗПК, указанный в уведомлении;\n\n3) налогоплательщик утратил статус участника соглашения о защите и поощрении капиталовложений.\n\n8. В случае, если в уведомлении указаны разные суммы затрат, которые подлежат возмещению за счет налоговых вычетов для СЗПК с различными сроками их применения, в первую очередь сумма налога (авансового платежа по налогу) уменьшается на суммы налоговых вычетов для СЗПК с меньшим периодом применения.\n\n9. Если по одному соглашению о защите и поощрении капиталовложений представляется несколько уведомлений, уменьшение суммы налога (авансового платежа по налогу) осуществляется в хронологическом порядке представления таких уведомлений.\n\n(Дополнение статьей - Федеральный закон от 28.06.2022 № 225-ФЗ)","article_title":"Статья 288.4. Особенности исчисления и уплаты налога на прибыль организаций налогоплательщиками - участниками соглашений о защите и поощрении капиталовложений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1e2211c95d28f28fb95c9c3129a56d7ef8ce0381d6cdcd5ec3274b4010b22dd"},{"code_id":"NK_RF_2","article_number":"289","version_date":"2000-07-31","article_text":"Налоговые агенты обязаны по истечении каждого отчетного (налогового) периода, в котором они производили выплаты налогоплательщику, представлять в налоговые органы по месту своего нахождения расчеты сумм доходов, выплаченных организациям, и сумм удержанных налогов за прошедший отчетный (налоговый) период (далее в настоящей главе - налоговый расчет) в порядке, определенном настоящей статьей. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, представляют налоговые декларации (налоговые расчеты) в налоговый орган по месту учета в качестве крупнейших налогоплательщиков. (Дополнение абзацем - Федеральный закон от 30.12.2006 № 268-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалогоплательщики, указанные в пункте 1 статьи 2752 настоящего Кодекса, обязаны по истечении каждого отчетного и налогового периода представлять в налоговые органы по месту учета (по месту учета в качестве крупнейших налогоплательщиков, по месту учета в качестве оператора нового морского месторождения углеводородного сырья) налоговые декларации с расчетом налоговых баз отдельно в отношении каждого нового морского месторождения углеводородного сырья. (Дополнение абзацем - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\nНалогоплательщики, указанные в пункте 31 статьи 286 настоящего Кодекса, освобождаются от обязанности представлять налоговые декларации за отчетные периоды 2020 и 2021 годов. (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nТеатры, музеи, библиотеки, концертные организации, являющиеся бюджетными учреждениями, представляют налоговую декларацию только по истечении налогового периода. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 215-ФЗ)\n\nЕсли участники консолидированной группы налогоплательщиков получают доходы, не включаемые в консолидированную налоговую базу этой группы, они представляют в налоговые органы по месту своего учета налоговые декларации только в части исчисления налога в отношении таких доходов.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nОтветственный участник консолидированной группы налогоплательщиков обязан представлять налоговые декларации по налогу на прибыль организаций по консолидированной группе налогоплательщиков в налоговый орган по месту регистрации договора о создании такой группы в порядке и сроки, которые установлены настоящей статьей для налоговой декларации по налогу.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 289. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95e3626d78f20e4029b0e1aaf933ce1fc9e96b31909f999505653af32c9fbf33"},{"code_id":"NK_RF_2","article_number":"290","version_date":"2000-07-31","article_text":"1. К доходам банков, кроме доходов, предусмотренных статьями 249 и 250 настоящего Кодекса, относятся также доходы от банковской деятельности, предусмотренные настоящей статьей. При этом доходы, предусмотренные статьями 249 и 250 настоящего Кодекса, определяются с учетом особенностей, предусмотренных настоящей статьей.\n\n2. К доходам банков в целях настоящей главы относятся, в частности, следующие доходы от осуществления банковской деятельности:\n\n1) в виде процентов от размещения банком от своего имени и за свой счет денежных средств, предоставления кредитов и займов;\n\n2) в виде платы за открытие и ведение банковских счетов клиентов, в том числе банков-корреспон\n\nдентов (включая иностранные банки-корреспонденты), и осуществления расчетов по их поручению, включая комиссионное и иное вознаграждение за переводные, инкассовые, аккредитивные и другие операции, оформление и обслуживание платежных карт и иных специальных средств, предназначенных для совершения банковских операций, за предоставление выписок и иных документов по счетам и за розыск сумм; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n3) от инкассации денежных средств, векселей, платежных и расчетных документов и кассового обслуживания клиентов;\n\n4) от проведения операций с иностранной валютой, осуществляемых в наличной и безналичной формах, включая комиссионные сборы (вознаграждения) при операциях по покупке или продаже иностранной валюты, в том числе за счет и по поручению клиента, от операций с валютными ценностями. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nДля определения доходов банков от операций продажи (покупки) иностранной валюты в отчетном (налоговом) периоде принимается положительная разница между доходами, определенными в соответствии с пунктом 2 статьи 250 настоящего Кодекса, и расходами, определенными в соответствии с подпунктом 6 пункта 1 статьи 265 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) по операциям купли-продажи драгоценных металлов в виде положительной (отрицательной) разницы, образующейся вследствие отклонения цены продажи (покупки) драгоценных металлов от учетных цен, установленных Центральным банком Российской Федерации на дату перехода права собственности на драгоценные металлы (на дату отражения по обезличенному металлическому счету операции купли-продажи драгоценных металлов); (В редакции Федерального закона от 28.11.2015 № 328-ФЗ)\n\n51) по операциям купли-продажи драгоценных камней в виде разницы между ценой реализации и учетной стоимостью; (Дополнение подпунктом - Федеральный закон от 28.11.2015 № 328-ФЗ)\n\n6) от операций по предоставлению банковских гарантий, авалей и поручительств за третьих лиц, предусматривающих исполнение в денежной форме; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n7) в виде положительной разницы между полученной при прекращении или реализации (последующей уступке) права требования (в том числе ранее приобретенного) суммой средств и учетной стоимостью данного права требования;\n\n8) от депозитарного обслуживания клиентов;\n\n9) от предоставления в аренду специально оборудованных помещений или сейфов для хранения документов и ценностей; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n10) в виде платы за доставку, перевозку денежных средств, ценных бумаг, иных ценностей и банковских документов (кроме инкассации);\n\n11) в виде платы за перевозку и хранение драгоценных металлов и драгоценных камней;\n\n12) в виде платы, получаемой банком от экспортеров и импортеров, за выполнение функций агентов валютного контроля;\n\n13) по операциям купли-продажи коллекционных монет в виде разницы между ценой реализации и ценой приобретения;\n\n14) в виде сумм, полученных банком по возвращенным кредитам (ссудам), убытки от списания которых были ранее учтены в составе расходов, уменьшивших налоговую базу, либо списанных за счет созданных резервов, отчисления на создание которых ранее уменьшали налоговую базу;\n\n15) в виде полученной банком компенсации понесенных расходов по оплате услуг сторонних организаций по контролю за соответствием стандартам слитков драгоценных металлов, получаемых банком у физических и юридических лиц;\n\n16) от осуществления форфейтинговых и факторинговых операций;\n\n17) от оказания услуг, связанных с установкой и эксплуатацией электронных систем документооборота между банком и клиентами, в том числе систем \"клиент-банк\"; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n18) в виде комиссионных сборов (вознаграждений) при проведении операций с валютными ценностями; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n19) в виде положительной переоценки драгоценных металлов и требований (обязательств), выраженных в драгоценных металлах, осуществляемой в порядке, установленном нормативными актами Центрального банка Российской Федерации; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 28.11.2015 № 328-ФЗ)\n\n20) в виде сумм восстановленного резерва на возможные потери по ссудам, расходы на формирование которого были приняты в составе расходов в порядке и на условиях, которые установлены статьей 292 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n21) в виде сумм восстановленных резервов под обесценение ценных бумаг, расходы на формирование которых были приняты в составе расходов в порядке и на условиях, которые установлены статьей 300 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n22) другие доходы, связанные с банковской деятельностью.","article_title":"Статья 290. Особенности определения доходов банков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a19e6766a4b8ee2fa71b24eade7ad2e44e1ae7306ccea40e66ec2ab860682f6c"},{"code_id":"NK_RF_2","article_number":"291","version_date":"2000-07-31","article_text":"1. К расходам банка, кроме расходов, предусмотренных статьями 254 - 269 настоящего Кодекса, относятся также расходы, понесенные при осуществлении банковской деятельности, предусмотренные настоящей статьей. При этом расходы, предусмотренные статьями 254 - 269 настоящего Кодекса, определяются с учетом особенностей, предусмотренных настоящей статьей.\n\n2. К расходам банков в целях настоящей главы относятся расходы, понесенные при осуществлении банковской деятельности, в частности, следующие виды расходов:\n\n1) проценты по:\n\nдоговорам банковского вклада (депозита) и прочим привлеченным денежным средствам физических и юридических лиц (включая банки-корреспонденты), в том числе иностранные, в том числе за использование денежных средств, находящихся на банковских счетах; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nсобственным долговым обязательствам (облигациям, депозитным или сберегательным сертификатам, векселям, займам или другим обязательствам);\n\nмежбанковским кредитам, включая овердрафт;\n\nприобретенным кредитам рефинансирования, включая приобретенные на аукционной основе в порядке, установленном Центральным банком Российской Федерации;\n\nзаймам и вкладам (депозитам) в драгоценных металлах;\n\nиным обязательствам банков перед клиентами, в том числе по средствам, депонированным клиентами для расчетов по аккредитивам. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nПроценты, начисленные в соответствии с настоящим пунктом, по межбанковским кредитам (депозитам) со сроком до 7 дней (включительно) учитываются при определении налоговой базы исходя из фактического срока действия договоров; (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\n2) суммы отчислений в резерв на возможные потери по ссудам, подлежащим резервированию в порядке, установленном статьей 292 настоящего Кодекса;\n\n(Подпункт 3 исключен - Федеральный закона от 29.05.2002 № 57-ФЗ)\n\n3) комиссионные сборы за услуги по корреспондентским отношениям, включая расходы по расчетно-кассовому обслуживанию клиентов, открытию им счетов в других банках, плату другим банкам (в том числе иностранным) за расчетно-кассовое обслуживание этих счетов, расчетные услуги Центрального банка Российской Федерации, инкассацию денежных средств, ценных бумаг, платежных документов и иные аналогичные расходы; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n4) расходы (убытки) от проведения операций с иностранной валютой, осуществляемых в наличной и безналичной формах, включая комиссионные сборы (вознаграждения) при операциях по покупке или продаже иностранной валюты, в том числе за счет и по поручению клиента, от операций с валютными ценностями и расходы по управлению и защите от валютных рисков. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nДля определения расходов банков от операций продажи (покупки) иностранной валюты в отчетном (налоговом) периоде принимается отрицательная разница между доходами, определенными в соответствии с пунктом 2 статьи 250 настоящего Кодекса, и расходами, определенными в соответствии с подпунктом 6 пункта 1 статьи 265 настоящего Кодекса; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) по операциям купли-продажи драгоценных металлов в виде отрицательной (положительной) разницы, образующейся вследствие отклонения цены продажи (покупки) драгоценных металлов от учетных цен, установленных Центральным банком Российской Федерации на дату перехода права собственности на драгоценные металлы (на дату отражения по обезличенному металлическому счету операции купли-продажи драгоценных металлов); (В редакции Федерального закона от 28.11.2015 № 328-ФЗ)\n\n51) убытки по операциям купли-продажи драгоценных камней в виде разницы между ценой реализации и учетной стоимостью; (Дополнение подпунктом - Федеральный закон от 28.11.2015 № 328-ФЗ)\n\n(Подпункт 7 исключен - Федеральный закона от 29.05.2002 № 57-ФЗ)\n\n6) расходы банка по хранению, транспортировке, контролю за соответствием стандартам качества драгоценных металлов в слитках и монете, расходы по аффинажу драгоценных металлов, а также иные расходы, связанные с проведением операций со слитками драгоценных металлов и монетой, содержащей драгоценные металлы; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n7) расходы по переводу пенсий и пособий, а также расходы по переводу денежных средств без открытия счетов физическим лицам; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n8) расходы по изготовлению и внедрению платежно-расчетных средств (пластиковых карточек, дорожных чеков и иных платежно-расчетных средств); (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n9) суммы, уплачиваемые за инкассацию банкнот, монет, чеков и других расчетно-платежных документов, а также расходы по упаковке (включая комплектование наличных денег), перевозке, пересылке и (или) доставке принадлежащих кредитной организации или ее клиентам ценностей; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n10) расходы по ремонту и (или) реставрации инкассаторских сумок, мешков и иного инвентаря, связанных с инкассацией денег, перевозкой и хранением ценностей, а также приобретению новых и замене пришедших в негодность сумок и мешков; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n11) расходы, связанные с уплатой сбора за государственную регистрацию ипотеки и внесением изменений и дополнений в регистрационную запись об ипотеке, а также с нотариальным удостоверением договора об ипотеке; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n12) расходы по аренде автомобильного транспорта для инкассации выручки и перевозке банковских документов и ценностей; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n13) расходы по аренде брокерских мест; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n14) расходы по оплате услуг расчетно-кассовых и вычислительных центров; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n15) расходы, связанные с осуществлением форфейтинговых и факторинговых операций; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n16) расходы по гарантиям, поручительствам, акцептам и авалям, предоставляемым банку другими организациями; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n17) комиссионные сборы (вознаграждения) за проведение операций с валютными ценностями, в том числе за счет и по поручению клиентов; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n18) в виде отрицательной переоценки драгоценных металлов и требований (обязательств), выраженных в драгоценных металлах, осуществляемой в порядке, установленном нормативными актами Центрального банка Российской Федерации; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 28.11.2015 № 328-ФЗ)\n\n19) суммы отчислений в резерв на возможные потери по ссудам, расходы на формирование которого учитываются в составе расходов в порядке и на условиях, которые установлены статьей 292 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n20) суммы отчислений в резервы под обесценение ценных бумаг, расходы на формирование которых учитываются в составе расходов в порядке и на условиях, которые установлены статьей 300 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n201) суммы страховых взносов банков, установленных в соответствии с федеральным законом о страховании вкладов физических лиц в банках Российской Федерации; (Дополнение подпунктом - Федеральный закон от 23.12.2003 № 178-ФЗ)\n\n202) суммы страховых взносов по договорам страхования на случай смерти или наступления инвалидности заемщика банка, в которых банк является выгодоприобретателем, при условии компенсации данных расходов заемщиками; (Дополнение подпунктом - Федеральный закон от 06.06.2005 № 58-ФЗ)\n\n21) другие расходы, связанные с банковской деятельностью. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 291. Особенности определения расходов банков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1aa942afd158240d65d62a25ef7a2119a08e2487fc3f8933c89dec3533bcac7d"},{"code_id":"NK_RF_2","article_number":"292","version_date":"2000-07-31","article_text":"Суммы отчислений в резервы на возможные потери по ссудам, сформированные в порядке, устанавливаемом Центральным банком Российской Федерации в соответствии с Федеральным законом \"О Центральном банке Российской Федерации (Банке России)\", признаются расходом с учетом ограничений, предусмотренных настоящей статьей. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПри определении налоговой базы не учитываются расходы в виде отчислений в резервы на возможные потери по ссудам, сформированные банками под задолженность, относимую к стандартной, в порядке, устанавливаемом Центральным банком Российской Федерации, а также в резервы на возможные потери по ссудам, сформированные под векселя, за исключением учтенных банками векселей третьих лиц, по которым вынесен протест в неплатеже. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nСуммы резервов на возможные потери по ссудам, отнесенные на расходы банка, используются банком при списании с баланса кредитной организации безнадежной задолженности по ссудам в порядке, установленном Центральным банком Российской Федерации. (Дополнение абзацем - Федеральный закон от 24.07.2007 № 216-ФЗ)\n\nПри принятии банком решения о списании с баланса кредитной организации безнадежной задолженности по ссудам прекращается начисление процентов на данную ссудную задолженность, если начисление таких процентов не прекращено ранее в соответствии с договором. (Дополнение абзацем - Федеральный закон от 24.07.2007 № 216-ФЗ)\n\nПри этом суммы резервов на возможные потери по ссудам, сформированные до даты отзыва (аннулирования) у банка лицензии на осуществление банковских операций, после отзыва (аннулирования) лицензии фиксируются и используются в порядке, установленном Центральным банком Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 23.04.2018 № 105-ФЗ)","article_title":"Статья 292. Расходы на формирование резервов банков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c31460b04e0f75a30c7c21e43d01dcc61bd38061b945e1de713dbd441926c2b"},{"code_id":"NK_RF_2","article_number":"293","version_date":"2000-07-31","article_text":"1. К доходам страховой организации, кроме доходов, предусмотренных статьями 249 и 250 настоящего Кодекса, которые определяются с учетом особенностей, предусмотренных настоящей статьей, относятся также доходы от страховой деятельности.\n\n2. К доходам страховых организаций в целях настоящей главы относятся следующие доходы от осуществления страховой деятельности:\n\n1) страховые премии (взносы) по договорам страхования, сострахования и перестрахования. При этом страховые премии (взносы) по договорам сострахования включаются в состав доходов страховщика (состраховщика) только в размере его доли страховой премии, установленной в договоре сострахования;\n\n2) суммы уменьшения (возврата) страховых резервов, образованных в предыдущие отчетные периоды с учетом изменения доли перестраховщиков в страховых резервах;\n\n3) вознаграждения и тантьемы (форма вознаграждения страховщика со стороны перестраховщика) по договорам перестрахования;\n\n4) вознаграждения от страховщиков по договорам сострахования;\n\n5) суммы возмещения перестраховщиками доли страховых выплат по рискам, переданным в перестрахование;\n\n6) суммы процентов на депо премий по рискам, принятым в перестрахование;\n\n7) доходы от реализации перешедшего к страховщику в соответствии с действующим законодательством права требования страхователя (выгодоприобретателя) к лицам, ответственным за причиненный ущерб;\n\n8) суммы санкций за неисполнение условий договоров страхования, признанные должником добровольно либо по решению суда; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n9) вознаграждения за оказание услуг страхового агента, брокера;\n\n10) вознаграждения, полученные стра\n\nховщиком за оказание услуг сюрвейера (осмотр принимаемого в страхование имущества и выдачу заключений об оценке страхового риска) и аварийного комиссара (определение причин, характера и размеров убытков при страховом событии);\n\n11) суммы возврата части страховых премий (взносов) по договорам перестрахования в случае их досрочного прекращения; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n111) сумма положительной разницы, возникшей у страховщика, осуществившего прямое возмещение убытков, в результате превышения средней суммы страховой выплаты, полученной от страховщика, застраховавшего гражданскую ответственность лица, причинившего вред, над суммой выплаты потерпевшему, осуществленной в порядке прямого возмещения убытков в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств; (Дополнение подпунктом - Федеральный закон от 15.11.2010 № 300-ФЗ)\n\n112) сумма положительной разницы, возникшей у страховщика, застраховавшего гражданскую ответственность лица, причинившего вред, в результате превышения страховой выплаты по договору обязательного страхования гражданской ответственности владельцев транспортных средств, осуществленной в порядке прямого возмещения убытков, над средней суммой страховой выплаты, возмещенной страховщику, осуществившему прямое возмещение убытков в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств; (Дополнение подпунктом - Федеральный закон от 15.11.2010 № 300-ФЗ)\n\n12) другие доходы, полученные при осуществлении страховой деятельности. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 293. Особенности определения доходов страховых организаций (страховщиков)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9861ada79d109510498ae591bee8203c246a6ad7cf0e680621b866b9485fb54d"},{"code_id":"NK_RF_2","article_number":"294","version_date":"2000-07-31","article_text":"1. К расходам страховой организации, кроме расходов, предусмотренных статьями 254 - 269 настоящего Кодекса, относятся также расходы, понесенные при осуществлении страховой деятельности, предусмотренные настоящей статьей. При этом расходы, предусмотренные статьями 254 - 269 настоящего Кодекса, определяются с учетом особенностей, предусмотренных настоящей статьей.\n\n2. К расходам страховых организаций в целях настоящей главы относятся следующие расходы, понесенные при осуществлении страховой деятельности:\n\n1) суммы отчислений в страховые резервы (с учетом изменения доли перестраховщиков в страховых резервах), формируемые на основании законодательства о страховании в порядке, утвержденном Центральным банком Российской Федерации; (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 23.07.2013 № 251-ФЗ)\n\n11) суммы отчислений в резерв гарантий и резерв текущих компенсационных выплат, формируемые в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств, в размерах, установленных в соответствии со структурой страховых тарифов; (Дополнение подпунктом - Федеральный закон от 29.12.2004 № 204-ФЗ)\n\n12) суммы отчислений в резервы (фонды), формируемые в соответствии с требованиями международных систем обязательного страхования гражданской ответственности владельцев транспортных средств, к которым присоединилась Российская Федерация; (Дополнение подпунктом - Федеральный закон от 29.12.2004 № 204-ФЗ)\n\n13) суммы отчислений в компенсационный фонд, формируемый профессиональным объединением страховщиков в соответствии с Федеральным законом \"Об обязательном страховании гражданской ответственности перевозчика за причинение вреда жизни, здоровью, имуществу пассажиров и о порядке возмещения такого вреда, причиненного при перевозках пассажиров метрополитеном\"; (Дополнение подпунктом - Федеральный закон от 14.06.2012 № 78-ФЗ)\n\n14) суммы отчислений в формируемый в соответствии с Федеральным законом от 25 июля 2011 года № 260-ФЗ \"О государственной поддержке в сфере сельскохозяйственного страхования и о внесении изменений в Федеральный закон \"О развитии сельского хозяйства\" фонд компенсационных выплат по договорам сельскохозяйственного страхования, осуществляемого с государственной поддержкой; (Дополнение подпунктом - Федеральный закон от 02.10.2012 № 162-ФЗ)\n\n2) страховые выплаты по договорам страхования, сострахования и перестрахования. В целях настоящей главы к страховым выплатам относятся выплаты рент, аннуитетов, пенсий и прочие выплаты, предусмотренные условиями договора страхования;\n\n3) суммы страховых премий (взносов) по рискам, переданным в перестрахование. Положения настоящего подпункта применяются к договорам перестрахования, заключенным российскими страховыми организациями с российскими и иностранными перестраховщиками и брокерами;\n\n4) вознаграждения и тантьемы по договорам перестрахования; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) суммы процентов на депо премий по рискам, переданным в перестрахование; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n6) вознаграждения состраховщику по договорам сострахования;\n\n7) возврат части страховых премий (взносов), а также выкупных сумм по договорам страхования, сострахования и перестрахования в случаях, предусмотренных законодательством и (или) условиями договора;\n\n8) вознаграждения за оказание услуг страхового агента и (или) страхового брокера;\n\n9) расходы по оплате организациям или отдельным физическим лицам оказанных ими услуг, связанных со страховой деятельностью, в том числе:\n\nуслуг актуариев;\n\nмедицинского обследования при заключении договоров страхования жизни и здоровья, если оплата такого медицинского обследования в соответствии с договорами осуществляется страховщиком;\n\nдетективных услуг, выполняемых организациями, имеющими лицензию на ведение указанной деятельности, связанных с установлением обоснованности страховых выплат;\n\nуслуг специалистов (в том числе экспертов, оценщиков, сюрвейеров, аварийных комиссаров, юристов), привлекаемых для оценки страхового риска, определения страховой стоимости имущества и размера страховой выплаты, оценки последствий страховых случаев, урегулирования страховых выплат, а также при осуществлении прямого возмещения убытков потерпевшим в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств; (В редакции Федерального закона от 25.12.2008 № 282-ФЗ)\n\nуслуг по изготовлению страховых свидетельств (полисов), бланков строгой отчетности, квитанций и иных подобных документов;\n\nуслуг организаций за выполнение ими письменных поручений работников по перечислению страховых взносов из заработной платы путем безналичных расчетов;\n\nуслуг медицинских организаций и других организаций по выдаче справок, статистических данных, заключений и иных аналогичных документов; (В редакции Федерального закона от 25.11.2013 № 317-ФЗ)\n\nинкассаторских услуг;\n\n91) сумма отрицательной разницы, возникшей у страховщика, осуществившего прямое возмещение убытков, в результате превышения выплаты потерпевшему, осуществленной в порядке прямого возмещения убытков в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств, над средней суммой страховой выплаты, полученной от страховщика, застраховавшего гражданскую ответственность лица, причинившего вред; (Дополнение подпунктом - Федеральный закон от 15.11.2010 № 300-ФЗ)\n\n92) сумма отрицательной разницы, возникшей у страховщика, застраховавшего гражданскую ответственность лица, причинившего вред, в результате превышения средней суммы страховой выплаты, возмещенной страховщику, осуществившему прямое возмещение убытков, над страховой выплатой по договору обязательного страхования гражданской ответственности владельцев транспортных средств, осуществленной в порядке прямого возмещения убытков в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств; (Дополнение подпунктом - Федеральный закон от 15.11.2010 № 300-ФЗ)\n\n10) другие расходы, непосредственно связанные со страховой деятельностью.\n\nК расходам организации, осуществляющей деятельность по страхованию экспортных кредитов и инвестиций от предпринимательских и (или) политических рисков в соответствии с Федеральным законом от 8 декабря 2003 года № 164-ФЗ \"Об основах государственного регулирования внешнеторговой деятельности\", также относятся суммы отчислений в страховые резервы, формируемые в порядке, установленном Правительством Российской Федерации, и суммы страховых премий (взносов) по рискам, переданным в перестрахование в соответствии с договорами перестрахования, заключенными с российскими и иностранными перестраховщиками и иными организациями, имеющими право на заключение договоров перестрахования. (В редакции Федерального закона от 15.04.2019 № 63-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 07.06.2013 № 131-ФЗ)","article_title":"Статья 294. Особенности определения расходов страховых организаций (страховщиков)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01382017ee29687c3a337f4b891bfc474797475c7ab9d0557ed0aaab7e25a817"},{"code_id":"NK_RF_2","article_number":"294.1","version_date":"2000-07-31","article_text":"1. К доходам страховых медицинских организаций - участников обязательного медицинского страхования, осуществляющих обязательное медицинское страхование, кроме доходов, предусмотренных статьями 249 и 250 настоящего Кодекса, относятся также средства, перечисляемые территориальными фондами обязательного медицинского страхования в соответствии с договором о финансовом обеспечении обязательного медицинского страхования и предназначенные на расходы на ведение дела по обязательному медицинскому страхованию, и средства, являющиеся вознаграждением за выполнение действий, предусмотренных указанным договором.\n\n2. К расходам страховых медицинских организаций - участников обязательного медицинского страхования, осуществляющих обязательное медицинское страхование, кроме расходов, предусмотренных статьями 254 - 269 настоящего Кодекса, относятся также расходы, понесенные указанными организациями при осуществлении страховой деятельности по обязательному медицинскому страхованию.\n\n(Дополнение статьей - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)","article_title":"Статья 294.1. Особенности определения доходов и расходов страховых медицинских организаций - участников обязательного медицинского страхования","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8058ed40661c39a36be6b28e051a8bca9f544251f55f3116020554862a6f22f0"},{"code_id":"NK_RF_2","article_number":"295","version_date":"2000-07-31","article_text":"В целях налогообложения доход, полученный от размещения пенсионных резервов, определяется как положительная разница между полученным доходом от размещения пенсионных резервов и доходом, рассчитанным исходя из ставки рефинансирования Центрального банка Российской Федерации и суммы размещенного резерва, с учетом времени фактического размещения, за исключением дохода, размещенного на солидарных пенсионных счетах, по итогам налогового периода. (В редакции Федерального закона от 29.12.2004 № 204-ФЗ)\n\nотчисления от дохода от размещения пенсионных резервов, направляемые в состав собственных средств фонда, осуществляемые в соответствии с законодательством Российской Федерации о негосударственных пенсионных фондах;\n\nдоходы от размещения собственных средств фонда в ценные бумаги, осуществления инвестиций и других вложений, определяемые в порядке, установленном настоящим Кодексом для соответствующих видов доходов;\n\nвознаграждение фонда, осуществляющего деятельность страховщика по обязательному пенсионному страхованию, включая постоянную часть вознаграждения и переменную часть вознаграждения;\n\nчасть суммы пенсионного взноса, направляемая на основании договора негосударственного пенсионного обеспечения в соответствии с пенсионными правилами фонда в состав собственных средств фонда на покрытие административных расходов в соответствии с законодательством Российской Федерации о негосударственных пенсионных фондах.\n\n(Пункт в редакции Федерального закона от 03.07.2019 № 162-ФЗ)","article_title":"Статья 295. Особенности определения доходов негосударственных пенсионных фондов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d42ef418fcc2756841eee154190223f5f83d55886d7e8352c2ff72fc9ca4112"},{"code_id":"NK_RF_2","article_number":"296","version_date":"2000-07-31","article_text":"1) расходы, связанные с размещением пенсионных резервов, включая вознаграждения управляющей компании, депозитария, профессиональных участников рынка ценных бумаг; (В редакции Федерального закона от 03.07.2019 № 162-ФЗ)\n\n2) обязательные расходы, связанные с хранением, поддержанием в рабочем состоянии и оценкой в соответствии с законодательством Российской Федерации имущества, в которое размещены пенсионные резервы;\n\n3) отчисления, направляемые в состав собственных средств фонда в соответствии с законодательством Российской Федерации, учитываемые в составе расходов; (В редакции Федерального закона от 03.07.2019 № 162-ФЗ)\n\n4) отчисления на формирование страхового резерва, осуществляемые в соответствии с законодательством Российской Федерации о негосударственных пенсионных фондах и в порядке, установленном Центральным банком Российской Федерации, до достижения установленного негосударственным пенсионным фондом размера страхового резерва, но не более 50 процентов величины резервов покрытия пенсионных обязательств. (Дополнение подпунктом - Федеральный закон от 29.12.2004 № 204-ФЗ) (В редакции Федерального закона от 03.07.2019 № 162-ФЗ)\n\n1) вознаграждения за оказание услуг по заключению договоров негосударственного пенсионного обеспечения, договоров долгосрочных сбережений и договоров обязательного пенсионного страхования в соответствии с законодательством Российской Федерации о негосударственных пенсионных фондах; (В редакции  федеральных законов от 29.12.2004 № 204-ФЗ, от 23.03.2024 № 58-ФЗ)\n\n2) оплата услуг актуариев;\n\n3) оплата услуг по изготовлению пенсионных свидетельств (полисов), бланков строгой отчетности, квитанций и иных подобных документов;\n\n31) вознаграждение за услуги по ведению пенсионных счетов в соответствии с законодательством Российской Федерации о негосударственных пенсионных фондах; (Дополнение подпунктом - Федеральный закон от 29.12.2004 № 204-ФЗ)\n\n32) вознаграждение управляющей компании, осуществляющей доверительное управление средствами пенсионных накоплений, средствами пенсионных резервов, включая постоянную часть вознаграждения и переменную часть вознаграждения, выплачиваемое фондом за счет собственных средств; (Дополнение подпунктом - Федеральный закон от 03.07.2019 № 162-ФЗ) (В редакции  Федерального закона от 23.03.2024 № 58-ФЗ)\n\n33) вознаграждение специализированному депозитарию и возмещение необходимых расходов, произведенных специализированным депозитарием, осуществляемые фондом за счет собственных средств в соответствии с договором на оказание услуг специализированного депозитария; (Дополнение подпунктом - Федеральный закон от 03.07.2019 № 162-ФЗ)\n\n34) ежегодные отчисления в резерв фонда по обязательному пенсионному страхованию, которые осуществляются за счет собственных средств фонда и сформированы в порядке, установленном статьей 201 Федерального закона от 7 мая 1998 года № 75-ФЗ \"О негосударственных пенсионных фондах\", за исключением расходов, указанных в пункте 4824 статьи 270 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 03.07.2019 № 162-ФЗ)\n\n35) средства, подлежащие оплате фондом в качестве гарантийных взносов в фонд гарантирования пенсионных накоплений в соответствии со статьей 15 Федерального закона от 28 декабря 2013 года № 422-ФЗ \"О гарантировании прав застрахованных лиц в системе обязательного пенсионного страхования Российской Федерации при формировании и инвестировании средств пенсионных накоплений, установлении и осуществлении выплат за счет средств пенсионных накоплений\" либо в фонд гарантирования пенсионных резервов в соответствии со статьей 20 Федерального закона от 28 декабря 2022 года № 555-ФЗ \"О гарантировании прав участников негосударственных пенсионных фондов в рамках деятельности по негосударственному пенсионному обеспечению и формированию долгосрочных сбережений\"; (Дополнение подпунктом - Федеральный закон от 03.07.2019 № 162-ФЗ) (В редакции  Федерального закона от 23.03.2024 № 58-ФЗ)\n\n36) расходы, связанные с осуществлением срочной пенсионной выплаты, единовременной выплаты или выплаты средств пенсионных накоплений правопреемникам умершего застрахованного лица, осуществляемые за счет собственных средств фонда; (Дополнение подпунктом - Федеральный закон от 03.07.2019 № 162-ФЗ)\n\n4) другие расходы, непосредственно связанные с деятельностью по обязательному пенсионному страхованию, негосударственному пенсионному обеспечению и (или) по формированию долгосрочных сбережений, осуществляемые фондом за счет собственных средств. (В редакции  Федерального закона от 23.03.2024 № 58-ФЗ)","article_title":"Статья 296. Особенности определения расходов негосударственных пенсионных фондов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb0ac25912479d72b15c14917473b79c6c429ebe3b18d0660bac6ac2caa32e53"},{"code_id":"NK_RF_2","article_number":"297","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 29.05.2002 № 57-ФЗ)","article_title":"Статья 297. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ff680a6f4753905da52a43ff1a4a3cacf903681a32080285ebbe488633fd7d8"},{"code_id":"NK_RF_2","article_number":"297.1","version_date":"2000-07-31","article_text":"1. К доходам налогоплательщиков - кредитны\n\nх потребительских кооперативов и микрофинансовых организаций относятся доходы, предусмотренные статьями 249 и 250 настоящего Кодекса и определяемые с учетом особенностей, предусмотренных настоящей статьей.\n\n2. К доходам кредитных потребительских кооперативов и микрофинансовых организаций в целях настоящей главы относятся, в частности, следующие доходы:\n\n1) доходы в виде процентов по займам, предоставленным в соответствии с законодательством Российской Федерации;\n\n2) доходы в виде сумм, полученных по возвращенным займам, убытки от списания которых ранее были учтены в составе расходов при определении налоговой базы;\n\n3) доходы в виде сумм, полученных кредитными потребительскими кооперативами и микрофинансовыми организациями по возвращенным займам, списанным за счет созданных резервов, отчисления на создание которых ранее были учтены в составе расходов при определении налоговой базы в порядке, установленном статьей 2973 настоящего Кодекса.\n\n3. Не включаются в доходы кредитных потребительских кооперативов и микрофинансовых организаций доходы в виде страховых выплат, полученных по договорам страхования на случай смерти или наступления инвалидности заемщика, и страховых выплат, полученных по договорам страхования имущества, являющегося обеспечением обязательств заемщика (залогом), в пределах суммы непогашенной задолженности заемщика по заемным (кредитным) средствам, начисленным процентам и признанным судом штрафным санкциям, пеням, погашаемой за счет указанных страховых выплат.\n\n(Дополнение статьей - Федеральный закон от 02.11.2013 № 301-ФЗ)","article_title":"Статья 297.1. Особенности определения доходов кредитных потребительских кооперативов и микрофинансовых организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c73127b31d7889012e86688c6d1164c03e8db4ace89e5453a6bbb64c8b5dd65"},{"code_id":"NK_RF_2","article_number":"297.2","version_date":"2000-07-31","article_text":"1. Расходы налогоплательщиков - кредитных потребительских кооперативов и микрофинансовых организаций, предусмотренные статьями 254 - 269 настоящего Кодекса и непосредственно связанные с предоставлением займов и иной приносящей доход деятельностью, предусмотренной законодательством о кредитной кооперации и микрофинансовой деятельности, учитываются для целей налогообложения с учетом особенностей, установленных настоящей статьей.\n\nВ целях налогообложения указанные расходы признаются в порядке и на условиях, которые предусмотрены настоящей главой. При этом расходы, осуществленные за счет средств целевого финансирования и целевых поступлений, при определении налоговой базы не учитываются.\n\n2. К расходам кредитных потребительских кооперативов и микрофинансовых организаций в целях настоящей главы относятся, в частности, следующие расходы:\n\n1) расходы в виде процентов по займам, кредитам и иным долговым обязательствам, связанным с привлечением денежных средств в соответствии с законодательством о кредитной кооперации и микрофинансовой деятельности, с учетом особенностей, предусмотренных статьей 269 настоящего Кодекса;\n\n2) расходы по гарантиям, поручительствам, предоставляемым кредитным потребительским кооперативам и микрофинансовым организациям другими организациями и физическими лицами;\n\n3) расходы в виде сумм отчислений в резерв на возможные потери по займам, расходы на формирование которого учитываются кредитными потребительскими кооперативами и микрофинансовыми организациями в составе расходов в порядке и на условиях, установленных статьей 2973 настоящего Кодекса;\n\n4) расходы в виде сумм страховых взносов по договорам страхования на случай смерти или наступления инвалидности заемщика кредитного потребительского кооператива или микрофинансовой организации, в которых кредитный потребительский кооператив или микрофинансовая организация является выгодоприобретателем, при условии компенсации данных расходов заемщиками.\n\n(Дополнение статьей - Федеральный закон от 02.11.2013 № 301-ФЗ)","article_title":"Статья 297.2. Особенности определения расходов кредитных потребительских кооперативов и микрофинансовых организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c6718e965c52007dc06345e5e8fb7f5ad6356d0c0c03c775edded7fe3ab51094"},{"code_id":"NK_RF_2","article_number":"297.3","version_date":"2000-07-31","article_text":"1. В целях настоящей главы кредитные потребительские кооперативы и микрофинансовые организации вправе, кроме резервов по сомнительным долгам, предусмотренных статьей 266 настоящего Кодекса, создавать резервы на возможные потери по займам в порядке, предусмотренном настоящей статьей.\n\n2. Суммы отчислений в резервы на возможные потери по займам, сформированные в порядке, устанавливаемом Центральным банком Российской Федерации в соответствии с Федеральным законом от 18 июля 2009 года № 190-ФЗ \"О кредитной кооперации\" и Федеральным законом от 2 июля 2010 года № 151-ФЗ \"О микрофинансовой деятельности и микрофинансовых организациях\", включаются в состав внереализационных расходов в течение отчетного (налогового) периода.\n\n3. Суммы резервов на возможные потери по займам используются кредитными потребительскими кооперативами и микрофинансовыми организациями при списании с баланса безнадежной задолженности по займам в порядке, установленном Центральным банком Российской Федерации.\n\nПри принятии кредитным потребительским кооперативом или микрофинансовой организацией решения о списании с баланса безнадежной задолженности по займам прекращается начисление процентов на данную задолженность, если начисление таких процентов не прекращено ранее в соответствии с договором.\n\n4. Суммы резервов на возможные потери по займам, отнесенные на расходы и не полностью использованные в отчетном (налоговом) периоде на покрытие убытков по безнадежной задолженности по займам, могут быть перенесены на следующий отчетный (налоговый) период. При этом сумма вновь создаваемого резерва должна быть скорректирована на сумму остатков резерва предыдущего отчетного (налогового) периода. В случае, если сумма вновь создаваемого в отчетном (налоговом) периоде резерва меньше, чем сумма остатка резерва предыдущего отчетного (налогового) периода, разница подлежит включению в состав внереализационных доходов в последнее число отчетного (налогового) периода. В случае, если сумма вновь создаваемого резерва больше, чем сумма остатка резерва предыдущего отчетного (налогового) периода, разница подлежит включению во внереализационные расходы в последнее число отчетного (налогового) периода.\n\n(Дополнение статьей - Федеральный закон от 02.11.2013 № 301-ФЗ)","article_title":"Статья 297.3. Расходы на формирование резервов на возможные потери по займам кредитных потребительских кооперативов и микрофинансовых организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f61b4c1b4286cc3f62a570404e91061e741d4a87009eccaac26d7214297ead39"},{"code_id":"NK_RF_2","article_number":"298","version_date":"2000-07-31","article_text":"К доходам налогоплательщиков, которые в соответствии с законодательством Российской Федерации о рынке ценных бумаг признаются профессиональными участниками рынка ценных бумаг (далее по тексту - профессиональные участники рынка ценных бумаг), кроме доходов, предусмотренных статьями 249 и 250 настоящего Кодекса, относятся также доходы от осуществления профессиональной деятельности на рынке ценных бумаг.\n\nК таким доходам, в частности, относятся:\n\n1) доходы от оказания посреднических и иных услуг на рынке ценных бумаг;\n\n2) часть дохода, возникающего от использования средств клиентов до момента их возврата клиентам в соответствии с условиями договора;\n\n3) доходы от предоставления услуг по хранению сертификатов ценных бумаг и (или) учету прав на ценные бумаги;\n\n4) доходы от оказания депозитарных услуг, включая услуги по предоставлению информации о ценных бумагах, ведению счета депо;\n\n5) доходы от оказания услуг по ведению реестра владельцев ценных бумаг;\n\n6) доходы от предоставления услуг, непосредственно способствующих заключению третьими лицами гражданско-правовых сделок с ценными бумагами;\n\n7) доходы от предоставления консультационных услуг на рынке ценных бумаг;\n\n8) доходы в виде сумм восстановленных резервов под обесценение ценных бумаг, ранее принятых на расходы согласно статье 300 настоящего Кодекса;\n\n9) прочие доходы, получаемые профессиональными участниками рынка ценных бумаг от своей профессиональной деятельности.","article_title":"Статья 298. Особенности определения доходов профессиональных участников рынка ценных бумаг","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecc72dd8b8df9fa2c9c831462907f03be88992dab4e1f92eeaa1f874905519eb"},{"code_id":"NK_RF_2","article_number":"299","version_date":"2000-07-31","article_text":"К расходам профессиональных участников рынка ценных бумаг, кроме расходов, указанных в статьях 254 - 269 настоящего Кодекса (с учетом ограничений, предусмотренных законодательством Российской Федерации о рынке ценных бумаг), относятся, в частности:\n\n1) расходы в виде взносов организаторам торговли и иным организациям (в том числе в соответствии с законодательством Российской Федерации некоммерческим организациям), имеющим соответствующую лицензию;\n\n2) расходы на поддержание и обслуживание торговых мест различного режима, возникающие в связи с осуществлением профессиональной деятельности;\n\n3) расходы на осуществление экспертизы, связанной с подлинностью представляемых документов, в том числе бланков (сертификатов) ценных бумаг;\n\n4) расходы, связанные с раскрытием информации о деятельности профессионального участника рынка ценных бумаг;\n\n5) расходы на создание и доначисление резервов под обесценение ценных бумаг согласно статье 300 настоящего Кодекса;\n\n6) расходы на участие в собраниях акционеров, проводимых эмитентами ценных бумаг или по их поручению;\n\n7) другие расходы, непосредственно связанные с деятельностью профессиональных участников рынка ценных бумаг.","article_title":"Статья 299. Особенности определения расходов профессиональных участников рынка ценных бумаг","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"07b41ada0c89c7861f590e9848d85e0cb9e359e4d90c91b9ff53ca0f6751ce8a"},{"code_id":"NK_RF_2","article_number":"299.1","version_date":"2000-07-31","article_text":"1. К доходам налогоплательщиков - клиринговых организаций относятся доходы, предусмотренные статьями 249 и 250 настоящего Кодекса, определяемые с учетом особенностей, предусмотренных настоящей статьей.\n\n2. При определении налоговой базы клиринговых организаций не учитываются следующие доходы:\n\n1) денежные средства и иное имущество, которые получены клиринговой организацией в качестве обеспечения исполнения обязательств участников клиринга, а также от реализации имущества, составляющего такое обеспечение;\n\n2) денежные средства и иное имущество, которые получены клиринговой организацией в целях осуществления расчетов по обязательствам участников клиринга, в том числе по договорам, стороной по которым является клиринговая организация (за исключением денежных средств и иного имущества, которые получены клиринговой организацией в качестве оплаты ее услуг), а также по договорам, заключаемым клиринговой организацией в целях исполнения обязательств перед участниками клиринга; (В редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\n3) денежные средства и иное имущество, которые получены клиринговой организацией от использования фондов, сформированных этой клиринговой организацией в целях обеспечения исполнения обязательств по гражданско-правовым договорам;\n\n4) денежные средства и иное имущество, внесенные в имущественный пул клиринговой организации в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\". (Дополнение подпунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 25.11.2009 № 281-ФЗ)","article_title":"Статья 299.1. Особенности определения доходов клиринговых организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d6f846f494b3cc1a9cc3d05f25c72fbd2ff952829beace015a34fe67522ef93"},{"code_id":"NK_RF_2","article_number":"299.2","version_date":"2000-07-31","article_text":"1. К расходам налогоплательщиков - клиринговых организаций относятся расходы, предусмотренные статьями 254 - 269 настоящего Кодекса, определяемые с учетом особенностей, предусмотренных настоящей статьей.\n\n2. При определении налоговой базы клиринговых организаций не учитываются следующие расходы:\n\n1) денежные средства и иное имущество, которые обеспечивают исполнение обязательств участников клиринга и переданы клиринговой организацией в счет исполнения таких обязательств;\n\n2) денежные средства и иное имущество, которые переданы клиринговой организацией участникам клиринга по итогам осуществления клиринга (расчетов), в том числе по договорам, стороной по которым является клиринговая организация, а также по договорам, совершаемым клиринговой организацией в целях исполнения обязательств перед участниками клиринга; (В редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\n3) денежные средства и иное имущество, которые переданы участникам клиринга и которые получены клиринговой организацией от использования фондов, сформированных клиринговой организацией за счет взносов данных участников клиринга в целях обеспечения исполнения обязательств по гражданско-правовым договорам;\n\n4) денежные средства и иное имущество, которые переданы участнику клиринга клиринговой организацией при погашении клиринговых сертификатов участия, выпущенных клиринговой организацией в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\". (Дополнение подпунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 25.11.2009 № 281-ФЗ)","article_title":"Статья 299.2. Особенности определения расходов клиринговых организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e3a2d69352319b6a13a0390e72029426348fedb6f46d4f54fc57a62e444bdc0b"},{"code_id":"NK_RF_2","article_number":"299.3","version_date":"2000-07-31","article_text":"1. При определении налоговой базы в соответствии со статьей 2752 настоящего Кодекса к доходам налогоплательщиков, указанных в пункте 1 статьи 2752 настоящего Кодекса, относятся доходы, указанные в статьях 249 и 250 настоящего Кодекса, и доходы, предусмотренные настоящей статьей, если они связаны с осуществлением деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья.\n\nПри этом доходы, предусмотренные статьями 249 и 250 настоящего Кодекса, определяются с учетом особенностей, предусмотренных настоящей статьей.\n\n2. К доходам налогоплательщиков, указанных в пункте 1 статьи 2752 настоящего Кодекса, от осуществления деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в целях настоящей главы относятся, в частности, следующие доходы:\n\n1) доход организации - владельца лицензии на пользование участком недр, в границах которого расположено новое морское месторождение углеводородного сырья, от реализации продуктов технологического передела углеводородного сырья, добытого на новом морском месторождении углеводородного сырья (сжиженного природного газа, стабильного конденсата, широкой фракции легких углеводородов).\n\nДоход от реализации нефтепродуктов, продуктов нефтехимии и газохимии, произведенных из углеводородного сырья, добытого на новом морском месторождении углеводородного сырья, не включается в налоговую базу, определяемую в порядке, установленном статьей 2752 настоящего Кодекса, а учитывается в целях налогообложения в общем порядке;\n\n2) доход организации - оператора нового морского месторождения углеводородного сырья от выполнения работ (оказания услуг), предусмотренных соответствующим операторским договором;\n\n3) доход организации - оператора нового морского месторождения углеводородного сырья от реализации углеводородного сырья, добытого на новом морском месторождении углеводородного сырья и приобретенного организацией - оператором нового морского месторождения углеводородного сырья у организации - владельца лицензии на пользование участком недр, в границах которого расположено указанное месторождение, а также продуктов технологического передела (сжиженного природного газа, стабильного конденсата, широкой фракции легких углеводородов), полученных из такого углеводородного сырья;\n\n4) доход от реализации товаров (имущественных прав), предназначенных для использования при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, по сделкам между организацией - владельцем лицензии на пользование участком недр, в границах которого расположено указанное новое морское месторождение углеводородного сырья, и организацией - оператором указанного нового морского месторождения углеводородного сырья;\n\n5) доход от реализации амортизируемого имущества, ранее непосредственно использовавшегося при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, определяемый в соответствии со статьей 249 настоящего Кодекса;\n\n6) доходы в виде процентов, полученных по договорам займа, в случае, если соответствующие заемные средства были предоставлены налогоплательщику, указанному в пункте 1 статьи 2752 настоящего Кодекса, для финансирования деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в отношении которого определяется налоговая база;\n\n7) доходы в виде сумм кредиторской задолженности по займам, кредитам и другим долговым обязательствам (включая задолженность по уплате процентов), списанной в связи с прощением долга либо по иным основаниям, если соответствующие заемные средства были привлечены для финансирования деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья;\n\n8) доходы от сдачи имущества (включая земельные участки) в аренду (субаренду), предусмотренные пунктом 4 части второй статьи 250 настоящего Кодекса, по договорам, заключенным между налогоплательщиками, указанными в пункте 1 статьи 2752 настоящего Кодекса, осуществляющими деятельность, связанную с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в отношении одного и того же месторождения при условии, что указанное имущество использовалось в отчетном (налоговом) периоде при осуществлении деятельности, связанной с добычей углеводородного сырья на указанном новом морском месторождении углеводородного сырья;\n\n9) доходы в виде положительной курсовой разницы, возникающей от переоценки требований (обязательств), за исключением переоценки выданных (полученных) авансов, включая задолженность по уплате процентов, если соответствующие требования (обязательства) возникли в связи с осуществлением деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья. (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n3. Учет доходов, которые не могут быть непосредственно отнесены к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, или к иной деятельности налогоплательщика, а также доходов, относящихся к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, осуществляемой в отношении нескольких новых морских месторождений углеводородного сырья, при определении налоговой базы в соответствии с положениями статьи 2752 настоящего Кодекса осуществляется в порядке, аналогичном установленному пунктом 4 статьи 2994 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 268-ФЗ)","article_title":"Статья 299.3. Особенности определения доходов от осуществления деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b122c619056e5df92543fa7b528a52e5afe19f448256b76a4adf182d745b8cbf"},{"code_id":"NK_RF_2","article_number":"299.4","version_date":"2000-07-31","article_text":"1. При определении налоговой базы в соответствии со статьей 2752 настоящего Кодекса к расходам налогоплательщика, указанного в пункте 1 статьи 2752 настоящего Кодекса, относятся обоснованные и документально подтвержденные расходы, понесенные налогоплательщиком, если эти расходы связаны с осуществлением таким налогоплательщиком деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья. При этом расходы, понесенные при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, определяются с учетом особенностей, установленных настоящей статьей.\n\n2. К расходам налогоплательщиков, указанных в пункте 1 статьи 2752 настоящего Кодекса, относятся, в частности, следующие виды расходов, понесенных ими при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья:\n\n1) расходы на освоение природных ресурсов на участке недр, в границах которого осуществляется деятельность, связанная с поиском, оценкой и (или) разведкой нового морского месторождения углеводородного сырья, с учетом особенностей, установленных пунктом 7 статьи 261 настоящего\n\n2) расходы в виде процентов по договорам займа, кредита и другим долговым обязательствам в случае, если соответствующие заемные средства были привлечены для финансирования деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья;\n\n3) расходы в виде сумм дебиторской задолженности по займу, кредиту или другим долговым обязательствам (включая суммы начисленных процентов), списанной в связи с прощением долга либо по иным основаниям, если соответствующие заемные средства были предоставлены налогоплательщику, указанному в пункте 1 статьи 2752 настоящего Кодекса, для финансирования деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в отношении которого определяется налоговая база;\n\n4) расходы на доставку (транспортировку) углеводородного сырья, добытого на новом морском месторождении углеводородного сырья, а также продуктов его технологического передела (сжиженного природного газа, стабильного конденсата и широкой фракции легких углеводородов) получателям;\n\n5) расходы организации - оператора нового морского месторождения углеводородного сырья в виде компенсации понесенных ранее расходов организации - владельца лицензии на пользование участком недр, в границах которого расположено новое морское месторождение углеводородного сырья либо в границах которого предполагается осуществлять поиск, оценку и (или) разведку нового морского месторождения углеводородного сырья, связанных с получением такой лицензии. К расходам, указанным в настоящем подпункте, относятся, в частности, платежи (бонусы, компенсации) за коммерческое открытие нового морского месторождения углеводородного сырья на соответствующем участке недр, а также любые другие аналогичные платежи;\n\n6) расходы в виде отрицательной курсовой разницы, возникающей при переоценке требований (обязательств), за исключением переоценки выданных (полученных) авансов, включая задолженность по уплате процентов, если соответствующие требования (обязательства) возникли в связи с осуществлением деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья. (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n3. К расходам, указанным в подпункте 4 пункта 2 настоящей статьи, относятся, в частности, расходы на доставку (транспортировку) магистральными трубопроводами, железнодорожным, водным и другим транспортом, расходы на слив, налив, погрузку, разгрузку и перегрузку, на оплату услуг в портах и транспортно-экспедиционных услуг, а также расходы на сжижение и регазификацию газа природного горючего. При этом в состав расходов на доставку (транспортировку) не включается сумма амортизации по основным средствам, принадлежащим налогоплательщику, указанному в пункте 1 статьи 2752 настоящего Кодекса, и используемым при доставке (транспортировке) углеводородного сырья.\n\n4. Расходы, которые не могут быть непосредственно отнесены к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, или к иной деятельности налогоплательщика, а также расходы, относящиеся к деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, осуществляемой в отношении нескольких месторождений, учитываются при определении налоговой базы в соответствии с положениями статьи 2752 настоящего Кодекса в доле, определяемой налогоплательщиком в соответствии с порядком распределения расходов. Указанный порядок устанавливается налогоплательщиком в учетной политике для целей налогообложения и подлежит применению в течение не менее пяти налоговых периодов.\n\n5. Налогоплательщик вправе обратиться в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, с заявлением о согласовании порядка распределения расходов, указанного в пункте 4 настоящей статьи. Форма заявления и порядок согласования указанного порядка устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 268-ФЗ)","article_title":"Статья 299.4. Особенности определения расходов, связанных с осуществлением деятельности по добыче углеводородного сырья на новом морском месторождении углеводородного сырья","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c0b582df6c0457d885c1d98965262b220cbde877288506d2378f4ba04ceca4d"},{"code_id":"NK_RF_2","article_number":"299.5","version_date":"2000-07-31","article_text":"1. К доходам налогоплательщиков - эмитентов российских депозитарных расписок относятся доходы, предусмотренные статьями 249 и 250 настоящего Кодекса, определяемые с учетом особенностей, предусмотренных настоящей статьей.\n\n2. При определении налоговой базы эмитентов российских депозитарных расписок не учитываются следующие доходы:\n\n1) денежные средства и иное имущество, имущественные права, которые получены эмитентом российских депозитарных расписок в связи с размещением таких расписок, за исключением денежных сумм, имущества, имущественных прав, полученных эмитентом российских депозитарных расписок в качестве вознаграждения за его услуги;\n\n2) денежные средства и иное имущество, имущественные права, которые получены эмитентом российских депозитарных расписок в связи с осуществлением им прав, закрепленных представляемыми ценными бумагами.\n\n3. К расходам налогоплательщиков - эмитентов российских депозитарных расписок относятся расходы, предусмотренные статьями 254 - 269 настоящего Кодекса, определяемые с учетом особенностей, предусмотренных настоящей статьей.\n\n4. При определении налоговой базы эмитентов российских депозитарных расписок не учитываются следующие расходы:\n\n1) денежные средства и иное имущество, имущественные права, переданные (уплаченные) эмитентом российских депозитарных расписок эмитенту или владельцам представляемых ценных бумаг в связи с размещением российских депозитарных расписок;\n\n2) денежные средства и иное имущество, имущественные права, которые переданы эмитентом российских депозитарных расписок владельцам российских депозитарных расписок в связи с осуществлением прав по российским депозитарным распискам.\n\n(Дополнение статьей - Федеральный закон от 28.12.2013 № 420-ФЗ)","article_title":"Статья 299.5. Особенности определения доходов и расходов эмитентов российских депозитарных расписок","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3ba5feb279ad7c0fb28a9b6ba330f86cd6b3b64a84267e61d5a8d133def089a"},{"code_id":"NK_RF_2","article_number":"300","version_date":"2000-07-31","article_text":"Профессиональные участники рынка ценных бумаг признаются осуществляющими дилерскую деятельность, если дилерская деятельность предусмотрена соответствующей лицензией, выданной участнику рынка ценных бумаг в установленном порядке.\n\nПрофессиональные участники рынка ценных бумаг, осуществляющие дилерскую деятельность, вправе относить на расходы в целях налогообложения отчисления в резервы под обесценение ценных бумаг в случае, если такие налогоплательщики определяют доходы и расходы по методу начисления. В таком случае суммы восстановленных резервов под обесценение ценных бумаг, отчисления на создание (корректировку) которых ранее были учтены при определении налоговой базы, признаются доходом указанных налогоплательщиков.\n\nУказанные резервы под обесценение ценных бумаг создаются (корректируются) по состоянию на конец отчетного (налогового) периода в размере превышения цен приобретения эмиссионных ценных бумаг, обращающихся на организованном рынке ценных бумаг, над их рыночной котировкой (расчетная величина резерва). При этом в цену приобретения ценной бумаги в целях настоящей главы также включаются расходы по ее приобретению. В 2022 году для целей настоящей статьи к обращающимся ценным бумагам относятся необращающиеся ценные бумаги, которые в период с 1 января до 1 марта 2022 года в соответствии с положениями настоящего Кодекса относились к обращающимся ценным бумагам. (В редакции  Федерального закона от 21.11.2022 № 443-ФЗ)\n\nРезервы создаются (корректируются) в отношении каждой ценной бумаги одного выпуска (дополнительного выпуска) ценных бумаг, удовлетворяющего указанным требованиям, независимо от изменения стоимости ценных бумаг других выпусков (дополнительных выпусков). (В редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\nПри реализации или ином выбытии ценных бумаг, в отношении которых ранее создавался резерв, отчисления на создание (корректировку) которого ранее были учтены при определении налоговой базы, сумма такого резерва подлежит включению в доходы налогоплательщика на дату реализации или иного выбытия ценной бумаги.\n\nВ случае, если по окончании отчетного (налогового) периода сумма резерва с учетом рыночных котировок ценных бумаг на конец этого периода оказывается недостаточна, налогоплательщик увеличивает сумму резерва в установленном выше порядке, и отчисления на увеличение резерва учитываются в составе расходов в целях налогообложения. Если на конец отчетного (налогового) периода сумма ранее созданного резерва с учетом восстановленных сумм превышает расчетную величину, резерв уменьшается налогоплательщиком (восстанавливается) до расчетной величины с включением в доходы суммы такого восстановления.\n\nРезервы под обесценение ценных бумаг создаются в валюте Российской Федерации независимо от валюты номинала ценной бумаги. Для ценных бумаг, номинированных в иностранной валюте, цена приобретения пересчитывается в рублях по официальному курсу Центрального банка Российской Федерации на дату приобретения ценной бумаги, а их рыночная котировка - по официальному курсу Центрального банка Российской Федерации на дату создания (корректировки) резерва. (В редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\nДля ценных бумаг, условиями выпуска которых предусмотрено частичное погашение их номинальной стоимости, при формировании (корректировке) резерва по состоянию на конец отчетного (налогового) периода цена приобретения корректируется с учетом доли частичного погашения номинальной стоимости ценной бумаги. (Дополнение частью - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\nНалогоплательщик, являющийся продавцом по первой части РЕПО или заимодавцем по операции займа ценными бумагами, не вправе формировать резервы под обесценение ценных бумаг по ценным бумагам, переданным по операции РЕПО (договору займа). (Дополнение частью - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\nНалогоплательщик, являющийся покупателем по первой части РЕПО или заемщиком по операции займа ценными бумагами, вправе формировать резервы под обесценение ценных бумаг по ценным бумагам, полученным по операции РЕПО (договору займа). (Дополнение частью - Федеральный закон от 25.11.2009 № 281-ФЗ)","article_title":"Статья 300. Расходы на формирование резервов под обесценение ценных бумаг у профессиональных участников рынка ценных бумаг, осуществляющих дилерскую деятельность","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"122dc43431cb84cd084cd228eeb9e3e99768412bf1908f62c6ada4bd81cf5f90"},{"code_id":"NK_RF_2","article_number":"301","version_date":"2000-07-31","article_text":"Абзац. (Утратил силу - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nВ целях настоящей главы не признается производным финансовым инструментом договор, требования по которому не подлежат судебной защите в соответствии с гражданским законодательством Российской Федерации и (или) применимым законодательством иностранных государств. Убытки, полученные от указанного договора, не учитываются при определении налоговой базы. (В редакции федеральных законов от 28.12.2013 № 420-ФЗ; от 03.07.2016 № 242-ФЗ)\n\nПод базисным активом производных финансовых инструментов понимается предмет срочной сделки (в том числе иностранная валюта, ценные бумаги и иное имущество и имущественные права, процентные ставки, кредитные ресурсы, индексы цен или процентных ставок, другие производные финансовые инструменты). (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nПод участниками срочных сделок понимаются организации, совершающие операции с производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\nНалогоплательщик вправе с учетом требований настоящей статьи самостоятельно квалифицировать сделку, условия которой предусматривают поставку базисного актива, признавая ее операцией с производным финансовым инструментом либо сделкой на поставку предмета сделки с отсрочкой исполнения. Критерии отнесения сделок, предусматривающих поставку предмета сделки (за исключением операций хеджирования), к категории операций с производными финансовыми инструментами должны быть определены налогоплательщиком в учетной политике для целей налогообложения. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 25.11.2009 № 281-ФЗ; от 03.07.2016 № 242-ФЗ)\n\nДатой окончания операции с производным финансовым инструментом является дата исполнения прав и обязанностей по операции с производным финансовым инструментом. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nОбязательства по производному финансовому инструменту без его переквалификации могут быть прекращены: (Дополнение абзацем - Федеральный закон от 25.11.2009 № 281-ФЗ) (В редакции федеральных законов от 28.12.2013 № 420-ФЗ; от 03.07.2016 № 242-ФЗ)\n\nзачетом (взаимозачетом) однородных требований и обязательств; (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nв порядке, определенном генеральным соглашением (единым договором), которое соответствует примерным условиям договоров, утвержденным в соответствии с Федеральным законом \"О рынке ценных бумаг\", если такое прекращение предусматривает определение суммы нетто-обязательства; (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nзачетом встречных требований, вытекающих из договоров, заключенных на условиях правил организованных торгов или правил клиринга, если такой зачет произведен в целях определения суммы нетто-обязательства. (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nВ целях настоящей статьи однородными признаются в том числе требования по поставке имеющих одинаковый объем прав ценных бумаг одного эмитента, одного вида, одной категории (типа) или одного паевого инвестиционного фонда (для инвестиционных паев паевых инвестиционных фондов), а также требования по уплате денежных средств в той же валюте. (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nНалогообложение сделок, квалифицированных как сделки на поставку предмета сделки с отсрочкой исполнения, осуществляется в порядке, предусмотренном настоящим Кодексом для соответствующих базисных активов таких сделок. (Дополнение абзацем - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\n1) порядок их заключения, обращения и исполнения устанавливается организатором торговли, имеющим на это право в соответствии с законодательством Российской Федерации или законодательством иностранных государств;\n\n2) информация о ценах производных финансовых инструментов публикуется в средствах массовой информации (в том числе электронных) либо может быть предоставлена организатором торговли или иным уполномоченным лицом любому заинтересованному лицу в течение трех лет после даты совершения операции с производным финансовым инструментом. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nСделка, которая заключается не на организованном рынке и условия которой не предусматривают поставки базисного актива, может быть квалифицирована только как производный финансовый инструмент. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\nСделки, квалифицированные как поставочные срочные сделки, а также как сделки на поставку предмета сделки с отсрочкой исполнения, в целях настоящей главы не подлежат переквалификации в расчетные срочные сделки в случае прекращения обязательств способами, отличными от надлежащего исполнения.\n\n(Дополнение пунктом - Федеральный закон от 25.11.2009 № 281-ФЗ)\n\nПод объектами хеджирования признаются имущество, имущественные права налогоплательщика, его обязательства, в том числе права требования и обязанности, носящие денежный характер, срок исполнения которых на дату совершения операции хеджирования не на\n\nступил, включая права требования и обязанности, осуществление (исполнение) которых обусловлено предъявлением требования стороны по договору и в отношении которых налогоплательщик принял решение о хеджировании. Базисные активы производных финансовых инструментов, которые используются для операции хеджирования, могут отличаться от объекта хеджирования. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nВ целях хеджирования допускается заключение более одного производного финансового инструмента разных видов, включая заключение нескольких производных финансовых инструментов в рамках одной операции хеджирования в течение срока хеджирования. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nДля подтверждения обоснованности отнесения операции (совокупности операций) с производными финансовыми инструментами к операции хеджирования налогоплательщик составляет на дату заключения данных сделок (первой из сделок - при заключении нескольких сделок в рамках одной операции хеджирования) по операции хеджирования справку, подтверждающую, что исходя из прогнозов налогоплательщика совершение данной операции (совокупности операций) позволяет уменьшить неблагоприятные последствия, связанные с изменением цены (в том числе рыночной котировки, курса) или иного показателя объекта хеджирования. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)","article_title":"Статья 301. Срочные сделки. Особенности налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"daa675e47d3a6502e70c2099f47e786e9956b5cd96d5bc9f7d229ef384b5e5b8"},{"code_id":"NK_RF_2","article_number":"302","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n1) сумма вариационной маржи, причитающейся к получению налогоплательщиком в течение отчетного (налогового) периода;\n\n2) иные суммы, причитающиеся к получению в течение отчетного (налогового) периода по операциям с производными финансовыми инструментами, обращающимися на организованном рынке, в том числе в порядке расчетов по операциям с производными финансовыми инструментами, предусматривающим поставку базисного актива. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n1) сумма вариационной маржи, подлежащая уплате налогоплательщиком в течение налогового (отчетного) периода;\n\n2) иные суммы, подлежащие уплате в течение налогового (отчетного) периода по операциям с производными финансовыми инструментами, обращающимися на организованном рынке, а также стоимость базисного актива, передаваемого по сделкам, предусматривающим поставку базисного актива; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n3) иные расходы, связанные с осуществлением операций с производными финансовыми инструментами, обращающимися на организованном рынке. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)","article_title":"Статья 302. Особенности формирования доходов и расходов налогоплательщика по операциям с производными финансовыми инструментами, обращающимися на организованном рынке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0fd1aae6e53ead71e9bfbf89715c15c0a1d64f26779601c8eeef25dc311d9d73"},{"code_id":"NK_RF_2","article_number":"303","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n1) суммы денежных средств, причитающиеся к получению в отчетном (налоговом) периоде одним из участников операции с производным финансовым инструментом при ее исполнении (окончании); (В редакции федеральных законов от 25.11.2009 № 281-ФЗ; от 03.07.2016 № 242-ФЗ)\n\n2) иные суммы, причитающиеся к получению в течение налогового (отчетного) периода по операциям с производными финансовыми инструментами, не обращающимися на организованном рынке, в том числе в порядке расчетов по операциям с производными финансовыми инструментами, предусматривающим поставку базисного актива. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n1) суммы денежных средств, подлежащие уплате в отчетном (налоговом) периоде одним из участников операции с производным финансовым инструментом при ее исполнении (окончании); (В редакции федеральных законов от 25.11.2009 № 281-ФЗ; от 03.07.2016 № 242-ФЗ)\n\n2) иные суммы, подлежащие уплате в течение налогового (отчетного) периода по операциям с производными финансовыми инструментами, не обращающимися на организованном рынке, а также стоимость базисного актива, передаваемого по сделкам, предусматривающим поставку базисного актива; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n3) иные расходы, связанные с осуществлением операций с производными финансовыми инструментами. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)","article_title":"Статья 303. Особенности формирования доходов и расходов налогоплательщика по операциям с производными финансовыми инструментами, не обращающимися на организованном рынке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05bd0e7c55e7ab0438ae897cb17205e4fa0ba97f11e4dac582fa4de8d8ded097"},{"code_id":"NK_RF_2","article_number":"304","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nБанки вправе уменьшить налоговую базу по прибыли, облагаемой по ставке, указанной в пункте 1 статьи 284 настоящего Кодекса, в отношении которой в соответствии с настоящей главой не предусмотрен отличный от общего порядок учета прибыли и убытка, на сумму убытка, полученного по операциям с поставочными срочными сделками, которые не обращаются на организованном рынке и базисным активом которых выступает иностранная валюта. (В редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nПрофессиональные участники рынка ценных бумаг, осуществляющие дилерскую деятельность, включая банки, вправе уменьшить налоговую базу по прибыли, облагаемой по ставке, указанной в пункте 1 статьи 284 настоящего Кодекса, в отношении которой в соответствии с настоящей главой не предусмотрен отличный от общего порядок учета прибыли и убытка, на сумму убытка, полученного по операциям с производными финансовыми инструментами, не обращающимися на организованном рынке. (В редакции федеральных законов от 28.12.2013 № 420-ФЗ; от 03.07.2016 № 242-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nПри заключении своп-контрактов и опционных контрактов, не обращающихся на организованном рынке, стороной по которым выступает центральный контрагент, который осуществляет свои функции в соответствии с законодательством о клиринговой деятельности и правилами клиринга и качество управления которого признано удовлетворительным в порядке, установленном Центральным банком Российской Федерации, налогоплательщик вправе учитывать доходы (расходы) по таким контрактам при определении налоговой базы по прибыли, облагаемой по ставке, указанной в пункте 1 статьи 284 настоящего Кодекса, в отношении которой в соответствии с настоящей главой не предусмотрен отличный от общего порядок учета прибыли и убытка. (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nЕсли налогоплательщик не воспользовался правом, предусмотренным предыдущим абзацем настоящего пункта, он вправе учитывать доходы (расходы) по всем базисным активам, причитающимся к получению за отчетный (налоговый) период по таким контрактам, при определении налоговой базы по необращающимся ценным бумагам и необращающимся производным финансовым инструментам. (Дополнение абзацем - Федеральный закон от 28.12.2013 № 420-ФЗ) (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\nДатами признания доходов (расходов) по такой операции признаются даты выплат, предусмотренные соответствующим договором.\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)","article_title":"Статья 304. Особенности определения налоговой базы по операциям с производными финансовыми инструментами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f54064bd5dafe37e2433a2f4e30874765f04697e27c132a66ad889262978291e"},{"code_id":"NK_RF_2","article_number":"305","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nЕсли фактическая цена необращающегося производного финансового инструмента отличается более чем на 20 процентов в сторону повышения (понижения) от расчетной стоимости этого финансового инструмента, доходы (расходы) налогоплательщика определяются исходя из расчетной стоимости, увеличенной (уменьшенной) на 20 процентов. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nВ отношении сделок, не признаваемых контролируемыми в соответствии с разделом V1 настоящего Кодекса, фактическая цена необращающегося производного финансового инструмента признается рыночной ценой и применяется для целей налогообложения. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)","article_title":"Статья 305. Особенности оценки для целей налогообложения операций с производными финансовыми инструментами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff749fb5698634fddc410e2ce0989b07a81d3fc122e553e9f592907285160946"},{"code_id":"NK_RF_2","article_number":"306","version_date":"2000-07-31","article_text":"1. Положениями статей 306 - 309 настоящего Кодекса устанавливаются особенности исчисления налога иностранными организациями, осуществляющими предпринимательскую деятельность на территории Российской Федерации, в случае, если такая деятельность создает постоянное представительство иностранной организации, а также исчисления налога иностранными организациями, не связанными с деятельностью через постоянное представительство в Российской Федерации, получающими доход из источников в Российской Федерации.\n\n2. Под постоянным представительством иностранной организации в Российской Федерации для целей настоящей главы понимается филиал, представительство, отделение, бюро, контора, агентство, любое другое обособленное подразделение или иное место деятельности этой организации (далее в настоящей главе - отделение), через которое организация регулярно осуществляет предпринимательскую деятельность на территории Российской Федерации, связанную с:\n\nпользованием недрами и (или) использованием других природных ресурсов;\n\nпроведением предусмотренных контрактами работ по строительству, установке, монтажу, сборке, наладке, обслуживанию и эксплуатации оборудования, в том числе игровых автоматов;\n\nпродажей товаров с расположенных на территории Российской Федерации и принадлежащих этой организации или арендуемых ею складов;\n\nосуществлением иных работ, оказанием услуг, ведением иной деятельности, за исключением предусмотренной пунктом 4 настоящей статьи.\n\nДеятельностью иностранной организации на территории Российской Федерации в целях настоящего Кодекса также признается деятельность, осуществляемая иностранной организацией - оператором нового морского месторождения углеводородного сырья и связанная с добычей углеводородного сырья на новом морском месторождении углеводородного сырья. (Дополнение абзацем - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n3. Постоянное представительство иностранной организации считается образованным с начала регулярного осуществления предпринимательской деятельности через ее отделение. При этом деятельность по созданию отделения сама по себе не создает постоянного представительства. Постоянное представительство прекращает существование с момента прекращения предпринимательской деятельности через отделение иностранной организации.\n\nПри пользовании недрами и (или) использовании других природных ресурсов постоянное представительство иностранной организации считается образованным с более ранней из следующих дат: даты вступления в силу лицензии (разрешения), удостоверяющей право этой организации на осуществление соответствующей деятельности, или даты фактического начала такой деятельности. В случае, если иностранная организация выполняет работы, оказывает услуги другому лицу, имеющему указанную лицензию (разрешение) или выступающему в качестве генерального подрядчика для лица, имеющего такую лицензию (разрешение), при решении вопросов, связанных с образованием и прекращением существования постоянного представительства этой иностранной организации, применяется порядок, аналогичный установленному пунктами 2 - 4 статьи 308 настоящего Кодекса.\n\n4. Факт осуществления иностранной организацией на территории Российской Федерации деятельности подготовительного и вспомогательного характера при отсутствии признаков постоянного представительства, предусмотренных пунктом 2 настоящей статьи, не может рассматриваться как приводящий к образованию постоянного представительства. К подготовительной и вспомогательной деятельности, в частности, относятся:\n\n1) использование сооружений исключительно для целей хранения, демонстрации и (или) поставки товаров, принадлежащих этой иностранной организации, до начала такой поставки;\n\n2) содержание запаса товаров, принадлежащих этой иностранной организации, исключительно для целей их хранения, демонстрации и (или) поставки до начала такой поставки;\n\n(Подпункт 3 исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\n3) содержание постоянного места деятельности исключительно для целей закупки товаров этой иностранной организацией; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n4) содержание постоянного места деятельности исключительно для сбора, обработки и (или) распространения информации, ведения бухгалтерского учета, маркетинга, рекламы или изучения рынка товаров (работ, услуг), реализуемых иностранной организацией, если такая деятельность не является основной (обычной) деятельностью этой организации; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n5) содержание постоянного места деятельности исключительно для целей простого подписания контрактов от имени этой организации, если подписание контрактов происходит в соответствии с детальными письменными инструкциями иностранной организации.(В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПоложения настоящего пункта не распространяются на постоянное место деятельности, которое используется или эксплуатируется иностранной организацией, если данная организация или взаимозависимая с ней организация осуществляет предпринимательскую деятельность в этом месте или в любом другом месте на территории Российской Федерации и при этом такая деятельность приводит к образованию постоянного представительства данной организации или взаимозависимой с ней организации в соответствии с положениями настоящей статьи, определяющими постоянное представительство, или совокупная деятельность в результате комбинации деятельности, осуществляемой данной организацией и взаимозависимой с ней организацией в этом месте или данной организацией либо взаимозависимыми организациями в двух разных местах, не носит подготовительный или вспомогательный характер при условии, что предпринимательская деятельность, осуществляемая данной организацией и взаимо\n\nзависимой с ней организацией в этом месте или данной организацией либо взаимозависимыми организациями в двух разных местах, представляет собой взаимодополняющие функции, которые являются частью единого бизнес-процесса, относящегося к предпринимательской деятельности. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n5. Факт владения иностранной организацией ценными бумагами, долями в капитале российских организаций, а также иным имуществом на территории Российской Федерации при отсутствии признаков постоянного представительства, предусмотренных пунктом 2 настоящей статьи, сам по себе не может рассматриваться для такой иностранной организации как приводящий к образованию постоянного представительства в Российской Федерации.\n\nФакт осуществления на территории Российской Федерации управляющим лицом иностранного инвестиционного фонда (компании), указанным в пункте 14 статьи 2513 настоящего Кодекса, а также нанятыми им лицами, их сотрудниками и (или) представителями функций по управлению активами такого фонда (компании) и факт осуществления функций, указанных в пункте 3 статьи 2462 настоящего Кодекса, в отношении фонда или организаций (структур без образования юридического лица), в которых прямо или косвенно участвует такой фонд (компания), а также иной деятельности, непосредственно связанной с реализацией указанных функций, сами по себе не могут рассматриваться как приводящие к образованию постоянного представительства в Российской Федерации указанного фонда (компании), иностранных организаций (структур без образования юридического лица), в которых прямо или косвенно участвует такой фонд (компания), и (или) прямых или косвенных акционеров (участников, пайщиков, партнеров) указанного фонда (компании). (Дополнение абзацем - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\n6. Факт заключения иностранной организацией договора простого товарищества или иного договора, предполагающего совместную деятельность его сторон (участников), осуществляемую полностью или частично на территории Российской Федерации, сам по себе не может рассматриваться для данной организации как приводящий к образованию постоянного представительства в Российской Федерации.\n\nДеятельность иностранной организации не приводит к образованию постоянного представительства в Российской Федерации, если такая организация осуществляет деятельность на территории Российской Федерации через брокера, комиссионера, управляющее лицо иностранного инвестиционного фонда (компании), указанное в пункте 14 статьи 2513 настоящего Кодекса, профессионального участника российского рынка ценных бумаг или любое другое лицо, действующее в рамках своей основной (обычной) деятельности (независимый агент). (В редакции  федеральных законов от 28.12.2017 № 436-ФЗ, от 31.07.2023 № 389-ФЗ)","article_title":"Статья 306. Особенности налогообложения иностранных организаций. Постоянное представительство иностранной организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8310235bab4f830b29d72baf8441336d05d31c18b664b7e52c63d81d3e38d48e"},{"code_id":"NK_RF_2","article_number":"307","version_date":"2000-07-31","article_text":"1. Объектом налогообложения для иностранных организаций, осуществляющих деятельность в Российской Федерации через постоянное представительство, признается:\n\nдоход, полученный иностранной организацией в результате осуществления деятельности на территории Российской Федерации через ее постоянное представительство, уменьшенный на величину произведенных этим постоянным представительством расходов, определяемых с учетом положений пункта 4 настоящей статьи;\n\nдоходы иностранной организации от владения, пользования и (или) распоряжения имуществом постоянного представительства этой организации в Российской Федерации за вычетом расходов, связанных с получением таких доходов;\n\nдругие доходы от источников в Российской Федерации, указанные в пункте 1 статьи 309 настоящего Кодекса, относящиеся к постоянному представительству.\n\n2. Налоговая база определяется как денежное выражение объекта налогообложения, установленного пунктом 1 настоящей статьи.\n\nПри определении налоговой базы иностранной некоммерческой организации учитываются положения пункта 2 статьи 251 настоящего Кодекса.\n\n3. В случае, если иностранная организация осуществляет на территории Российской Федерации деятельность подготовительного и (или) вспомогательного характера в интересах третьих лиц, приводящую к образованию постоянного представительства, и при этом в отношении такой деятельности не предусмотрено получение вознаграждения, налоговая база определяется в размере 20 процентов от суммы расходов этого постоянного представительства, связанных с такой деятельностью.\n\n4. При наличии у иностранной организации на территории Российской Федерации более чем одного отделения, деятельность через которые приводит к образованию постоянного представительства, налоговая база и сумма налога рассчитываются отдельно по каждому отделению.\n\nВ случае, если иностранная организация осуществляет через такие отделения деятельность в рамках единого технологического процесса, или в других аналогичных случаях по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, такая организация вправе рассчитывать налогооблагаемую прибыль, относящуюся к ее деятельности через отделение на территории Российской Федерации, в целом по группе таких отделений (в том числе по всем отделениям) при условии применения всеми включенными в группу отделениями единой учетной политики в целях налогообложения. При этом иностранная организация самостоятельно определяет, какое из отделений будет вести налоговый учет, а также представлять налоговые декларации по месту нахождения каждого отделения. Сумма налога на прибыль, подлежащая уплате в бюджет в таком случае, распределяется между отделениями в общем порядке, предусмотренном статьей 288 настоящего Кодекса. При этом не учитываются стоимость основных средств и нематериальных активов, а также среднесписочная численность работников (фонд оплаты труда работников), не относящихся к деятельности иностранной организации на территории Российской Федерации через постоянное представительство. (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 29.07.2004 № 95-ФЗ)\n\nИностранная организация - оператор нового морского месторождения углеводородного сырья, осуществляющая более чем через одно отделение деятельность на территории Российской Федерации (или признаваемую таковой в соответствии с пунктом 2 статьи 306 настоящего Кодекса), связанную с добычей углеводородного сырья на указанном новом морском месторождении углеводородного сырья, вправе определять налоговую базу по такой деятельности, относящейся к одному и тому же новому морскому месторождению углеводородного сырья, в целом по группе таких отделений (в том числе по всем отделениям) при условии применения всеми включенными в группу отделениями единой учетной политики в целях налогообложения. При этом иностранная организация самостоятельно определяет, какое из отделений будет вести налоговый учет и представлять налоговые декларации по месту нахождения каждого отделения. В этом случае уплата налога производится через одно из таких отделений по выбору налогоплательщика. Уведомление о выборе отделения, через которое производится уплата налога, направляется налогоплательщиком в налоговые органы по месту нахождения каждого из отделений до 30 ноября года, предшествующего налоговому периоду. (Дополнение абзацем - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\nНалоговая декларация по итогам налогового (отчетного) периода, а также годовой отчет о деятельности в Российской Федерации по форме, утверждаемой федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, представляются иностранной организацией, осуществляющей деятельность в Российской Федерации через постоянное представительство, в налоговый орган по месту нахождения постоянного представительства этой организации в порядке и в сроки, установленные статьей 289 настоящего Кодекса. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 29.06.2004 № 58-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nАбзац. (Исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nПри прекращении деятельности постоянного представительства иностранной организации в Российской Федерации до окончания налогового периода налоговая декларация за последний отчетный период представляется иностранной организацией в течение месяца со дня прекращения деятельности постоянного представительства. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nУказанные в настоящем пункте обстоятельства принимаются во внимание при распределении доходов и расходов между иностранной организацией и ее постоянным представительством в Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 307. Особенности налогообложения иностранных организаций, осуществляющих деятельность через постоянное представительство в Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"813c725277eac9f96103bc57b8da8be9e2dbf5ecbe987695fba02ea0bc204650"},{"code_id":"NK_RF_2","article_number":"308","version_date":"2000-07-31","article_text":"1. Под строительной площадкой иностранной организации на территории Российской Федерации в целях настоящей главы понимается:\n\n1) место строительства новых, а также реконструкции, технического перевооружения и (или) ремонта существующих объектов недвижимого имущества (за исключением воздушных и морских судов, судов внутреннего плавания и космических объектов); (В редакции Федерального закона от 18.07.2011 № 215-ФЗ)\n\n2) место строительства и (или) монтажа, ремонта, реконструкции и (или) технического перевооружения сооружений, в том числе плавучих и буровых установок, а также машин и оборудования, нормальное функционирование которых требует жесткого крепления на фундаменте или к конструктивным элементам зданий, сооружений или плавучих сооружений. (В редакции Федерального закона от 18.07.2011 № 215-ФЗ)\n\n2. При определении срока существования строительной площадки в целях исчисления налога, а также постановки на учет иностранной организации в налоговых органах работы и иные операции, продолжительность которых включается в этот срок, включают все виды производимых иностранной организацией на этой строительной площадке подготовительных, строительных и (или) монтажных работ, в том числе работ по созданию подъездных путей, коммуникаций, электрических кабелей, дренажа и других объектов инфраструктуры, кроме объектов инфраструкт\n\nуры, изначально создаваемых для иных целей, не связанных с данной строительной площадкой.\n\nВ случае, если иностранная организация, являясь генеральным подрядчиком, поручает выполнение части подрядных работ другим лицам (субподрядчикам), то период времени, затраченный субподрядчиками на выполнение работ, считается временем, затраченным самим генеральным подрядчиком. Настоящее положение не применяется в отношении периода работ, выполняемых субподрядчиком по прямым договорам с застройщиком или техническим заказчиком и не входящих в объем работ, порученных генеральному подрядчику, за исключением случаев, когда эти лица и генеральный подрядчик являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса. (В редакции федеральных законов от 18.07.2011 № 227-ФЗ; от 28.11.2011 № 337-ФЗ)\n\nВ случае, если субподрядчик является иностранной организацией, его деятельность на этой строительной площадке также рассматривается как создающая постоянное представительство этой организации-субподрядчика.\n\nДанное положение применяется к организации-субподрядчику, продолжительность деятельности которой составляет в совокупности не менее 30 календарных дней, при условии, что генподрядчик имеет постоянное представительство. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n3. Началом существования строительной площадки в налоговых целях считается более ранняя из следующих дат: дата подписания акта о передаче площадки подрядчику (акта о допуске персонала субподрядчика для выполнения его части совокупного объема работ) или дата фактического начала работ.\n\nОкончанием существования стройплощадки является дата подписания застройщиком или техническим заказчиком акта сдачи-приемки объекта или предусмотренного договором комплекса работ. Окончанием работ субподрядчика считается дата подписания акта сдачи-приемки работ генеральному подрядчику. В случае, если акт сдачи-приемки не оформлялся или работы фактически окончились после подписания такого акта, строительная площадка считается прекратившей существование (работы субподрядчика считаются законченными) на дату фактического окончания подготовительных, строительных или монтажных работ, входящих в объем работ соответствующего лица на данной стройплощадке. (В редакции Федерального закона от 28.11.2011 № 337-ФЗ)\n\nПродолжение или возобновление после перерыва работ на строительном объекте после подписания акта, указанного в пункте 3 настоящей статьи, приводит к присоединению срока ведения продолжающихся или возобновленных работ и перерыва между работами к совокупному сроку существования строительной площадки только в случае, если:\n\n1) территория (акватория) возобновленных работ является территорией (акваторией) прекращенных ранее работ или вплотную примыкает к ней;\n\n2) продолжающиеся или возобновленные работы на объекте поручены лицу, ранее выполнявшему работы на этой строительной площадке, или новый и прежний подрядчики являются взаимозависимыми лицами.\n\nЕсли продолжение или возобновление работ связано со строительством или монтажом нового объекта на той же строительной площадке либо с реконструкцией ранее законченного объекта, срок ведения таких продолжающихся или возобновленных работ и перерыва между работами также присоединяется к совокупному сроку существования строительной площадки. (В редакции Федерального закона от 18.07.2011 № 215-ФЗ)\n\nВ остальных случаях, включая выполнение ремонта, реконструкции или технического перевооружения ранее сданного застройщику или техническому заказчику объекта, срок ведения продолжающихся или возобновленных работ и перерыв между работами не подлежит присоединению к совокупному сроку существования строительной площадки, начатому работами по сданному ранее объекту. (В редакции Федерального закона от 28.11.2011 № 337-ФЗ)","article_title":"Статья 308. Особенности налогообложения иностранных организаций при осуществлении деятельности на строительной площадке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b1fecd3b12e068116a0076a27742de6f33fa9b236e167fed0f9d0c802d8cccf5"},{"code_id":"NK_RF_2","article_number":"309","version_date":"2000-07-31","article_text":"1) дивиденды, выплачиваемые иностранной организации - акционеру (участнику) российских организаций. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nДля целей настоящей статьи к доходам в виде дивидендов относится также доход от доверительного управления составляющим паевой инвестиционный фонд имуществом, выплачиваемый иностранной организации - пайщику по принадлежащим ей инвестиционным паям пропорционально доле в праве общей собственности на имущество, составляющее этот фонд; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n2) доходы, получаемые в результате распределения в пользу иностранных организаций прибыли или имущества организаций, иных лиц или их объединений, в том числе при их ликвидации (с учетом положений абзаца второго пункта 1 части второй статьи 250 настоящего Кодекса); (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n3) процентный доход от следующих долговых обязательств любого вида, включая облигации с правом на участие в прибылях и конвертируемые облигации:\n\nгосударственные и муниципальные эмиссионные ценные бумаги, условиями выпуска и обращения которых предусмотрено получение доходов в виде процентов;\n\nиные долговые обязательства российских организаций, индивидуальных предпринимателей, не указанные в абзаце втором настоящего подпункта; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nдолговые обязательства иностранных организаций, осуществляющих деятельность в Российской Федерации через постоянное представительство, при условии, что задолженность, по которой выплачиваются проценты, возникла в связи с деятельностью указанного постоянного представительства; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n(Подпункт в редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n4) доходы от использования в Российской Федерации прав на объекты интеллектуальной собственности. К таким доходам, в частности, относятся платежи любого вида, получаемые в качестве возмещения за использование или за предоставление права использования любого авторского права на произведения литературы, искусства или науки, включая кинематографические фильмы и фильмы или записи для телевидения или радиовещания, использование (предоставление права использования) любых патентов, товарных знаков, чертежей или моделей, планов, секретной формулы или процесса, либо использование (предоставление права использования) информации, касающейся промышленного, коммерческого или научного опыта;\n\n5) доходы от реализации акций (долей) организаций, более 50 процентов активов которых прямо или косвенно состоит из недвижимого имущества, находящегося на территории Российской Федерации, а также финансовых инструментов, производных от таких акций (долей), за исключением акций, признаваемых обращающимися на организованном рынке ценных бумаг в соответствии с пунктом 9 статьи 280 настоящего Кодекса; (В редакции Федерального закона от 24.11.2014 № 376-ФЗ)\n\n6) доходы от реализации недвижимого имущества, находящегося на территории Российской Федерации;\n\n7) доходы от сдачи в аренду или субаренду имущества, используемого на территории Российской Федерации, в том числе доходы от лизинговых операций, доходы от предоставления в аренду или субаренду морских и воздушных судов и (или) транспортных средств, а также контейнеров, используемых в международных перевозках. При этом доход от лизинговых операций, связанных с приобретением и использованием предмета лизинга лизингополучателем, рассчитывается исходя из всей суммы лизингового платежа за минусом возмещения стоимости лизингового имущества (при лизинге) лизингодателю; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n8) доходы от международных перевозок (в том числе демереджи и прочие платежи, возникающие при перевозках). В целях настоящей статьи термин \"демередж\" употребляется в значении, установленном Кодексом торгового мореплавания Российской Федерации. (В редакции Федерального закона от 06.06.2005 № 58-ФЗ)\n\nПод международными перевозками понимаются любые перевозки морским, речным или воздушным судном, автотранспортным средством или железнодорожным транспортом, за исключением случаев, когда перевозка осуществляется исключительно между пунктами, находящимися за пределами Российской Федерации;\n\n9) штрафы и пени за нарушение российскими лицами, государственными органами и (или) исполнительными органами местного самоуправления договорных обязательств;\n\n91) доходы от реализации (в том числе погашения) инвестиционных паев закрытых паевых инвестиционных фондов, относящихся к категориям рентных фондов или фондов недвижимости, а также комбинированных и иных фондов, более 50 процентов активов которых прямо или косвенно состоит из недвижимого имущества, находящегося на территории Российской Федерации; (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 306-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n92) доходы по операциям с цифровыми финансовыми активами и (или) цифровыми правами, включающими одновременно цифровые финансовые активы и утилитарные цифровые права; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n93) доходы, указанные в пунктах 30 и 31 части второй статьи 250 настоящего Кодекса, выплаченные в пользу иностранной организации - участника соглашения о сервисных рисках или соглашения об управлении финансированием; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n94) доходы, полученные иностранной организацией от выполнения работ (оказания услуг) на территории Российской Федерации взаимозависимому лицу, определяемому в соответствии со статьей 1051 настоящего Кодекса.\n\nВ целях настоящего подпункта работы считаются выполненными (услуги считаются оказанными) на территории Российской Федерации, если покупатель работ (услуг) осуществляет деятельность на территории Российской Федерации. Место осуществления деятельности такого покупателя определяется по месту государственной регистрации организации (месту нахождения постоянного представительства, если работы выполнены (услуги оказаны) постоянному представительству);\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n95) доходы от осуществления майнинга цифровой валюты, полученной в связи с участием в деятельности майнинг-пула; (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n10) иные аналогичные доходы.\n\nПремии по перестрахованию и тантьемы, уплачиваемые иностранному партнеру, не признаются доходами от источников в Российской Федерации.\n\nУказанные расходы иностранной организации учитываются при определении налоговой базы, если к дате выплаты этих доходов в распоряжении налогового агента, удерживающего налог с таких доходов в соответствии с настоящей статьей, имеются представленные этой иностранной организацией документально подтвержденные данные о таких расходах.","article_title":"Статья 309. Особенности налогообложения иностранных организаций, не осуществляющих деятельность через постоянное представительство в Российской Федерации и получающих доходы от источников в Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85262f6de248052f3f4ff7240a25d524359c2c10a5f367c74b740f385c1b8e68"},{"code_id":"NK_RF_2","article_number":"309.1","version_date":"2000-07-31","article_text":"1. Прибылью (убытком) контролируемой иностранной компании признается величина прибыли (убытка) этой компании, определенная одним из следующих способов в соответствии с порядком, установленным настоящей статьей:\n\n1) по данным ее финансовой отчетности, составленной в соответствии с личным законом такой компании за финансовый год. В этом случае прибылью (убытком) контролируемой иностранной компании признается величина прибыли (убытка) этой компании до налогообложения с учетом особенностей, предусмотренных пунктами 3, 31, 7 и 8 настоящей статьи; (В редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\n2) по правилам, установленным настоящей главой для налогоплательщиков - российских организаций.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n11. Определение прибыли (убытка) контролируемой иностранной компании в соответствии с подпунктом 1 пункта 1 настоящей статьи осуществляется при выполнении одного из следующих условий:\n\n1) постоянным местонахождением этой контролируемой иностранной компании является иностранное государство, с которым имеется международный договор Российской Федерации по вопросам налогообложения, за исключением государств (территорий), не обеспечивающих обмена информацией для целей налогообложения с Российской Федерацией;\n\n2) в отношении финансовой отчетности представлено аудиторское заключение, которое не содержит отрицательного мнения или отказа в выражении мнения.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\n12. Определение прибыли (убытка) контролируемой иностранной компании в соответствии с подпунктом 1 пункта 1 настоящей статьи осуществляется с учетом следующих требований:\n\n1) в целях определения прибыли (убытка) контролируемой иностранной компании в соответствии с подпунктом 1 пункта 1 настоящей статьи используется неконсолидированная финансовая отчетность такой компании, составленная в соответствии со стандартом, установленным личным законом такой компании.\n\nВ случае, если личным законом контролируемой иностранной компании не установлен стандарт составления финансовой отчетности, прибыль (убыток) такой контролируемой иностранной компании определяется по данным финансовой отчетности, составленной в соответствии с Международными стандартами финансовой отчетности либо иными международно признанными стандартами составления финансовой отчетности, принимаемыми иностранными фондовыми биржами и иностранными депозитарно-клиринговыми организациями, включенными в перечень иностранных финансовых посредников, для принятия решения о допуске ценных бумаг к торгам. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nПрибыль (убыток) контролируемой иностранной компании определяется по данным финансовой отчетности, составленной в соответствии с Международными стандартами финансовой отчетности либо иными международно признанными стандартами составления финансовой отчетности, принимаемыми иностранными фондовыми биржами и иностранными депозитарно-клиринговыми организациями, включенными в перечень иностранных финансовых посредников, для принятия решения о допуске ценных бумаг к торгам, также в случае, если по состоянию на дату окончания финансового года, за который составляется финансовая отчетность, выполнялось одно из следующих условий: (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nв отношении указанной иностранной компании или налогоплательщика, являющегося контролирующим лицом указанной иностранной компании, действовали введенные иностранными\n\nгосударствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями запретительные, ограничительные и (или) иные аналогичные меры, заключающиеся в установлении запретов и (или) ограничений на предоставление такому налогоплательщику в отношении указанной иностранной компании документов, предусмотренных подпунктом 1 пункта 5 статьи 2515 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nпостоянным местонахождением указанной иностранной компании являлось иностранное государство, включенное в соответствии с законодательством Российской Федерации в перечень иностранных государств и территорий, совершающих в отношении Российской Федерации, российских юридических и физических лиц недружественные действия; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n2) в случае, если в соответствии с личным законом контролируемой иностранной компании ее финансовая отчетность не подлежит обязательному аудиту, определение прибыли (убытка) такой контролируемой иностранной компании в целях настоящего Кодекса осуществляется на основании финансовой отчетности, аудит которой проведен в соответствии с международными стандартами аудита. Соблюдение условий, установленных настоящим подпунктом, не требуется для целей применения подпункта 1 пункта 11 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\n13. В случае невыполнения условий, установленных пунктом 11 настоящей статьи, а также по выбору налогоплательщика - контролирующего лица (с учетом положений абзаца второго настоящего пункта и положений пункта 14 настоящей статьи) прибыль (убыток) контролируемой иностранной компании определяется в соответствии с подпунктом 2 пункта 1 настоящей статьи, за исключением положений, установленных абзацами первым и вторым пункта 2 и пунктами 3 - 5, 7 настоящей статьи.\n\nВ случае, если порядок определения прибыли (убытка) контролируемой иностранной компании в соответствии с подпунктом 2 пункта 1 настоящей статьи применяется по выбору налогоплательщика, такой порядок подлежит применению в отношении соответствующей контролируемой иностранной компании в течение не менее пяти налоговых периодов с даты начала его применения, что должно быть закреплено в учетной политике налогоплательщика - контролирующего лица.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\n2. Прибыль (убыток) контролируемой иностранной компании, определенная по данным финансовой отчетности этой компании и выраженная в иностранной валюте, уменьшенная на величину дивидендов (распределенной прибыли), учитываемых в соответствии с порядком, предусмотренным пунктом 1 статьи 2515 настоящего Кодекса, подлежит пересчету в рубли с применением среднего курса иностранной валюты к рублю Российской Федерации, установленного Центральным банком Российской Федерации, определяемого за период, за который в соответствии с личным законом такой компании составляется финансовая отчетность за финансовый год.\n\nСумма прибыли (убытка) каждой контролируемой иностранной компании должна быть документально подтверждена ее финансовой отчетностью, составленной за соответствующий период (периоды), с приложением ее финансовой и налоговой отчетности.\n\nВ случае определения суммы прибыли (убытка) контролируемой иностранной компании в соответствии с подпунктом 2 пункта 1 настоящей статьи сумма прибыли (убытка) контролируемой иностранной компании определяется в официальной валюте государства (территории) постоянного местонахождения иностранной организации и подлежит пересчету в рубли с применением среднего курса иностранной валюты к рублю Российской Федерации, установленного Центральным банком Российской Федерации, определяемого за календарный год, за который определяется сумма прибыли (убытка) контролируемой иностранной компании. Сумма прибыли (убытка) контролируемой иностранной компании должна быть подтверждена документами, позволяющими определить сумму прибыли. Такими документами, в частности, могут быть выписки с расчетных счетов иностранной контролируемой организации, первичные документы, подтверждающие произведенные операции согласно обычаям делового оборота иностранной компании.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n3. При определении прибыли (убытка) контролируемой иностранной компании не учитываются следующие доходы (расходы) этой компании за период, за который в соответствии с личным законом такой компании составляется финансовая отчетность за финансовый год:\n\n1) в виде сумм от переоценки и (или) обесценения долей в уставном (складочном) капитале (фонде) организаций, паев в паевых фондах кооперативов и паевых инвестиционных фондах, ценных бумаг, производных финансовых инструментов по справедливой стоимости, произведенных в соответствии с применимыми стандартами составления финансовой отчетности, признанных в составе прибыли (убытка) контролируемой иностранной компании до налогообложения; (В редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\n11) в виде сумм доходов от реализации или иного выбытия долей в уставном (складочном) капитале (фонде) организаций, паев в паевых фондах кооперативов и паевых инвестиционных фондах, ценных бумаг и расходов, признанных при выбытии указанных активов в составе прибыли (убытка) контролируемой иностранной компании до налогообложения; (Дополнение подпунктом - Федеральный закон от 28.12.2017 № 436-ФЗ) (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n2) в виде сумм прибыли (убытка) дочерних (ассоциированных) организаций (за исключением дивидендов), признанных в финансовой отчетности контролируемой иностранной компании в соответствии с ее личным законом (учетной политикой этой компании для целей составления ее финансовой отчетности);\n\n3) в виде сумм расходов на формирование резервов и доходов от восстановления резервов. При этом прибыль контролируемой иностранной компании уменьшается на суммы расходов, уменьшающих величину ранее сформированного резерва. В случае, если по данным финансовой отчетности контролируемой иностранной компании, составленной в соответствии с ее личным законом за финансовый год, определен убыток, то расходы, которые уменьшают величину ранее сформированного резерва, увеличивают сумму такого убытка. Установленный настоящим подпунктом порядок учета при определении прибыли (убытка) контролируемой иностранной компании сумм расходов, уменьшающих величину ранее сформированного резерва, применяется при условии раскрытия в финансовой отчетности контролируемой иностранной компании сумм расходов, уменьшающих ранее сформированные резервы, или при условии документального подтверждения таких расходов.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nПрибыль (убыток) от выбытия финансовых активов определяется как соответствующие доходы, уменьшенные на величину расходов в следующем порядке:\n\nдоходы при реализации или ином выбытии финансовых активов определяются в соответствии с применимыми стандартами составления финансовой отчетности;\n\nрасходы при реализации или ином выбытии финансовых активов определяются либо исходя из стоимости указанных финансовых активов по данным учета контролируемой иностранной компании на дату принятия указанных финансовых активов к учету в случае, если указанные финансовые активы приняты к учету в финансовом году, начавшемся в 2015 году, или в любом последующем финансовом году, либо исходя из стоимости указанных финансовых активов по данным учета контролируемой иностранной компании на первое число финансового года, начавшегося в 2015 году, в случае, если указанные финансовые активы приняты к учету в финансовых годах, предшествующих финансовому году, начавшемуся в 2015 году. При этом при реализации или ином выбытии долей в уставном (складочном) капитале (фонде) организации в состав расходов, указанных в настоящем абзаце, также включаются расходы контролируемой иностранной компании в сумме денежных средств, внесенных в имущество (капитал) такой организации в финансовом году, начавшемся в 2015 году, или в любом последующем финансовом году, если соответствующие расходы изменяют стоимость долей в уставном (складочном) капитале (фонде) организации по данным учета контролируемой иностранной компании. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nВ случае, если по состоянию на конец финансового года, в котором произошло выбытие финансовых активов, сведения о стоимости таких финансовых активов на дату их принятия к учету (на первое число финансового года, начавшегося в 2015 году, в случае, если указанные финансовые активы приняты к учету в финансовых годах, предшествующих финансовому году, начавшемуся в 2015 году) отсутствуют, налогоплательщик вправе определить такую стоимость посредством корректировки доходов от выбытия указанных финансовых активов на суммы от их переоценки, в том числе убытка от их обесценения, учтенные в финансовой отчетности контролируемой иностранной компании, за финансовые годы, начавшиеся после 2015 года включительно.\n\nДля целей настоящего пункта стоимость финансовых активов подтверждается данными учета иностранной организации, пояснениями к ее финансовой отчетности (если применимо) и (или) расчетом, основанным на корректировке доходов от реализации или иного выбытия указанных финансовых активов на суммы от их переоценки, определенные в соответствии с применимыми стандартами составления финансовой отчетности, и определяется в валюте финансовой отчетности контролируемой иностранной компании.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ) (В редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\n4. В целях настоящего Кодекса следующие доходы признаются доходами от пассивной деятельности:\n\n1) дивиденды;\n\n2) доходы, получаемые в результате распределения прибыли или имущества организаций, иных лиц или их объединений, в том числе при их ликвидации;\n\n3) процентный доход от долговых обязательств любого вида, включая облигации с правом на участие в прибылях и конвертируемые облигации;\n\n4) доходы от использования прав на объекты интеллектуальной собственности.\n\nК таким доходам, в частности, относятся платежи любого вида, получаемые в качестве возмещения за использование или за предоставление права использования любого авторского права на произведения литературы, искусства или науки, включая кинематографические фильмы и фильмы или записи для телевидения или радиовещания, использование (предоставление права использования) любых патентов, товарных знаков, чертежей или моделей, планов, секретной формулы или процесса либо использование (предоставление права использования) информации, касающейся промышленного, коммерческого или научного опыта;\n\n5) доходы от реализации акций (долей) и (или) уступки прав в иностранной организации, не являющейся юридическим лицом по иностранному праву;\n\n6) доходы по операциям с производными финансовыми инструментами; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n7) доходы от реализации недвижимого имущества;\n\n8) доходы от сдачи в аренду или субаренду имущества, в том числе доходы от лизинговых операций, за исключением следующих доходов:\n\nот предоставления в аренду или субаренду морских судов, судов смешанного (река - море) плавания или воздушных судов и (или) транспортных средств, а также контейнеров, используемых в международных перевозках;\n\nот предоставления в аренду или субаренду подземных хранилищ газа и трубопроводов, используемых для транспортировки углеводородов.\n\nВ целях настоящего подпункта определение суммы дохода от лизинговых операций, связанных с приобретением и использованием предмета лизинга лизингополучателем, производится исходя из общей суммы лизингового платежа за вычетом возмещения стоимости лизингового имущества (при лизинге) лизингодателю;\n\n9) доходы от реализации (в том числе погашения) инвестиционных паев паевых инвестиционных фондов;\n\n10) доходы от оказания консультационных, юридических, бухгалтерских, аудиторских, инжиниринговых, рекламных, маркетинговых услуг, услуг по обработке информации, а также от проведения научно-исследовательских и опытно-конструкторских работ;\n\n11) доходы от услуг по предоставлению персонала;\n\n12) иные доходы, аналогичные доходам, указанным в подпунктах 1 - 11 настоящего пункта.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n5. Доходы, не указанные в пункте 4 настоящей статьи, в целях настоящего Кодекса признаются доходами от активной деятельности.\n\nПри этом доходы, указанные в подпунктах 3 и 6 пункта 4 настоящей статьи, признаются доходами от активной деятельности в случае, если извлечение прибыли от таких доходов осуществляется на основании специального разрешения (лицензии) и является основной целью деятельности иностранной компании, являющейся банком в соответствии с законодательством иностранного государства.\n\nДоходы иностранной компании, указанные в подпункте 6 пункта 4 настоящей статьи, признаются доходами от активной деятельности в случаях, если такие доходы получены от реализации товаров на основании договоров (контрактов), по условиям которых осуществляется поставка базисного актива, или такие доходы получены по операциям хеджирования в целях компенсации неблагоприятных последствий, связанных с изменением стоимости соответствующего объекта хеджирования, и к которым требования международных стандартов финансовой отчетности применяются как к производным финансовым инструментам, при условии раскрытия соответствующих сведений в финансовой отчетности контролируемой иностранной компании (включая примечания к финансовой отчетности). (Дополнение абзацем - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\nДоходы по операциям с финансовыми инструментами срочных сделок (производными финансовыми инструментами), указанные в настоящем пункте, признаются доходами от активной деятельности при условии, что в случае реализации соответствующего базисного актива по договору купли-продажи такие доходы не признавались бы доходами от пассивной деятельности. (Дополнение абзацем - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n6. Налоговая база контролируемой иностранной компании определяется отдельно в отношении каждой контролируемой иностранной компании.\n\n71. Убыток контролируемой иностранной компании, определенный одним из способов, установленных пунктом 1 настоящей статьи, не может быть перенесен на будущие периоды, если налогоплательщиком - контролирующим лицом не представлено уведомление о контролируемой иностранной компании за период, за который получен указанный убыток.\n\nВ случае, если налогоплательщик прекращает быть контролирующим лицом контролируемой иностранной компании, он утрачивает право переноса убытка такой компании на будущие периоды в части, не учтенной им ранее при исчислении прибыли контролируемой иностранной компании. (Дополнение абзацем - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\nСовокупная прибыль (убыток) контролируемой иностранной компании за период, предшествующий финансовому году, начавшемуся в 2015 году, определяется как сумма прибылей (убытков) до налогообложения по данным финансовой отчетности контролируемой иностранной компании за три финансовых года, непосредственно предшествующие финансовому году, начавшемуся в 2015 году, без учета особенностей, предусмотренных пунктами 3 и 31 настоящей статьи.\n\nПри этом в случае, если на последнее число финансового года, непосредственно предшествующего финансовому году, начавшемуся в 2015 году, контролируемой иностранной компании на праве собственности принадлежат доли в уставном (складочном) капитале (фонде) организаций, паи в паевых фондах кооперативов и паевых инвестиционных фондах, ценные бумаги, производные финансовые инструменты, переоценка которых по справедливой стоимости не признавалась ни в одном году из трех финансовых лет, непосредственно предшествующих финансовому году, начавшемуся в 2015 году, в составе прибыли (убытка) контролируемой иностранной компании до налогообложения, совокупная прибыль (убыток) такой контролируемой иностранной компании за период, предшествующий финансовому году, начавшемуся в 2015 году, корректируется на накопленную переоценку таких активов по справедливой стоимости за период с даты их приобретения (с первого числа финансового года, начавшегося в 2012 году, если дата приобретения приходится на период до указанной даты) до последнего числа финансового года, непосредственно предшествующего финансовому году, начавшемуся в 2015 году.\n\n(Пункт в редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\nо взаимозависимого лица, а также расходы контролируемой иностранной компании в виде цены приобретения ценных бумаг и (или) имущественных прав (в том числе долей, паев) исключаются из прибыли (убытка) контролируемой иностранной компании при условии, что цена реализации ценных бумаг и (или) имущественных прав (в том числе долей, паев) определена исходя из их документально подтвержденной стоимости по данным учета контролируемой иностранной компании на дату перехода права собственности на указанные ценные бумаги и (или) имущественные права (в том числе доли, паи), но не выше рыночной стоимости указанных ценных бумаг и (или) имущественных прав (в том числе долей, паев) на дату перехода права собственности, определяемой в соответствии со статьей 280 настоящего Кодекса для налогоплательщиков-организаций и в соответствии со статьей 212 настоящего Кодекса для налогоплательщиков - физических лиц с учетом положений статьи 1053 настоящего Кодекса.\n\nЕсли иное не указано в абзацах четвертом - седьмом настоящего пункта, положения абзаца первого настоящего пункта применяются при условии, что процедура ликвидации контролируемой иностранной компании завершена до 1 марта 2019 года. (В редакции Федерального закона от 19.02.2018 № 34-ФЗ)\n\nПредельный срок завершения процедуры ликвидации контролируемой иностранной компании, указанный в абзаце втором настоящего пункта, продлевается в следующих случаях:\n\nесли решение акционеров (учредителей) или иных уполномоченных лиц о ликвидации контролируемой иностранной компании принято до 1 июля 2018 года, но процедура ликвидации не может быть завершена до 1 марта 2019 года в связи с ограничениями, установленными личным законом контролируемой иностранной компании, либо участием контролируемой иностранной компании в судебном разбирательстве, процедура ликвидации контролируемой иностранной компании должна быть завершена не позднее окончания 365 последовательных календарных дней, считая с даты окончания таких ограничений и (или) судебных разбирательств; (В редакции Федерального закона от 19.02.2018 № 34-ФЗ)\n\nесли личным законом контролируемой иностранной компании установлен минимальный период владения акциями (долями, паями) в контролируемой иностранной компании и (или) в ее дочерних организациях и (или) иностранных структурах без образования юридического лица, при несоблюдении которого возникает обязанность уплатить налог, установленный законодательством иностранного государства, и при этом начало такого периода приходится на дату до 1 января 2015 года, а окончание такого периода приходится на дату после 1 марта 2019 года, процедура ликвидации контролируемой иностранной компании должна быть завершена не позднее окончания 365 последовательных календарных дней, считая с даты окончания минимального периода, указанного в настоящем абзаце; (В редакции Федерального закона от 19.02.2018 № 34-ФЗ)\n\nесли решение о ликвидации иностранной компании не может быть принято до 1 марта 2019 года в связи с ограничениями, установленными условиями выпуска обращающихся облигаций, отвечающих требованиям, установленным подпунктом 1 пункта 21 статьи 310 настоящего Кодекса, процедура ликвидации контролируемой иностранной компании должна быть завершена не позднее окончания 365 последовательных календарных дней, считая с даты окончания действия таких ограничений для указанной компании. (В редакции Федерального закона от 19.02.2018 № 34-ФЗ)\n\nПри этом стоимость ценных бумаг и (или) имущественных прав (в том числе долей, паев), приобретенных непосредственно у контролируемой иностранной компании налогоплательщиком, признаваемым контролирующим лицом, либо его взаимозависимым лицом, принимается к учету у такого налогоплательщика (его взаимозависимого лица) исходя из документально подтвержденной стоимости по данным учета контролируемой иностранной компании на дату перехода права собственности на указанные ценные бумаги и (или) имущественные права (в том числе доли, паи), но не выше рыночной стоимости указанных ценных бумаг и (или) имущественных прав (в том числе долей, паев) на дату перехода права собственности, определяемой в соответствии со статьей 280 настоящего Кодекса для налогоплательщиков-организаций и в соответствии со статьей 212 настоящего Кодекса для налогоплательщиков - физических лиц с учетом положений статьи 1053 настоящего Кодекса.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nСумма налога, исчисленного в соответствии с законодательством иностранного государства, должна быть документально подтверждена, а в случае отсутствия у Российской Федерации с государством (территорией) действующего международного договора Российской Федерации по вопросам налогообложения заверена компетентным органом иностранного государства, уполномоченным по контролю и надзору в области налогов.\n\nВ случае, если контролируемая иностранная компания входит в состав иностранной консолидированной группы налогоплательщиков, для целей определения суммы налога, исчисленного в отношении прибыли такой контролируемой иностранной компании в соответствии с законодательством иностранного государства, может быть учтена часть суммы налога, исчисленного в отношении такой иностранной консолидированной группы налогоплательщиков. При этом указанная часть определяется в порядке, установленном пунктом 2 статьи 2513-1 настоящего Кодекса для контролируемой иностранной компании, входящей в иностранную консолидированную группу налогоплательщиков. (Дополнение абзацем - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\nВ случае, если в соответствии с законодательством иностранного государства срок исчисления налога в отношении прибыли контролируемой иностранной компании за соответствующий период установлен на более позднюю дату, чем предусмотренная главой 23 настоящего Кодекса или настоящей главой дата предоставления налогоплательщиком - контролирующим лицом налоговой декларации, соответствующая сумма налога учитывается при исчислении налога в отношении прибыли контролируемой иностранной компании за налоговый период, следующий за календарным годом, за который была исчислена сумма налога в отношении этой прибыли в соответствии с законодательством иностранного государства. (Дополнение абзацем - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nПри этом совокупный размер исчисленных в соответствии с законодательством иностранного государства сумм налогов не может превышать сумму налога, исчисленного в отношении прибыли контролируемой иностранной компании за налоговый период, следующий за календарным годом, за который была исчислена сумма налога в отношении этой прибыли в соответствии с законодательством иностранного государства. (Дополнение абзацем - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nУстановление срока исчисления налога в отношении прибыли контролируемой иностранной компании за соответствующий период на более позднюю дату, чем предусмотренная главой 23 настоящего Кодекса или настоящей главой дата предоставления налогоплательщиком - контролирующим лицом налоговой декларации, должно быть подтверждено путем представления налогоплательщиком - контролирующим лицом в налоговый орган по месту нахождения соответствующих документов одновременно с представлением налоговой декларации за налоговый период, следующий за календарным годом, за который была исчислена сумма налога в отношении этой прибыли в соответствии с законодательством иностранного государства. (Дополнение абзацем - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nубыток контролируемой иностранной компании, полученный до перехода на уплату налога на доходы физических лиц с фиксированной прибыли, может быть учтен налогоплательщиком при определении прибыли контролируемой иностранной компании начиная с налогового периода, в котором он отказался от уплаты налога на доходы физических лиц с фиксированной прибыли;\n\nубыток контролируемой иностранной компании, полученный в периоды уплаты налогоплательщиком налога на доходы физических лиц с фиксированной прибыли, может быть учтен налогоплательщиком при определении прибыли контролируемой иностранной компании начиная с налогового периода, в котором он отказался от уплаты налога на доходы физических лиц с фиксированной прибыли. При этом величина убытка, указанного в настоящем абзаце, определяется как отрицательная величина от суммы убытков и прибылей до налогообложения по данным финансовой отчетности контролируемой иностранной компании за периоды уплаты налогоплательщиком налога на доходы физических лиц с фиксированной прибыли.\n\nОпределение величины и документальное подтверждение прибыли (убытка) в целях настоящего пункта осуществляются на основании совокупности положений настоящей статьи и статьи 2515 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 309.1. Особенности налогообложения прибыли контролируемых иностранных компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46d1dbfd6eb189708b0e05064b4e4ceed7cdc3912320b9ea36399f3b24b04953"},{"code_id":"NK_RF_2","article_number":"310","version_date":"2000-07-31","article_text":"Налог с видов доходов, указанных в подпункте 1 пункта 1 статьи 309 настоящего Кодекса, исчисляется по ставке, предусмотренной подпунктом 3 пункта 3 статьи 284 настоящего Кодекса, а в отношении таких видов доходов, выплачиваемых международной холдинговой компанией, исчисляется по ставкам, предусмотренным подпунктами 12 и 13 пункта 3 статьи 284 настоящего Кодекса, в случаях, установленных соответственно подпунктами 12 и 13 пункта 3 статьи 284 настоящего Кодекса. (В редакции  федеральных законов от 03.08.2018 № 294-ФЗ, от 26.03.2022 № 66-ФЗ)\n\nНалог с видов доходов, указанных в абзаце втором подпункта 3 пункта 1 статьи 309 настоящего Кодекса, исчисляется по ставке, предусмотренной пунктом 4 статьи 284 настоящего Кодекса.\n\nНалог с видов доходов, указанных в подпункте 2, абзаце третьем подпункта 3 и подпунктах 4, 7 (в части доходов от сдачи в аренду или субаренду имущества, используемого на территории Российской Федерации, в том числе по лизинговым операциям), 9, 91 - 93, 95 и 10 пункта 1 статьи 309 настоящего Кодекса, исчисляется по ставкам, предусмотренным подпунктом 1 пункта 2 статьи 284 настоящего Кодекса, а в отношении видов доходов, указанных в абзаце третьем подпункта 3 и подпункте 4 пункта 1 статьи 309 настоящего Кодекса, выплачиваемых международной холдинговой компанией, исчисляется по ставкам, предусмотренным подпунктом 4 пункта 4 и пунктом 43 статьи 284 настоящего Кодекса, в случаях, установленных соответственно подпунктом 4 пункта 4 и пунктом 43 статьи 284 настоящего Кодекса. Налог с видов доходов, указанных в подпункте 94 пункта 1 статьи 309 настоящего Кодекса, исчисляется по ставке, предусмотренной подпунктом 4 пункта 2 статьи 284 настоящего Кодекса. (В редакции  федеральных законов от 02.11.2013 № 306-ФЗ, от 26.03.2022 № 66-ФЗ, от 27.11.2023 № 539-ФЗ, от 29.11.2024 № 418-ФЗ)\n\nНалог с видов доходов, указанных в подпунктах 7 (в части доходов от предоставления в аренду или субаренду морских, воздушных судов или иных подвижных транспортных средств или контейнеров, используемых в международных перевозках) и 8 пункта 1 статьи 309 настоящего Кодекса, исчисляется по ставке, предусмотренной подпунктом 2 пункта 2 статьи 284 настоящего Кодекса. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНалог с видов доходов, указанных в подпунктах 5 и 6 пункта 1 статьи 309 настоящего Кодекса, исчисляется с учетом положений пунктов 2 и 4 указанной статьи по ставкам, предусмотренным пунктом 1 статьи 284 настоящего Кодекса. В случае, если расходы, указанные в пункте 4 статьи 309 настоящего Кодекса, не признаются расходом для целей налогообложения, с таких доходов налог исчисляется по ставкам, предусмотренным подпунктом 1 пункта 2 статьи 284 настоящего Кодекса. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nСумма налога, удержанного с доходов иностранных организаций в соответствии с настоящим пунктом, перечисляется налоговым агентом в федеральный бюджет в валюте Российской Федерации в порядке, предусмотренном пунктами 2 и 4 статьи 287 настоящего Кодекса. При этом пересчет суммы налога, исчисленной в иностранной валюте, в валюту Российской Федерации осуществляется по официальному курсу Центрального банка Российской Федерации на дату выплаты дохода иностранной организации. (В редакции  федеральных законов от 24.11.2008 № 205-ФЗ, от 27.07.2010 № 229-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nВ случае, если доход выплачивается иностранной организации в натуральной или иной неденежной форме, в том числе в форме осуществления взаимозачетов, или в случае, если сумма налога, подлежащего удержанию, превосходит сумму дохода иностранной организации, получаемого в денежной форме, налоговый агент обязан перечислить налог в бюджет в исчисленной сумме, уменьшив соответствующим образом доход иностранной организации, получаемый в неденежной форме.\n\nНалог с доходов в денежной форме, подлежащих выплате (перечислению) по эмиссионным ценным бумагам с обязательным централизованным хранением в отношении выпусков эмиссионных ценных бумаг с обязательным централизованным хранением, государственная регистрация которых или присвоение идентификационного номера которым осуществлены после 1 января 2012 года, за исключением случаев, установленных настоящей статьей, лицу, имеющему в соответствии с действующим законодательством право на получение таких доходов и являющемуся иностранной организацией, исчисляется и удерживается депозитарием, осуществляющим выплату (перечисление) указанных доходов налогоплательщику. В случае выплаты дохода в виде дивидендов по акциям международных холдинговых компаний налоговый агент применяет налоговую ставку, установленную подпунктом 12 пункта 3 статьи 284 настоящего Кодекса, на основании документального подтверждения, представленного такой компанией налоговому агенту до даты выплаты соответствующего дохода, что на день принятия решения международной компании (организации, указанной в пункте 11 статьи 242 настоящего Кодекса) о выплате дивидендов она одновременно является международной холдинговой компанией и публичной компанией, а также являлась публичной компанией по состоянию на 1 января 2018 года, или налоговую ставку, установленную подпунктом 13 пункта 3 статьи 284 настоящего Кодекса, на основании документального подтверждения, что на день принятия решения международной холдинговой компанией о выплате дивидендов она выполняла условия, установленные статьей 28410 настоящего Кодекса. Международная холдинговая компания - эмитент ценных бумаг, выплачивающая доходы в виде дивидендов, обязана довести до сведения налогового агента соответствующее подтверждение не позднее пяти дней с даты, на которую в соответствии с решением о выплате (объявлении) дивидендов определяются лица, имеющие право на их получение, но не позднее дня выплаты дивидендов в порядке, предусмотренном пунктами 51 и 52 статьи 275 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.06.2011 № 122-ФЗ) (В редакции федеральных законов от 29.06.2012 № 97-ФЗ, от 25.12.2018 № 490-ФЗ, от 25.02.2022 № 18-ФЗ, от 26.03.2022 № 66-ФЗ)\n\nНалог исчисляется и удерживается депозитарием, в котором открыты счет депо иностранного номинального держателя, счет депо иностранного уполномоченного держателя и (или) счет депо депозитарных программ, в соответствии с положениями статьи 3101 настоящего Кодекса при получении доходов в денежной форме по следующим ценным бумагам, которые учитываются на указанных счетах (за исключением доходов, указанных в подпункте 7 пункта 2 настоящей статьи): (Дополнение абзацем - Федеральный закон от 29.12.2012 № 282-ФЗ) (В редакции федеральных законов от 02.11.2013 № 306-ФЗ; от 28.11.2015 № 326-ФЗ)\n\nпо государственным ценным бумагам Российской Федерации с обязательным централизованным хранением; (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\nпо государственным ценным бумагам субъектов Российской Федерации с обязательным централизованным хранением; (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\nпо муниципальным ценным бумагам с обязательным централизованным хранением; (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\nпо эмиссионным ценным бумагам с обязательным централизованным хранением, выпущенным российскими организациями, государственная регистрация выпуска которых или присвоение идентификационного номера которым осуществлены после 1 января 2012 года; (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\nпо иным эмиссионным ценным бумагам, выпущенным российскими организациями (за исключением эмиссионных ценных бумаг с обязательным централизованным хранением выпусков, государственная регистрация которых или присвоение идентификационного номера которым осуществлены до 1 января 2012 года). (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\n1) случаев, когда налоговый агент уведомлен получателем дохода, что выплачиваемый доход относится к постоянному представительству получателя дохода в Российской Федерации, и в распоряжении налогового агента находится информация о соответствующем идентификационном номере налогоплательщика - получателя дохода; (В редакции  федеральных законов от 02.07.2021 № 305-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n2) случаев, когда в отношении дохода, выплачиваемого иностранной организации, статьей 284 настоящего Кодекса предусмотрена налоговая ставка 0 процентов; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n3) случаев выплаты доходов, полученных при выполнении соглашений о разделе продукции, если законодательством Российской Федерации о налогах и сборах предусмотрено освобождение таких доходов от удержания налога в Российской Федерации при их перечислении иностранным организациям;\n\n4) случаев выплаты доходов, которые в соответствии с международными договорами (соглашениями) не облагаются налогом в Российской Федерации, при условии предъявления иностранной организацией, имеющей фактическое право на получение соответствующего дохода, налоговому агенту п\n\nодтверждения, предусмотренного пунктом 1 статьи 312 настоящего Кодекса. При этом в случае выплаты доходов по операциям с иностранными банками подтверждение факта постоянного местонахождения иностранного банка в государстве, с которым имеется международный договор (соглашение), регулирующий вопросы налогообложения, не требуется, если такое местонахождение подтверждается сведениями общедоступных информационных справочников; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 07.06.2011 № 132-ФЗ, от 24.11.2014 № 376-ФЗ, от 09.11.2020 № 368-ФЗ)\n\n5) случаев выплаты доходов организациям, являющимся иностранными организаторами XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в соответствии со статьей 3 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\" или иностранными маркетинговыми партнерами Международного олимпийского комитета в соответствии со статьей 31 указанного Федерального закона; (Дополнение подпунктом - Федеральный закон от 01.12.2007 № 310-ФЗ) (В редакции Федерального закона от 30.07.2010 № 242-ФЗ)\n\n6) случаев выплаты доходов, связанных с распространением продукции средств массовой информации, касающейся XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, официальным вещательным компаниям в соответствии со статьей 31 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 30.07.2010 № 242-ФЗ)\n\n7) случаев выплаты процентных доходов:\n\nпо государственным ценным бумагам Российской Федерации, государственным ценным бумагам субъектов Российской Федерации и муниципальным ценным бумагам;\n\nвыплачиваемых российскими организациями по обращающимся облигациям, выпущенным этими организациями в соответствии с законодательством иностранных государств;\n\n(Дополнение подпунктом - Федеральный закон от 29.06.2012 № 97-ФЗ)\n\n8) случаев выплаты российскими организациями процентных доходов по долговым обязательствам перед иностранными организациями при одновременном выполнении следующих условий:\n\nдолговые обязательства российских организаций, по которым выплачиваются процентные доходы, возникли в связи с размещением иностранными организациями обращающихся облигаций;\n\nиностранные организации, являющиеся эмитентами обращающихся облигаций, или иностранные организации, уполномоченные на получение процентных доходов, подлежащих выплате по обращающимся облигациям, или иностранные организации, которым были уступлены права и обязанности по выпущенным обращающимся облигациям, эмитентом которых является другая иностранная организация, которым российскими организациями выплачиваются процентные доходы по долговым обязательствам, на дату выплаты процентного дохода имеют постоянное место нахождения в государствах, с которыми Российская Федерация имеет международные договоры Российской Федерации по вопросам налогообложения, и предъявили российской организации, осуществляющей выплату процентного дохода, подтверждение того, что иностранная организация имеет постоянное место нахождения в государстве, с которым Российская Федерация имеет международный договор Российской Федерации по вопросам налогообложения. Такое подтверждение должно быть заверено компетентным органом соответствующего иностранного государства. В случае, если такое подтверждение составлено на иностранном языке, налоговому агенту предоставляется также перевод подтверждения на русский язык; (В редакции Федерального закона от 28.11.2015 № 327-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 29.06.2012 № 97-ФЗ)\n\n9) случаев выплаты доходов UEFA (Union of European Football Associations), FIFA (Federation Internationale de Football Association) и дочерним организациям FIFA, указанным в Федеральном законе \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года и внесении изменений в отдельные законодательные акты Российской Федерации\" и являющимся иностранными организациями; (Дополнение подпунктом - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции Федерального закона от 01.05.2019 № 101-ФЗ)\n\n10) случаев выплаты доходов конфедерациям, национальным футбольным ассоциациям, производителям медиаинформации FIFA, поставщикам товаров (работ, услуг) FIFA, указанным в Федеральном законе \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года  и внесении изменений в отдельные законодательные акты Российской Федерации\" и являющимся иностранными организациями, в связи с осуществлением мероприятий, предусмотренных указанным Федеральным законом; (Дополнение подпунктом - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции Федерального закона от 01.05.2019 № 101-ФЗ)\n\n11) случаев выплаты налоговым агентом следующих видов доходов, которые не облагались налогом в Российской Федерации согласно международным договорам Российской Федерации по вопросам налогообложения до дня принятия указа Президента Российской Федерации о приостановлении Российской Федерацией действия отдельных положений международных договоров Российской Федерации по вопросам налогообложения (далее в настоящей статье - Указ), и которые выплачиваются иностранным организациям, расположенным на территориях иностранных государств, действие отдельных положений международных договоров Российской Федерации по вопросам налогообложения с которыми приостановлено Указом, при условии представления иностранной организацией налоговому агенту подтверждений, предусмотренных пунктом 1 статьи 312 настоящего Кодекса:\n\nпроцентных доходов, выплачиваемых иностранным экспортно-кредитным агентствам и иностранным организациям, осуществляющим банковскую деятельность в соответствии с их личным законом, по соглашениям, устанавливающим или изменяющим долговые обязательства между российской организацией - должником и иностранной организацией - кредитором, если такие соглашения заключены до дня принятия Указа и если российская организация - должник и иностранная организация - кредитор не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса. При этом подтверждение факта постоянного местонахождения иностранного банка в государстве, с которым имеется международный договор (соглашение), который регулирует вопросы налогообложения и действие отдельных положений которого приостановлено Указом, не требуется, если такое местонахождение подтверждается сведениями общедоступных информационных справочников;\n\nдоходов от сдачи в аренду (лизинг) воздушных судов (включая вспомогательные силовые установки и (или) авиационные двигатели) по заключенным с иностранными организациями - арендодателями (лизингодателями) до 5 марта 2022 года договорам аренды (лизинга) воздушных судов, зарегистрированных или подлежащих регистрации в Государственном реестре гражданских воздушных судов Российской Федерации, если иностранная организация - получатель дохода и российская организация - лизингополучатель не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса. При этом в случае внесения изменений в условия договоров аренды (лизинга) воздушных судов с иностранными организациями - арендодателями (лизингодателями) после дня принятия Указа положения настоящего подпункта применяются к доходам в сумме, не превышающей суммы доходов от сдачи в аренду (лизинг) воздушных судов (включая вспомогательные силовые установки и (или) авиационные двигатели), определяемой согласно действовавшим до дня принятия Указа положениям указанных договоров;\n\nдоходов от использования и (или) предоставления прав использования аудиовизуальных произведений и иных результатов интеллектуальной деятельности и средств индивидуализации (роялти) на телеканалах при наземном эфирном, спутниковом, кабельном и (или) ином распространении таких телеканалов, если российская организация, выплачивающая доходы, и иностранная организация - получатель доходов не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\nдоходов от использования и (или) предоставления права использования объекта авторского права и (или) смежных прав (любого произведения литературы, искусства или науки, включая компьютерные программы, кинематографические фильмы, фонограммы, записи на пленку или другие носители для использования в радио- и телевизионных передачах или другие средства воспроизведения и распространения информации), любого патента, чертежа, модели, схемы, секретной формулы, технологии либо информации относительно промышленного, коммерческого или научного опыта (ноу-хау), если российская организация, выплачивающая доходы, и иностранная организация - получатель доходов не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\nдоходов от реализации морских судов, зарегистрированных в Российском международном реестре судов и находящихся на территории Российской Федерации, если российская организация, выплачивающая доходы, и иностранная организация - получатель доходов не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\nдоходов от международных перевозок по договорам, заключенным с иностранными организациями до дня принятия Указа, если российская организация, выплачивающая доходы, и иностранная организация - получатель доходов не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\nдоходов от предоставления в аренду или субаренду морских судов по договорам, заключенным с иностранными организациями - арендодателями (фрахтовщиками) до дня принятия Указа, если российская организация, выплачивающая доходы, и иностранная организация - получатель доходов не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n12) случаев, когда иностранной организацией получен доход в виде прекращения обязательств в части уплаты сумм задолженности по процентам в связи с прощением долга по долговым обязательствам такой иностранной организации перед налоговым агентом при выполнении следующих условий:\n\nпрощение задолженности происходит на основании соглашения, утверждаемого в иностранном государстве в судебном порядке в рамках финансового оздоровления такой иностранной организации;\n\nзаимодавец - налоговый агент и заемщик - иностранная организация входят в одну международную группу компаний;\n\nв отношении такой иностранной организации на дату прекращения обязательств действуют запретительные, ограничительные и (или) аналогичные меры, заключающиеся в установлении запретов и (или) ограничений на проведение расчетов и (или) осуществление финансовых операций, запретов и (или) ограничений на проведение операций, связанных с заемным финансированием и (или) приобретением либо отчуждением ценных бумаг (долей участия в уставном капитале), введенные начиная с 2022 года иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями.\n\n(Дополнение подпунктом - Федеральный закон от 23.07.2025 № 227-ФЗ)\n\n1) обращающимися облигациями признаются облигации и иные долговые обязательства, которые прошли процедуру листинга, и (или) были допущены к обращению на одной или нескольких иностранных фондовых биржах, и (или) учет прав на которые осуществляется иностранными депозитарно-клиринговыми организациями, при условии, что такие иностранные фондовые биржи и иностранные депозитарно-клиринговые организации включены в перечень иностранных финансовых посредников. До момента утверждения указанного перечня обращающимися облигациями признаются облигации и иные долговые обязательства, которые прошли процедуру листинга, и (или) были допущены к обращению на одной или нескольких иностранных фондовых биржах, и (или) учет прав на которые осуществляется иностранными депозитарно-клиринговыми организациями. Подтверждение фактов, указанных в настоящем подпункте, осуществляется российской организацией на основании сведений, полученных от соответствующих иностранных фондовых бирж и (или) иностранных депозитарно-клиринговых организаций, или проспектов эмиссии соответствующих обращающихся облигаций или иных документов, относящихся к выпуску этих облигаций, либо на основании сведений из общедоступных источников информации. (В редакции  федеральных законов от 23.07.2013 № 251-ФЗ, от 24.11.2014 № 376-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nПодтверждение фактов, указанных в настоящем подпункте, осуществляется по состоянию на 5 марта 2022 года, если начиная с этой даты листинг обращающихся облигаций был аннулирован, и (или) допуск обращающихся облигаций к торгам на иностранных фондовых биржах был аннулирован, и (или) иностранные депозитарно-клиринговые организации прекратили учет прав на обращающиеся облигации в связи с недружественными действиями иностранных государств, в которых такие облигации прошли процедуру листинга и (или) были допущены к обращению на одной или нескольких фондовых биржах этих иностранных государств, и (или) учет прав на такие облигации осуществлялся депозитарно-клиринговыми организациями этих иностранных государств; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n2) при применении подпунктов 7 и 8 пункта 2 настоящей статьи к российским организациям приравниваются иностранные организации, осуществляющие деятельность в Российской Федерации через постоянное представительство (в части такой деятельности);\n\n3) при применении абзаца второго подпункта 8 пункта 2 настоящей статьи долговые обязательства российских организаций перед иностранными организациями признаются возникшими в связи с размещением иностранными организациями обращающихся облигаций, если об этом имеется указание в договоре, регулирующем соответствующее долговое обязательство, и (или) в условиях выпуска соответствующих обращающихся облигаций и (или) проспекте их эмиссии либо наличие такой связи подтверждается фактическим движением денежных средств при размещении соответствующих обращающихся облигаций;\n\n31) при применении абзаца третьего подпункта 8 пункта 2 настоящей статьи в отношении налоговых периодов, начинающихся после 31 декабря 2021 года, иностранная организация считается выполняющей требования абзаца третьего подпункта 8 пункта 2 настоящей статьи на дату получения дохода при условии, что у российской организации, осуществляющей выплату процентного дохода, имеется подтверждение того, что иностранная организация имела постоянное место нахождения в государстве, с которым Российская Федерация имеет (имела) действующий международный договор Российской Федерации по вопросам налогообложения, составленное и заверенное компетентным органом соответствующего иностранного государства в 2021 году. Положения настоящего подпункта применяются в отношении обращающихся облигаций, выпуск и (или) размещение которых состоялись не позднее 5 марта 2022 года; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n4) условия освобождения от исчисления и удержания суммы налога с процентных доходов, выплачиваемых иностранным организациям, предусмотренные подпунктом 8 пункта 2 настоящей статьи, применяются также к доходам, выплачиваемым российской организацией на основании поручительства, гарантии или иного обеспечения, предоставленных российской организацией по долговым обязательствам перед иностранной организацией и (или) по соответствующим обращающимся облигациям, а также к иным доходам, выплачиваемым российской организацией, при условии, что такие выплаты предусмотрены условиями соответствующего долгового обязательства либо осуществляются в связи с изменением условий выпуска обращающихся облигаций и (или) долговых обязательств, в том числе в связи с их досрочным выкупом и (или) погашением;\n\n41) условия освобождения от исполнения обязанностей налогового агента в отношении процентных доходов, выплачиваемых иностранным организациям, предусмотренные подпунктом 8 пункта 2 настоящей статьи, применяются также к процентным доходам, выплачиваемым российской организацией иностранным лицам по долговым обязательствам, связанным с выпуском иностранными организациями обращающихся облигаций (еврооблигаций), в соответствии с Указом Президента Российской Федерации от 5 марта 2022 года № 95 \"О временном порядке исполнения обязательств перед некоторыми иностранными кредиторами\"; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n5) при применении подпунктов 7 и 8 пункта 2 настоящей статьи к обращающимся облигациям, выпущенным российскими организациями в соответствии с законодательством иностранных государств, приравниваются обращающиеся облигации, выпущенные иностранными организациями, в порядке редомициляции которых зарегистрированы международные компании, до даты их регистрации, при условии соответствия таких облигаций требованиям, установленным настоящим пунктом, и при условии признания международных компаний международными холдинговыми компаниями в соответствии со статьей 242 настоящего Кодекса на дату выплаты указанных процентных доходов. (Дополнение подпунктом - Федеральный закон от 03.08.2018 № 294-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.06.2012 № 97-ФЗ)\n\n1) процентных доходов, выплачиваемых иностранным экспортно-кредитным агентствам и иностранным организациям, осуществляющим банковскую деятельность в соответствии с их личным законом, по соглашениям, устанавливающим или изменяющим долговые обязательства между российской организацией - должником и иностранной организацией - кредитором, если такие соглашения заключены до дня принятия Указа и если российская организация - должник и иностранная орг\n\nанизация - кредитор не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса. При этом подтверждение факта постоянного местонахождения иностранного банка в государстве, с которым имеется международный договор (соглашение), который регулирует вопросы налогообложения и действие отдельных положений которого приостановлено Указом, не требуется, если такое местонахождение подтверждается сведениями общедоступных информационных справочников;\n\n2) доходов от сдачи в аренду (лизинг) воздушных судов (включая вспомогательные силовые установки и (или) авиационные двигатели) по заключенным с иностранными организациями - арендодателями (лизингодателями) до 5 марта 2022 года договорам аренды (лизинга) воздушных судов, зарегистрированных или подлежащих регистрации в Государственном реестре гражданских воздушных судов Российской Федерации, если иностранная организация - получатель дохода и российская организация - лизингополучатель не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса. При этом в случае внесения изменений в условия договоров аренды (лизинга) воздушных судов с иностранными организациями - арендодателями (лизингодателями) после дня принятия Указа положения настоящего подпункта применяются в отношении доходов в сумме, не превышающей суммы доходов от сдачи в аренду (лизинг) воздушных судов (включая вспомогательные силовые установки и (или) авиационные двигатели), определяемой согласно действовавшим до дня принятия Указа положениям указанных договоров;\n\n3) доходов от использования и (или) предоставления прав использования аудиовизуальных произведений и иных результатов интеллектуальной деятельности и средств индивидуализации (роялти) на телеканалах при наземном эфирном, спутниковом, кабельном и (или) ином распространении таких телеканалов, если российская организация, выплачивающая доходы, и иностранная организация - получатель доходов не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\n4) доходов от использования и (или) предоставления права использования объекта авторского права и (или) смежных прав (любого произведения литературы, искусства или науки, включая компьютерные программы, кинематографические фильмы, фонограммы, записи на пленку или другие носители для использования в радио- и телевизионных передачах или другие средства воспроизведения и распространения информации), любого патента, чертежа, модели, схемы, секретной формулы, технологии либо информации относительно промышленного, коммерческого или научного опыта (ноу-хау), если российская организация, выплачивающая доходы, и иностранная организация - получатель доходов не являются взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nИсчисление, удержание и перечисление в бюджет соответствующих сумм налога осуществляется организациями, являющимися участниками консолидированной группы налогоплательщиков, самостоятельно, без участия ответственного участника консолидированной группы налогоплательщиков (за исключением случаев, когда налоговым агентом по правилам настоящей статьи выступает такой ответственный участник).\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 310. Особенности исчисления и уплаты налога с доходов, полученных иностранной организацией от источников в Российской Федерации, удерживаемого налоговым агентом","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b4bd8e2f3ba1a36113f10b6b3cd9294995980fc09c6dafeff099a2e00f93a5d"},{"code_id":"NK_RF_2","article_number":"310.1","version_date":"2000-07-31","article_text":"1. Депозитарий признается налоговым агентом, осуществляющим исчисление и уплату налога в отношении доходов по следующим ценным бумагам, которые учитываются на счете депо иностранного номинального держателя, счете депо иностранного уполномоченного держателя и (или) счете депо депозитарных программ:\n\n1) по государственным ценным бумагам Российской Федерации с обязательным централизованным хранением;\n\n2) по государственным ценным бумагам субъектов Российской Федерации с обязательным централизованным хранением;\n\n3) по муниципальным ценным бумагам с обязательным централизованным хранением;\n\n4) по эмиссионным ценным бумагам с обязательным централизованным хранением, выпущенным российскими организациями, государственная регистрация выпуска которых или присвоение идентификационного номера которым осуществлены после 1 января 2012 года;\n\n5) по иным эмиссионным ценным бумагам, выпущенным российскими организациями, за исключением эмиссионных ценных бумаг с обязательным централизованным хранением выпусков, государственная регистрация которых или присвоение идентификационного номера которым осуществлены до 1 января 2012 года.\n\n1) обобщенной информации об организациях, осуществляющих права по ценным бумагам, указанным в пункте 1 настоящей статьи, за исключением доверительных управляющих, которые действуют не в интересах иностранного инвестиционного фонда (инвестиционной компании), который в соответствии с личным законом такого фонда (компании) относится к схемам коллективного инвестирования;\n\n2) обобщенной информации об организациях, в чьих интересах доверительный управляющий осуществляет права по ценным бумагам, указанным в пункте 1 настоящей статьи, при условии, что такой доверительный управляющий действует не в интересах иностранного инвестиционного фонда (инвестиционной компании), который в соответствии с личным законом такого фонда (компании) относится к схемам коллективного инвестирования.\n\n1) обобщенной информации об организациях, осуществляющих права по ценным бумагам иностранного эмитента, удостоверяющим права в отношении ценных бумаг, указанных в пункте 1 настоящей статьи, за исключением доверительных управляющих, которые действуют не в интересах иностранного инвестиционного фонда (инвестиционной компании), который в соответствии с личным законом такого фонда (компании) относится к схемам коллективного инвестирования;\n\n2) обобщенной информации об организациях, в чьих интересах доверительный управляющий осуществляет права по ценным бумагам иностранного эмитента, удостоверяющим права в отношении ценных бумаг, указанных в пункте 1 настоящей статьи, при условии, что такой доверительный управляющий действует не в интересах иностранного инвестиционного фонда (инвестиционной компании), который в соответствии с личным законом такого фонда (компании) относится к схемам коллективного инвестирования.\n\n1) в отношении организаций, указанных в подпункте 1 пункта 2, подпункте 1 пункта 3 и пункте 5 настоящей статьи, соответственно сведения о количестве ценных бумаг, указанных в пункте 1 настоящей статьи, и о количестве ценных бумаг иностранного эмитента, удостоверяющих права в отношении ценных бумаг соответствующей российской организации, права по которым осуществляются организациями на дату, определенную решением российской организации о выплате дохода по ценным бумагам;\n\n2) в отношении организаций, указанных в подпункте 2 пункта 2, подпункте 2 пункта 3 и пункте 4 настоящей статьи, соответственно сведения о количестве ценных бумаг, указанных в пункте 1 настоящей статьи, и о количестве ценных бумаг иностранного эмитента, удостоверяющих права в отношении ценных бумаг соответствующей российской организации, права по которым осуществляются доверительным управляющим в интересах соответствующих организаций на дату, определенную решением о выплате дохода по ценным бумагам.\n\nДля целей применения пониженных налоговых ставок (освобождения от налога), установленных настоящим Кодексом или международными договорами Российской Федерации по вопросам налогообложения, сведения о количестве ценных бумаг, предусмотренные пунктом 7 настоящей статьи, представляются налоговому агенту с указанием:\n\nгосударств, налоговыми резидентами которых являются лица, осуществляющие (в отношении которых осуществляются) права по ценным бумагам и имеющие фактическое право на выплачиваемый доход;\n\nположений настоящего Кодекса или международного договора Российской Федерации по вопросам налогообложения, предусматривающих пониженную налоговую ставку (освобождение от налогообложения).\n\nВ случае, если лицом, осуществляющим (в отношении которого осуществляются) права по ценным бумагам, при определении налоговой базы у которого в соответствии с настоящим Кодексом учитываются доходы по этим ценным бумагам в виде процентов, является российская организация, сведения о количестве ценных бумаг, предусмотренные пунктом 7 настоящей статьи, представляются налоговому агенту с указанием идентификационного номера налогоплательщика этой организации.\n\nВ случае выплаты дохода в виде дивидендов по акциям международных холдинговых компаний налоговый агент применяет налоговую ставку, установленную подпунктом 12 пункта 3 статьи 284 настоящего Кодекса, на основании документального подтверждения, представленного такой компанией налоговому агенту, что на день принятия решения международной компании (организации, указанной в пункте 11 статьи 242 настоящего Кодекса) о выплате дивидендов она одновременно является международной холдинговой компанией и публичной компанией, а также являлась публичной компанией по состоянию на 1 января 2018 года, или налоговую ставку, установленную подпунктом 13 пункта 3 статьи 284 настоящего Кодекса, на основании документального подтверждения, что на день принятия решения международной компанией о выплате дивидендов она выполняла условия, установленные статьей 28410 настоящего Кодекса. Международная холдинговая компания - эмитент ценных бумаг, выплачивающая доходы в виде дивидендов, обязана довести до сведения налогового агента соответствующее подтверждение не позднее пяти дней с даты, на которую в соответствии с решением о выплате (объявлении) дивидендов определяются лица, имеющие право на их получение, но не позднее дня выплаты дивидендов в порядке, предусмотренном пунктами 51 и 52 статьи 275 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 25.12.2018 № 490-ФЗ) (В редакции  федеральных законов от 25.02.2022 № 18-ФЗ, от 26.03.2022 № 66-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\nЕсли иное не предусмотрено настоящим пунктом, в отношении доходов, полученных в виде дивидендов по акциям российских организаций, налоговый агент исчисляет и уплачивает сумму налога на основании обобщенной информации, предусмотренной пунктом 7 настоящей статьи, по налоговой ставке, установленной настоящим Кодексом или международным договором Российской Федерации по вопросам налогообложения для доходов в виде дивидендов, применение которой не зависит от доли участия в капитале, суммы вложений в капитал организации или срока владения соответствующими акциями. (В редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\nВ случае, если лицом, осуществляющим (в отношении которого осуществляются) права по ценным бумагам, у которого в соответствии с настоящим Кодексом учитываются доходы по этим ценным бумагам в виде процентов, является российская организация, налоговый агент не исчисляет и не уплачивает сумму налога в отношении таких доходов при условии наличия у налогового агента информации, указанной в пункте 8 настоящей статьи. (Дополнение абзацем - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\nВозврат суммы излишне уплаченного налога осуществляется налогоплательщику в порядке, установленном настоящим Кодексом.\n\nВ случае, если информация, предусмотренная пунктом 7 настоящей статьи, не была представлена в отношении доходов в виде дивидендов по акциям (долям) международных холдинговых компаний, которые являются публичными компаниями на день принятия решения такой компании о выплате дивидендов и являлись публичными по состоянию на 1 января 2018 года, указанные доходы подлежат налогообложению по налоговой ставке, установленной подпунктом 2 пункта 3 статьи 284 настоящего Кодекса. Положения настоящего абзаца применяются в отношении доходов, выплаченных до 1 января 2029 года. (Дополнение абзацем - Федеральный закон от 25.12.2018 № 490-ФЗ)\n\n10. Обобщенная информация об организациях, предусмотренная пунктом 7 настоящей статьи, представляется депозитарию иностранным номинальным держателем, иностранным уполномоченным держателем, а также лицом, которому депозитарий открыл счет депо депозитарных программ, не позднее:\n\n1) пяти дней с даты, на которую депозитарием, осуществляющим обязательное централизованное хранение ценных бумаг, раскрыта информация о передаче своим депонентам причитающихся им выплат по ценным бумагам (для ценных бумаг с обязательным централизованным хранением);\n\n2) семи дней с даты, на которую в соответствии с решением организации определяются лица, имеющие право на получение дивидендов (для акций, выпущенных российскими организациями).\n\nНалоговый агент вправе не осуществлять перерасчет ранее удержанного налога в соответствии с настоящим пунктом в случае, если уточненная обобщенная информация, предусмотренная пунктом 7 настоящей статьи, представлена налоговому агенту менее чем за пять дней до истечения срока, указанного в абзаце первом настоящего пункта.\n\nУплата сумм исчисленного налога в случае его перерасчета осуществляется налоговым агентом за счет сумм налога в отношении выплат по ценным бумагам, удержанных им до осуществления перерасчета, а также денежных средств лиц, указанных в пункте 9 настоящей статьи, в порядке, установленном договором между налоговым агентом и такими лицами.\n\n12. Обобщенная информация, предусмотренная пунктом 7 настоящей статьи, представляется иностранной организацией, действующей в интересах третьих лиц, в одной или нескольких из следующих форм:\n\n1) документ на бумажном носителе, подписанный уполномоченным лицом иностранной организации;\n\n2) электронный документ, подписанный усиленной квалифицированной электронной подписью или усиленной неквалифицированной электронной подписью в соответствии с Федеральным законом от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\", без представления документа на бумажном носителе;\n\n3) электронный документ, переданный с использованием системы международных финансовых телекоммуникаций СВИФТ, без представления документа на бумажном носителе.\n\n13. Налоговый агент определяет форму (формы) представления ему обобщенной информации из числа форм, предусмотренных пунктом 12 настоящей статьи, а также условия использования этой формы (этих форм).\n\n14. Депозитарий, осуществляющий выплату доходов, указанных в пункте 1 настоящей статьи, осуществляет исчисление и уплату суммы налога на прибыль организаций в соответствии с настоящей статьей в отношении всех сумм доходов, выплачиваемых по дисконтным облигациям, выпущенным российскими организациями.\n\nВозврат суммы излишне уплаченного налога осуществляется налогоплательщику в порядке, установленном настоящим Кодексом.\n\n15. На налогового агента не может быть возложена\n\nобязанность по исчислению и уплате суммы налога в отношении выплат, предусмотренных настоящей статьей, не удержанного им вследствие представления ему организацией, действующей в интересах третьих лиц, недостоверной и (или) неполной информации и (или) документов, а также в случае отказа такой организации представить по запросу налогового органа, проводящего камеральную или выездную налоговую проверку (налоговый мониторинг), информацию и (или) документы, истребуемые в соответствии со статьей 3102 настоящего Кодекса. (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nВ случаях, указанных в настоящем пункте, к налоговому агенту также не применяются налоговые санкции.\n\n16. Иностранный номинальный держатель, иностранный уполномоченный держатель и (или) лицо, которому открыт счет депозитарных программ, вправе участвовать в отношениях с налоговым агентом, регулируемых настоящей статьей, самостоятельно или через своего уполномоченного представителя в соответствии со статьей 26 настоящего Кодекса.\n\n17. Требования настоящей статьи не распространяются на выплату доходов по ценным бумагам иностранных организаций, в том числе допущенных к размещению и (или) публичному обращению в Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 29.12.2012 № 282-ФЗ) (В редакции Федерального закона от 02.11.2013 № 306-ФЗ)","article_title":"Статья 310.1. Особенности исчисления и уплаты налога в отношении доходов по государственным ценным бумагам, муниципальным ценным бумагам, а также по эмиссионным ценным бумагам, выпущенным российскими организациями, выплачиваемых иностранным организациям, действующим в интересах третьих лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3fbe33bf6005f715930eebe1347f33cdaf5bcc915b01dc50b176021b9ced3fc2"},{"code_id":"NK_RF_2","article_number":"310.2","version_date":"2000-07-31","article_text":"1) копии документов, подтверждающих государственную регистрацию и полное наименование организации, осуществлявшей на дату, определенную решением российской организации о выплате дохода по ценным бумагам, права по ценным бумагам такой российской организации (ценным бумагам иностранной организации, удостоверяющим права в отношении акций российской организации);\n\n2) копии документов, подтверждающих государственную регистрацию и полное наименование организации, в интересах которой доверительный управляющий осуществлял на дату, определенную решением российской организации о выплате дохода по ценным бумагам, права по ценным бумагам такой российской организации (ценным бумагам иностранной организации, удостоверяющим права в отношении акций российской организации);\n\n3) копии и оригиналы документов, подтверждающих осуществление организацией на дату, определенную решением российской организации о выплате дохода, прав по ценным бумагам такой российской организации (ценным бумагам иностранной организации, удостоверяющим права в отношении акций российской организации), а в случае применения пониженных налоговых ставок или освобождения от налогообложения, предусмотренных настоящим Кодексом или международными договорами Российской Федерации по вопросам налогообложения, также документы, подтверждающие налоговое резидентство такой организации; (В редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\n4) копии и оригиналы документов, подтверждающих осуществление доверительным управляющим на дату, определенную решением российской организации о выплате дохода по ценным бумагам, прав по ценным бумагам такой российской организации (ценным бумагам иностранной организации, удостоверяющим права в отношении акций российской организации) в интересах организации, а также документы, подтверждающие налоговое резидентство такой организации;\n\n5) иные документы, подтверждающие правильность исчисления и уплаты налога, в том числе документы, подтверждающие достоверность информации, представленной иностранными организациями, действующими в интересах третьих лиц.\n\nСрок представления документов, истребованных в соответствии с настоящей статьей, может быть продлен решением налогового органа, но не более чем на три месяца.\n\n(Дополнение статьей - Федеральный закон от 02.11.2013 № 306-ФЗ)","article_title":"Статья 310.2. Истребование документов, связанных с исчислением и уплатой налога в отношении доходов по государственным ценным бумагам, муниципальным ценным бумагам, а также по эмиссионным ценным бумагам, выпущенным российскими организациями, выплачиваемых иностранным организациям, действующим в интересах третьих лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cd25ba5c6364a8bc3c34b4c179ced09f09d68a0afb2bde17dde3f06732622a9"}]$law7v026$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
